enum class TutorTab {
    DASHBOARD, STORYLEARNING, SHADOWING, VOCABULARY, MNEMONICS, GOALS
}

class MainActivity : ComponentActivity() {
    lateinit var speechHelper: TutorSpeechHelper

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        window.addFlags(android.view.WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON)
        enableEdgeToEdge()

        speechHelper = TutorSpeechHelper(this)

        setContent {
            MyApplicationTheme {
                val app = application as TutorApplication
                val tutorViewModel: TutorViewModel = viewModel(
                    factory = TutorViewModelFactory(
                        app,
                        app.liveChatRepository,
                        app.acceleratorRepository,
                        app.dictionaryRepository,
                        app.contentRepository,
                        app.vocabularyRepository,
                        app.mnemonicRepository,
                        app.shadowingRepository
                    )
                )

                val speakText by tutorViewModel.textToSpeak.collectAsStateWithLifecycle()
                val streamingChunk by tutorViewModel.streamingSpeechChunk.collectAsStateWithLifecycle()
                val currentGoal by tutorViewModel.goal.collectAsStateWithLifecycle()
                val activeSessionState by tutorViewModel.activeSession.collectAsStateWithLifecycle()
                val playbackSpeedState by tutorViewModel.playbackSpeed.collectAsStateWithLifecycle()
                val selectedVoiceState by tutorViewModel.selectedVoice.collectAsStateWithLifecycle()

                // Keep SpeechHelper selected voice synchronized with ViewModel state
                LaunchedEffect(selectedVoiceState) {
                    speechHelper.updateSelectedVoice(selectedVoiceState)
                }

                // Ultra-low latency streaming TTS playback as sentences arrive from Gemini
                LaunchedEffect(streamingChunk) {
                    val chunk = streamingChunk
                    if (chunk != null && chunk.sentence.isNotBlank()) {
                        val targetLang = activeSessionState?.language ?: currentGoal?.targetLanguage ?: "Spanish"
                        val cefr = activeSessionState?.cefrLevel ?: currentGoal?.cefrLevel ?: "B1"
                        val stress = activeSessionState?.stressLevel ?: 0
                        speechHelper.speakStreamingSentence(
                            sentence = chunk.sentence,
                            isFirstSentence = chunk.isFirst,
                            isFinalSentence = chunk.isFinal,
                            languageName = targetLang,
                            cefrLevel = cefr,
                            stressLevel = stress,
                            speedMultiplier = playbackSpeedState
                        )
                        tutorViewModel.clearStreamingSpeechChunk()
                    }
                }

                // Fallback non-streaming Text-To-Speech when whole text is delivered
                LaunchedEffect(speakText) {
                    val text = speakText
                    if (!text.isNullOrBlank()) {
                        val targetLang = activeSessionState?.language ?: currentGoal?.targetLanguage ?: "Spanish"
                        val cefr = activeSessionState?.cefrLevel ?: currentGoal?.cefrLevel ?: "B1"
                        val stress = activeSessionState?.stressLevel ?: 0
                        speechHelper.speak(
                            text = text,
                            languageName = targetLang,
                            cefrLevel = cefr,
                            stressLevel = stress,
                            speedMultiplier = playbackSpeedState
                        )
                        tutorViewModel.clearSpeechText()
                    }
                }

                MainLayout(viewModel = tutorViewModel, speechHelper = speechHelper)
            }
        }
    }

    override fun onDestroy() {
        super.onDestroy()
        speechHelper.shutdown()
    }
}

@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun MainLayout(viewModel: TutorViewModel, speechHelper: TutorSpeechHelper) {
    val context = LocalContext.current
    val app = context.applicationContext as com.example.TutorApplication
    val shadowingViewModel: com.example.ui.shadowing.ShadowingViewModel = androidx.lifecycle.viewmodel.compose.viewModel(
        factory = com.example.ui.shadowing.ShadowingViewModelFactory(
            app,
            app.shadowingRepository,
            app.vocabularyRepository
        )
    )
    val currentTab = remember { mutableStateOf(TutorTab.DASHBOARD) }
    val vocabularySubTab = remember { mutableStateOf(0) }

    val activeSession by viewModel.activeSession.collectAsStateWithLifecycle()
    val isAiLoading by viewModel.isAiLoading.collectAsStateWithLifecycle()
    val isEndingSession by viewModel.isEndingSession.collectAsStateWithLifecycle()
    val evaluation by viewModel.currentEvaluation.collectAsStateWithLifecycle()

    val currentGoal by viewModel.goal.collectAsStateWithLifecycle()
    val sessions by viewModel.allSessions.collectAsStateWithLifecycle()
    val vocabulary by viewModel.allVocabulary.collectAsStateWithLifecycle()
    val languageIslands by viewModel.languageIslands.collectAsStateWithLifecycle()
    val mistakes by viewModel.allMistakes.collectAsStateWithLifecycle()

    val stories by viewModel.allStories.collectAsStateWithLifecycle()
    val isGeneratingStory by viewModel.isGeneratingStory.collectAsStateWithLifecycle()
    val activeStory by viewModel.activeStory.collectAsStateWithLifecycle()
    val wordTranslation by viewModel.wordTranslation.collectAsStateWithLifecycle()
    val isTranslatingWord by viewModel.isTranslatingWord.collectAsStateWithLifecycle()
    val generatedMnemonic by viewModel.generatedMnemonic.collectAsStateWithLifecycle()
    val selectedVoice by viewModel.selectedVoice.collectAsStateWithLifecycle()
    val shadowingInputContent by com.example.ui.shadowing.ShadowingEngine.currentInput.collectAsStateWithLifecycle()

    LaunchedEffect(selectedVoice) {
        speechHelper.selectedVoice = selectedVoice
    }

    Scaffold(
        modifier = Modifier.fillMaxSize(),
        bottomBar = {
            if (activeSession == null) {
                NavigationBar(
                    containerColor = MaterialTheme.colorScheme.surface,
                    tonalElevation = 8.dp
                ) {
                    NavigationBarItem(
                        selected = currentTab.value == TutorTab.DASHBOARD,
                        onClick = { currentTab.value = TutorTab.DASHBOARD },
                        icon = { Icon(Icons.Default.Home, contentDescription = "Dashboard") },
                        label = { Text("Practice", fontSize = 9.sp, fontWeight = FontWeight.SemiBold) },
                        colors = NavigationBarItemDefaults.colors(
                            selectedIconColor = LingoPrimary,
                            selectedTextColor = LingoPrimary,
                            indicatorColor = LingoPrimary.copy(alpha = 0.15f)
                        ),
                        modifier = Modifier.testTag("nav_tab_dashboard")
                    )
                    NavigationBarItem(
                        selected = currentTab.value == TutorTab.STORYLEARNING,
                        onClick = { currentTab.value = TutorTab.STORYLEARNING },
                        icon = { Icon(Icons.Default.AutoStories, contentDescription = "StoryLearning") },
                        label = { Text("Story", fontSize = 9.sp, fontWeight = FontWeight.SemiBold) },
                        colors = NavigationBarItemDefaults.colors(
                            selectedIconColor = LingoPrimary,
                            selectedTextColor = LingoPrimary,
                            indicatorColor = LingoPrimary.copy(alpha = 0.15f)
                        ),
                        modifier = Modifier.testTag("nav_tab_storylearning")
                    )
                    NavigationBarItem(
                        selected = currentTab.value == TutorTab.SHADOWING,
                        onClick = { currentTab.value = TutorTab.SHADOWING },
                        icon = { Icon(Icons.Default.Hearing, contentDescription = "Adaptive Shadowing") },
                        label = { Text("Shadowing", fontSize = 9.sp, fontWeight = FontWeight.SemiBold) },
                        colors = NavigationBarItemDefaults.colors(
                            selectedIconColor = LingoPrimary,
                            selectedTextColor = LingoPrimary,
                            indicatorColor = LingoPrimary.copy(alpha = 0.15f)
                        ),
                        modifier = Modifier.testTag("nav_tab_shadowing")
                    )
                    NavigationBarItem(
                        selected = currentTab.value == TutorTab.VOCABULARY,
                        onClick = { currentTab.value = TutorTab.VOCABULARY },
                        icon = { Icon(Icons.Default.Book, contentDescription = "Vocabulary") },
                        label = { Text("Vocab", fontSize = 9.sp, fontWeight = FontWeight.SemiBold) },
                        colors = NavigationBarItemDefaults.colors(
                            selectedIconColor = LingoPrimary,
                            selectedTextColor = LingoPrimary,
                            indicatorColor = LingoPrimary.copy(alpha = 0.15f)
                        ),
                        modifier = Modifier.testTag("nav_tab_vocabulary")
                    )
                    NavigationBarItem(
                        selected = currentTab.value == TutorTab.MNEMONICS,
                        onClick = { currentTab.value = TutorTab.MNEMONICS },
                        icon = { Icon(Icons.Default.Memory, contentDescription = "Mnemotechnika") },
                        label = { Text("Mnemo", fontSize = 9.sp, fontWeight = FontWeight.SemiBold) },
                        colors = NavigationBarItemDefaults.colors(
                            selectedIconColor = LingoPrimary,
                            selectedTextColor = LingoPrimary,
                            indicatorColor = LingoPrimary.copy(alpha = 0.15f)
                        ),
                        modifier = Modifier.testTag("nav_tab_mnemonics")
                    )
                    NavigationBarItem(
                        selected = currentTab.value == TutorTab.GOALS,
                        onClick = { currentTab.value = TutorTab.GOALS },
                        icon = { Icon(Icons.Default.Settings, contentDescription = "Goals") },
                        label = { Text("Goals", fontSize = 9.sp, fontWeight = FontWeight.SemiBold) },
                        colors = NavigationBarItemDefaults.colors(
                            selectedIconColor = LingoPrimary,
                            selectedTextColor = LingoPrimary,
                            indicatorColor = LingoPrimary.copy(alpha = 0.15f)
                        ),
                        modifier = Modifier.testTag("nav_tab_goals")
                    )
                }
            }
        }
    ) { innerPadding ->
        val currentEval = evaluation
        Box(
            modifier = Modifier
                .fillMaxSize()
                .background(MaterialTheme.colorScheme.background)
        ) {
            if (shadowingInputContent != null) {
                com.example.ui.shadowing.ShadowingEngineBottomSheet(
                    viewModel = shadowingViewModel,
                    speechHelper = speechHelper,
                    onNavigateToChat = { scenarioTitle, scenarioKey, initialPrompt ->
                        viewModel.startNewSession(scenarioKey, scenarioTitle, 0, initialPrompt)
                        currentTab.value = TutorTab.DASHBOARD
                    },
                    onDismissRequest = {
                        com.example.ui.shadowing.ShadowingEngine.dismissEngine()
                    }
                )
            }

            if (activeSession != null) {
                // Interactive Spoken/Text Conversation Screen overlay
                ConversationScreen(
                    session = activeSession!!,
                    viewModel = viewModel,
                    isAiLoading = isAiLoading,
                    speechHelper = speechHelper
                )
            } else {
                // Content Tab Screens
                Box(
                    modifier = Modifier
                        .fillMaxSize()
                        .padding(innerPadding)
                ) {
                    when (currentTab.value) {
                        TutorTab.DASHBOARD -> {
                            DashboardScreen(
                                goal = currentGoal,
                                sessions = sessions,
                                vocabulary = vocabulary,
                                mistakes = mistakes,
                                viewModel = viewModel,
                                currentTab = currentTab,
                                vocabularySubTab = vocabularySubTab,
                                speechHelper = speechHelper,
                                onStartScenario = { key, title, stress -> viewModel.startNewSession(key, title, stress) }
                            )
                        }
                        TutorTab.STORYLEARNING -> {
                            StoryReaderTab(
                                viewModel = viewModel,
                                stories = stories,
                                isGeneratingStory = isGeneratingStory,
                                activeStory = activeStory,
                                wordTranslation = wordTranslation,
                                isTranslatingWord = isTranslatingWord,
                                generatedMnemonic = generatedMnemonic,
                                goal = currentGoal,
                                currentTab = currentTab,
                                speechHelper = speechHelper
                            )
                        }
                        TutorTab.VOCABULARY -> VocabularyScreen(
                            vocabulary = vocabulary,
                            languageIslands = languageIslands,
                            mistakes = mistakes,
                            viewModel = viewModel,
                            subTabSelected = vocabularySubTab,
                            speechHelper = speechHelper
                        )
                        TutorTab.MNEMONICS -> MnemonicsScreen(
                            viewModel = viewModel,
                            currentTab = currentTab,
                            speechHelper = speechHelper
                        )
                        TutorTab.SHADOWING -> com.example.ui.shadowing.ShadowingScreen(
                            viewModel = shadowingViewModel,
                            speechHelper = speechHelper,
                            targetLanguageFromGoal = currentGoal?.targetLanguage ?: "Spanish",
                            onNavigateToChat = { title, key, initialVibe ->
                                viewModel.startNewSession(key, title, 0, initialVibe)
                                currentTab.value = TutorTab.DASHBOARD
                            }
                        )
                        TutorTab.GOALS -> GoalsScreen(
                            goal = currentGoal,
                            viewModel = viewModel,
                            speechHelper = speechHelper
                        )
                    }
                }
            }

            if (isEndingSession) {
                Box(
                    modifier = Modifier
                        .fillMaxSize()
                        .background(Color.Black.copy(alpha = 0.85f))
                        .clickable(enabled = false) {}, // absorb clicks to prevent background taps
                    contentAlignment = Alignment.Center
                ) {
                    Column(
                        horizontalAlignment = Alignment.CenterHorizontally,
                        verticalArrangement = Arrangement.Center,
                        modifier = Modifier.padding(24.dp)
                    ) {
                        CircularProgressIndicator(
                            color = LingoPrimary,
                            strokeWidth = 4.dp,
                            modifier = Modifier.size(56.dp)
                        )
                        Spacer(modifier = Modifier.height(24.dp))
                        Text(
                            text = "Analizuję Twoją lekcję... 🧠",
                            color = Color.White,
                            fontSize = 20.sp,
                            fontWeight = FontWeight.Bold,
                            textAlign = TextAlign.Center
                        )
                        Spacer(modifier = Modifier.height(8.dp))
                        Text(
                            text = "Lingo analizuje Twój akcent, słownictwo oraz gramatykę, aby przygotować spersonalizowaną ocenę i plan nauki.",
                            color = Color.White.copy(alpha = 0.7f),
                            fontSize = 14.sp,
                            textAlign = TextAlign.Center,
                            lineHeight = 20.sp
                        )
                        Spacer(modifier = Modifier.height(6.dp))
                        Text(
                            text = "To potrwa tylko chwilę...",
                            color = Color.White.copy(alpha = 0.5f),
                            fontSize = 12.sp,
                            fontStyle = FontStyle.Italic,
                            textAlign = TextAlign.Center
                        )
                    }
                }
            }
        }
    }
}

