    vocabulary: List<Vocabulary>,
    mistakes: List<Mistake>,
    viewModel: TutorViewModel,
    currentTab: MutableState<TutorTab>,
    vocabularySubTab: MutableState<Int>,
    speechHelper: TutorSpeechHelper,
    onStartScenario: (String, String, Int) -> Unit
