    val userKey by viewModel.apiKey.collectAsStateWithLifecycle()
    val currentEval by viewModel.currentEvaluation.collectAsStateWithLifecycle()
    val showStressLevelDialog = remember { mutableStateOf(false) }
    val selectedKey = remember { mutableStateOf("") }
    val selectedTitle = remember { mutableStateOf("") }
    val selectedCategory = remember { mutableStateOf("classic") } // "story", "malaga", "classic", "cities"
    val malagaActiveInfoTab = remember { mutableStateOf("historia") } // "historia", "pogoda", "gospodarka", "kultura", "slang"
    val showVocabAddedToast = remember { mutableStateOf<String?>(null) }

    val stories by viewModel.allStories.collectAsStateWithLifecycle()
    val isGeneratingStory by viewModel.isGeneratingStory.collectAsStateWithLifecycle()
    val activeStory by viewModel.activeStory.collectAsStateWithLifecycle()
    val wordTranslation by viewModel.wordTranslation.collectAsStateWithLifecycle()
    val isTranslatingWord by viewModel.isTranslatingWord.collectAsStateWithLifecycle()
    val generatedMnemonic by viewModel.generatedMnemonic.collectAsStateWithLifecycle()

