        // Combined compact Daily Goal and Weekly Statistics Card
        item {
            val calendar = java.util.Calendar.getInstance().apply {
                set(java.util.Calendar.HOUR_OF_DAY, 0)
                set(java.util.Calendar.MINUTE, 0)
                set(java.util.Calendar.SECOND, 0)
                set(java.util.Calendar.MILLISECOND, 0)
            }
            val midnightToday = calendar.timeInMillis
            val sessionsToday = sessions.filter { it.timestamp >= midnightToday }
            val completedSecondsToday = sessionsToday.sumOf { it.durationSeconds }
            val completedMinutesToday = completedSecondsToday / 60
            val dailyGoalMinutes = goal?.dailyGoalMinutes ?: 15
            val progressFraction = if (dailyGoalMinutes > 0) completedMinutesToday.toFloat() / dailyGoalMinutes.toFloat() else 0f
            val clampedProgress = progressFraction.coerceIn(0f, 1f)

            Card(
                modifier = Modifier.fillMaxWidth(),
                shape = RoundedCornerShape(12.dp),
                colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.2f)),
