                val currentTargetLang = goal?.targetLanguage ?: "Spanish"
                val flagshipData = remember(currentTargetLang) { getFlagshipConcentricDataForLanguage(currentTargetLang) }

                // Category Selector Block (Two side-by-side, third below)
                Column(
