                            modifier = Modifier.fillMaxWidth()
                        ) {
                            // Header Introduction
                            Card(
                                modifier = Modifier.fillMaxWidth(),
                                shape = RoundedCornerShape(16.dp),
                                colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surface),
                                border = BorderStroke(1.dp, MaterialTheme.colorScheme.outlineVariant.copy(alpha = 0.5f))
                            ) {
                                Column(modifier = Modifier.padding(16.dp)) {
                                    Row(
                                        verticalAlignment = Alignment.CenterVertically
                                    ) {
                                        Box(
                                            modifier = Modifier
                                                .size(44.dp)
                                                .clip(CircleShape)
                                                .background(LingoSecondary.copy(alpha = 0.15f)),
                                            contentAlignment = Alignment.Center
                                        ) {
                                            Text(flagshipData.flagEmoji, fontSize = 24.sp)
                                        }
                                        Spacer(modifier = Modifier.width(12.dp))
                                        Column {
                                            Text(
                                                text = flagshipData.title,
                                                fontWeight = FontWeight.Bold,
                                                fontSize = 16.sp,
                                                color = MaterialTheme.colorScheme.onSurface
                                            )
                                            Text(
                                                text = flagshipData.subtitle,
                                                fontSize = 12.sp,
                                                color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.6f)
                                            )
                                        }
                                    }
                                }
                            }

                            // Render 6 sequential lessons
                            flagshipData.lessons.forEach { lesson ->
                                val lessonId = lesson.id
                                val lessonNumber = lesson.number
                                val lessonTitle = lesson.title
                                val lessonIcon = lesson.icon
                                val lessonDescription = lesson.description
                                val scenariosList = lesson.scenarios
                                val keyVocabList = lesson.keyVocab

                                val isExpanded = expandedLessonId.value == lessonId
