                                                                Text("Pokaż lokalne słownictwo (${keyVocabList.size}) 📚", fontSize = 12.sp, fontWeight = FontWeight.SemiBold, color = LingoSecondary)
                                                            }
                                                            Text(if (vocabExpanded.value) "▲" else "▼", fontSize = 10.sp, color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.5f))
                                                        }
                                                        
                                                        if (vocabExpanded.value) {
                                                            Column(modifier = Modifier.padding(start = 12.dp, end = 12.dp, bottom = 12.dp)) {
                                                                val contextObj = androidx.compose.ui.platform.LocalContext.current
                                                                keyVocabList.forEach { kv ->
                                                                    val vWord = kv["word"] ?: ""
                                                                    val vTrans = kv["translation"] ?: ""
                                                                    val vCtx = kv["context"] ?: ""

                                                                    Row(
                                                                        modifier = Modifier
                                                                            .fillMaxWidth()
                                                                            .padding(vertical = 6.dp),
                                                                        horizontalArrangement = Arrangement.SpaceBetween,
                                                                        verticalAlignment = Alignment.CenterVertically
                                                                    ) {
                                                                        Column(modifier = Modifier.weight(1f)) {
                                                                            Text(vWord, fontWeight = FontWeight.Bold, fontSize = 13.sp, color = LingoPrimary)
                                                                            Text(vTrans, fontSize = 12.sp, color = MaterialTheme.colorScheme.onSurface)
                                                                            Text("\"$vCtx\"", fontSize = 11.sp, fontStyle = FontStyle.Italic, color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.6f))
                                                                        }
                                                                        Row(verticalAlignment = Alignment.CenterVertically) {
                                                                            IconButton(
                                                                                onClick = {
                                                                                    speechHelper.speak(vWord, goal?.targetLanguage ?: "Spanish", "B1")
                                                                                },
                                                                                modifier = Modifier.size(36.dp)
                                                                            ) {
                                                                                Icon(Icons.Default.VolumeUp, contentDescription = "Odsłuchaj", tint = LingoSecondary, modifier = Modifier.size(18.dp))
                                                                            }
                                                                            IconButton(
                                                                                onClick = {
                                                                                    viewModel.addCustomVocabulary(vWord, vTrans, vCtx)
                                                                                    Toast.makeText(contextObj, "Dodano: $vWord 📚", Toast.LENGTH_SHORT).show()
                                                                                },
                                                                                modifier = Modifier.size(36.dp)
                                                                            ) {
                                                                                Icon(Icons.Default.Add, contentDescription = "Dodaj do SRS", tint = LingoPrimary, modifier = Modifier.size(18.dp))
                                                                            }
                                                                        }
                                                                    }
                                                                    Divider(color = MaterialTheme.colorScheme.outlineVariant.copy(alpha = 0.15f))
                                                                }
                                                            }
                                                        }
                                                    }
                                                }

                                                Spacer(modifier = Modifier.height(16.dp))

                                                // 3. Scenario Header
                                                Text(
                                                    text = "Wybierz scenariusz do odegrania: 🚀",
                                                    fontSize = 12.sp,
                                                    fontWeight = FontWeight.Bold,
                                                    color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.8f),
                                                    modifier = Modifier.padding(bottom = 8.dp)
                                                )

                                                // List of scenarios under this lesson
                                                scenariosList.forEach { sc ->
                                                    val scTitle = sc["title"] ?: ""
                                                    val scSubtitle = sc["subtitle"] ?: ""
                                                    val scKey = sc["key"] ?: ""
                                                    val scDifficulty = sc["difficulty"] ?: ""
                                                    val scEmoji = sc["emoji"] ?: ""

                                                    Card(
                                                        modifier = Modifier
                                                            .fillMaxWidth()
                                                            .padding(vertical = 6.dp),
                                                        shape = RoundedCornerShape(12.dp),
                                                        colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surface),
                                                        border = BorderStroke(1.dp, MaterialTheme.colorScheme.outlineVariant.copy(alpha = 0.4f))
                                                    ) {
                                                        Column(modifier = Modifier.padding(12.dp)) {
                                                            Row(
                                                                verticalAlignment = Alignment.CenterVertically,
                                                                horizontalArrangement = Arrangement.SpaceBetween,
                                                                modifier = Modifier.fillMaxWidth()
                                                            ) {
                                                                Row(
                                                                    verticalAlignment = Alignment.CenterVertically,
                                                                    modifier = Modifier.weight(1f)
                                                                ) {
                                                                    Box(
                                                                        modifier = Modifier
                                                                            .size(32.dp)
                                                                            .clip(CircleShape)
                                                                            .background(LingoPrimary.copy(alpha = 0.08f)),
                                                                        contentAlignment = Alignment.Center
                                                                    ) {
                                                                        Text(scEmoji, fontSize = 16.sp)
                                                                    }
                                                                    Spacer(modifier = Modifier.width(8.dp))
                                                                    Text(
                                                                        text = scTitle,
                                                                        fontWeight = FontWeight.Bold,
                                                                        fontSize = 13.sp,
                                                                        color = MaterialTheme.colorScheme.onSurface
                                                                    )
                                                                }
                                                                
                                                                // Difficulty badge
                                                                Box(
                                                                    modifier = Modifier
                                                                        .clip(RoundedCornerShape(6.dp))
                                                                        .background(
                                                                            when (scDifficulty) {
                                                                                "A1-A2" -> Color(0xFFE8F5E9)
                                                                                "A2-B1" -> Color(0xFFEFFFDE)
                                                                                "B1-B2" -> Color(0xFFFFFDE7)
                                                                                else -> Color(0xFFFFF3E0)
                                                                            }
                                                                        )
                                                                        .padding(horizontal = 6.dp, vertical = 2.dp)
                                                                ) {
                                                                    Text(
                                                                        text = scDifficulty,
                                                                        fontSize = 10.sp,
                                                                        fontWeight = FontWeight.Bold,
                                                                        color = when (scDifficulty) {
                                                                            "A1-A2" -> Color(0xFF2E7D32)
                                                                            "A2-B1" -> Color(0xFF558B2F)
                                                                            "B1-B2" -> Color(0xFFF57F17)
                                                                            else -> Color(0xFFE65100)
                                                                        }
                                                                    )
                                                                }
                                                            }

                                                            Spacer(modifier = Modifier.height(6.dp))
                                                            Text(
                                                                text = scSubtitle,
                                                                fontSize = 12.sp,
                                                                color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.6f),
                                                                lineHeight = 16.sp
                                                            )

                                                            Spacer(modifier = Modifier.height(10.dp))

                                                            Button(
                                                                onClick = {
                                                                    selectedKey.value = scKey
                                                                    selectedTitle.value = scTitle
                                                                    showStressLevelDialog.value = true
                                                                },
                                                                colors = ButtonDefaults.buttonColors(containerColor = LingoPrimary),
                                                                shape = RoundedCornerShape(8.dp),
                                                                contentPadding = PaddingValues(horizontal = 12.dp, vertical = 6.dp),
                                                                modifier = Modifier
                                                                    .align(Alignment.End)
                                                                    .height(32.dp)
                                                            ) {
                                                                Icon(Icons.Default.PlayArrow, contentDescription = null, modifier = Modifier.size(14.dp))
                                                                Spacer(modifier = Modifier.width(4.dp))
                                                                Text("Rozpocznij Scenkę", fontSize = 11.sp, fontWeight = FontWeight.Bold)
                                                            }
                                                        }
                                                    }
                                                }
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    }
                    "classic" -> {
                        val classicScenarios = remember(currentTargetLang) { getClassicScenariosForLanguage(currentTargetLang) }
                        val contextObj = androidx.compose.ui.platform.LocalContext.current

                        Column(verticalArrangement = Arrangement.spacedBy(14.dp)) {
                            classicScenarios.forEach { item ->
                                val sKey = item["key"] as? String ?: ""
                                val sTitle = item["title"] as? String ?: ""
                                val sOrigTitle = item["originalTitle"] as? String ?: sTitle
                                val sIcon = item["icon"] as? String ?: "💬"
                                val sDiff = item["difficulty"] as? String ?: "All Levels"
                                val sTag = item["testTag"] as? String ?: "scenario_$sKey"
                                val sMission = item["mission"] as? String ?: ""
                                @Suppress("UNCHECKED_CAST")
                                val sPhrases = item["phrases"] as? List<Map<String, String>> ?: emptyList()

                                val phrasesExpanded = remember { mutableStateOf(false) }

                                Card(
                                    modifier = Modifier
                                        .fillMaxWidth()
                                        .testTag(sTag),
                                    shape = RoundedCornerShape(16.dp),
                                    colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surface),
                                    border = BorderStroke(1.dp, MaterialTheme.colorScheme.outlineVariant.copy(alpha = 0.45f))
                                ) {
                                    Column(modifier = Modifier.padding(16.dp)) {
                                        // Header row: Icon, Title, CEFR Badge
                                        Row(
                                            modifier = Modifier.fillMaxWidth(),
                                            horizontalArrangement = Arrangement.SpaceBetween,
                                            verticalAlignment = Alignment.CenterVertically
                                        ) {
                                            Row(
                                                verticalAlignment = Alignment.CenterVertically,
                                                modifier = Modifier.weight(1f)
                                            ) {
                                                Box(
                                                    modifier = Modifier
                                                        .size(38.dp)
                                                        .clip(CircleShape)
                                                        .background(LingoPrimary.copy(alpha = 0.12f)),
                                                    contentAlignment = Alignment.Center
                                                ) {
                                                    Text(sIcon, fontSize = 20.sp)
                                                }
                                                Spacer(modifier = Modifier.width(10.dp))
                                                Column {
                                                    Text(
                                                        text = sTitle,
                                                        fontWeight = FontWeight.Bold,
                                                        fontSize = 15.sp,
                                                        color = MaterialTheme.colorScheme.onSurface
                                                    )
                                                    Text(
                                                        text = sOrigTitle,
                                                        fontSize = 11.sp,
                                                        color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.55f)
                                                    )
                                                }
                                            }
                                            Surface(
                                                color = LingoSecondary.copy(alpha = 0.15f),
                                                shape = RoundedCornerShape(8.dp),
                                                modifier = Modifier.padding(start = 6.dp)
                                            ) {
                                                Text(
                                                    text = sDiff,
                                                    color = LingoSecondary,
                                                    fontSize = 10.sp,
                                                    fontWeight = FontWeight.Bold,
                                                    modifier = Modifier.padding(horizontal = 8.dp, vertical = 4.dp)
                                                )
                                            }
                                        }

                                        Spacer(modifier = Modifier.height(10.dp))

                                        // Mission Objective Box
                                        Surface(
                                            color = MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.4f),
                                            shape = RoundedCornerShape(10.dp),
                                            modifier = Modifier.fillMaxWidth()
                                        ) {
                                            Row(
                                                modifier = Modifier.padding(horizontal = 10.dp, vertical = 8.dp),
                                                verticalAlignment = Alignment.Top
                                            ) {
                                                Text("🎯 ", fontSize = 12.sp)
                                                Text(
                                                    text = sMission,
                                                    fontSize = 12.sp,
                                                    color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.8f),
                                                    lineHeight = 16.sp
                                                )
                                            }
                                        }

                                        Spacer(modifier = Modifier.height(10.dp))

                                        // Must-know phrases accordion
                                        Surface(
                                            color = MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.25f),
                                            shape = RoundedCornerShape(10.dp),
                                            modifier = Modifier
                                                .fillMaxWidth()
                                                .clickable { phrasesExpanded.value = !phrasesExpanded.value }
                                        ) {
                                            Column {
                                                Row(
                                                    modifier = Modifier
                                                        .fillMaxWidth()
                                                        .padding(horizontal = 10.dp, vertical = 8.dp),
                                                    horizontalArrangement = Arrangement.SpaceBetween,
                                                    verticalAlignment = Alignment.CenterVertically
                                                ) {
                                                    Row(verticalAlignment = Alignment.CenterVertically) {
                                                        Icon(Icons.Default.Star, contentDescription = null, tint = LingoPrimary, modifier = Modifier.size(15.dp))
                                                        Spacer(modifier = Modifier.width(6.dp))
                                                        Text(
                                                            text = "3 Zwroty-Klucze (Must-Know) 💡",
                                                            fontSize = 12.sp,
                                                            fontWeight = FontWeight.SemiBold,
                                                            color = LingoPrimary
                                                        )
                                                    }
                                                    Text(if (phrasesExpanded.value) "▲" else "▼", fontSize = 10.sp, color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.5f))
                                                }

                                                if (phrasesExpanded.value) {
                                                    Column(
                                                        modifier = Modifier.padding(start = 10.dp, end = 10.dp, bottom = 8.dp),
                                                        verticalArrangement = Arrangement.spacedBy(6.dp)
                                                    ) {
                                                        sPhrases.forEach { ph ->
                                                            val esText = ph["es"] ?: ""
                                                            val plText = ph["pl"] ?: ""
                                                            val ctxText = ph["ctx"] ?: ""

                                                            Row(
                                                                modifier = Modifier
                                                                    .fillMaxWidth()
                                                                    .clip(RoundedCornerShape(8.dp))
                                                                    .background(MaterialTheme.colorScheme.surface)
                                                                    .padding(horizontal = 8.dp, vertical = 6.dp),
                                                                horizontalArrangement = Arrangement.SpaceBetween,
                                                                verticalAlignment = Alignment.CenterVertically
                                                            ) {
                                                                Column(modifier = Modifier.weight(1f)) {
                                                                    Text(esText, fontWeight = FontWeight.Bold, fontSize = 12.sp, color = LingoPrimary)
                                                                    Text(plText, fontSize = 11.sp, color = MaterialTheme.colorScheme.onSurface)
                                                                    Text("\"$ctxText\"", fontSize = 10.sp, fontStyle = FontStyle.Italic, color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.55f))
                                                                }
                                                                Row(verticalAlignment = Alignment.CenterVertically) {
                                                                    IconButton(
                                                                        onClick = {
                                                                            speechHelper.speak(esText, goal?.targetLanguage ?: "Spanish", "B1")
                                                                        },
                                                                        modifier = Modifier.size(32.dp)
                                                                    ) {
                                                                        Icon(Icons.Default.VolumeUp, contentDescription = "Odsłuchaj", tint = LingoSecondary, modifier = Modifier.size(16.dp))
                                                                    }
                                                                    IconButton(
                                                                        onClick = {
                                                                            viewModel.addCustomVocabulary(esText, plText, ctxText)
                                                                            Toast.makeText(contextObj, "Dodano: $esText 📚", Toast.LENGTH_SHORT).show()
                                                                        },
                                                                        modifier = Modifier.size(32.dp)
                                                                    ) {
                                                                        Icon(Icons.Default.Add, contentDescription = "Dodaj do SRS", tint = LingoPrimary, modifier = Modifier.size(16.dp))
                                                                    }
                                                                }
                                                            }
                                                        }
                                                    }
                                                }
                                            }
                                        }

                                        Spacer(modifier = Modifier.height(12.dp))

                                        // Action Button: Start Scenario
                                        Button(
                                            onClick = {
                                                selectedKey.value = sKey
                                                selectedTitle.value = sOrigTitle
                                                showStressLevelDialog.value = true
                                            },
                                            colors = ButtonDefaults.buttonColors(containerColor = LingoPrimary),
                                            shape = RoundedCornerShape(10.dp),
                                            modifier = Modifier
                                                .fillMaxWidth()
                                                .height(42.dp)
                                        ) {
                                            Icon(Icons.Default.PlayArrow, contentDescription = null, modifier = Modifier.size(18.dp))
                                            Spacer(modifier = Modifier.width(6.dp))
                                            Text("Rozpocznij Scenkę 🚀", fontWeight = FontWeight.Bold, fontSize = 13.sp)
                                        }
                                    }
                                }
                            }
                        }
                    }
                    "cities" -> {
                        val contextObj = androidx.compose.ui.platform.LocalContext.current
                        val currentTargetLang = goal?.targetLanguage ?: "Spanish"

                        val defaultCountry = when {
                            currentTargetLang.equals("English", ignoreCase = true) -> "Wielka Brytania"
                            currentTargetLang.equals("German", ignoreCase = true) -> "Niemcy"
                            currentTargetLang.equals("French", ignoreCase = true) -> "Francja"
                            currentTargetLang.equals("Italian", ignoreCase = true) -> "Włochy"
                            else -> "Hiszpania"
                        }
                        val defaultCityHint = when {
                            currentTargetLang.equals("English", ignoreCase = true) -> "Miasto (np. Manchester, Oxford, Dublin, Boston)"
                            currentTargetLang.equals("German", ignoreCase = true) -> "Miasto (np. Hamburg, Frankfurt, Salzburg, Berno)"
                            currentTargetLang.equals("French", ignoreCase = true) -> "Miasto (np. Bordeaux, Strasburg, Genewa, Montreal)"
                            currentTargetLang.equals("Italian", ignoreCase = true) -> "Miasto (np. Bolonia, Palermo, Wenecja, Turyn)"
                            else -> "Miasto (np. Granada, Bilbao, Bogotá, Buenos Aires)"
                        }
                        val defaultCountryHint = when {
                            currentTargetLang.equals("English", ignoreCase = true) -> "Kraj (np. Wielka Brytania, USA, Kanada, Irlandia)"
                            currentTargetLang.equals("German", ignoreCase = true) -> "Kraj (np. Niemcy, Austria, Szwajcaria)"
                            currentTargetLang.equals("French", ignoreCase = true) -> "Kraj (np. Francja, Belgia, Szwajcaria, Kanada)"
                            currentTargetLang.equals("Italian", ignoreCase = true) -> "Kraj (np. Włochy, Szwajcaria)"
                            else -> "Kraj (np. Hiszpania, Kolumbia, Argentyna, Meksyk)"
                        }

                        val inputCity = remember { mutableStateOf("") }
                        val inputCountry = remember(currentTargetLang) { mutableStateOf(defaultCountry) }
                        val selectedLevel = remember { mutableStateOf("B2") }

                        val isGenerating = viewModel.isGeneratingCityModule.collectAsStateWithLifecycle().value
                        val generatedModule = viewModel.generatedCityModule.collectAsStateWithLifecycle().value
                        val generatedCityHub = viewModel.generatedCityHub.collectAsStateWithLifecycle().value

                        val curatedCities = remember(currentTargetLang) {
                            getCuratedCitiesForLanguage(currentTargetLang)
                        }

                        val curatedSectionTitle = when {
                            currentTargetLang.equals("English", ignoreCase = true) -> "Wyselekcjonowane Metropolie Anglojęzyczne 🇬🇧 🇺🇸"
                            currentTargetLang.equals("German", ignoreCase = true) -> "Wyselekcjonowane Metropolie Niemieckojęzyczne 🇩🇪 🇦🇹 🇨🇭"
                            currentTargetLang.equals("French", ignoreCase = true) -> "Wyselekcjonowane Metropolie Francuskojęzyczne 🇫🇷"
                            currentTargetLang.equals("Italian", ignoreCase = true) -> "Wyselekcjonowane Metropolie Włoskie 🇮🇹"
                            else -> "Wyselekcjonowane Metropolie Hiszpanii 🇪🇸"
                        }

                        Column(verticalArrangement = Arrangement.spacedBy(16.dp)) {
                            // Section 1: Pre-curated City Hubs (Language Adaptive)
                            Text(
                                text = curatedSectionTitle,
                                fontSize = 14.sp,
                                fontWeight = FontWeight.Bold,
                                color = MaterialTheme.colorScheme.onSurface
                            )

                            curatedCities.forEach { cityHub ->
                                CityHubItemCard(
                                    hub = cityHub,
                                    targetLanguage = currentTargetLang,
                                    onPlayScenario = { scKey, scTitle, _ ->
                                        selectedKey.value = scKey
                                        selectedTitle.value = scTitle
                                        showStressLevelDialog.value = true
                                    },
                                    onAddVocab = { word, trans, ctx ->
                                        viewModel.addCustomVocabulary(word, trans, ctx)
                                    },
                                    speechHelper = speechHelper,
                                    isGeneratedBadge = false
                                )
                            }

                            // Section 2: AI City Generator Form
                            Card(
                                modifier = Modifier
                                    .fillMaxWidth()
                                    .padding(top = 8.dp, bottom = 8.dp),
                                shape = RoundedCornerShape(16.dp),
                                colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surface),
                                border = BorderStroke(1.dp, MaterialTheme.colorScheme.outlineVariant.copy(alpha = 0.5f))
                            ) {
                                Column(modifier = Modifier.padding(16.dp)) {
                                    Row(
                                        verticalAlignment = Alignment.CenterVertically
                                    ) {
                                        Box(
                                            modifier = Modifier
                                                .size(40.dp)
                                                .clip(CircleShape)
                                                .background(LingoPrimary.copy(alpha = 0.15f)),
                                            contentAlignment = Alignment.Center
                                        ) {
                                            Text("✨", fontSize = 20.sp)
                                        }
                                        Spacer(modifier = Modifier.width(12.dp))
                                        Column {
                                            Text(
                                                text = "Zaprojektuj Własne Miasto z AI",
                                                fontWeight = FontWeight.Bold,
                                                fontSize = 15.sp,
                                                color = MaterialTheme.colorScheme.onSurface
                                            )
                                            Text(
                                                text = "Wpisz dowolne miasto świata i otrzymaj natychmiast scenariusze oraz zwroty!",
                                                fontSize = 11.sp,
                                                color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.6f)
                                            )
                                        }
                                    }

                                    Spacer(modifier = Modifier.height(14.dp))

                                    OutlinedTextField(
                                        value = inputCity.value,
                                        onValueChange = { inputCity.value = it },
                                        label = { Text(defaultCityHint) },
                                        modifier = Modifier.fillMaxWidth().testTag("city_input_field"),
                                        singleLine = true,
                                        shape = RoundedCornerShape(12.dp)
                                    )

                                    Spacer(modifier = Modifier.height(8.dp))

                                    OutlinedTextField(
                                        value = inputCountry.value,
                                        onValueChange = { inputCountry.value = it },
                                        label = { Text(defaultCountryHint) },
                                        modifier = Modifier.fillMaxWidth().testTag("country_input_field"),
                                        singleLine = true,
                                        shape = RoundedCornerShape(12.dp)
                                    )

                                    Spacer(modifier = Modifier.height(12.dp))

                                    Text("Poziom trudności (CEFR):", fontSize = 12.sp, fontWeight = FontWeight.Bold)
                                    Row(
                                        modifier = Modifier.fillMaxWidth().padding(vertical = 4.dp),
                                        horizontalArrangement = Arrangement.spacedBy(6.dp)
                                    ) {
                                        val levels = listOf("A1", "A2", "B1", "B2", "C1", "C2")
                                        levels.forEach { lvl ->
                                            val isSelected = selectedLevel.value == lvl
                                            FilterChip(
                                                selected = isSelected,
                                                onClick = { selectedLevel.value = lvl },
                                                label = { Text(lvl, fontSize = 11.sp) },
                                                colors = FilterChipDefaults.filterChipColors(
                                                    selectedContainerColor = LingoPrimary,
                                                    selectedLabelColor = Color.White
                                                )
                                            )
                                        }
                                    }

                                    Spacer(modifier = Modifier.height(14.dp))

                                    Button(
                                        onClick = {
                                            if (inputCity.value.isBlank()) {
                                                Toast.makeText(contextObj, "Wpisz nazwę miasta!", Toast.LENGTH_SHORT).show()
                                            } else {
                                                viewModel.generateCityModule(inputCity.value.trim(), inputCountry.value.trim(), selectedLevel.value)
                                            }
                                        },
                                        enabled = !isGenerating,
                                        colors = ButtonDefaults.buttonColors(containerColor = LingoPrimary),
                                        shape = RoundedCornerShape(12.dp),
                                        modifier = Modifier.fillMaxWidth().height(46.dp).testTag("generate_city_module_button")
                                    ) {
                                        if (isGenerating) {
                                            CircularProgressIndicator(color = Color.White, modifier = Modifier.size(20.dp))
                                            Spacer(modifier = Modifier.width(10.dp))
                                            Text("Projektowanie modułu AI...", fontSize = 13.sp)
                                        } else {
                                            Icon(Icons.Default.PlayArrow, contentDescription = null, modifier = Modifier.size(18.dp))
                                            Spacer(modifier = Modifier.width(8.dp))
                                            Text("Stwórz Immersyjny Moduł ✨", fontWeight = FontWeight.Bold, fontSize = 13.sp)
                                        }
                                    }
                                }
                            }

                            // Section 3: Generated AI City Module Output (Structured / Identical to Curated Hubs)
                            if (isGenerating) {
                                Card(
                                    modifier = Modifier.fillMaxWidth().padding(vertical = 8.dp),
                                    shape = RoundedCornerShape(16.dp),
                                    colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surface),
                                    border = BorderStroke(1.dp, MaterialTheme.colorScheme.outlineVariant.copy(alpha = 0.4f))
                                ) {
                                    Box(
                                        modifier = Modifier.fillMaxWidth().padding(vertical = 36.dp),
                                        contentAlignment = Alignment.Center
                                    ) {
                                        Column(horizontalAlignment = Alignment.CenterHorizontally) {
                                            CircularProgressIndicator(color = LingoPrimary)
                                            Spacer(modifier = Modifier.height(14.dp))
                                            Text(
                                                text = "AI tworzy scenariusze i lokalny slang...",
                                                fontSize = 13.sp,
                                                fontWeight = FontWeight.Medium,
                                                color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.7f)
                                            )
                                        }
                                    }
                                }
                            } else if (generatedCityHub != null) {
                                CityHubItemCard(
                                    hub = generatedCityHub,
                                    targetLanguage = currentTargetLang,
                                    onPlayScenario = { scKey, scTitle, _ ->
                                        selectedKey.value = scKey
                                        selectedTitle.value = scTitle
                                        showStressLevelDialog.value = true
                                    },
                                    onAddVocab = { word, trans, ctx ->
                                        viewModel.addCustomVocabulary(word, trans, ctx)
                                    },
                                    speechHelper = speechHelper,
                                    isGeneratedBadge = true,
                                    onClear = { viewModel.clearCityModule() }
                                )
                            } else if (generatedModule != null) {
                                Card(
                                    modifier = Modifier
                                        .fillMaxWidth()
                                        .padding(bottom = 16.dp),
                                    shape = RoundedCornerShape(16.dp),
                                    colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surface),
                                    border = BorderStroke(1.dp, MaterialTheme.colorScheme.outlineVariant.copy(alpha = 0.3f))
                                ) {
                                    Column(modifier = Modifier.padding(16.dp)) {
                                        MarkdownContent(
                                            text = generatedModule,
                                            onAddVocab = { word, trans, explanation ->
                                                viewModel.addCustomVocabulary(word, trans, explanation)
                                                Toast.makeText(contextObj, "Dodano: $word 📚", Toast.LENGTH_SHORT).show()
                                            }
                                        )

                                        Spacer(modifier = Modifier.height(18.dp))

                                        Row(
                                            modifier = Modifier.fillMaxWidth(),
                                            horizontalArrangement = Arrangement.spacedBy(10.dp)
                                        ) {
                                            OutlinedButton(
                                                onClick = { viewModel.clearCityModule() },
                                                shape = RoundedCornerShape(12.dp),
                                                modifier = Modifier.weight(1f)
                                            ) {
                                                Text("Wyczyść 🗑️", fontSize = 12.sp)
                                            }

                                            Button(
                                                onClick = {
                                                    selectedKey.value = "custom_city_" + inputCity.value.trim().lowercase() + "_" + selectedLevel.value.lowercase()
                                                    selectedTitle.value = "${inputCity.value.trim()} (${selectedLevel.value})"
                                                    showStressLevelDialog.value = true
                                                },
                                                colors = ButtonDefaults.buttonColors(containerColor = LingoSecondary),
                                                shape = RoundedCornerShape(12.dp),
                                                modifier = Modifier.weight(1.8f)
                                            ) {
                                                Icon(Icons.Default.PlayArrow, contentDescription = null, modifier = Modifier.size(18.dp))
                                                Spacer(modifier = Modifier.width(6.dp))
                                                Text("Zagraj tę rolę! 🚀", fontWeight = FontWeight.Bold, fontSize = 13.sp)
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }
    }
}

@Composable
fun CityHubItemCard(
    hub: CityHubData,
    targetLanguage: String,
    onPlayScenario: (key: String, title: String, initialPrompt: String) -> Unit,
    onAddVocab: (word: String, trans: String, ctx: String) -> Unit,
    speechHelper: TutorSpeechHelper,
    isGeneratedBadge: Boolean = false,
    onClear: (() -> Unit)? = null
) {
    val cityExpanded = remember { mutableStateOf(isGeneratedBadge) }
    val vocabExpanded = remember { mutableStateOf(isGeneratedBadge) }
    val contextObj = androidx.compose.ui.platform.LocalContext.current

    Card(
        modifier = Modifier.fillMaxWidth(),
        shape = RoundedCornerShape(16.dp),
        colors = CardDefaults.cardColors(
            containerColor = if (isGeneratedBadge) MaterialTheme.colorScheme.primaryContainer.copy(alpha = 0.22f) else MaterialTheme.colorScheme.surface
        ),
        border = BorderStroke(
            if (isGeneratedBadge) 1.5.dp else 1.dp,
            if (isGeneratedBadge) LingoPrimary.copy(alpha = 0.75f) else MaterialTheme.colorScheme.outlineVariant.copy(alpha = 0.45f)
        )
    ) {
        Column(modifier = Modifier.padding(16.dp)) {
            if (isGeneratedBadge) {
                Row(
                    modifier = Modifier
                        .fillMaxWidth()
                        .padding(bottom = 8.dp),
                    horizontalArrangement = Arrangement.SpaceBetween,
                    verticalAlignment = Alignment.CenterVertically
                ) {
                    Surface(
                        color = LingoPrimary,
                        shape = RoundedCornerShape(6.dp)
                    ) {
                        Text(
                            text = "✨ WYGENEROWANY MODUŁ AI",
                            color = Color.White,
                            fontSize = 9.sp,
                            fontWeight = FontWeight.Bold,
                            modifier = Modifier.padding(horizontal = 8.dp, vertical = 3.dp)
                        )
                    }
                    if (onClear != null) {
                        IconButton(
                            onClick = onClear,
                            modifier = Modifier.size(24.dp)
                        ) {
                            Icon(
                                imageVector = Icons.Default.Close,
                                contentDescription = "Wyczyść moduł",
                                tint = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.6f),
                                modifier = Modifier.size(16.dp)
                            )
                        }
                    }
                }
            }

            // Header Row: City Icon, Name, Tagline & Expand Button
            Row(
                modifier = Modifier
                    .fillMaxWidth()
                    .clickable { cityExpanded.value = !cityExpanded.value },
                horizontalArrangement = Arrangement.SpaceBetween,
                verticalAlignment = Alignment.CenterVertically
            ) {
                Row(verticalAlignment = Alignment.CenterVertically, modifier = Modifier.weight(1f)) {
                    Box(
                        modifier = Modifier
                            .size(42.dp)
                            .clip(CircleShape)
                            .background(LingoPrimary.copy(alpha = 0.12f)),
                        contentAlignment = Alignment.Center
                    ) {
                        Text(hub.icon, fontSize = 22.sp)
                    }
                    Spacer(modifier = Modifier.width(12.dp))
                    Column {
                        Row(verticalAlignment = Alignment.CenterVertically) {
                            Text(
                                text = hub.name,
                                fontWeight = FontWeight.Bold,
                                fontSize = 16.sp,
                                color = MaterialTheme.colorScheme.onSurface
                            )
                            if (hub.country.isNotBlank()) {
                                Spacer(modifier = Modifier.width(6.dp))
                                Text(
                                    text = "(${hub.country})",
                                    fontSize = 12.sp,
                                    color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.6f)
                                )
                            }
                        }
                        if (hub.tagline.isNotBlank()) {
                            Text(
                                text = hub.tagline,
                                fontSize = 11.sp,
                                color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.6f),
                                maxLines = 1,
                                overflow = TextOverflow.Ellipsis
                            )
                        }
                    }
                }
                IconButton(
                    onClick = { cityExpanded.value = !cityExpanded.value },
                    modifier = Modifier.size(32.dp)
                ) {
                    Icon(
                        imageVector = if (cityExpanded.value) Icons.Default.KeyboardArrowUp else Icons.Default.KeyboardArrowDown,
                        contentDescription = "Rozwiń",
                        tint = LingoPrimary
                    )
                }
            }

            // Collapsible Content
            if (cityExpanded.value) {
                Spacer(modifier = Modifier.height(12.dp))

                // Description
                if (hub.description.isNotBlank()) {
                    Text(
                        text = hub.description,
                        fontSize = 12.sp,
                        color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.8f),
                        lineHeight = 16.sp
                    )
                    Spacer(modifier = Modifier.height(12.dp))
                }

                // 3 Must-Know Phrases Accordion
                if (hub.keyVocab.isNotEmpty()) {
                    Surface(
                        color = MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.35f),
                        shape = RoundedCornerShape(10.dp),
                        modifier = Modifier
                            .fillMaxWidth()
                            .clickable { vocabExpanded.value = !vocabExpanded.value }
                    ) {
                        Column {
                            Row(
                                modifier = Modifier
                                    .fillMaxWidth()
                                    .padding(horizontal = 10.dp, vertical = 8.dp),
                                horizontalArrangement = Arrangement.SpaceBetween,
                                verticalAlignment = Alignment.CenterVertically
                            ) {
                                Row(verticalAlignment = Alignment.CenterVertically) {
                                    Icon(Icons.Default.Book, contentDescription = null, tint = LingoSecondary, modifier = Modifier.size(15.dp))
                                    Spacer(modifier = Modifier.width(6.dp))
                                    Text("3 Zwroty-Klucze & Slang (${hub.keyVocab.size}) 📚", fontSize = 12.sp, fontWeight = FontWeight.SemiBold, color = LingoSecondary)
                                }
                                Text(if (vocabExpanded.value) "▲" else "▼", fontSize = 10.sp, color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.5f))
                            }

                            if (vocabExpanded.value) {
                                Column(
                                    modifier = Modifier.padding(start = 10.dp, end = 10.dp, bottom = 8.dp),
                                    verticalArrangement = Arrangement.spacedBy(6.dp)
                                ) {
                                    hub.keyVocab.forEach { kv ->
                                        Row(
                                            modifier = Modifier
                                                .fillMaxWidth()
                                                .clip(RoundedCornerShape(8.dp))
                                                .background(MaterialTheme.colorScheme.surface)
                                                .padding(horizontal = 8.dp, vertical = 6.dp),
                                            horizontalArrangement = Arrangement.SpaceBetween,
                                            verticalAlignment = Alignment.CenterVertically
                                        ) {
                                            Column(modifier = Modifier.weight(1f)) {
                                                Text(kv.word, fontWeight = FontWeight.Bold, fontSize = 12.sp, color = LingoPrimary)
                                                Text(kv.translation, fontSize = 11.sp, color = MaterialTheme.colorScheme.onSurface)
                                                if (kv.context.isNotBlank()) {
                                                    Text("\"${kv.context}\"", fontSize = 10.sp, fontStyle = FontStyle.Italic, color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.55f))
                                                }
                                            }
                                            Row(verticalAlignment = Alignment.CenterVertically) {
                                                IconButton(
                                                    onClick = {
                                                        speechHelper.speak(kv.word, targetLanguage, "B1")
                                                    },
                                                    modifier = Modifier.size(32.dp)
                                                ) {
                                                    Icon(Icons.Default.VolumeUp, contentDescription = "Odsłuchaj", tint = LingoSecondary, modifier = Modifier.size(16.dp))
                                                }
                                                IconButton(
                                                    onClick = {
                                                        onAddVocab(kv.word, kv.translation, kv.context)
                                                        Toast.makeText(contextObj, "Dodano: ${kv.word} 📚", Toast.LENGTH_SHORT).show()
                                                    },
                                                    modifier = Modifier.size(32.dp)
                                                ) {
                                                    Icon(Icons.Default.Add, contentDescription = "Dodaj do SRS", tint = LingoPrimary, modifier = Modifier.size(16.dp))
                                                }
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    }

                    Spacer(modifier = Modifier.height(14.dp))
                }

                // Scenarios List for this city
                if (hub.scenarios.isNotEmpty()) {
                    Text(
                        text = "Wybierz scenariusz do odegrania: 🚀",
                        fontSize = 12.sp,
                        fontWeight = FontWeight.Bold,
                        color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.8f)
                    )

                    Spacer(modifier = Modifier.height(6.dp))

                    hub.scenarios.forEach { sc ->
                        Card(
                            modifier = Modifier
                                .fillMaxWidth()
                                .padding(vertical = 4.dp),
                            shape = RoundedCornerShape(10.dp),
                            colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.35f)),
                            border = BorderStroke(1.dp, MaterialTheme.colorScheme.outlineVariant.copy(alpha = 0.3f))
                        ) {
                            Column(modifier = Modifier.padding(10.dp)) {
                                Row(
                                    verticalAlignment = Alignment.CenterVertically,
                                    horizontalArrangement = Arrangement.SpaceBetween,
                                    modifier = Modifier.fillMaxWidth()
                                ) {
                                    Row(verticalAlignment = Alignment.CenterVertically, modifier = Modifier.weight(1f)) {
                                        Text(sc.emoji, fontSize = 16.sp)
                                        Spacer(modifier = Modifier.width(6.dp))
                                        Text(
                                            text = sc.title,
                                            fontWeight = FontWeight.Bold,
                                            fontSize = 13.sp,
                                            color = MaterialTheme.colorScheme.onSurface
                                        )
                                    }
                                    Surface(
                                        color = LingoSecondary.copy(alpha = 0.15f),
                                        shape = RoundedCornerShape(6.dp)
                                    ) {
                                        Text(
                                            text = sc.difficulty,
                                            color = LingoSecondary,
                                            fontSize = 9.sp,
                                            fontWeight = FontWeight.Bold,
                                            modifier = Modifier.padding(horizontal = 6.dp, vertical = 2.dp)
                                        )
                                    }
                                }

                                Spacer(modifier = Modifier.height(4.dp))

                                Text(
                                    text = sc.subtitle,
                                    fontSize = 11.sp,
                                    color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.7f),
                                    lineHeight = 15.sp
                                )

                                Spacer(modifier = Modifier.height(8.dp))

                                Button(
                                    onClick = {
                                        onPlayScenario(sc.key, "${hub.name}: ${sc.title}", sc.initialPrompt)
                                    },
                                    colors = ButtonDefaults.buttonColors(containerColor = LingoPrimary),
                                    shape = RoundedCornerShape(8.dp),
                                    modifier = Modifier
                                        .fillMaxWidth()
                                        .height(36.dp)
                                ) {
                                    Icon(Icons.Default.PlayArrow, contentDescription = null, modifier = Modifier.size(16.dp))
                                    Spacer(modifier = Modifier.width(4.dp))
                                    Text("Zagraj tę rolę! 🚀", fontWeight = FontWeight.Bold, fontSize = 12.sp)
                                }
                            }
                        }
                    }
                }

                if (onClear != null) {
                    Spacer(modifier = Modifier.height(10.dp))
                    OutlinedButton(
                        onClick = onClear,
                        shape = RoundedCornerShape(8.dp),
                        modifier = Modifier.fillMaxWidth().height(36.dp)
                    ) {
                        Text("Wyczyść ten moduł 🗑️", fontSize = 12.sp)
                    }
                }
            }
        }
    }
}

data class FlagshipLesson(
