@Composable
fun StatCard(
    title: String,
    value: String,
    icon: androidx.compose.ui.graphics.vector.ImageVector,
    color: Color,
    modifier: Modifier = Modifier
) {
    Card(
        modifier = modifier,
        shape = RoundedCornerShape(16.dp),
        colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surface),
        elevation = CardDefaults.cardElevation(defaultElevation = 2.dp)
    ) {
        Column(modifier = Modifier.padding(16.dp)) {
            Row(
                verticalAlignment = Alignment.CenterVertically,
                horizontalArrangement = Arrangement.SpaceBetween,
                modifier = Modifier.fillMaxWidth()
            ) {
                Text(
                    text = title,
                    fontSize = 12.sp,
                    fontWeight = FontWeight.SemiBold,
                    color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.6f)
                )
                Icon(icon, contentDescription = null, tint = color, modifier = Modifier.size(18.dp))
            }
            Spacer(modifier = Modifier.height(8.dp))
            Text(
                text = value,
                fontSize = 24.sp,
                fontWeight = FontWeight.Bold,
                color = MaterialTheme.colorScheme.onSurface
            )
        }
    }
}

@Composable
fun ScenarioCard(
    title: String,
    subtitle: String,
    iconText: String,
    difficulty: String,
    onClick: () -> Unit,
    modifier: Modifier = Modifier
) {
    Card(
        modifier = modifier
            .fillMaxWidth()
            .clickable { onClick() },
        shape = RoundedCornerShape(16.dp),
        colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surface),
        elevation = CardDefaults.cardElevation(defaultElevation = 2.dp)
    ) {
        Row(
            modifier = Modifier.padding(16.dp),
            verticalAlignment = Alignment.CenterVertically
        ) {
            Box(
                modifier = Modifier
                    .size(48.dp)
                    .clip(CircleShape)
                    .background(LingoPrimary.copy(alpha = 0.1f)),
                contentAlignment = Alignment.Center
            ) {
                Text(iconText, fontSize = 22.sp)
            }
            Spacer(modifier = Modifier.width(16.dp))
            Column(modifier = Modifier.weight(1f)) {
                Text(
                    text = title,
                    fontWeight = FontWeight.Bold,
                    fontSize = 15.sp,
                    color = MaterialTheme.colorScheme.onSurface
                )
                Text(
                    text = subtitle,
                    fontSize = 12.sp,
                    color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.6f),
                    maxLines = 1,
                    overflow = TextOverflow.Ellipsis
                )
            }
            Spacer(modifier = Modifier.width(8.dp))
            Surface(
                shape = RoundedCornerShape(8.dp),
                color = LingoSecondary.copy(alpha = 0.1f)
            ) {
                Text(
                    text = difficulty,
                    color = LingoSecondary,
                    fontSize = 10.sp,
                    fontWeight = FontWeight.Bold,
                    modifier = Modifier.padding(horizontal = 8.dp, vertical = 4.dp)
                )
            }
        }
    }
}

// ==========================================
// 2. VOCABULARY SCREEN
// ==========================================
@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun VocabularyScreen(
    languageIslands: List<Vocabulary>,
    vocabulary: List<Vocabulary>,
    mistakes: List<Mistake>,
    viewModel: TutorViewModel,
    subTabSelected: MutableState<Int>,
    speechHelper: TutorSpeechHelper
) {
    val context = LocalContext.current
    val coroutineScope = rememberCoroutineScope()
    val query = remember { mutableStateOf("") }
    val showAddDialog = remember { mutableStateOf(false) }
    val showFlashcardOverlay = remember { mutableStateOf(false) }
    val showSrsSetupDialog = remember { mutableStateOf(false) }
    val activeSrsCards = remember { mutableStateOf<List<SrsCard>>(emptyList()) }
    val goal by viewModel.goal.collectAsStateWithLifecycle()

    val filteredList = vocabulary.filter {
        it.word.contains(query.value, ignoreCase = true) ||
                it.translation.contains(query.value, ignoreCase = true)
    }

    val now = System.currentTimeMillis()
    val dueVocab = vocabulary.filter { it.nextReviewTimestamp <= now }
    val dueMistakes = mistakes.filter { !it.isResolved && it.nextReviewTimestamp <= now }
    val totalDue = dueVocab.size + dueMistakes.size

    Box(
        modifier = Modifier.fillMaxSize()
    ) {
        Column(
            modifier = Modifier
                .fillMaxSize()
                .padding(16.dp)
        ) {
            // Header row with title and Add Word button
            Row(
                modifier = Modifier.fillMaxWidth(),
                horizontalArrangement = Arrangement.SpaceBetween,
                verticalAlignment = Alignment.CenterVertically
            ) {
                Column {
                    Text(
                        text = "Vocabulary & Mistakes Bank 📚",
                        fontSize = 22.sp,
                        fontWeight = FontWeight.Black,
                        color = MaterialTheme.colorScheme.onBackground
                    )
                    Text(
                        text = "Słówka: ${vocabulary.size} | Błędy: ${mistakes.size}",
                        fontSize = 13.sp,
                        color = MaterialTheme.colorScheme.onBackground.copy(alpha = 0.6f)
                    )
                }

                Button(
                    onClick = { showAddDialog.value = true },
                    colors = ButtonDefaults.buttonColors(containerColor = LingoPrimary),
                    contentPadding = PaddingValues(horizontal = 12.dp, vertical = 6.dp),
                    modifier = Modifier
                        .height(40.dp)
                        .testTag("add_vocab_btn")
                ) {
                    Icon(Icons.Default.Add, contentDescription = "Add Word", modifier = Modifier.size(16.dp))
                    Spacer(modifier = Modifier.width(4.dp))
                    Text("Add Word", fontSize = 12.sp)
                }
            }

            Spacer(modifier = Modifier.height(16.dp))

            // Sub-tab selection chips (Anki Style list controller)
            Row(
                modifier = Modifier
                    .fillMaxWidth()
                    .padding(bottom = 12.dp)
                    .horizontalScroll(rememberScrollState()),
                horizontalArrangement = Arrangement.spacedBy(8.dp)
            ) {
                FilterChip(
                    selected = subTabSelected.value == 0,
                    onClick = { subTabSelected.value = 0 },
                    label = { Text("📖 Moje Słowa (${vocabulary.size})", maxLines = 1) },
                    colors = FilterChipDefaults.filterChipColors(
                        selectedContainerColor = LingoPrimary.copy(alpha = 0.15f),
                        selectedLabelColor = LingoPrimary
                    )
                )
                FilterChip(
                    selected = subTabSelected.value == 1,
                    onClick = { subTabSelected.value = 1 },
                    label = { Text("⚠️ Moje Błędy (${mistakes.size})", maxLines = 1) },
                    colors = FilterChipDefaults.filterChipColors(
                        selectedContainerColor = LingoStreakOrange.copy(alpha = 0.15f),
                        selectedLabelColor = LingoStreakOrange
                    )
                )
                FilterChip(
                    selected = subTabSelected.value == 2,
                    onClick = { subTabSelected.value = 2 },
                    label = { Text("🏝️ Wyspy (${languageIslands.size})", maxLines = 1) },
                    colors = FilterChipDefaults.filterChipColors(
                        selectedContainerColor = Color(0xFF4CAF50).copy(alpha = 0.15f),
                        selectedLabelColor = Color(0xFF4CAF50)
                    )
                )
            }
            // SRS Hero Training Card
            Card(
                modifier = Modifier
                    .fillMaxWidth()
                    .padding(bottom = 16.dp),
                shape = RoundedCornerShape(20.dp),
                colors = CardDefaults.cardColors(
                    containerColor = if (totalDue > 0) LingoPrimary.copy(alpha = 0.12f) else MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.4f)
                ),
                border = BorderStroke(1.5.dp, if (totalDue > 0) LingoPrimary else MaterialTheme.colorScheme.outline.copy(alpha = 0.2f))
            ) {
                Row(
                    modifier = Modifier.padding(16.dp),
                    verticalAlignment = Alignment.CenterVertically
                ) {
                    Column(modifier = Modifier.weight(1f)) {
                        Row(verticalAlignment = Alignment.CenterVertically) {
                            Text(
                                text = "Centrum Powtórek PRO (SRS)",
                                fontWeight = FontWeight.Bold,
                                fontSize = 16.sp,
                                color = MaterialTheme.colorScheme.onSurface
                            )
                            Spacer(modifier = Modifier.width(6.dp))
                            Surface(
                                shape = RoundedCornerShape(6.dp),
                                color = LingoSecondary
                            ) {
                                Text(
                                    text = "PRO",
                                    fontSize = 9.sp,
                                    fontWeight = FontWeight.Bold,
                                    color = Color.White,
                                    modifier = Modifier.padding(horizontal = 4.dp, vertical = 2.dp)
                                )
                            }
                        }
                        Spacer(modifier = Modifier.height(4.dp))
                        Text(
                            text = if (totalDue > 0) {
                                "Masz dziś $totalDue zaległych powtórek do zrobienia (słówka: ${dueVocab.size}, błędy: ${dueMistakes.size})."
                            } else {
                                "Świetna robota! Wszystkie fiszki i błędy są powtórzone na dziś. Wracaj jutro!"
                            },
                            fontSize = 12.sp,
                            color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.7f),
                            lineHeight = 16.sp
                        )
                    }

                    Spacer(modifier = Modifier.width(12.dp))

                    Button(
                        onClick = { showSrsSetupDialog.value = true },
                        colors = ButtonDefaults.buttonColors(
                            containerColor = if (totalDue > 0) LingoPrimary else MaterialTheme.colorScheme.onSurface.copy(alpha = 0.12f)
                        ),
                        shape = RoundedCornerShape(12.dp),
                        contentPadding = PaddingValues(horizontal = 14.dp, vertical = 8.dp),
                        modifier = Modifier.height(40.dp)
                    ) {
                        Icon(
                            imageVector = if (totalDue > 0) Icons.Default.PlayArrow else Icons.Default.Refresh,
                            contentDescription = "Start Review",
                            tint = if (totalDue > 0) Color.White else MaterialTheme.colorScheme.onSurface,
                            modifier = Modifier.size(18.dp)
                        )
                        Spacer(modifier = Modifier.width(4.dp))
                        Text(
                            text = if (totalDue > 0) "Trenuj" else "Wybierz",
                            fontSize = 12.sp,
                            fontWeight = FontWeight.Bold,
                            color = if (totalDue > 0) Color.White else MaterialTheme.colorScheme.onSurface
                        )
                    }
                }
            }

            if (subTabSelected.value == 0) {
                // --- VOCABULARY SUBTAB ---
                // Search bar
                OutlinedTextField(
                    value = query.value,
                    onValueChange = { query.value = it },
                    placeholder = { Text("Search word or translation...") },
                    leadingIcon = { Icon(Icons.Default.Search, contentDescription = null) },
                    modifier = Modifier
                        .fillMaxWidth()
                        .testTag("vocab_search_input"),
                    shape = RoundedCornerShape(12.dp),
                    colors = OutlinedTextFieldDefaults.colors(
                        focusedBorderColor = LingoPrimary,
                        unfocusedBorderColor = MaterialTheme.colorScheme.outline.copy(alpha = 0.5f)
                    ),
                    singleLine = true
                )

                Spacer(modifier = Modifier.height(16.dp))

                if (filteredList.isEmpty()) {
                    Box(
                        modifier = Modifier
                            .fillMaxWidth()
                            .weight(1f),
                        contentAlignment = Alignment.Center
                    ) {
                        Column(
                            horizontalAlignment = Alignment.CenterHorizontally,
                            modifier = Modifier.padding(32.dp)
                        ) {
                            Icon(
                                Icons.Default.Book,
                                contentDescription = null,
                                tint = MaterialTheme.colorScheme.onBackground.copy(alpha = 0.2f),
                                modifier = Modifier.size(80.dp)
                            )
                            Spacer(modifier = Modifier.height(16.dp))
                            Text(
                                text = "No words here yet",
                                fontWeight = FontWeight.Bold,
                                fontSize = 16.sp,
                                color = MaterialTheme.colorScheme.onBackground.copy(alpha = 0.5f)
                            )
                            Text(
                                text = "Words recommended by Lingo during dialogues will be saved here automatically, or you can add your own!",
                                textAlign = TextAlign.Center,
                                fontSize = 13.sp,
                                color = MaterialTheme.colorScheme.onBackground.copy(alpha = 0.4f),
                                modifier = Modifier.padding(horizontal = 16.dp)
                            )
                        }
                    }
                } else {
                    LazyColumn(
                        modifier = Modifier.weight(1f),
                        verticalArrangement = Arrangement.spacedBy(10.dp)
                    ) {
                        items(filteredList, key = { it.id }) { vocab ->
                            VocabItemRow(vocab = vocab, viewModel = viewModel, speechHelper = speechHelper)
                        }
                    }
                }
            } else if (subTabSelected.value == 1) {
                // --- MISTAKES SUBTAB ---
                LazyColumn(
                    modifier = Modifier
                        .fillMaxWidth()
                        .weight(1f),
                    verticalArrangement = Arrangement.spacedBy(12.dp)
                ) {
                    if (mistakes.isEmpty()) {
                        item {
                            Box(
                                modifier = Modifier
                                    .fillMaxWidth()
                                    .padding(40.dp),
                                contentAlignment = Alignment.Center
                            ) {
                                Column(horizontalAlignment = Alignment.CenterHorizontally) {
                                    Text("🎉", fontSize = 48.sp)
                                    Spacer(modifier = Modifier.height(12.dp))
                                    Text(
                                        text = "Brak błędów! Gratulacje!",
                                        fontWeight = FontWeight.Bold,
                                        fontSize = 16.sp,
                                        color = MaterialTheme.colorScheme.onBackground
                                    )
                                    Text(
                                        text = "Wszystkie błędy z sesji z tutorem zostały rozwiązane.",
                                        fontSize = 12.sp,
                                        color = MaterialTheme.colorScheme.onBackground.copy(alpha = 0.6f),
                                        textAlign = TextAlign.Center
                                    )
                                }
                            }
                        }
                    } else {
                        items(mistakes.size) { index ->
                            val m = mistakes[index]

                            var translatedText by remember(m.id) { mutableStateOf<String?>(null) }
                            var isTranslating by remember(m.id) { mutableStateOf(false) }

                            Card(
                                modifier = Modifier.fillMaxWidth(),
                                shape = RoundedCornerShape(16.dp),
                                colors = CardDefaults.cardColors(
                                    containerColor = if (m.isResolved) LingoSuccessGreen.copy(alpha = 0.05f) else LingoStreakOrange.copy(alpha = 0.05f)
                                ),
                                border = BorderStroke(
                                    1.dp,
                                    if (m.isResolved) LingoSuccessGreen.copy(alpha = 0.2f) else LingoStreakOrange.copy(alpha = 0.2f)
                                )
                            ) {
                                Column(modifier = Modifier.padding(16.dp)) {
                                    Row(
                                        modifier = Modifier.fillMaxWidth(),
                                        horizontalArrangement = Arrangement.SpaceBetween,
                                        verticalAlignment = Alignment.CenterVertically
                                    ) {
                                        Row(horizontalArrangement = Arrangement.spacedBy(6.dp)) {
                                            Surface(
                                                shape = RoundedCornerShape(6.dp),
                                                color = LingoStreakOrange.copy(alpha = 0.15f)
                                            ) {
                                                Text(
                                                    text = m.type.uppercase(),
                                                    fontSize = 9.sp,
                                                    fontWeight = FontWeight.Black,
                                                    color = LingoStreakOrange,
                                                    modifier = Modifier.padding(horizontal = 6.dp, vertical = 2.dp)
                                                )
                                            }
                                            Surface(
                                                shape = RoundedCornerShape(6.dp),
                                                color = if (m.isResolved) LingoSuccessGreen.copy(alpha = 0.15f) else Color.Gray.copy(alpha = 0.15f)
                                            ) {
                                                Text(
                                                    text = if (m.isResolved) "ROZWIĄZANE" else "DO NAUKI",
                                                    fontSize = 9.sp,
                                                    fontWeight = FontWeight.Black,
                                                    color = if (m.isResolved) LingoSuccessGreen else Color.Gray,
                                                    modifier = Modifier.padding(horizontal = 6.dp, vertical = 2.dp)
                                                )
                                            }
                                        }

                                        Row(
                                            verticalAlignment = Alignment.CenterVertically,
                                            horizontalArrangement = Arrangement.spacedBy(8.dp)
                                        ) {
                                            IconButton(
                                                onClick = { viewModel.resolveMistake(m) },
                                                modifier = Modifier.size(24.dp)
                                            ) {
                                                Icon(
                                                    imageVector = if (m.isResolved) Icons.Default.CheckCircle else Icons.Default.Circle,
                                                    contentDescription = "Toggle resolved",
                                                    tint = if (m.isResolved) LingoSuccessGreen else Color.Gray,
                                                    modifier = Modifier.size(20.dp)
                                                )
                                            }

                                            IconButton(
                                                onClick = { viewModel.deleteMistake(m.id) },
                                                modifier = Modifier.size(24.dp)
                                            ) {
                                                Icon(
                                                    imageVector = Icons.Default.Delete,
                                                    contentDescription = "Delete sentence",
                                                    tint = LingoErrorRed.copy(alpha = 0.6f),
                                                    modifier = Modifier.size(20.dp)
                                                )
                                            }
                                        }
                                    }

                                    Spacer(modifier = Modifier.height(12.dp))

                                    // Corrected Sentence (Styled cleanly without crosses or markers as a main sentence)
                                    Text(
                                        text = m.correctedSentence,
                                        fontSize = 16.sp,
                                        fontWeight = FontWeight.Bold,
                                        color = MaterialTheme.colorScheme.onSurface
                                    )

                                    Spacer(modifier = Modifier.height(10.dp))

                                    // Explanation Row
                                    Text(
                                        text = "Wyjaśnienie:",
                                        fontSize = 11.sp,
                                        fontWeight = FontWeight.Bold,
                                        color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.5f)
                                    )
                                    Spacer(modifier = Modifier.height(4.dp))
                                    Text(
                                        text = m.explanation,
                                        fontSize = 12.sp,
                                        color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.8f)
                                    )

                                    if (translatedText != null) {
                                        Spacer(modifier = Modifier.height(8.dp))
                                        Text(
                                            text = "Wyjaśnienie po polsku (AI):",
                                            fontSize = 11.sp,
                                            fontWeight = FontWeight.Bold,
                                            color = LingoPrimary
                                        )
                                        Spacer(modifier = Modifier.height(4.dp))
                                        Text(
                                            text = translatedText!!,
                                            fontSize = 12.sp,
                                            color = MaterialTheme.colorScheme.onSurface,
                                            fontStyle = FontStyle.Italic
                                        )
                                    }

                                    Spacer(modifier = Modifier.height(12.dp))

                                    Row(
                                        modifier = Modifier.fillMaxWidth(),
                                        horizontalArrangement = Arrangement.SpaceBetween,
                                        verticalAlignment = Alignment.CenterVertically
                                    ) {
                                        Text(
                                            text = "Kolejna powtórka: ${m.nextReviewTimestamp.let {
                                                val diff = it - System.currentTimeMillis()
                                                if (diff <= 0) "Teraz" else "${(diff / (24 * 60 * 60 * 1000L)) + 1} dni"
                                            }}",
                                            fontSize = 10.sp,
                                            color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.4f)
                                        )

                                        if (translatedText == null) {
                                            TextButton(
                                                onClick = {
                                                    if (!isTranslating) {
                                                        isTranslating = true
                                                        coroutineScope.launch {
                                                            val trans = com.example.data.api.TutorAiService.translateMistakeToPolish(m.correctedSentence, m.explanation)
                                                            translatedText = trans?.translatedExplanation ?: "Błąd tłumaczenia"
                                                            isTranslating = false
                                                        }
                                                    }
                                                },
                                                contentPadding = PaddingValues(0.dp),
                                                modifier = Modifier.height(24.dp)
                                            ) {
                                                if (isTranslating) {
                                                    CircularProgressIndicator(modifier = Modifier.size(12.dp), strokeWidth = 1.5.dp)
                                                } else {
                                                    Text("Tłumacz na polski 🇵🇱", fontSize = 11.sp, color = LingoPrimary)
                                                }
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
            } else if (subTabSelected.value == 2) {
                // --- LANGUAGE ISLANDS SUBTAB ---
                LazyColumn(
                    modifier = Modifier.fillMaxWidth().weight(1f),
                    verticalArrangement = Arrangement.spacedBy(10.dp)
                ) {
                    if (languageIslands.isEmpty()) {
                        item {
                            Box(modifier = Modifier.fillMaxWidth().padding(32.dp), contentAlignment = Alignment.Center) {
                                Text("Brak zapisanych Wysp Językowych.", color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.5f))
                            }
                        }
                    } else {
                        items(languageIslands, key = { it.id }) { island ->
                            IslandItemCard(vocab = island, viewModel = viewModel, speechHelper = speechHelper)
                        }
                    }
                }
            }
        }

        // Overlay is inside the parent Box, which overlays on top of the list nicely!
                if (showFlashcardOverlay.value && activeSrsCards.value.isNotEmpty()) {
            FlashcardsOverlay(
                cards = activeSrsCards.value,
                onDismiss = { showFlashcardOverlay.value = false },
                viewModel = viewModel,
                speechHelper = speechHelper
            )
        }
    }

    if (showSrsSetupDialog.value) {
        AlertDialog(
            onDismissRequest = { showSrsSetupDialog.value = false },
            title = {
                Row(verticalAlignment = Alignment.CenterVertically) {
                    Icon(
                        imageVector = Icons.Default.Star,
                        contentDescription = null,
                        tint = LingoPrimary,
                        modifier = Modifier.size(24.dp)
                    )
                    Spacer(modifier = Modifier.width(8.dp))
                    Text("Inteligentne Powtórki PRO", fontWeight = FontWeight.Bold, fontSize = 18.sp)
                }
            },
            text = {
                Column(verticalArrangement = Arrangement.spacedBy(12.dp)) {
                    Text(
                        text = "Wybierz tryb treningu Spaced Repetition (SRS), aby utrwalić wiedzę w pamięci długotrwałej.",
                        fontSize = 13.sp,
                        color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.7f)
                    )

                    // Session Option 1: Due Items (Recommended)
                    Card(
                        modifier = Modifier
                            .fillMaxWidth()
                            .clickable {
                                val cards = mutableListOf<SrsCard>()
                                dueVocab.forEach { v ->
                                    cards.add(SrsCard(v.id, true, v.word, v.translation, "Słówko (${v.language})", v.sentenceContext, v.language, v.masteryLevel, v.nextReviewTimestamp, v, v.language_code, v.last_response_latency_ms, v.interference_tag))
                                }
                                dueMistakes.forEach { m ->
                                    cards.add(SrsCard(m.id, false, m.originalSentence, m.correctedSentence, "Popraw błąd (${m.type})", m.explanation, goal?.targetLanguage ?: "Spanish", if (m.isResolved) 2 else m.repetitions, m.nextReviewTimestamp, m, m.language_code, m.last_response_latency_ms, m.interference_tag))
                                }
                                activeSrsCards.value = cards.shuffled()
                                showSrsSetupDialog.value = false
                                showFlashcardOverlay.value = true
                            },
                        colors = CardDefaults.cardColors(
                            containerColor = if (totalDue > 0) LingoPrimary.copy(alpha = 0.08f) else MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.3f)
                        ),
                        border = BorderStroke(1.dp, if (totalDue > 0) LingoPrimary.copy(alpha = 0.3f) else Color.Transparent)
                    ) {
                        Row(
                            modifier = Modifier.padding(12.dp),
                            verticalAlignment = Alignment.CenterVertically
                        ) {
                            Box(
                                modifier = Modifier
                                    .size(36.dp)
                                    .clip(CircleShape)
                                    .background(if (totalDue > 0) LingoPrimary else Color.Gray.copy(alpha = 0.3f)),
                                contentAlignment = Alignment.Center
                            ) {
                                Icon(Icons.Default.PlayArrow, contentDescription = null, tint = Color.White, modifier = Modifier.size(20.dp))
                            }
                            Spacer(modifier = Modifier.width(12.dp))
                            Column(modifier = Modifier.weight(1f)) {
                                Text("Zaplanowane na dziś (SRS)", fontWeight = FontWeight.Bold, fontSize = 14.sp)
                                Text("Słówka: ${dueVocab.size} | Błędy: ${dueMistakes.size}", fontSize = 12.sp, color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.6f))
                            }
                            if (totalDue > 0) {
                                Badge(containerColor = LingoPrimary) {
                                    Text("$totalDue", color = Color.White, fontSize = 10.sp, fontWeight = FontWeight.Bold, modifier = Modifier.padding(horizontal = 4.dp))
                                }
                            }
                        }
                    }

                    // Session Option 2: All Vocabulary
                    Card(
                        modifier = Modifier
                            .fillMaxWidth()
                            .clickable(enabled = vocabulary.isNotEmpty()) {
                                val cards = vocabulary.map { v ->
                                    SrsCard(v.id, true, v.word, v.translation, "Słówko (${v.language})", v.sentenceContext, v.language, v.masteryLevel, v.nextReviewTimestamp, v, v.language_code, v.last_response_latency_ms, v.interference_tag)
                                }.shuffled()
                                activeSrsCards.value = cards
                                showSrsSetupDialog.value = false
                                showFlashcardOverlay.value = true
                            },
                        colors = CardDefaults.cardColors(
                            containerColor = MaterialTheme.colorScheme.surface
                        ),
                        border = BorderStroke(1.dp, MaterialTheme.colorScheme.outline.copy(alpha = 0.2f))
                    ) {
                        Row(
                            modifier = Modifier.padding(12.dp),
                            verticalAlignment = Alignment.CenterVertically
                        ) {
                            Box(
                                modifier = Modifier
                                    .size(36.dp)
                                    .clip(CircleShape)
                                    .background(LingoSecondary.copy(alpha = 0.15f)),
                                contentAlignment = Alignment.Center
                            ) {
                                Icon(Icons.Default.Book, contentDescription = null, tint = LingoSecondary, modifier = Modifier.size(18.dp))
                            }
                            Spacer(modifier = Modifier.width(12.dp))
                            Column(modifier = Modifier.weight(1f)) {
                                Text("Wszystkie Słówka", fontWeight = FontWeight.Bold, fontSize = 14.sp)
                                Text("Przejrzyj cały swój słownik (${vocabulary.size} słówek)", fontSize = 11.sp, color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.5f))
                            }
                        }
                    }

                    // Session Option 3: All Mistakes
                    Card(
                        modifier = Modifier
                            .fillMaxWidth()
                            .clickable(enabled = mistakes.isNotEmpty()) {
                                val cards = mistakes.map { m ->
                                    SrsCard(m.id, false, m.originalSentence, m.correctedSentence, "Popraw błąd (${m.type})", m.explanation, goal?.targetLanguage ?: "Spanish", if (m.isResolved) 2 else m.repetitions, m.nextReviewTimestamp, m, m.language_code, m.last_response_latency_ms, m.interference_tag)
                                }.shuffled()
                                activeSrsCards.value = cards
                                showSrsSetupDialog.value = false
                                showFlashcardOverlay.value = true
                            },
                        colors = CardDefaults.cardColors(
                            containerColor = MaterialTheme.colorScheme.surface
                        ),
                        border = BorderStroke(1.dp, MaterialTheme.colorScheme.outline.copy(alpha = 0.2f))
                    ) {
                        Row(
                            modifier = Modifier.padding(12.dp),
                            verticalAlignment = Alignment.CenterVertically
                        ) {
                            Box(
                                modifier = Modifier
                                    .size(36.dp)
                                    .clip(CircleShape)
                                    .background(LingoStreakOrange.copy(alpha = 0.15f)),
                                contentAlignment = Alignment.Center
                            ) {
                                Icon(Icons.Default.Error, contentDescription = null, tint = LingoStreakOrange, modifier = Modifier.size(18.dp))
                            }
                            Spacer(modifier = Modifier.width(12.dp))
                            Column(modifier = Modifier.weight(1f)) {
                                Text("Wszystkie Błędy", fontWeight = FontWeight.Bold, fontSize = 14.sp)
                                Text("Przećwicz wszystkie błędy z sesji (${mistakes.size} błędów)", fontSize = 11.sp, color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.5f))
                            }
                        }
                    }
                }
            },
            confirmButton = {
                TextButton(onClick = { showSrsSetupDialog.value = false }) {
                    Text("Anuluj", color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.6f))
                }
            }
        )
    }

    // Manual word input dialog
    if (showAddDialog.value) {
        var word by remember { mutableStateOf("") }
        var translation by remember { mutableStateOf("") }
        var sentenceContext by remember { mutableStateOf("") }

        AlertDialog(
            onDismissRequest = { showAddDialog.value = false },
            title = { Text("Add Custom Word", fontWeight = FontWeight.Bold) },
            text = {
                Column(verticalArrangement = Arrangement.spacedBy(12.dp)) {
                    OutlinedTextField(
                        value = word,
                        onValueChange = { word = it },
                        label = { Text("Word/Phrase") },
                        modifier = Modifier
                            .fillMaxWidth()
                            .testTag("vocab_word_input"),
                        singleLine = true
                    )
                    OutlinedTextField(
                        value = translation,
                        onValueChange = { translation = it },
                        label = { Text("English Translation") },
                        modifier = Modifier
                            .fillMaxWidth()
                            .testTag("vocab_trans_input"),
                        singleLine = true
                    )
                    OutlinedTextField(
                        value = sentenceContext,
                        onValueChange = { sentenceContext = it },
                        label = { Text("Example Sentence (Context)") },
                        modifier = Modifier
                            .fillMaxWidth()
                            .testTag("vocab_context_input"),
                        maxLines = 2
                    )
                }
            },
            confirmButton = {
                Button(
                    onClick = {
                        if (word.isNotBlank() && translation.isNotBlank()) {
                            viewModel.addCustomVocabulary(word, translation, sentenceContext)
                            showAddDialog.value = false
                        } else {
                            Toast.makeText(context, "Please fill in both Word and Translation", Toast.LENGTH_SHORT).show()
                        }
                    },
                    colors = ButtonDefaults.buttonColors(containerColor = LingoPrimary),
                    modifier = Modifier.testTag("vocab_save_btn")
                ) {
                    Text("Save")
                }
            },
            dismissButton = {
                TextButton(onClick = { showAddDialog.value = false }) {
                    Text("Cancel")
                }
            }
        )
    }
}

@Composable
fun IslandItemCard(vocab: Vocabulary, viewModel: TutorViewModel, speechHelper: TutorSpeechHelper) {
    var expanded by remember { mutableStateOf(false) }

    val ctxLines = vocab.sentenceContext.lines()
    val buzanAnchor = ctxLines.firstOrNull { it.startsWith("Hak Buzana:") }?.substringAfter("Hak Buzana:")?.trim() ?: "Brak haka"
    val branchLines = ctxLines.filter { it.trim().startsWith("•") }

    Card(
        modifier = Modifier
            .fillMaxWidth()
            .clickable { expanded = !expanded },
        colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surface),
        shape = RoundedCornerShape(16.dp),
        border = BorderStroke(1.dp, MaterialTheme.colorScheme.outline.copy(alpha = 0.1f)),
        elevation = CardDefaults.cardElevation(defaultElevation = 2.dp)
    ) {
        Column(modifier = Modifier.padding(16.dp)) {
            // Hak Buzana banner
            Surface(
                color = Color(0xFFFFF3E0),
                shape = RoundedCornerShape(8.dp),
                modifier = Modifier.fillMaxWidth().padding(bottom = 12.dp)
            ) {
                Row(
                    modifier = Modifier.padding(horizontal = 12.dp, vertical = 8.dp),
                    verticalAlignment = Alignment.CenterVertically
                ) {
                    Text("🧠", fontSize = 16.sp)
                    Spacer(modifier = Modifier.width(8.dp))
                    Text(
                        text = "Hak Buzana: $buzanAnchor",
                        fontSize = 13.sp,
                        fontWeight = FontWeight.SemiBold,
                        color = Color(0xFFE65100)
                    )
                }
            }

            // Rdzeń Quinna
            Row(
                verticalAlignment = Alignment.CenterVertically,
                horizontalArrangement = Arrangement.SpaceBetween,
                modifier = Modifier.fillMaxWidth()
            ) {
                Column(modifier = Modifier.weight(1f)) {
                    Text(
                        text = "🟡 ${vocab.word}",
                        fontWeight = FontWeight.Bold,
                        fontSize = 18.sp,
                        color = MaterialTheme.colorScheme.onSurface
                    )
                    Spacer(modifier = Modifier.height(4.dp))
                    Text(
                        text = vocab.translation,
                        fontSize = 14.sp,
                        color = MaterialTheme.colorScheme.onSurfaceVariant
                    )
                }
                IconButton(
                    onClick = { speechHelper.speak(vocab.word, vocab.language, "B1") },
                    modifier = Modifier.size(40.dp)
                ) {
                    Icon(
                        imageVector = Icons.Default.VolumeUp,
                        contentDescription = "Słuchaj",
                        tint = LingoPrimary,
                        modifier = Modifier.size(24.dp)
                    )
                }
                
                IconButton(
                    onClick = { viewModel.deleteVocabulary(vocab.id) },
                    modifier = Modifier.size(40.dp)
                ) {
                    Icon(
                        Icons.Default.Delete,
                        contentDescription = "Usuń",
                        tint = LingoErrorRed.copy(alpha = 0.6f),
                        modifier = Modifier.size(24.dp)
                    )
                }
            }

            AnimatedVisibility(visible = expanded) {
                Column(modifier = Modifier.fillMaxWidth().padding(top = 16.dp)) {
                    HorizontalDivider(color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.05f))
                    Spacer(modifier = Modifier.height(12.dp))
                    
                    Text(
                        text = "🌿 Gałęzie (Kontekst):",
                        fontWeight = FontWeight.Bold,
                        fontSize = 13.sp,
                        color = MaterialTheme.colorScheme.primary,
                        modifier = Modifier.padding(bottom = 8.dp)
                    )

                    branchLines.forEach { line ->
                        val cleanLine = line.trim().removePrefix("•").trim()
                        val foreignText = cleanLine.substringBefore(" (").trim()
                        
                        Row(
                            modifier = Modifier
                                .fillMaxWidth()
                                .padding(vertical = 4.dp),
                            verticalAlignment = Alignment.Top
                        ) {
                            Text("•", color = MaterialTheme.colorScheme.primary, modifier = Modifier.padding(end = 8.dp))
                            Column(modifier = Modifier.weight(1f)) {
                                Text(
                                    text = cleanLine,
                                    fontSize = 13.sp,
                                    color = MaterialTheme.colorScheme.onSurface
                                )
                            }
                            IconButton(
                                onClick = { 
                                    val combinedText = fullCleanSentence(vocab.word, foreignText)
                                    speechHelper.speak(combinedText, vocab.language, "B1") 
                                },
                                modifier = Modifier.size(24.dp).padding(start = 4.dp)
                            ) {
                                Icon(
                                    imageVector = Icons.Default.VolumeUp,
                                    contentDescription = "Słuchaj gałęzi",
                                    tint = LingoPrimary,
                                    modifier = Modifier.size(18.dp)
                                )
                            }
                        }
                    }
                    
                    if (vocab.polishContextTranslation.isNotBlank()) {
                        Spacer(modifier = Modifier.height(12.dp))
                        Surface(
                            color = MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.5f),
                            shape = RoundedCornerShape(8.dp),
                            modifier = Modifier.fillMaxWidth()
                        ) {
                            Text(
                                text = "💡 Wyjaśnienie AI:\n${vocab.polishContextTranslation}",
                                fontSize = 12.sp,
                                fontStyle = FontStyle.Italic,
                                modifier = Modifier.padding(12.dp),
                                color = MaterialTheme.colorScheme.onSurfaceVariant
                            )
                        }
                    }
                }
            }
        }
    }
}

@Composable
fun VocabItemRow(vocab: Vocabulary, viewModel: TutorViewModel, speechHelper: TutorSpeechHelper) {
    var expanded by remember { mutableStateOf(false) }
    val coroutineScope = rememberCoroutineScope()

    Card(
        modifier = Modifier
            .fillMaxWidth()
            .clickable { expanded = !expanded },
        colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surface),
        shape = RoundedCornerShape(16.dp),
        elevation = CardDefaults.cardElevation(defaultElevation = 1.dp)
    ) {
        Column(modifier = Modifier.padding(16.dp)) {
            Row(
                verticalAlignment = Alignment.CenterVertically,
                horizontalArrangement = Arrangement.SpaceBetween,
                modifier = Modifier.fillMaxWidth()
            ) {
                Column(modifier = Modifier.weight(1f)) {
                    Row(
                        verticalAlignment = Alignment.CenterVertically,
                        horizontalArrangement = Arrangement.spacedBy(6.dp)
                    ) {
                        Text(
                            text = vocab.word,
                            fontWeight = FontWeight.Bold,
                            fontSize = 16.sp,
                            color = MaterialTheme.colorScheme.onSurface
                        )
                        IconButton(
                            onClick = { speechHelper.speak(vocab.word, vocab.language, "B1") },
                            modifier = Modifier.size(24.dp)
                        ) {
                            Icon(
                                imageVector = Icons.Default.VolumeUp,
                                contentDescription = "Słuchaj słówka",
                                tint = LingoPrimary,
                                modifier = Modifier.size(16.dp)
                            )
                        }
                    }
                    Text(
                        text = vocab.translation,
                        fontSize = 13.sp,
                        color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.6f)
                    )
                }

                Row(
                    verticalAlignment = Alignment.CenterVertically,
                    horizontalArrangement = Arrangement.spacedBy(12.dp)
                ) {
                    // Mastery level badge dot
                    val masteryColor = when (vocab.masteryLevel) {
                        1 -> LingoSecondaryLight // Learning
                        2 -> LingoSuccessGreen // Mastered
                        else -> LingoGold // New
                    }
                    val masteryLabel = when (vocab.masteryLevel) {
                        1 -> "Learning"
                        2 -> "Mastered"
                        else -> "New"
                    }

                    Surface(
                        shape = RoundedCornerShape(12.dp),
                        color = masteryColor.copy(alpha = 0.15f),
                        modifier = Modifier.clickable { viewModel.toggleVocabMastery(vocab) }
                    ) {
                        Row(
                            verticalAlignment = Alignment.CenterVertically,
                            modifier = Modifier.padding(horizontal = 10.dp, vertical = 4.dp)
                        ) {
                            Box(
                                modifier = Modifier
                                    .size(6.dp)
                                    .clip(CircleShape)
                                    .background(masteryColor)
                            )
                            Spacer(modifier = Modifier.width(6.dp))
                            Text(
                                text = masteryLabel,
                                fontSize = 10.sp,
                                fontWeight = FontWeight.Bold,
                                color = masteryColor
                            )
                        }
                    }

                    IconButton(
                        onClick = { viewModel.deleteVocabulary(vocab.id) },
                        modifier = Modifier.size(36.dp)
                    ) {
                        Icon(
                            Icons.Default.Delete,
                            contentDescription = "Delete Word",
                            tint = LingoErrorRed.copy(alpha = 0.6f),
                            modifier = Modifier.size(18.dp)
                        )
                    }
                }
            }

            if (expanded) {
                Spacer(modifier = Modifier.height(10.dp))
                Divider(color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.05f))
                Spacer(modifier = Modifier.height(8.dp))

                // Automatically trigger persistent translation in background if blank
                LaunchedEffect(expanded) {
                    if (expanded) {
                        viewModel.autoTranslateVocabulary(vocab)
                    }
                }

                if (vocab.sentenceContext.isNotBlank()) {
                    Row(
                        verticalAlignment = Alignment.CenterVertically,
                        horizontalArrangement = Arrangement.SpaceBetween,
                        modifier = Modifier.fillMaxWidth()
                    ) {
                        Column(modifier = Modifier.weight(1f)) {
                            Text(
                                text = "Kontekst (Context):",
                                fontWeight = FontWeight.SemiBold,
                                fontSize = 11.sp,
                                color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.5f)
                            )
                            Text(
                                text = vocab.sentenceContext,
                                fontSize = 13.sp,
                                color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.8f)
                            )
                        }
                        IconButton(
                            onClick = { speechHelper.speak(vocab.sentenceContext, vocab.language, "B1") },
                            modifier = Modifier.size(32.dp)
                        ) {
                            Icon(
                                imageVector = Icons.Default.VolumeUp,
                                contentDescription = "Słuchaj zdania",
                                tint = LingoPrimary,
                                modifier = Modifier.size(18.dp)
                            )
                        }
                    }
                }

                val hasTranslatedWord = vocab.polishWordTranslation.isNotBlank()
                val hasTranslatedCtx = vocab.polishContextTranslation.isNotBlank() || vocab.sentenceContext.isBlank()

                if (hasTranslatedWord && hasTranslatedCtx) {
                    Spacer(modifier = Modifier.height(10.dp))
                    Text(
                        text = "Tłumaczenie po polsku 🇵🇱:",
                        fontWeight = FontWeight.Bold,
                        fontSize = 11.sp,
                        color = LingoPrimary
                    )
                    if (vocab.polishWordTranslation.isNotBlank()) {
                        Text(
                            text = "Słówko: ${vocab.polishWordTranslation}",
                            fontSize = 13.sp,
                            fontWeight = FontWeight.Bold,
                            color = MaterialTheme.colorScheme.onSurface
                        )
                    }
                    if (vocab.sentenceContext.isNotBlank() && vocab.polishContextTranslation.isNotBlank()) {
                        Text(
                            text = "Zdanie: \"${vocab.polishContextTranslation}\"",
                            fontSize = 12.sp,
                            fontStyle = FontStyle.Italic,
                            color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.8f)
                        )
                    }
                } else {
                    Spacer(modifier = Modifier.height(10.dp))
                    Row(
                        verticalAlignment = Alignment.CenterVertically,
                        horizontalArrangement = Arrangement.spacedBy(8.dp)
                    ) {
                        CircularProgressIndicator(modifier = Modifier.size(12.dp), strokeWidth = 1.5.dp, color = LingoPrimary)
                        Text("Trwa automatyczne tłumaczenie na polski...", fontSize = 11.sp, color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.5f))
                    }
                }
            }
        }
    }
}

// Interactive Flashcards game Overlay
@Composable
fun FlashcardsOverlay(
    cards: List<SrsCard>,
    onDismiss: () -> Unit,
    viewModel: TutorViewModel,
    speechHelper: TutorSpeechHelper
) {
    val currentIndex = remember { mutableStateOf(0) }
    val isFlipped = remember(currentIndex.value) { mutableStateOf(false) }
    val mnemonics by viewModel.allMnemonics.collectAsStateWithLifecycle(emptyList())
    val coroutineScope = rememberCoroutineScope()

    // Timing state for user response latency profiling
    val revealTime = remember(currentIndex.value) { mutableStateOf(0L) }
    LaunchedEffect(isFlipped.value) {
        if (isFlipped.value) {
            revealTime.value = System.currentTimeMillis()
        }
    }

    if (currentIndex.value >= cards.size) {
        // Game complete
        AlertDialog(
            onDismissRequest = onDismiss,
            title = { Text("Trening zakończony!", fontWeight = FontWeight.Bold, color = MaterialTheme.colorScheme.onSurface) },
            text = { Text("Świetna robota! Wszystkie zaplanowane fiszki i błędy zostały powtórzone.", fontSize = 14.sp, color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.8f)) },
            confirmButton = {
                Button(onClick = onDismiss, colors = ButtonDefaults.buttonColors(containerColor = LingoPrimary)) {
                    Text("Super", color = Color.White)
                }
            }
        )
        return
    }

    val card = cards[currentIndex.value]
    val targetFlag = when (card.language_code.lowercase()) {
        "english", "angielski" -> "🇬🇧"
        "spanish", "hiszpański" -> "🇪🇸"
        "german", "niemiecki" -> "🇩🇪"
        "french", "francuski" -> "🇫🇷"
        "italian", "włoski" -> "🇮🇹"
        "polish", "polski" -> "🇵🇱"
        else -> "🌍"
    }

    // Asynchronous translation states
    var vocabWordPl by remember(currentIndex.value) { mutableStateOf<String?>(null) }
    var isTranslatingVocabWord by remember(currentIndex.value) { mutableStateOf(false) }

    var contextPl by remember(currentIndex.value) { mutableStateOf<String?>(null) }
    var isTranslatingContext by remember(currentIndex.value) { mutableStateOf(false) }

    var mistakePl by remember(currentIndex.value) { mutableStateOf<com.example.data.api.MistakeTranslationResponse?>(null) }
    var isTranslatingMistake by remember(currentIndex.value) { mutableStateOf(false) }

    // Variable-Context Dynamic SRS states
    var dynamicContext by remember(currentIndex.value) { mutableStateOf<com.example.data.api.DynamicContextResponse?>(null) }
    var isGeneratingDynamicContext by remember(currentIndex.value) { mutableStateOf(false) }

    // Launch translation eagerly as soon as the card changes
    LaunchedEffect(currentIndex.value) {
        if (card.isVocabulary) {
            val v = card.rawObject as? Vocabulary
            val lang = v?.language ?: "Spanish"

            // 1. Word translation
            if (v != null && v.polishWordTranslation.isNotBlank()) {
                vocabWordPl = v.polishWordTranslation
            } else {
                if (vocabWordPl == null && !isTranslatingVocabWord) {
                    isTranslatingVocabWord = true
                    try {
                        val translated = com.example.data.api.TutorAiService.translateSentenceToPolish(card.front, lang)
                        vocabWordPl = translated
                        v?.let {
                            viewModel.updateVocabulary(it.copy(polishWordTranslation = translated))
                        }
                    } catch (e: Exception) {
                        vocabWordPl = card.back
                    }
                    isTranslatingVocabWord = false
                }
            }

            // 2. Context translation
            if (card.hint.isNotBlank() && contextPl == null && !isTranslatingContext) {
                isTranslatingContext = true
                if (v != null && v.polishContextTranslation.isNotBlank()) {
                    contextPl = v.polishContextTranslation
                } else {
                    try {
                        val translatedCtx = com.example.data.api.TutorAiService.translateSentenceToPolish(card.hint, lang)
                        contextPl = translatedCtx
                        v?.let {
                            viewModel.updateVocabulary(it.copy(polishContextTranslation = translatedCtx))
                        }
                    } catch (e: Exception) {
                        contextPl = "Brak tłumaczenia kontekstu"
                    }
                }
                isTranslatingContext = false
            }

            // 3. Dynamic context generation (Variable-Context Dynamic SRS)
            if (v != null && !isGeneratingDynamicContext) {
                isGeneratingDynamicContext = true
                try {
                    val res = com.example.data.api.TutorAiService.generateDynamicSrsContext(
                        word = card.front,
                        translation = card.back,
                        language = lang,
                        currentContext = card.hint
                    )
                    dynamicContext = res
                    viewModel.updateVocabulary(v.copy(
                        sentenceContext = res.newSentence,
                        polishContextTranslation = res.translation,
                        interference_tag = res.interferenceTag
                    ))
                } catch (e: Exception) {
                    Log.e("FlashcardsOverlay", "Dynamic context generation failed", e)
                }
                isGeneratingDynamicContext = false
            }
        } else {
            if (mistakePl == null && !isTranslatingMistake) {
                isTranslatingMistake = true
                mistakePl = com.example.data.api.TutorAiService.translateMistakeToPolish(card.back, card.hint)
                isTranslatingMistake = false
            }
        }
    }

    Box(
        modifier = Modifier
            .fillMaxSize()
            .background(Color.Black.copy(alpha = 0.85f))
            .clickable { /* Block clicks to parent background */ }
            .padding(16.dp),
        contentAlignment = Alignment.Center
    ) {
        Column(
            horizontalAlignment = Alignment.CenterHorizontally,
            verticalArrangement = Arrangement.SpaceBetween,
            modifier = Modifier
                .fillMaxWidth()
                .fillMaxHeight(0.95f)
        ) {
            // Header
            Row(
                modifier = Modifier.fillMaxWidth(),
                horizontalArrangement = Arrangement.SpaceBetween,
                verticalAlignment = Alignment.CenterVertically
            ) {
                Column {
                    Text(
                        text = "Inteligentne Powtórki PRO 🧠",
                        color = Color.White,
                        fontWeight = FontWeight.Black,
                        fontSize = 20.sp,
                        letterSpacing = 0.5.sp
                    )
                    Text(
                        text = "Karta ${currentIndex.value + 1} z ${cards.size}",
                        color = Color.White.copy(alpha = 0.6f),
                        fontSize = 13.sp
                    )
                }
                IconButton(
                    onClick = onDismiss,
                    modifier = Modifier
                        .clip(CircleShape)
                        .background(Color.White.copy(alpha = 0.1f))
                ) {
                    Icon(Icons.Default.Close, contentDescription = "Close", tint = Color.White)
                }
            }

            Spacer(modifier = Modifier.height(16.dp))

            // The Unified Learning Card
            Card(
                modifier = Modifier
                    .fillMaxWidth()
                    .weight(1f),
                shape = RoundedCornerShape(24.dp),
                colors = CardDefaults.cardColors(
                    containerColor = Color(0xFF0F172A) // Sleek midnight slate
                ),
                border = BorderStroke(
                    1.5.dp,
                    if (card.isVocabulary) LingoPrimary.copy(alpha = 0.4f) else LingoStreakOrange.copy(alpha = 0.4f)
                ),
                elevation = CardDefaults.cardElevation(defaultElevation = 8.dp)
            ) {
                Column(
                    modifier = Modifier
                        .fillMaxSize()
                        .padding(20.dp)
                ) {
                    // Top Row: Type Badge + Quick Delete Button
                    Row(
                        modifier = Modifier.fillMaxWidth(),
                        horizontalArrangement = Arrangement.SpaceBetween,
                        verticalAlignment = Alignment.CenterVertically
                    ) {
                        Surface(
                            shape = RoundedCornerShape(8.dp),
                            color = if (card.isVocabulary) LingoPrimary.copy(alpha = 0.15f) else LingoStreakOrange.copy(alpha = 0.15f)
                        ) {
                            Row(
                                modifier = Modifier.padding(horizontal = 8.dp, vertical = 4.dp),
                                verticalAlignment = Alignment.CenterVertically,
                                horizontalArrangement = Arrangement.spacedBy(4.dp)
                            ) {
                                Box(
                                    modifier = Modifier
                                        .size(6.dp)
                                        .clip(CircleShape)
                                        .background(if (card.isVocabulary) LingoPrimary else LingoStreakOrange)
                                )
                                Text(
                                    text = card.title.uppercase(),
                                    fontSize = 10.sp,
                                    fontWeight = FontWeight.Black,
                                    color = if (card.isVocabulary) LingoPrimaryLight else LingoStreakOrange,
                                    letterSpacing = 0.5.sp
                                )
                            }
                        }

                        // TRASH BUTTON - Allows direct deletion of vocabulary/sentences from the card
                        IconButton(
                            onClick = {
                                if (card.isVocabulary) {
                                    viewModel.deleteVocabulary(card.id)
                                } else {
                                    viewModel.deleteMistake(card.id)
                                }
                                currentIndex.value += 1
                            },
                            modifier = Modifier
                                .size(32.dp)
                                .clip(CircleShape)
                                .background(Color.White.copy(alpha = 0.05f))
                        ) {
                            Icon(
                                imageVector = Icons.Default.Delete,
                                contentDescription = "Usuń z bazy",
                                tint = Color(0xFFEF4444).copy(alpha = 0.8f),
                                modifier = Modifier.size(16.dp)
                            )
                        }
                    }

                    Spacer(modifier = Modifier.height(16.dp))

                    if (!isFlipped.value) {
                        // --- AWERS (KREATYWNE TŁUMACZENIE / ACTIVE RECALL CHALLENGE) ---
                        LazyColumn(
                            modifier = Modifier.weight(1f),
                            horizontalAlignment = Alignment.CenterHorizontally,
                            verticalArrangement = Arrangement.spacedBy(20.dp)
                        ) {
                            item {
                                Column(horizontalAlignment = Alignment.CenterHorizontally) {
                                    Icon(
                                        imageVector = Icons.Default.Language,
                                        contentDescription = null,
                                        tint = LingoPrimaryLight,
                                        modifier = Modifier.size(36.dp)
                                    )
                                    Spacer(modifier = Modifier.height(8.dp))
                                    Text(
                                        text = if (card.isVocabulary) "WYZWANIE SŁOWNICTWA AI" else "WYZWANIE TŁUMACZENIOWE AI",
                                        fontSize = 11.sp,
                                        fontWeight = FontWeight.Bold,
                                        color = LingoPrimaryLight,
                                        letterSpacing = 1.5.sp
                                    )
                                    Spacer(modifier = Modifier.height(4.dp))
                                    Text(
                                        text = "Jak poprawnie wypowiedzieć to w języku obcym?",
                                        fontSize = 12.sp,
                                        color = Color.White.copy(alpha = 0.6f),
                                        textAlign = TextAlign.Center
                                    )
                                }
                            }

                            item {
                                Card(
                                    modifier = Modifier.fillMaxWidth(),
                                    shape = RoundedCornerShape(16.dp),
                                    colors = CardDefaults.cardColors(containerColor = Color.White.copy(alpha = 0.04f)),
                                    border = BorderStroke(1.dp, Color.White.copy(alpha = 0.08f))
                                ) {
                                    Column(
                                        modifier = Modifier.padding(16.dp),
                                        horizontalAlignment = Alignment.CenterHorizontally
                                    ) {
                                        Text(
                                            text = "TŁUMACZENIE (JĘZYK POLSKI) 🇵🇱",
                                            fontSize = 9.sp,
                                            fontWeight = FontWeight.Black,
                                            color = Color.White.copy(alpha = 0.4f),
                                            letterSpacing = 1.sp
                                        )
                                        Spacer(modifier = Modifier.height(8.dp))
                                        
                                        if (card.isVocabulary) {
                                            if (isTranslatingVocabWord) {
                                                CircularProgressIndicator(modifier = Modifier.size(20.dp), color = LingoPrimary)
                                            } else {
                                                Text(
                                                    text = "🇵🇱 ${vocabWordPl ?: card.back}",
                                                    fontSize = 22.sp,
                                                    fontWeight = FontWeight.Black,
                                                    color = Color.White,
                                                    textAlign = TextAlign.Center
                                                )
                                            }
                                        } else {
                                            if (isTranslatingMistake) {
                                                CircularProgressIndicator(modifier = Modifier.size(20.dp), color = LingoPrimary)
                                            } else {
                                                Text(
                                                    text = "🇵🇱 ${mistakePl?.translatedSentence ?: "Trwa pobieranie..."}",
                                                    fontSize = 18.sp,
                                                    fontWeight = FontWeight.Bold,
                                                    color = Color.White,
                                                    textAlign = TextAlign.Center,
                                                    lineHeight = 24.sp
                                                )
                                            }
                                        }
                                    }
                                }
                            }

                            if (card.isVocabulary && (card.hint.isNotBlank() || dynamicContext != null)) {
                                item {
                                    Card(
                                        modifier = Modifier.fillMaxWidth(),
                                        shape = RoundedCornerShape(16.dp),
                                        colors = CardDefaults.cardColors(containerColor = Color.White.copy(alpha = 0.02f)),
                                        border = BorderStroke(1.dp, Color.White.copy(alpha = 0.05f))
                                    ) {
                                        Column(
                                            modifier = Modifier.padding(16.dp),
                                            horizontalAlignment = Alignment.CenterHorizontally
                                        ) {
                                            Text(
                                                text = "PODPOWIEDŹ KONTEKSTOWA (PL) 🇵🇱",
                                                fontSize = 9.sp,
                                                fontWeight = FontWeight.Black,
                                                color = Color.White.copy(alpha = 0.4f),
                                                letterSpacing = 1.sp
                                            )
                                            Spacer(modifier = Modifier.height(6.dp))
                                            if (isGeneratingDynamicContext) {
                                                Row(
                                                    verticalAlignment = Alignment.CenterVertically,
                                                    horizontalArrangement = Arrangement.Center,
                                                    modifier = Modifier.fillMaxWidth()
                                                ) {
                                                    CircularProgressIndicator(modifier = Modifier.size(16.dp), color = LingoPrimary)
                                                    Spacer(modifier = Modifier.width(8.dp))
                                                    Text("Tworzenie unikalnego kognitywnego neuro-kontekstu...", fontSize = 11.sp, color = Color.White.copy(alpha = 0.5f))
                                                }
                                            } else {
                                                val displayText = dynamicContext?.translation ?: contextPl ?: "Trwa ładowanie..."
                                                Text(
                                                    text = displayText,
                                                    fontSize = 13.sp,
                                                    fontStyle = FontStyle.Italic,
                                                    color = Color.White.copy(alpha = 0.8f),
                                                    textAlign = TextAlign.Center,
                                                    lineHeight = 18.sp
                                                )
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    } else {
                        // --- REWERS (POKAZANIE POPRAWNEJ WERSJI I DETALICZNA ANALIZA AI) ---
                        LazyColumn(
                            modifier = Modifier.weight(1f),
                            horizontalAlignment = Alignment.CenterHorizontally,
                            verticalArrangement = Arrangement.spacedBy(16.dp)
                        ) {
                            item {
                                Column(horizontalAlignment = Alignment.CenterHorizontally) {
                                    Text(
                                        text = "SPRAWDŹ POPRAWNĄ WERSJĘ $targetFlag",
                                        fontSize = 10.sp,
                                        fontWeight = FontWeight.Bold,
                                        color = LingoSuccessGreen,
                                        letterSpacing = 1.5.sp
                                    )
                                    Spacer(modifier = Modifier.height(6.dp))
                                    Row(
                                        verticalAlignment = Alignment.CenterVertically,
                                        horizontalArrangement = Arrangement.Center,
                                        modifier = Modifier.fillMaxWidth().padding(horizontal = 16.dp)
                                    ) {
                                        Text(
                                            text = "$targetFlag ${if (card.isVocabulary) card.front else card.back}",
                                            fontSize = if (card.isVocabulary) 32.sp else 22.sp,
                                            fontWeight = FontWeight.Black,
                                            color = LingoSuccessGreen,
                                            textAlign = TextAlign.Center,
                                            lineHeight = if (card.isVocabulary) 38.sp else 28.sp,
                                            modifier = Modifier.weight(1f, fill = false).padding(horizontal = 8.dp)
                                        )
                                        IconButton(
                                            onClick = {
                                                val textToSpeak = if (card.isVocabulary) card.front else card.back
                                                val speakLang = if (card.language.isNotBlank()) card.language else "Spanish"
                                                speechHelper.speak(textToSpeak, speakLang, "B1")
                                            },
                                            modifier = Modifier.size(48.dp)
                                        ) {
                                            Icon(
                                                imageVector = Icons.Default.VolumeUp,
                                                contentDescription = "Odsłuchaj",
                                                tint = LingoSuccessGreen,
                                                modifier = Modifier.size(28.dp)
                                            )
                                        }
                                    }
                                }
                            }

                            if (card.isVocabulary) {
                                if (card.hint.isNotBlank() || dynamicContext != null) {
                                    item {
                                        Card(
                                            modifier = Modifier.fillMaxWidth(),
                                            shape = RoundedCornerShape(16.dp),
                                            colors = CardDefaults.cardColors(containerColor = Color.White.copy(alpha = 0.04f)),
                                            border = BorderStroke(1.dp, Color.White.copy(alpha = 0.08f))
                                        ) {
                                            Column(modifier = Modifier.padding(16.dp)) {
                                                Row(
                                                    modifier = Modifier.fillMaxWidth(),
                                                    horizontalArrangement = Arrangement.SpaceBetween,
                                                    verticalAlignment = Alignment.CenterVertically
                                                ) {
                                                    Text(
                                                        text = "DYNAMICZNY NEURO-KONTEKST AI:",
                                                        fontSize = 9.sp,
                                                        fontWeight = FontWeight.Black,
                                                        color = LingoPrimaryLight,
                                                        letterSpacing = 1.sp
                                                    )
                                                    if (isGeneratingDynamicContext) {
                                                        CircularProgressIndicator(modifier = Modifier.size(12.dp), color = LingoPrimaryLight)
                                                    } else {
                                                        val tag = dynamicContext?.interferenceTag ?: card.interference_tag
                                                        if (tag.isNotBlank() && !tag.equals("none", ignoreCase = true)) {
                                                            Surface(
                                                                color = LingoStreakOrange.copy(alpha = 0.15f),
                                                                shape = RoundedCornerShape(6.dp)
                                                            ) {
                                                                Text(
                                                                    text = "⚠️ ${tag.uppercase()}",
                                                                    fontSize = 8.sp,
                                                                    fontWeight = FontWeight.Bold,
                                                                    color = LingoStreakOrange,
                                                                    modifier = Modifier.padding(horizontal = 6.dp, vertical = 2.dp)
                                                                )
                                                            }
                                                        }
                                                    }
                                                }
                                                Spacer(modifier = Modifier.height(6.dp))
                                                val sentenceToDisplay = dynamicContext?.newSentence ?: card.hint
                                                Text(
                                                    text = "\"$sentenceToDisplay\"",
                                                    fontSize = 15.sp,
                                                    fontStyle = FontStyle.Italic,
                                                    fontWeight = FontWeight.Medium,
                                                    color = Color.White.copy(alpha = 0.95f)
                                                )
                                                Spacer(modifier = Modifier.height(10.dp))
                                                Text(
                                                    text = "TŁUMACZENIE ZDANIA:",
                                                    fontSize = 9.sp,
                                                    fontWeight = FontWeight.Black,
                                                    color = Color.White.copy(alpha = 0.4f),
                                                    letterSpacing = 1.sp
                                                )
                                                Spacer(modifier = Modifier.height(4.dp))
                                                val transToDisplay = dynamicContext?.translation ?: contextPl ?: "Brak tłumaczenia"
                                                Text(
                                                    text = transToDisplay,
                                                    fontSize = 13.sp,
                                                    color = Color.White.copy(alpha = 0.7f)
                                                )

                                                // Regenerate button
                                                Spacer(modifier = Modifier.height(12.dp))
                                                Row(
                                                    modifier = Modifier.fillMaxWidth(),
                                                    horizontalArrangement = Arrangement.End
                                                ) {
                                                    TextButton(
                                                        onClick = {
                                                            coroutineScope.launch {
                                                                isGeneratingDynamicContext = true
                                                                try {
                                                                    val res = com.example.data.api.TutorAiService.generateDynamicSrsContext(
                                                                        word = card.front,
                                                                        translation = card.back,
                                                                        language = card.language,
                                                                        currentContext = sentenceToDisplay
                                                                    )
                                                                    dynamicContext = res
                                                                    val v = card.rawObject as? Vocabulary
                                                                    v?.let {
                                                                        viewModel.updateVocabulary(it.copy(
                                                                            sentenceContext = res.newSentence,
                                                                            polishContextTranslation = res.translation,
                                                                            interference_tag = res.interferenceTag
                                                                        ))
                                                                    }
                                                                } catch (e: Exception) {
                                                                    Log.e("FlashcardsOverlay", "Dynamic context regeneration failed", e)
                                                                }
                                                                isGeneratingDynamicContext = false
                                                            }
                                                        },
                                                        enabled = !isGeneratingDynamicContext
                                                    ) {
                                                        Icon(Icons.Default.Refresh, contentDescription = null, modifier = Modifier.size(14.dp), tint = LingoPrimaryLight)
                                                        Spacer(modifier = Modifier.width(4.dp))
                                                        Text("Nowy kontekst kognitywny", fontSize = 11.sp, color = LingoPrimaryLight)
                                                    }
                                                }
                                            }
                                        }
                                    }
                                }
                            } else {
                                item {
                                    Card(
                                        modifier = Modifier.fillMaxWidth(),
                                        shape = RoundedCornerShape(16.dp),
                                        colors = CardDefaults.cardColors(containerColor = Color.White.copy(alpha = 0.04f)),
                                        border = BorderStroke(1.dp, Color.White.copy(alpha = 0.08f))
                                    ) {
                                        Column(modifier = Modifier.padding(16.dp)) {
                                            Text(
                                                text = "WYJAŚNIENIE BŁĘDU (AI):",
                                                fontSize = 9.sp,
                                                fontWeight = FontWeight.Black,
                                                color = LingoStreakOrange,
                                                letterSpacing = 1.sp
                                            )
                                            Spacer(modifier = Modifier.height(6.dp))
                                            Text(
                                                text = mistakePl?.translatedExplanation ?: card.hint,
                                                fontSize = 13.sp,
                                                color = Color.White.copy(alpha = 0.9f),
                                                lineHeight = 18.sp
                                            )
                                        }
                                    }
                                }
                            }

                            // Interactive Mnemonic Trigger inside card if vocabulary
                            if (card.isVocabulary) {
                                val v = card.rawObject as? Vocabulary
                                val mnem = v?.let { vocab ->
                                    mnemonics.find { m -> m.wordOrPhrase.equals(vocab.word, ignoreCase = true) }
                                }

                                if (mnem != null) {
                                    item {
                                        val rich = remember(mnem.association) { parseMnemonic(mnem.association) }
                                        Card(
                                            modifier = Modifier.fillMaxWidth(),
                                            shape = RoundedCornerShape(16.dp),
                                            colors = CardDefaults.cardColors(containerColor = Color(0xFFFEF3C7).copy(alpha = 0.12f)),
                                            border = BorderStroke(1.dp, Color(0xFFFCD34D).copy(alpha = 0.35f))
                                        ) {
                                            Column(modifier = Modifier.padding(14.dp), verticalArrangement = Arrangement.spacedBy(8.dp)) {
                                                Row(verticalAlignment = Alignment.CenterVertically) {
                                                    Text("🧠", fontSize = 16.sp)
                                                    Spacer(modifier = Modifier.width(6.dp))
                                                    Text(
                                                        text = "HAK PAMIĘCIOWY (MNEMOTECHNIKA AI)",
                                                        fontSize = 10.sp,
                                                        fontWeight = FontWeight.Bold,
                                                        color = Color(0xFFFCD34D)
                                                    )
                                                }

                                                if (rich != null) {
                                                    Row(
                                                        verticalAlignment = Alignment.CenterVertically,
                                                        horizontalArrangement = Arrangement.spacedBy(8.dp),
                                                        modifier = Modifier
                                                            .fillMaxWidth()
                                                            .clip(RoundedCornerShape(8.dp))
                                                            .background(Color.White.copy(alpha = 0.05f))
                                                            .padding(8.dp)
                                                    ) {
                                                        Text(text = rich.emojis, fontSize = 24.sp)
                                                        Text(
                                                            text = rich.visualScene,
                                                            fontSize = 11.sp,
                                                            fontStyle = FontStyle.Italic,
                                                            color = Color.White.copy(alpha = 0.9f),
                                                            lineHeight = 15.sp
                                                        )
                                                    }

                                                    Text(
                                                        text = rich.association,
                                                        fontSize = 12.5.sp,
                                                        fontWeight = FontWeight.SemiBold,
                                                        color = Color(0xFFFEF3C7),
                                                        lineHeight = 17.sp
                                                    )

                                                    if (rich.situation.isNotBlank()) {
                                                        Text(
                                                            text = "💡 Kiedy użyć: ${rich.situation}",
                                                            fontSize = 11.sp,
                                                            color = Color.White.copy(alpha = 0.7f),
                                                            lineHeight = 15.sp
                                                        )
                                                    }
                                                } else {
                                                    Text(
                                                        text = mnem.association,
                                                        fontSize = 12.sp,
                                                        color = Color.White.copy(alpha = 0.85f),
                                                        lineHeight = 16.sp
                                                    )
                                                }
                                            }
                                        }
                                    }
                                } else if (v != null) {
                                    item {
                                        val isGeneratingReviewMnem = remember { mutableStateOf(false) }
                                        Surface(
                                            modifier = Modifier.fillMaxWidth(),
                                            shape = RoundedCornerShape(12.dp),
                                            color = Color.White.copy(alpha = 0.05f),
                                            border = BorderStroke(1.dp, Color.White.copy(alpha = 0.15f))
                                        ) {
                                            Row(
                                                modifier = Modifier
                                                    .fillMaxWidth()
                                                    .padding(10.dp),
                                                horizontalArrangement = Arrangement.SpaceBetween,
                                                verticalAlignment = Alignment.CenterVertically
                                            ) {
                                                Column(modifier = Modifier.weight(1f)) {
                                                    Text(
                                                        text = "Trudne słówko?",
                                                        fontSize = 11.sp,
                                                        fontWeight = FontWeight.Bold,
                                                        color = Color.White.copy(alpha = 0.9f)
                                                    )
                                                    Text(
                                                        text = "Stwórz mnemotechnikę AI, by zapamiętać je 4x szybciej",
                                                        fontSize = 10.sp,
                                                        color = Color.White.copy(alpha = 0.6f)
                                                    )
                                                }
                                                Button(
                                                    onClick = {
                                                        isGeneratingReviewMnem.value = true
                                                        viewModel.generateAndSaveRichMnemonic(v.word, v.language) {
                                                            isGeneratingReviewMnem.value = false
                                                        }
                                                    },
                                                    enabled = !isGeneratingReviewMnem.value,
                                                    colors = ButtonDefaults.buttonColors(containerColor = LingoPrimary),
                                                    shape = RoundedCornerShape(8.dp),
                                                    contentPadding = PaddingValues(horizontal = 10.dp, vertical = 6.dp)
                                                ) {
                                                    if (isGeneratingReviewMnem.value) {
                                                        CircularProgressIndicator(
                                                            modifier = Modifier.size(14.dp),
                                                            color = Color.White,
                                                            strokeWidth = 2.dp
                                                        )
                                                    } else {
                                                        Text("🧠 Stwórz Hak AI", fontSize = 10.sp, fontWeight = FontWeight.Bold)
                                                    }
                                                }
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
            }

            Spacer(modifier = Modifier.height(16.dp))

            if (!isFlipped.value) {
                // Bottom Flip Button
                Button(
                    onClick = { isFlipped.value = true },
                    modifier = Modifier
                        .fillMaxWidth()
                        .height(52.dp),
                    colors = ButtonDefaults.buttonColors(containerColor = LingoPrimary),
                    shape = RoundedCornerShape(14.dp)
                ) {
                    Icon(imageVector = Icons.Default.Visibility, contentDescription = null, tint = Color.White)
                    Spacer(modifier = Modifier.width(8.dp))
                    Text("Pokaż odpowiedź & Analizę AI 👁️", fontWeight = FontWeight.Bold, fontSize = 14.sp)
                }
            } else {
                // Action Rating Panel (SRS) at the bottom
                Column(
                    modifier = Modifier.fillMaxWidth(),
                    verticalArrangement = Arrangement.spacedBy(8.dp)
                ) {
                    Text(
                        text = "Oceń swoją odpowiedź (SRS):",
                        fontSize = 12.sp,
                        color = Color.White.copy(alpha = 0.6f),
                        fontWeight = FontWeight.Bold,
                        modifier = Modifier.align(Alignment.CenterHorizontally)
                    )
                    Row(
                        modifier = Modifier.fillMaxWidth(),
                        horizontalArrangement = Arrangement.spacedBy(8.dp)
                    ) {
                        // AGAIN BUTTON
                        Button(
                            onClick = {
                                val latency = if (revealTime.value > 0) System.currentTimeMillis() - revealTime.value else 0L
                                if (card.isVocabulary) {
                                    viewModel.processVocabSrsReview(card.rawObject as Vocabulary, rating = 1, latencyMs = latency)
                                } else {
                                    viewModel.processMistakeSrsReview(card.rawObject as Mistake, rating = 1, latencyMs = latency)
                                }
                                currentIndex.value += 1
                            },
                            modifier = Modifier.weight(1f),
                            colors = ButtonDefaults.buttonColors(containerColor = Color(0xFFEF4444)),
                            shape = RoundedCornerShape(14.dp),
                            contentPadding = PaddingValues(vertical = 12.dp)
                        ) {
                            Column(horizontalAlignment = Alignment.CenterHorizontally) {
                                Text("Znowu 🔴", fontWeight = FontWeight.Bold, fontSize = 13.sp, color = Color.White)
                                Text("1 dzień", fontSize = 10.sp, color = Color.White.copy(alpha = 0.8f))
                            }
                        }

                        // GOOD BUTTON
                        Button(
                            onClick = {
                                val latency = if (revealTime.value > 0) System.currentTimeMillis() - revealTime.value else 0L
                                if (card.isVocabulary) {
                                    viewModel.processVocabSrsReview(card.rawObject as Vocabulary, rating = 4, latencyMs = latency)
                                } else {
                                    viewModel.processMistakeSrsReview(card.rawObject as Mistake, rating = 4, latencyMs = latency)
                                }
                                currentIndex.value += 1
                            },
                            modifier = Modifier.weight(1.2f),
                            colors = ButtonDefaults.buttonColors(containerColor = Color(0xFF3B82F6)),
                            shape = RoundedCornerShape(14.dp),
                            contentPadding = PaddingValues(vertical = 12.dp)
                        ) {
                            Column(horizontalAlignment = Alignment.CenterHorizontally) {
                                Text("Dobrze 🔵", fontWeight = FontWeight.Bold, fontSize = 13.sp, color = Color.White)
                                val nextDays = if (card.masteryLevel == 0) "1 dzień" else if (card.masteryLevel == 1) "3 dni" else "7 dni"
                                Text(nextDays, fontSize = 10.sp, color = Color.White.copy(alpha = 0.8f))
                            }
                        }

                        // EASY BUTTON
                        Button(
                            onClick = {
                                val latency = if (revealTime.value > 0) System.currentTimeMillis() - revealTime.value else 0L
                                if (card.isVocabulary) {
                                    viewModel.processVocabSrsReview(card.rawObject as Vocabulary, rating = 5, latencyMs = latency)
                                } else {
                                    viewModel.processMistakeSrsReview(card.rawObject as Mistake, rating = 5, latencyMs = latency)
                                }
                                currentIndex.value += 1
                            },
                            modifier = Modifier.weight(1f),
                            colors = ButtonDefaults.buttonColors(containerColor = Color(0xFF10B981)),
                            shape = RoundedCornerShape(14.dp),
                            contentPadding = PaddingValues(vertical = 12.dp)
                        ) {
                            Column(horizontalAlignment = Alignment.CenterHorizontally) {
                                Text("Łatwe 🟢", fontWeight = FontWeight.Bold, fontSize = 13.sp, color = Color.White)
                                val nextDays = if (card.masteryLevel == 0) "3 dni" else if (card.masteryLevel == 1) "7 dni" else "14 dni"
                                Text(nextDays, fontSize = 10.sp, color = Color.White.copy(alpha = 0.8f))
                            }
                        }
                    }

                    // Hide Answer flip back button
                    OutlinedButton(
                        onClick = { isFlipped.value = false },
                        modifier = Modifier.align(Alignment.CenterHorizontally),
                        border = BorderStroke(1.dp, Color.White.copy(alpha = 0.2f)),
                        shape = RoundedCornerShape(12.dp)
                    ) {
                        Text("Ukryj odpowiedź 🙈", color = Color.White.copy(alpha = 0.6f), fontSize = 11.sp)
                    }
                }
            }
        }
    }
}

private fun Modifier.fillOuterHorizontalMaxWidth(): Modifier = this.fillMaxWidth()

// ==========================================
// 3. HISTORY SCREEN
// ==========================================
@Composable
fun HistoryScreen(
    sessions: List<Session>,
    viewModel: TutorViewModel
) {
    val activeCompletedSession = remember { mutableStateOf<Session?>(null) }

    if (activeCompletedSession.value != null) {
        // Show historical report details
        EvaluationScreen(
            evaluation = SessionEvaluationResponse(
                fluencyScore = activeCompletedSession.value!!.fluencyScore,
                strengths = activeCompletedSession.value!!.feedbackStrength,
                improvements = activeCompletedSession.value!!.feedbackImprovement,
                grammarTips = activeCompletedSession.value!!.feedbackGrammar,
                studyPlan = activeCompletedSession.value!!.feedbackStudyPlan
            ),
            viewModel = viewModel,
            sessionTitle = activeCompletedSession.value!!.title,
            onClose = { activeCompletedSession.value = null }
        )
    } else {
        Column(
            modifier = Modifier
                .fillMaxSize()
                .padding(16.dp)
        ) {
            Text(
                text = "Session History",
                fontSize = 22.sp,
                fontWeight = FontWeight.Bold,
                color = MaterialTheme.colorScheme.onBackground
            )
            Text(
                text = "Review your spoken achievements and study suggestions",
                fontSize = 13.sp,
                color = MaterialTheme.colorScheme.onBackground.copy(alpha = 0.6f)
            )

            Spacer(modifier = Modifier.height(16.dp))

            if (sessions.isEmpty()) {
                Box(
                    modifier = Modifier
                        .fillMaxWidth()
                        .weight(1f),
                    contentAlignment = Alignment.Center
                ) {
                    Column(horizontalAlignment = Alignment.CenterHorizontally) {
                        Icon(
                            Icons.Default.List,
                            contentDescription = null,
                            tint = MaterialTheme.colorScheme.onBackground.copy(alpha = 0.2f),
                            modifier = Modifier.size(80.dp)
                        )
                        Spacer(modifier = Modifier.height(16.dp))
                        Text(
                            text = "No history available",
                            fontWeight = FontWeight.Bold,
                            fontSize = 16.sp,
                            color = MaterialTheme.colorScheme.onBackground.copy(alpha = 0.5f)
                        )
                    }
                }
            } else {
                LazyColumn(
                    modifier = Modifier.weight(1f),
                    verticalArrangement = Arrangement.spacedBy(12.dp)
                ) {
                    items(sessions, key = { it.id }) { session ->
                        HistorySessionCard(
                            session = session,
                            onViewReport = { activeCompletedSession.value = session },
                            onDelete = { viewModel.deleteSession(session.id) }
                        )
                    }
                }
            }
        }
    }
}

@Composable
fun HistorySessionCard(
    session: Session,
    onViewReport: () -> Unit,
    onDelete: () -> Unit
) {
    val dateText = remember(session.timestamp) {
        SimpleDateFormat("MMM dd, yyyy", Locale.getDefault()).format(Date(session.timestamp))
    }

    Card(
        modifier = Modifier.fillMaxWidth(),
        shape = RoundedCornerShape(16.dp),
        colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surface),
        elevation = CardDefaults.cardElevation(defaultElevation = 2.dp)
    ) {
        Column(modifier = Modifier.padding(16.dp)) {
            Row(
                modifier = Modifier.fillMaxWidth(),
                horizontalArrangement = Arrangement.SpaceBetween,
                verticalAlignment = Alignment.CenterVertically
            ) {
                Column {
                    Text(
                        text = session.title,
                        fontWeight = FontWeight.Bold,
                        fontSize = 16.sp,
                        color = MaterialTheme.colorScheme.onSurface
                    )
                    Text(
                        text = "$dateText • ${session.language} (${session.cefrLevel})",
                        fontSize = 12.sp,
                        color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.6f)
                    )
                }

                IconButton(onClick = onDelete) {
                    Icon(
                        Icons.Default.Delete,
                        contentDescription = "Delete Session",
                        tint = LingoErrorRed.copy(alpha = 0.5f)
                    )
                }
            }

            Spacer(modifier = Modifier.height(12.dp))
            Divider(color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.05f))
            Spacer(modifier = Modifier.height(12.dp))

            Row(
                modifier = Modifier.fillMaxWidth(),
                horizontalArrangement = Arrangement.SpaceBetween,
                verticalAlignment = Alignment.CenterVertically
            ) {
                Row(verticalAlignment = Alignment.CenterVertically) {
                    Text(
                        text = "Fluency Score: ",
                        fontSize = 13.sp,
                        color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.7f)
                    )
                    Text(
                        text = "${session.fluencyScore}%",
                        fontWeight = FontWeight.Bold,
                        fontSize = 15.sp,
                        color = if (session.fluencyScore >= 75) LingoSuccessGreen else LingoGold
                    )
                }

                Button(
                    onClick = onViewReport,
                    colors = ButtonDefaults.buttonColors(containerColor = LingoPrimary),
                    contentPadding = PaddingValues(horizontal = 12.dp, vertical = 4.dp),
                    shape = RoundedCornerShape(10.dp),
                    modifier = Modifier.height(32.dp)
                ) {
                    Text("View Report", fontSize = 11.sp, fontWeight = FontWeight.Bold)
                }
            }
        }
    }
}

// ==========================================
// 4. GOALS SCREEN
// ==========================================
@Composable
fun GoalsScreen(
    goal: UserGoal?,
    viewModel: TutorViewModel,
    speechHelper: TutorSpeechHelper
) {
    val context = LocalContext.current
    val targetLanguage = remember { mutableStateOf(goal?.targetLanguage ?: "Spanish") }
    val cefrLevel = remember { mutableStateOf(goal?.cefrLevel ?: "A2") }
    val focusArea = remember { mutableStateOf(goal?.focusArea ?: "General Fluency") }
    val dailyMinutes = remember { mutableStateOf(goal?.dailyGoalMinutes ?: 15) }
    val currentApiKey by viewModel.apiKey.collectAsStateWithLifecycle()
    val apiKeyText = remember { mutableStateOf(currentApiKey) }
    var isApiKeyVisible by remember { mutableStateOf(false) }

    val currentModel by viewModel.selectedModel.collectAsStateWithLifecycle()
    val modelText = remember { mutableStateOf(currentModel) }

    LaunchedEffect(currentApiKey) {
        apiKeyText.value = currentApiKey
    }

    LaunchedEffect(currentModel) {
        modelText.value = currentModel
    }

    val isTesting by viewModel.isTestingConnection.collectAsStateWithLifecycle()
    val testResult by viewModel.testConnectionResult.collectAsStateWithLifecycle()

    // Sync state when goal load changes
    LaunchedEffect(goal) {
        if (goal != null) {
            targetLanguage.value = goal.targetLanguage
            cefrLevel.value = goal.cefrLevel
            focusArea.value = goal.focusArea
            dailyMinutes.value = goal.dailyGoalMinutes
        }
    }

    val languages = listOf("Spanish", "English", "Italian", "German", "French", "Russian", "Japanese", "Chinese", "Korean")
    val cefrLevels = listOf("A1", "A2", "B1", "B2", "C1", "C2")

    val currentVocabs by viewModel.allVocabulary.collectAsStateWithLifecycle(emptyList())
    val currentMistakes by viewModel.allMistakes.collectAsStateWithLifecycle(emptyList())
    val currentStories by viewModel.allStories.collectAsStateWithLifecycle(emptyList())
    val currentSessions by viewModel.allSessions.collectAsStateWithLifecycle(emptyList())

    // Async live inspection of the inspected language (even if not yet saved as active)
    var inspectedStats by remember { mutableStateOf<Triple<Int, Int, Int>?>(null) }
    LaunchedEffect(targetLanguage.value) {
        inspectedStats = viewModel.getLanguageResourceStatsSync(targetLanguage.value)
    }
    
    // Detailed list of speech focus areas with descriptions and icons
    val focusAreas = listOf(
        Triple("General Fluency", "Płynność i Konwersacja", "Naturalny przepływ rozmowy, budowanie pewności siebie i swobodnej ekspresji."),
        Triple("Professional Speech", "Biznes i Praca", "Słownictwo zawodowe, spotkania biznesowe, negocjacje i terminologia branżowa."),
        Triple("Travel Dialogue", "Podróże i Codzienne Sytuacje", "Komunikacja w hotelu, restauracji, na lotnisku, zakupy i zapytania o drogę."),
        Triple("Grammar Practice", "Poprawność i Gramatyka", "Struktura zdań, właściwy dobór czasów oraz korygowanie nawykowych błędów."),
        Triple("Pronunciation Focus", "Wymowa i Akcent", "Poprawa fonetyki, intonacji, czystości dźwięków i redukcji akcentu."),
        Triple("Slang & Idioms", "Słownictwo i Slang", "Zwroty potoczne, idiomy oraz naturalne wyrażenia używane przez native speakerów.")
    )
    val minuteGoals = listOf(10, 15, 30, 45)

    LazyColumn(
        modifier = Modifier
            .fillMaxSize()
            .padding(16.dp),
        verticalArrangement = Arrangement.spacedBy(16.dp)
    ) {
        item {
            Text(
                text = "Learning Goals & Preferences",
                fontSize = 22.sp,
                fontWeight = FontWeight.Bold,
                color = MaterialTheme.colorScheme.onBackground
            )
            Text(
                text = "Customize Lingo's speech parameters and difficulty levels",
                fontSize = 13.sp,
                color = MaterialTheme.colorScheme.onBackground.copy(alpha = 0.6f)
            )
        }

        // Quick 1-Click Goal Presets
        item {
            Card(
                modifier = Modifier.fillMaxWidth(),
                colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surface),
                shape = RoundedCornerShape(16.dp),
                border = BorderStroke(1.dp, MaterialTheme.colorScheme.outlineVariant.copy(alpha = 0.5f))
            ) {
                Column(modifier = Modifier.padding(16.dp)) {
                    Row(
                        modifier = Modifier.fillMaxWidth(),
                        horizontalArrangement = Arrangement.SpaceBetween,
                        verticalAlignment = Alignment.CenterVertically
                    ) {
                        Row(
                            verticalAlignment = Alignment.CenterVertically,
                            horizontalArrangement = Arrangement.spacedBy(8.dp)
                        ) {
                            Box(
                                modifier = Modifier
                                    .size(32.dp)
                                    .clip(CircleShape)
                                    .background(LingoPrimary.copy(alpha = 0.12f)),
                                contentAlignment = Alignment.Center
                            ) {
                                Icon(
                                    imageVector = Icons.Default.Bolt,
                                    contentDescription = null,
                                    tint = LingoPrimary,
                                    modifier = Modifier.size(18.dp)
                                )
                            }
                            Column {
                                Text(
                                    text = "Szybkie Presety Celów (1-Click Presets)",
                                    fontWeight = FontWeight.Bold,
                                    fontSize = 15.sp,
                                    color = MaterialTheme.colorScheme.onSurface
                                )
                                Text(
                                    text = "Gotowe profile dydaktyczne zsynchronizowane z CEFR i lektorem",
                                    fontSize = 11.sp,
                                    color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.6f)
                                )
                            }
                        }
                    }

                    Spacer(modifier = Modifier.height(12.dp))

                    val presets = listOf(
                        Triple(
                            "🏖️ Wakacje & Podróże",
                            "A2 • Podróże i Codzienne Sytuacje • 15 min",
                            Triple("A2", "Travel Dialogue", 15)
                        ),
                        Triple(
                            "💼 Biznes & Kariera PRO",
                            "B2 • Biznes i Praca • 30 min",
                            Triple("B2", "Professional Speech", 30)
                        ),
                        Triple(
                            "🗣️ Swobodna Płynność Mowy",
                            "B1 • Płynność i Konwersacja • 15 min",
                            Triple("B1", "General Fluency", 15)
                        ),
                        Triple(
                            "📚 Egzamin & Gramatyka",
                            "B2 • Poprawność i Gramatyka • 45 min",
                            Triple("B2", "Grammar Practice", 45)
                        ),
                        Triple(
                            "🎙️ Wymowa & Akcent",
                            "A2 • Wymowa i Akcent • 15 min",
                            Triple("A2", "Pronunciation Focus", 15)
                        )
                    )

                    FlowRow(
                        horizontalArrangement = Arrangement.spacedBy(8.dp),
                        verticalArrangement = Arrangement.spacedBy(8.dp)
                    ) {
                        presets.forEach { (presetTitle, _, config) ->
                            val isPresetActive = cefrLevel.value == config.first &&
                                    focusArea.value == config.second &&
                                    dailyMinutes.value == config.third

                            FilterChip(
                                selected = isPresetActive,
                                onClick = {
                                    cefrLevel.value = config.first
                                    focusArea.value = config.second
                                    dailyMinutes.value = config.third
                                    viewModel.updateGoal(
                                        targetLanguage = targetLanguage.value,
                                        cefrLevel = config.first,
                                        focusArea = config.second,
                                        dailyMinutes = config.third
                                    )
                                    Toast.makeText(context, "Zapisano preset: $presetTitle", Toast.LENGTH_SHORT).show()
                                },
                                label = {
                                    Text(
                                        text = "$presetTitle (${config.first} • ${config.third} min)",
                                        fontSize = 12.sp,
                                        fontWeight = FontWeight.SemiBold
                                    )
                                },
                                colors = FilterChipDefaults.filterChipColors(
                                    selectedContainerColor = LingoPrimary,
                                    selectedLabelColor = Color.White
                                )
                            )
                        }
                    }
                }
            }
        }

        // Language Select
        item {
            Card(
                modifier = Modifier.fillMaxWidth(),
                colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surface),
                shape = RoundedCornerShape(16.dp),
                border = BorderStroke(1.dp, MaterialTheme.colorScheme.outlineVariant.copy(alpha = 0.5f))
            ) {
                Column(modifier = Modifier.padding(16.dp)) {
                    Row(
                        modifier = Modifier.fillMaxWidth(),
                        horizontalArrangement = Arrangement.SpaceBetween,
                        verticalAlignment = Alignment.CenterVertically
                    ) {
                        Text("Target Language (Język docelowy)", fontWeight = FontWeight.Bold, fontSize = 16.sp)
                        val flagIcon = when (targetLanguage.value.lowercase()) {
                            "spanish" -> "🇪🇸"
                            "english" -> "🇬🇧"
                            "italian" -> "🇮🇹"
                            "german" -> "🇩🇪"
                            "french" -> "🇫🇷"
                            "russian" -> "🇷🇺"
                            "japanese" -> "🇯🇵"
                            "chinese" -> "🇨🇳"
                            "korean" -> "🇰🇷"
                            else -> "🌐"
                        }
                        Text(flagIcon, fontSize = 20.sp)
                    }
                    Spacer(modifier = Modifier.height(6.dp))
                    Text(
                        "Każdy język posiada odizolowaną bazę słownictwa, historii i błędów. Zmiana języka nie kasuje Twojego dorobku w innych językach.",
                        fontSize = 12.sp,
                        color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.65f),
                        lineHeight = 16.sp
                    )
                    Spacer(modifier = Modifier.height(12.dp))
                    FlowRow(
                        horizontalArrangement = Arrangement.spacedBy(8.dp),
                        verticalArrangement = Arrangement.spacedBy(8.dp)
                    ) {
                        languages.forEach { lang ->
                            val langEmoji = when (lang.lowercase()) {
                                "spanish" -> "🇪🇸"
                                "english" -> "🇬🇧"
                                "italian" -> "🇮🇹"
                                "german" -> "🇩🇪"
                                "french" -> "🇫🇷"
                                "russian" -> "🇷🇺"
                                "japanese" -> "🇯🇵"
                                "chinese" -> "🇨🇳"
                                "korean" -> "🇰🇷"
                                else -> "🌐"
                            }
                            FilterChip(
                                selected = targetLanguage.value == lang,
                                onClick = {
                                    targetLanguage.value = lang
                                    viewModel.updateGoal(
                                        targetLanguage = lang,
                                        cefrLevel = cefrLevel.value,
                                        focusArea = focusArea.value,
                                        dailyMinutes = dailyMinutes.value
                                    )
                                    Toast.makeText(context, "Zapisano język docelowy: $lang", Toast.LENGTH_SHORT).show()
                                },
                                label = { Text("$langEmoji $lang", fontSize = 12.sp, fontWeight = FontWeight.SemiBold) },
                                colors = FilterChipDefaults.filterChipColors(
                                    selectedContainerColor = LingoPrimary,
                                    selectedLabelColor = Color.White
                                )
                            )
                        }
                    }

                    Spacer(modifier = Modifier.height(14.dp))
                    // Active language progress isolation preview (dynamic real-time inspect)
                    val langSessions = inspectedStats?.first ?: currentSessions.count { it.language.equals(targetLanguage.value, ignoreCase = true) }
                    val langStories = currentStories.count { (it.language.ifBlank { it.language_code }).equals(targetLanguage.value, ignoreCase = true) }
                    val langVocabCount = inspectedStats?.second ?: currentVocabs.count { it.language.equals(targetLanguage.value, ignoreCase = true) || it.language_code.equals(targetLanguage.value, ignoreCase = true) }
                    val langMistakesCount = inspectedStats?.third ?: currentMistakes.count { it.language_code.equals(targetLanguage.value, ignoreCase = true) }

                    Row(
                        modifier = Modifier
                            .fillMaxWidth()
                            .clip(RoundedCornerShape(10.dp))
                            .background(LingoPrimary.copy(alpha = 0.08f))
                            .border(1.dp, LingoPrimary.copy(alpha = 0.25f), RoundedCornerShape(10.dp))
                            .padding(10.dp),
                        verticalAlignment = Alignment.CenterVertically,
                        horizontalArrangement = Arrangement.SpaceBetween
                    ) {
                        Column {
                            Row(
                                verticalAlignment = Alignment.CenterVertically,
                                horizontalArrangement = Arrangement.spacedBy(6.dp)
                            ) {
                                Text(
                                    text = "Baza dla: ${targetLanguage.value}",
                                    fontWeight = FontWeight.Bold,
                                    fontSize = 12.sp,
                                    color = LingoPrimary
                                )
                                Box(
                                    modifier = Modifier
                                        .clip(RoundedCornerShape(4.dp))
                                        .background(Color(0xFF2E7D32).copy(alpha = 0.15f))
                                        .padding(horizontal = 5.dp, vertical = 1.dp)
                                ) {
                                    Text(
                                        text = "IZOLOWANA",
                                        fontSize = 9.sp,
                                        fontWeight = FontWeight.Bold,
                                        color = Color(0xFF2E7D32)
                                    )
                                }
                            }
                            Spacer(modifier = Modifier.height(2.dp))
                            Text(
                                text = "Sesje: $langSessions • Słówka: $langVocabCount • Opowiadania: $langStories • Do powtórki: $langMistakesCount",
                                fontSize = 11.sp,
                                color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.75f)
                            )
                        }
                        Icon(
                            imageVector = Icons.Default.Shield,
                            contentDescription = "Izolacja danych",
                            tint = LingoPrimary,
                            modifier = Modifier.size(20.dp)
                        )
                    }

                    // Special Alphabet & Phonics Support info banner for Non-Latin / Slavic alphabets
                    val isNonLatin = when (targetLanguage.value.lowercase()) {
                        "russian", "japanese", "chinese", "korean" -> true
                        else -> false
                    }
                    if (isNonLatin) {
                        Spacer(modifier = Modifier.height(10.dp))
                        val (alphabetTitle, alphabetSubtitle) = when (targetLanguage.value.lowercase()) {
                            "russian" -> Pair("Wsparcie Cyrylicy & Fonetyki Słowiańskiej", "Lingo rozpoznaje cyrylicę, stosuje miękkie/twarde znaki i transkrypcję fonetyczną ułatwiającą czytanie.")
                            "japanese" -> Pair("Wsparcie Kana & Kanji", "Dostępny system zapisu Hiragana, Katakana i kanji wraz z transkrypcją Romaji.")
                            "chinese" -> Pair("System Pinyin & Tony", "Obsługa uproszczonych znaków Hanzi i transkrypcji Pinyin ze znakami tonów.")
                            "korean" -> Pair("Alfabet Hangul (한글)", "Modularny alfabet fonetyczny Hangul z automatycznym podziałem na bloki sylabowe.")
                            else -> Pair("System Fonetyczny", "Wsparcie rodzimego alfabetu i transkrypcji.")
                        }
                        Row(
                            modifier = Modifier
                                .fillMaxWidth()
                                .clip(RoundedCornerShape(10.dp))
                                .background(MaterialTheme.colorScheme.secondaryContainer.copy(alpha = 0.4f))
                                .border(1.dp, MaterialTheme.colorScheme.secondary.copy(alpha = 0.3f), RoundedCornerShape(10.dp))
                                .padding(10.dp),
                            verticalAlignment = Alignment.CenterVertically,
                            horizontalArrangement = Arrangement.spacedBy(8.dp)
                        ) {
                            Text(
                                text = when (targetLanguage.value.lowercase()) {
                                    "russian" -> "🇷🇺"
                                    "japanese" -> "🇯🇵"
                                    "chinese" -> "🇨🇳"
                                    "korean" -> "🇰🇷"
                                    else -> "🔤"
                                },
                                fontSize = 18.sp
                            )
                            Column {
                                Text(
                                    text = alphabetTitle,
                                    fontSize = 11.sp,
                                    fontWeight = FontWeight.Bold,
                                    color = MaterialTheme.colorScheme.onSecondaryContainer
                                )
                                Text(
                                    text = alphabetSubtitle,
                                    fontSize = 10.sp,
                                    color = MaterialTheme.colorScheme.onSecondaryContainer.copy(alpha = 0.8f),
                                    lineHeight = 14.sp
                                )
                            }
                        }
                    }
                }
            }
        }

        // CEFR Select
        item {
            Card(
                modifier = Modifier.fillMaxWidth(),
                colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surface),
                shape = RoundedCornerShape(16.dp),
                border = BorderStroke(1.dp, MaterialTheme.colorScheme.outlineVariant.copy(alpha = 0.5f))
            ) {
                Column(modifier = Modifier.padding(16.dp)) {
                    Text("CEFR Speaking Level (Poziom zaawansowania)", fontWeight = FontWeight.Bold, fontSize = 16.sp)
                    Spacer(modifier = Modifier.height(4.dp))
                    Text(
                        "Wybierz swój poziom CEFR. Dobór słownictwa, gramatyki oraz prędkość mówienia Lingo dostosują się automatycznie do wybranego poziomu.",
                        fontSize = 12.sp,
                        color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.6f),
                        lineHeight = 16.sp
                    )
                    Spacer(modifier = Modifier.height(14.dp))
                    FlowRow(
                        horizontalArrangement = Arrangement.spacedBy(8.dp),
                        verticalArrangement = Arrangement.spacedBy(8.dp)
                    ) {
                        cefrLevels.forEach { lvl ->
                            val cefrLabel = when (lvl) {
                                "A1" -> "A1 (Początkujący)"
                                "A2" -> "A2 (Podstawowy)"
                                "B1" -> "B1 (Średniozaawansowany)"
                                "B2" -> "B2 (Ponadpodstawowy)"
                                "C1" -> "C1 (Zaawansowany)"
                                "C2" -> "C2 (Biegły / Fluent)"
                                else -> lvl
                            }
                            FilterChip(
                                selected = cefrLevel.value == lvl,
                                onClick = {
                                    cefrLevel.value = lvl
                                    viewModel.updateGoal(
                                        targetLanguage = targetLanguage.value,
                                        cefrLevel = lvl,
                                        focusArea = focusArea.value,
                                        dailyMinutes = dailyMinutes.value
                                    )
                                    Toast.makeText(context, "Zapisano poziom CEFR: $lvl", Toast.LENGTH_SHORT).show()
                                },
                                label = { Text(cefrLabel, fontSize = 11.sp, fontWeight = FontWeight.Medium) },
                                colors = FilterChipDefaults.filterChipColors(
                                    selectedContainerColor = LingoPrimary,
                                    selectedLabelColor = Color.White
                                )
                            )
                        }
                    }

                    Spacer(modifier = Modifier.height(12.dp))
                    // Live CEFR behavior dynamic description
                    val (behaviorTitle, behaviorDesc) = when (cefrLevel.value) {
                        "A1" -> Pair("Tryb A1: Elementarne zwroty i wolne tempo", "Tutor używa 1-2 krótkich zdań, tylko podstawowych czasowników (teraźniejszość), a silnik TTS zwalnia tempo mowy. Zero trudnych form gramatycznych.")
                        "A2" -> Pair("Tryb A2: Proste dialogi sytuacyjne", "Zdania do 2 linijek, podstawowe czasy przeszłe i przyszłe, wspierające wskazówki i codzienne zwroty przetrwania.")
                        "B1" -> Pair("Tryb B1: Złożona konwersacja i opowiadanie", "Tutor formułuje 2-3 zdania złożone, wprowadza naturalne spójniki, dialogi sytuacyjne i wymaga dłuższych odpowiedzi od ucznia.")
                        "B2" -> Pair("Tryb B2: Płynność, idiomy i dyskusje", "Swobodna argumentacja, szerszy zasób idiomów, precyzyjne czasy i zaawansowane struktury gramatyczne.")
                        "C1" -> Pair("Tryb C1: Język akademicki i zawodowy", "Wysublimowane słownictwo, niuanse kulturowe, naturalne idiomy native speakerów i zaawansowana analiza stylu.")
                        "C2" -> Pair("Tryb C2: Poziom Native / Bilingual Master", "Pełna biegłość kulturowa, dwuznaczności, zaawansowane metafory, szybkie tempo mowy native speakera.")
                        else -> Pair("Dopasowanie CEFR", "Dostosowanie gramatyki i lektora do Twojego poziomu.")
                    }

                    Row(
                        modifier = Modifier
                            .fillMaxWidth()
                            .clip(RoundedCornerShape(10.dp))
                            .background(MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.35f))
                            .border(1.dp, MaterialTheme.colorScheme.outlineVariant.copy(alpha = 0.4f), RoundedCornerShape(10.dp))
                            .padding(10.dp),
                        verticalAlignment = Alignment.CenterVertically,
                        horizontalArrangement = Arrangement.spacedBy(10.dp)
                    ) {
                        Icon(
                            imageVector = Icons.Default.AutoAwesome,
                            contentDescription = null,
                            tint = LingoPrimary,
                            modifier = Modifier.size(20.dp)
                        )
                        Column {
                            Text(
                                text = behaviorTitle,
                                fontWeight = FontWeight.Bold,
                                fontSize = 12.sp,
                                color = MaterialTheme.colorScheme.onSurface
                            )
                            Spacer(modifier = Modifier.height(2.dp))
                            Text(
                                text = behaviorDesc,
                                fontSize = 11.sp,
                                color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.7f),
                                lineHeight = 15.sp
                            )
                        }
                    }
                }
            }
        }

        // Focus Area Select
        item {
            Card(
                modifier = Modifier.fillMaxWidth(),
                colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surface),
                shape = RoundedCornerShape(16.dp),
                border = BorderStroke(1.dp, MaterialTheme.colorScheme.outlineVariant.copy(alpha = 0.5f))
            ) {
                Column(modifier = Modifier.padding(16.dp)) {
                    Text(
                        text = "Speech Focus Area (Obszar koncentracji)",
                        fontWeight = FontWeight.Bold,
                        fontSize = 16.sp,
                        color = MaterialTheme.colorScheme.onSurface
                    )
                    Spacer(modifier = Modifier.height(4.dp))
                    Text(
                        text = "Wskaż aspekt języka, na który Lingo powinien położyć największy nacisk, udzielając wskazówek i analizując Twój głos.",
                        fontSize = 12.sp,
                        color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.6f),
                        lineHeight = 16.sp
                    )
                    Spacer(modifier = Modifier.height(16.dp))
                    
                    Column(verticalArrangement = Arrangement.spacedBy(10.dp)) {
                        focusAreas.forEach { area ->
                            val isSelected = focusArea.value == area.first
                            val icon = when (area.first) {
                                "General Fluency" -> Icons.Default.Chat
                                "Professional Speech" -> Icons.Default.Work
                                "Travel Dialogue" -> Icons.Default.Flight
                                "Grammar Practice" -> Icons.Default.Class
                                "Pronunciation Focus" -> Icons.Default.Mic
                                "Slang & Idioms" -> Icons.Default.Lightbulb
                                else -> Icons.Default.Chat
                            }
                            Row(
                                modifier = Modifier
                                    .fillMaxWidth()
                                    .clip(RoundedCornerShape(12.dp))
                                    .background(
                                        if (isSelected) LingoPrimary.copy(alpha = 0.08f)
                                        else MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.2f)
                                    )
                                    .border(
                                        width = 1.5.dp,
                                        color = if (isSelected) LingoPrimary else Color.Transparent,
                                        shape = RoundedCornerShape(12.dp)
                                    )
                                    .clickable {
                                        focusArea.value = area.first
                                        viewModel.updateGoal(
                                            targetLanguage = targetLanguage.value,
                                            cefrLevel = cefrLevel.value,
                                            focusArea = area.first,
                                            dailyMinutes = dailyMinutes.value
                                        )
                                        Toast.makeText(context, "Zapisano obszar: ${area.second}", Toast.LENGTH_SHORT).show()
                                    }
                                    .padding(12.dp),
                                verticalAlignment = Alignment.CenterVertically
                            ) {
                                Box(
                                    modifier = Modifier
                                        .size(36.dp)
                                        .clip(CircleShape)
                                        .background(
                                            if (isSelected) LingoPrimary.copy(alpha = 0.2f)
                                            else MaterialTheme.colorScheme.onSurface.copy(alpha = 0.05f)
                                        ),
                                    contentAlignment = Alignment.Center
                                ) {
                                    Icon(
                                        imageVector = icon,
                                        contentDescription = null,
                                        tint = if (isSelected) LingoPrimary else MaterialTheme.colorScheme.onSurface.copy(alpha = 0.6f),
                                        modifier = Modifier.size(18.dp)
                                    )
                                }
                                
                                Spacer(modifier = Modifier.width(12.dp))
                                
                                Column(modifier = Modifier.weight(1f)) {
                                    Text(
                                        text = area.second,
                                        fontWeight = FontWeight.Bold,
                                        fontSize = 14.sp,
                                        color = if (isSelected) LingoPrimary else MaterialTheme.colorScheme.onSurface
                                    )
                                    Spacer(modifier = Modifier.height(2.dp))
                                    Text(
                                        text = area.third,
                                        fontSize = 11.sp,
                                        color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.6f),
                                        lineHeight = 15.sp
                                    )
                                }
                                
                                Spacer(modifier = Modifier.width(8.dp))
                                
                                RadioButton(
                                    selected = isSelected,
                                    onClick = {
                                        focusArea.value = area.first
                                        viewModel.updateGoal(
                                            targetLanguage = targetLanguage.value,
                                            cefrLevel = cefrLevel.value,
                                            focusArea = area.first,
                                            dailyMinutes = dailyMinutes.value
                                        )
                                        Toast.makeText(context, "Zapisano obszar: ${area.second}", Toast.LENGTH_SHORT).show()
                                    },
                                    colors = RadioButtonDefaults.colors(
                                        selectedColor = LingoPrimary,
                                        unselectedColor = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.3f)
                                    )
                                )
                            }
                        }
                    }

                    Spacer(modifier = Modifier.height(14.dp))

                    // Interactive Dialogue Simulation Preview Card
                    val (sampleUserSpeech, sampleTutorReply, pedagogicalReason) = when {
                        cefrLevel.value in listOf("A1", "A2") && focusArea.value == "Travel Dialogue" -> Triple(
                            "Hola, quiero un café por favor.",
                            "¡Hola! Claro que sí, ¿lo quieres con leche o solo? También tenemos croissants recién hechos. ¿Te pongo uno?",
                            "Krótkie pytania, słownictwo kawiarniano-hotelowe, natychmiastowe zachęcenie do prostej odpowiedzi A1/A2."
                        )
                        cefrLevel.value in listOf("A1", "A2") && focusArea.value == "Grammar Practice" -> Triple(
                            "Yesterday I go to market.",
                            "Great try! Just remember: in the past we say 'I went'. Where did you go yesterday after the market?",
                            "Łagodna, natychmiastowa korekta czasu przeszłego bez przerywania swobody wypowiedzi."
                        )
                        cefrLevel.value in listOf("C1", "C2") && focusArea.value == "Professional Speech" -> Triple(
                            "We need to optimize the quarterly deliverable pipeline.",
                            "Indeed, aligning cross-functional stakeholders on key OKRs will mitigate downstream friction. Which risk assessment methodology are you prioritizing for this sprint?",
                            "Zaawansowany leksykon zarządczy B2B, konstrukcje analityczne i tempo native speakera."
                        )
                        cefrLevel.value in listOf("C1", "C2") && focusArea.value == "Slang & Idioms" -> Triple(
                            "I was really stressed before the presentation.",
                            "I hear you! It’s totally normal to have butterflies in your stomach, but once you bite the bullet, it’s smooth sailing. How did the team take it?",
                            "Naturalne idiomy native speakerów ('butterflies in stomach', 'bite the bullet') z płynnym podtrzymaniem wątku."
                        )
                        focusArea.value == "Pronunciation Focus" -> Triple(
                            "Bonjour, je voudrais réserver une table.",
                            "Parfait! Faites attention au son 'r' dans 'réserver' — faites-le vibrer doucement dans la gorge. Voulez-vous une table pour deux?",
                            "Specjalny akcent na fonetykę, artykulację i aparat mowy."
                        )
                        else -> Triple(
                            "Hello! How are you doing today?",
                            "Hey there! I'm doing fantastic, thanks for asking. How has your day been so far — anything interesting happen?",
                            "Zrównoważony, płynny dialog dostosowany do poziomu ${cefrLevel.value} i profilu ${focusArea.value}."
                        )
                    }

                    Column(
                        modifier = Modifier
                            .fillMaxWidth()
                            .clip(RoundedCornerShape(12.dp))
                            .background(LingoPrimary.copy(alpha = 0.05f))
                            .border(1.dp, LingoPrimary.copy(alpha = 0.2f), RoundedCornerShape(12.dp))
                            .padding(12.dp)
                    ) {
                        Row(
                            verticalAlignment = Alignment.CenterVertically,
                            horizontalArrangement = Arrangement.spacedBy(6.dp)
                        ) {
                            Icon(
                                imageVector = Icons.Default.ChatBubbleOutline,
                                contentDescription = null,
                                tint = LingoPrimary,
                                modifier = Modifier.size(16.dp)
                            )
                            Text(
                                text = "Symulacja Dialogu Live (${cefrLevel.value} • ${focusArea.value})",
                                fontSize = 12.sp,
                                fontWeight = FontWeight.Bold,
                                color = LingoPrimary
                            )
                        }
                        Spacer(modifier = Modifier.height(8.dp))
                        
                        // User utterance sample
                        Row(
                            modifier = Modifier
                                .fillMaxWidth()
                                .padding(start = 20.dp)
                                .clip(RoundedCornerShape(8.dp))
                                .background(MaterialTheme.colorScheme.surface)
                                .border(1.dp, MaterialTheme.colorScheme.outlineVariant.copy(alpha = 0.5f), RoundedCornerShape(8.dp))
                                .padding(8.dp),
                            horizontalArrangement = Arrangement.End
                        ) {
                            Text(
                                text = "Uczeń: „$sampleUserSpeech”",
                                fontSize = 11.sp,
                                fontStyle = androidx.compose.ui.text.font.FontStyle.Italic,
                                color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.8f)
                            )
                        }
                        
                        Spacer(modifier = Modifier.height(6.dp))
                        
                        // Tutor reply sample
                        Row(
                            modifier = Modifier
                                .fillMaxWidth()
                                .padding(end = 20.dp)
                                .clip(RoundedCornerShape(8.dp))
                                .background(LingoPrimary.copy(alpha = 0.12f))
                                .border(1.dp, LingoPrimary.copy(alpha = 0.3f), RoundedCornerShape(8.dp))
                                .padding(8.dp)
                        ) {
                            Text(
                                text = "Lingo: „$sampleTutorReply”",
                                fontSize = 11.sp,
                                fontWeight = FontWeight.Medium,
                                color = MaterialTheme.colorScheme.onSurface
                            )
                        }
                        
                        Spacer(modifier = Modifier.height(6.dp))
                        Text(
                            text = "Wskazówka dydaktyczna: $pedagogicalReason",
                            fontSize = 10.sp,
                            color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.6f),
                            lineHeight = 13.sp
                        )
                    }
                }
            }
        }

        // Daily Minutes Goal Select with Live Progress Indicator
        item {
            val startOfToday = remember {
                Calendar.getInstance().apply {
                    set(Calendar.HOUR_OF_DAY, 0)
                    set(Calendar.MINUTE, 0)
                    set(Calendar.SECOND, 0)
                    set(Calendar.MILLISECOND, 0)
                }.timeInMillis
            }
            val todaySessions = currentSessions.filter {
                it.timestamp >= startOfToday && it.language.equals(targetLanguage.value, ignoreCase = true)
            }
            val todaySeconds = todaySessions.sumOf { it.durationSeconds }
            val todayMinutes = todaySeconds / 60
            val targetMins = dailyMinutes.value
            val progressFraction = if (targetMins > 0) (todayMinutes.toFloat() / targetMins.toFloat()).coerceIn(0f, 1f) else 0f
            val isTargetReached = todayMinutes >= targetMins && targetMins > 0

            Card(
                modifier = Modifier.fillMaxWidth(),
                colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surface),
                shape = RoundedCornerShape(16.dp),
                border = BorderStroke(1.dp, MaterialTheme.colorScheme.outlineVariant.copy(alpha = 0.5f))
            ) {
                Column(modifier = Modifier.padding(16.dp)) {
                    Row(
                        modifier = Modifier.fillMaxWidth(),
                        horizontalArrangement = Arrangement.SpaceBetween,
                        verticalAlignment = Alignment.CenterVertically
                    ) {
                        Text("Daily Speaking Goal (Dzienny Cel Rozmowy)", fontWeight = FontWeight.Bold, fontSize = 15.sp)
                        Icon(
                            imageVector = Icons.Default.Timer,
                            contentDescription = null,
                            tint = LingoPrimary,
                            modifier = Modifier.size(20.dp)
                        )
                    }
                    Spacer(modifier = Modifier.height(10.dp))
                    FlowRow(
                        horizontalArrangement = Arrangement.spacedBy(8.dp),
                        verticalArrangement = Arrangement.spacedBy(8.dp)
                    ) {
                        minuteGoals.forEach { mins ->
                            FilterChip(
                                selected = dailyMinutes.value == mins,
                                onClick = {
                                    dailyMinutes.value = mins
                                    viewModel.updateGoal(
                                        targetLanguage = targetLanguage.value,
                                        cefrLevel = cefrLevel.value,
                                        focusArea = focusArea.value,
                                        dailyMinutes = mins
                                    )
                                    Toast.makeText(context, "Zapisano cel: $mins min", Toast.LENGTH_SHORT).show()
                                },
                                label = { Text("$mins Mins") },
                                colors = FilterChipDefaults.filterChipColors(
                                    selectedContainerColor = LingoPrimary,
                                    selectedLabelColor = Color.White
                                )
                            )
                        }
                    }

                    Spacer(modifier = Modifier.height(14.dp))

                    // Live Daily Goal Progress Card
                    Column(
                        modifier = Modifier
                            .fillMaxWidth()
                            .clip(RoundedCornerShape(12.dp))
                            .background(if (isTargetReached) Color(0xFFE8F5E9) else MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.4f))
                            .border(
                                1.dp,
                                if (isTargetReached) Color(0xFF81C784) else MaterialTheme.colorScheme.outlineVariant.copy(alpha = 0.4f),
                                RoundedCornerShape(12.dp)
                            )
                            .padding(12.dp)
                    ) {
                        Row(
                            modifier = Modifier.fillMaxWidth(),
                            horizontalArrangement = Arrangement.SpaceBetween,
                            verticalAlignment = Alignment.CenterVertically
                        ) {
                            Row(
                                verticalAlignment = Alignment.CenterVertically,
                                horizontalArrangement = Arrangement.spacedBy(6.dp)
                            ) {
                                Icon(
                                    imageVector = if (isTargetReached) Icons.Default.CheckCircle else Icons.Default.HourglassBottom,
                                    contentDescription = null,
                                    tint = if (isTargetReached) Color(0xFF2E7D32) else LingoPrimary,
                                    modifier = Modifier.size(16.dp)
                                )
                                Text(
                                    text = if (isTargetReached) "Cel dzienny zrealizowany!" else "Postęp dzisiejszego celu",
                                    fontSize = 12.sp,
                                    fontWeight = FontWeight.Bold,
                                    color = if (isTargetReached) Color(0xFF2E7D32) else MaterialTheme.colorScheme.onSurface
                                )
                            }
                            Text(
                                text = "$todayMinutes / $targetMins min (${(progressFraction * 100).toInt()}%)",
                                fontSize = 11.sp,
                                fontWeight = FontWeight.SemiBold,
                                color = if (isTargetReached) Color(0xFF2E7D32) else LingoPrimary
                            )
                        }

                        Spacer(modifier = Modifier.height(8.dp))

                        LinearProgressIndicator(
                            progress = { progressFraction },
                            modifier = Modifier
                                .fillMaxWidth()
                                .height(8.dp)
                                .clip(RoundedCornerShape(4.dp)),
                            color = if (isTargetReached) Color(0xFF2E7D32) else LingoPrimary,
                            trackColor = MaterialTheme.colorScheme.outlineVariant.copy(alpha = 0.3f)
                        )

                        Spacer(modifier = Modifier.height(6.dp))
                        Text(
                            text = if (isTargetReached) {
                                "Świetna robota! Osiągnąłeś dzisiejszą normę aktywnej mowy w języku ${targetLanguage.value}."
                            } else {
                                "Pozostało jeszcze ${targetMins - todayMinutes} min ćwiczeń konwersacyjnych, aby zrealizować dzisiejszą normę."
                            },
                            fontSize = 10.sp,
                            color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.65f),
                            lineHeight = 13.sp
                        )
                    }
                }
            }
        }

        // Voice Selection Section (Lektor & Profile Głosowe)
        item {
            val selectedVoicePref by viewModel.selectedVoice.collectAsStateWithLifecycle()
            var playingVoicePreview by remember { mutableStateOf<String?>(null) }

            // Sync speaking state
            LaunchedEffect(speechHelper.isSpeaking) {
                if (!speechHelper.isSpeaking) {
                    playingVoicePreview = null
                }
            }

            Card(
                modifier = Modifier.fillMaxWidth(),
                colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surface),
                shape = RoundedCornerShape(20.dp),
                border = BorderStroke(1.dp, MaterialTheme.colorScheme.outlineVariant.copy(alpha = 0.5f))
            ) {
                Column(modifier = Modifier.padding(16.dp)) {
                    Row(
                        modifier = Modifier.fillMaxWidth(),
                        horizontalArrangement = Arrangement.SpaceBetween,
                        verticalAlignment = Alignment.CenterVertically
                    ) {
                        Row(
                            verticalAlignment = Alignment.CenterVertically,
                            horizontalArrangement = Arrangement.spacedBy(8.dp)
                        ) {
                            Box(
                                modifier = Modifier
                                    .size(36.dp)
                                    .clip(CircleShape)
                                    .background(LingoPrimary.copy(alpha = 0.12f)),
                                contentAlignment = Alignment.Center
                            ) {
                                Icon(
                                    imageVector = Icons.Default.RecordVoiceOver,
                                    contentDescription = null,
                                    tint = LingoPrimary,
                                    modifier = Modifier.size(20.dp)
                                )
                            }
                            Column {
                                Text(
                                    text = "Profil Głosu Lektora (Voice AI)",
                                    fontWeight = FontWeight.Bold,
                                    fontSize = 16.sp,
                                    color = MaterialTheme.colorScheme.onSurface
                                )
                                Text(
                                    text = "Unikatowe barwy i osobowości lektorskie",
                                    fontSize = 11.sp,
                                    color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.6f)
                                )
                            }
                        }
                    }

                    Spacer(modifier = Modifier.height(14.dp))

                    data class VoiceItem(
                        val id: String,
                        val title: String,
                        val genderBadge: String,
                        val genderColor: Color,
                        val description: String,
                        val icon: androidx.compose.ui.graphics.vector.ImageVector,
                        val sampleGreeting: String
                    )

                    val currentLang = targetLanguage.value.lowercase()
                    val voicesList = listOf(
                        VoiceItem(
                            id = "Sulafat",
                            title = "Sulafat • Warm & Calm",
                            genderBadge = "🌿 GŁOS ŻEŃSKI • CIEPŁY I SPOKOJNY",
                            genderColor = Color(0xFFF43F5E),
                            description = "Ciepły, niezwykle kojący i spokojny głos native speakerki obniżający barierę językową i stres. Idealny do uważnego słuchania i powtórek.",
                            icon = Icons.Default.Spa,
                            sampleGreeting = when (currentLang) {
                                "spanish" -> "Hola. Respira hondo. Soy Sulafat. Aprenderemos con total calma, paso a paso y a tu propio ritmo."
                                "french" -> "Bonjour. Détends-toi. Je suis Sulafat. Nous allons apprendre sereinement et sans aucun stress."
                                "german" -> "Hallo. Nimm dir Zeit. Ich bin Sulafat. Wir lernen ganz entspannt und in deinem eigenen Tempo."
                                "italian" -> "Ciao. Respira con calma. Sono Sulafat. Impareremo insieme passo dopo passo con serenità."
                                "english" -> "Hello. Take a relaxed breath. I'm Sulafat. We will practice gently and master the language at your own pace."
                                else -> "Hello, I am Sulafat. Let's learn and practice calmly at your own comfortable pace."
                            }
                        ),
                        VoiceItem(
                            id = "Erinome",
                            title = "Erinome • Clear & Precise",
                            genderBadge = "🎓 GŁOS MĘSKI • PRECYZYJNY",
                            genderColor = Color(0xFF3B82F6),
                            description = "Wyrazisty, krystalicznie czysty i precyzyjnie artykułowany głos męski lektora. Idealny do nauki struktur gramatycznych i poprawnej wymowy sylab.",
                            icon = Icons.Default.School,
                            sampleGreeting = when (currentLang) {
                                "spanish" -> "Hola. Soy Erinome. Nos enfocaremos en la gramática exacta y la articulación perfecta de cada palabra."
                                "french" -> "Bonjour. Je suis Erinome. Nous allons perfectionner votre dictionnaire, votre grammaire et votre diction."
                                "german" -> "Hallo. Ich bin Erinome. Wir konzentrieren uns heute auf präzise Aussprache und fehlerfreie Grammatik."
                                "italian" -> "Ciao. Sono Erinome. Lavoreremo sulla pronuncia esatta e sulla struttura corretta delle frasi."
                                "english" -> "Hello. I am Erinome. We will focus on precise articulation, clear grammar structures, and flawless pronunciation."
                                else -> "Hello, I am Erinome. Let's practice structured grammar and clear pronunciation step by step."
                            }
                        ),
                        VoiceItem(
                            id = "Despina",
                            title = "Despina • Smooth & Natural",
                            genderBadge = "✨ GŁOS ŻEŃSKI • NATURALNY",
                            genderColor = Color(0xFF10B981),
                            description = "Aksamitny, melodyjny i wyjątkowo naturalny głos kobiecy o doskonałej płynności. Doskonały do oswajania się z autentycznym, codziennym tempem rozmowy.",
                            icon = Icons.Default.AutoAwesome,
                            sampleGreeting = when (currentLang) {
                                "spanish" -> "¡Hola! Qué alegría saludarte. Soy Despina. Disfrutemos de una conversación súper fluida y muy natural hoy."
                                "french" -> "Salut ! Ravi de te parler. Je suis Despina. Pratiquons une conversation fluide, vivante et spontanée."
                                "german" -> "Hallo! Schön dich zu hören. Ich bin Despina. Lass uns ein ganz natürliches und fließendes Gespräch führen."
                                "italian" -> "Ciao! Che bello sentirti. Sono Despina. Facciamo una conversazione piacevole, fluida e del tutto naturale."
                                "english" -> "Hi there! Wonderful to meet you. I'm Despina. Let's have a highly natural and smooth conversation today."
                                else -> "Hello! Great to hear you. I am Despina. Let's practice a fluid and completely natural real-world conversation."
                            }
                        ),
                        VoiceItem(
                            id = "Achird",
                            title = "Achird • Friendly & Conversational",
                            genderBadge = "💬 GŁOS MĘSKI • TOWARZYSKI",
                            genderColor = Color(0xFFD97706),
                            description = "Ciepły, charyzmatyczny i niezwykle przyjacielski głos męski o swobodnej intonacji. Przygotuje Cię do spontanicznych dialogów i pewnego mówienia w gronie znajomych.",
                            icon = Icons.Default.Face,
                            sampleGreeting = when (currentLang) {
                                "spanish" -> "¡Buenas! ¿Qué tal todo? Soy Achird. Vamos a charlar de forma súper amigable y pasar un rato genial hablando."
                                "french" -> "Salut toi ! Comment ça va ? Je suis Achird. Discutons en toute décontraction, comme deux bons amis !"
                                "german" -> "Hi! Wie geht's dir? Ich bin Achird. Lass uns einfach ganz locker quatschen und unsere Kenntnisse anwenden."
                                "italian" -> "Ehi, ciao! Come va? Sono Achird. Facciamo una chiacchierata amichevole e divertente in totale relax."
                                "english" -> "Hey there! How's it going? I'm Achird. Let's have a friendly, casual chat and build your confidence together!"
                                else -> "Hey! Nice to meet you. I am Achird. Let's have a friendly, casual talk to practice active communication."
                            }
                        )
                    )

                    Column(verticalArrangement = Arrangement.spacedBy(10.dp)) {
                        // CEFR-aligned speed indicator
                        val suggestedSpeed = TutorSpeechHelper.getSuggestedSpeedForCefr(cefrLevel.value)
                        Row(
                            modifier = Modifier
                                .fillMaxWidth()
                                .clip(RoundedCornerShape(8.dp))
                                .background(LingoPrimary.copy(alpha = 0.07f))
                                .border(1.dp, LingoPrimary.copy(alpha = 0.2f), RoundedCornerShape(8.dp))
                                .padding(horizontal = 10.dp, vertical = 6.dp),
                            verticalAlignment = Alignment.CenterVertically,
                            horizontalArrangement = Arrangement.SpaceBetween
                        ) {
                            Row(
                                verticalAlignment = Alignment.CenterVertically,
                                horizontalArrangement = Arrangement.spacedBy(6.dp)
                            ) {
                                Icon(
                                    imageVector = Icons.Default.Speed,
                                    contentDescription = null,
                                    tint = LingoPrimary,
                                    modifier = Modifier.size(16.dp)
                                )
                                Text(
                                    text = "Auto-Sync tempa z CEFR: ${cefrLevel.value} (${String.format(java.util.Locale.US, "%.2fx", suggestedSpeed)})",
                                    fontSize = 11.sp,
                                    fontWeight = FontWeight.SemiBold,
                                    color = LingoPrimary
                                )
                            }
                            Text(
                                text = "Aktywne",
                                fontSize = 10.sp,
                                fontWeight = FontWeight.Bold,
                                color = Color(0xFF2E7D32)
                            )
                        }

                        voicesList.forEach { voice ->
                            val isSelected = selectedVoicePref.equals(voice.id, ignoreCase = true)
                            val isPlaying = playingVoicePreview == voice.id && speechHelper.isSpeaking

                            Surface(
                                modifier = Modifier
                                    .fillMaxWidth()
                                    .clip(RoundedCornerShape(14.dp))
                                    .clickable {
                                        viewModel.saveVoice(voice.id)
                                        speechHelper.updateSelectedVoice(voice.id)
                                    },
                                shape = RoundedCornerShape(14.dp),
                                color = if (isSelected) LingoPrimary.copy(alpha = 0.08f)
                                        else MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.25f),
                                border = BorderStroke(
                                    width = if (isSelected) 1.8.dp else 1.dp,
                                    color = if (isSelected) LingoPrimary else MaterialTheme.colorScheme.outlineVariant.copy(alpha = 0.35f)
                                )
                            ) {
                                Column(
                                    modifier = Modifier.padding(14.dp),
                                    verticalArrangement = Arrangement.spacedBy(10.dp)
                                ) {
                                    // Header: Avatar, Name + Badge, Selection Indicator
                                    Row(
                                        modifier = Modifier.fillMaxWidth(),
                                        verticalAlignment = Alignment.CenterVertically
                                    ) {
                                        Box(
                                            modifier = Modifier
                                                .size(42.dp)
                                                .clip(CircleShape)
                                                .background(
                                                    if (isSelected) LingoPrimary.copy(alpha = 0.2f)
                                                    else voice.genderColor.copy(alpha = 0.15f)
                                                ),
                                            contentAlignment = Alignment.Center
                                        ) {
                                            Icon(
                                                imageVector = voice.icon,
                                                contentDescription = null,
                                                tint = if (isSelected) LingoPrimary else voice.genderColor,
                                                modifier = Modifier.size(22.dp)
                                            )
                                        }

                                        Spacer(modifier = Modifier.width(12.dp))

                                        Column(modifier = Modifier.weight(1f)) {
                                            Text(
                                                text = voice.title,
                                                fontWeight = FontWeight.Bold,
                                                fontSize = 15.sp,
                                                color = if (isSelected) LingoPrimary else MaterialTheme.colorScheme.onSurface
                                            )
                                            Spacer(modifier = Modifier.height(2.dp))
                                            Surface(
                                                color = voice.genderColor.copy(alpha = 0.12f),
                                                shape = RoundedCornerShape(4.dp)
                                            ) {
                                                Text(
                                                    text = voice.genderBadge,
                                                    fontSize = 10.sp,
                                                    fontWeight = FontWeight.Bold,
                                                    color = voice.genderColor,
                                                    modifier = Modifier.padding(horizontal = 6.dp, vertical = 2.dp)
                                                )
                                            }
                                        }

                                        // Selection Radio Badge
                                        Box(
                                            modifier = Modifier
                                                .size(24.dp)
                                                .clip(CircleShape)
                                                .background(
                                                    if (isSelected) LingoPrimary else Color.Transparent
                                                )
                                                .border(
                                                    width = 2.dp,
                                                    color = if (isSelected) LingoPrimary else MaterialTheme.colorScheme.onSurface.copy(alpha = 0.3f),
                                                    shape = CircleShape
                                                ),
                                            contentAlignment = Alignment.Center
                                        ) {
                                            if (isSelected) {
                                                Icon(
                                                    imageVector = Icons.Default.Check,
                                                    contentDescription = "Wybrany",
                                                    tint = Color.White,
                                                    modifier = Modifier.size(14.dp)
                                                )
                                            }
                                        }
                                    }

                                    // Description
                                    Text(
                                        text = voice.description,
                                        fontSize = 12.sp,
                                        color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.75f),
                                        lineHeight = 16.5.sp
                                    )

                                    // Bottom Action: Test Voice Audio Sample
                                    Row(
                                        modifier = Modifier.fillMaxWidth(),
                                        horizontalArrangement = Arrangement.SpaceBetween,
                                        verticalAlignment = Alignment.CenterVertically
                                    ) {
                                        OutlinedButton(
                                            onClick = {
                                                if (isPlaying) {
                                                    speechHelper.stop()
                                                    playingVoicePreview = null
                                                } else {
                                                    speechHelper.stop()
                                                    playingVoicePreview = voice.id
                                                    speechHelper.speakPreview(
                                                        text = voice.sampleGreeting,
                                                        languageName = targetLanguage.value,
                                                        voiceProfile = voice.id,
                                                        cefrLevel = cefrLevel.value
                                                    )
                                                }
                                            },
                                            modifier = Modifier.height(36.dp),
                                            shape = RoundedCornerShape(8.dp),
                                            colors = ButtonDefaults.outlinedButtonColors(
                                                containerColor = if (isPlaying) voice.genderColor.copy(alpha = 0.15f) else MaterialTheme.colorScheme.surface,
                                                contentColor = if (isPlaying) voice.genderColor else MaterialTheme.colorScheme.onSurface
                                            ),
                                            border = BorderStroke(
                                                width = 1.dp,
                                                color = if (isPlaying) voice.genderColor else MaterialTheme.colorScheme.outlineVariant
                                            ),
                                            contentPadding = PaddingValues(horizontal = 12.dp, vertical = 4.dp)
                                        ) {
                                            Icon(
                                                imageVector = if (isPlaying) Icons.Default.Stop else Icons.Default.PlayArrow,
                                                contentDescription = null,
                                                modifier = Modifier.size(16.dp),
                                                tint = if (isPlaying) voice.genderColor else LingoPrimary
                                            )
                                            Spacer(modifier = Modifier.width(6.dp))
                                            Text(
                                                text = if (isPlaying) "Zatrzymaj próbkę" else "Odsłuchaj barwę głosu",
                                                fontSize = 12.sp,
                                                fontWeight = FontWeight.SemiBold
                                            )
                                        }

                                        if (isSelected) {
                                            Text(
                                                text = "● Aktywny lektor",
                                                fontSize = 11.sp,
                                                fontWeight = FontWeight.Bold,
                                                color = LingoPrimary
                                            )
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }

        // AI Model Configuration Section
        item {
            data class ModelInfo(
                val id: String,
                val name: String,
                val badge: String,
                val badgeColor: Color,
                val description: String,
                val latencyText: String
            )

            val modelsInfo = listOf(
                ModelInfo(
                    id = "gemini-3.5-flash",
                    name = "Gemini 3.5 Flash",
                    badge = "⚡ REKOMENDOWANY DO CZATU I ACCELERATORA",
                    badgeColor = Color(0xFF2E7D32),
                    description = "Ultra-szybkie odpowiedzi, perfekcyjna gramatyka, bogate idiomy i błyskawiczne generowanie mini-map myśli.",
                    latencyText = "< 400ms • Błyskawiczny czas reakcji"
                ),
                ModelInfo(
                    id = "gemini-3.1-flash-lite-preview",
                    name = "Gemini 3.1 Flash Lite",
                    badge = "🚀 EKSTREMALNIE SZYBKI (SUB-SECOND)",
                    badgeColor = Color(0xFFE65100),
                    description = "Maksymalna prędkość generowania i najmniejsze zużycie tokenów. Doskonały do natychmiastowych podpowiedzi.",
                    latencyText = "< 250ms • Najniższe opóźnienie"
                ),
                ModelInfo(
                    id = "gemini-3.1-pro-preview",
                    name = "Gemini 3.1 Pro Preview",
                    badge = "🧠 ZAAWANSOWANA NEURODYDAKTYKA",
                    badgeColor = Color(0xFF1565C0),
                    description = "Zaawansowane wnioskowanie, głęboka analiza fonetyczna i rozbudowane wyjaśnienia językowe.",
                    latencyText = "~800ms • Najwyższa precyzja"
                )
            )

            Card(
                modifier = Modifier.fillMaxWidth(),
                colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surface),
                shape = RoundedCornerShape(16.dp),
                border = BorderStroke(1.dp, MaterialTheme.colorScheme.outlineVariant.copy(alpha = 0.5f))
            ) {
                Column(modifier = Modifier.padding(14.dp)) {
                    Row(
                        modifier = Modifier.fillMaxWidth(),
                        horizontalArrangement = Arrangement.SpaceBetween,
                        verticalAlignment = Alignment.CenterVertically
                    ) {
                        Text(
                            text = "Wybór Modelu AI (LLM Architecture)",
                            fontWeight = FontWeight.Bold,
                            fontSize = 15.sp,
                            color = MaterialTheme.colorScheme.onSurface
                        )
                        Icon(
                            imageVector = Icons.Default.Memory,
                            contentDescription = null,
                            tint = LingoPrimary,
                            modifier = Modifier.size(18.dp)
                        )
                    }
                    Spacer(modifier = Modifier.height(4.dp))
                    Text(
                        text = "Wybierz preferowany model językowy Gemini dopasowany do Twojego stylu nauki.",
                        fontSize = 11.sp,
                        color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.6f),
                        lineHeight = 15.sp
                    )
                    Spacer(modifier = Modifier.height(10.dp))

                    Column(verticalArrangement = Arrangement.spacedBy(8.dp)) {
                        modelsInfo.forEach { mi ->
                            val isSelected = modelText.value == mi.id
                            Surface(
                                modifier = Modifier
                                    .fillMaxWidth()
                                    .clip(RoundedCornerShape(12.dp))
                                    .clickable {
                                        modelText.value = mi.id
                                        viewModel.saveModel(mi.id)
                                    },
                                shape = RoundedCornerShape(12.dp),
                                color = if (isSelected) LingoPrimary.copy(alpha = 0.08f) else MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.25f),
                                border = BorderStroke(
                                    width = if (isSelected) 1.5.dp else 1.dp,
                                    color = if (isSelected) LingoPrimary else MaterialTheme.colorScheme.outlineVariant.copy(alpha = 0.35f)
                                )
                            ) {
                                Column(modifier = Modifier.padding(10.dp)) {
                                    Row(
                                        modifier = Modifier.fillMaxWidth(),
                                        verticalAlignment = Alignment.CenterVertically,
                                        horizontalArrangement = Arrangement.SpaceBetween
                                    ) {
                                        Row(
                                            verticalAlignment = Alignment.CenterVertically,
                                            horizontalArrangement = Arrangement.spacedBy(6.dp),
                                            modifier = Modifier.weight(1f)
                                        ) {
                                            RadioButton(
                                                selected = isSelected,
                                                onClick = {
                                                    modelText.value = mi.id
                                                    viewModel.saveModel(mi.id)
                                                },
                                                colors = RadioButtonDefaults.colors(
                                                    selectedColor = LingoPrimary,
                                                    unselectedColor = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.3f)
                                                ),
                                                modifier = Modifier.size(20.dp)
                                            )
                                            Text(
                                                text = mi.name,
                                                fontWeight = FontWeight.Bold,
                                                fontSize = 12.5.sp,
                                                color = if (isSelected) LingoPrimary else MaterialTheme.colorScheme.onSurface
                                            )
                                        }
                                        Surface(
                                            color = mi.badgeColor.copy(alpha = 0.12f),
                                            shape = RoundedCornerShape(4.dp)
                                        ) {
                                            Text(
                                                text = mi.badge,
                                                fontSize = 8.5.sp,
                                                fontWeight = FontWeight.Bold,
                                                color = mi.badgeColor,
                                                modifier = Modifier.padding(horizontal = 5.dp, vertical = 2.dp)
                                            )
                                        }
                                    }
                                    Spacer(modifier = Modifier.height(4.dp))
                                    Text(
                                        text = mi.description,
                                        fontSize = 10.5.sp,
                                        color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.7f),
                                        lineHeight = 14.sp,
                                        modifier = Modifier.padding(start = 26.dp)
                                    )
                                    Spacer(modifier = Modifier.height(2.dp))
                                    Text(
                                        text = mi.latencyText,
                                        fontSize = 9.5.sp,
                                        fontWeight = FontWeight.SemiBold,
                                        color = mi.badgeColor,
                                        modifier = Modifier.padding(start = 26.dp)
                                    )
                                }
                            }
                        }
                    }

                    Spacer(modifier = Modifier.height(10.dp))

                    OutlinedTextField(
                        value = modelText.value,
                        onValueChange = { 
                            modelText.value = it 
                            viewModel.saveModel(it)
                        },
                        label = { Text("Własny model ID") },
                        placeholder = { Text("np. gemini-3.5-flash") },
                        singleLine = true,
                        modifier = Modifier
                            .fillMaxWidth()
                            .testTag("custom_model_input"),
                        shape = RoundedCornerShape(10.dp),
                        colors = OutlinedTextFieldDefaults.colors(
                            focusedBorderColor = LingoPrimary,
                            focusedLabelColor = LingoPrimary,
                            unfocusedBorderColor = MaterialTheme.colorScheme.outlineVariant.copy(alpha = 0.5f)
                        )
                    )
                }
