        }

        // API Key Configuration Section
        item {
            val uriHandler = LocalUriHandler.current
            Card(
                modifier = Modifier.fillMaxWidth(),
                colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surface),
                shape = RoundedCornerShape(16.dp),
                border = BorderStroke(1.dp, MaterialTheme.colorScheme.outlineVariant)
            ) {
                Column(modifier = Modifier.padding(16.dp)) {
                    Row(
                        modifier = Modifier.fillMaxWidth(),
                        horizontalArrangement = Arrangement.SpaceBetween,
                        verticalAlignment = Alignment.CenterVertically
                    ) {
                        Text(
                            text = "Konfiguracja Klucza API",
                            fontWeight = FontWeight.Bold,
                            fontSize = 15.sp,
                            color = MaterialTheme.colorScheme.onSurface
                        )
                        Icon(
                            imageVector = Icons.Default.Key,
                            contentDescription = null,
                            tint = LingoPrimary,
                            modifier = Modifier.size(20.dp)
                        )
                    }
                    Spacer(modifier = Modifier.height(6.dp))
                    Text(
                        text = "Wprowadź swój klucz API Gemini, aby połączyć się z inteligentnym lektorem. Klucz jest przechowywany bezpiecznie wyłącznie na Twoim urządzeniu.",
                        fontSize = 12.sp,
                        color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.6f),
                        lineHeight = 16.sp
                    )
                    Spacer(modifier = Modifier.height(10.dp))

                    // API Key active source message
                    val sysKey = com.example.BuildConfig.GEMINI_API_KEY
                    val hasSysKey = sysKey.isNotEmpty() && sysKey != "MY_GEMINI_API_KEY"
                    val activeKeyInfo = if (apiKeyText.value.trim().isNotEmpty()) {
                        "Używasz klucza użytkownika (wprowadzonego ręcznie)"
                    } else if (hasSysKey) {
                        "Używasz klucza systemowego (AI Studio Secrets)"
                    } else {
                        "⚠️ Brak aktywnego klucza API (wprowadź go poniżej)"
                    }

                    Text(
                        text = activeKeyInfo,
                        fontSize = 11.sp,
                        fontWeight = FontWeight.SemiBold,
                        color = if (apiKeyText.value.trim().isEmpty() && !hasSysKey) MaterialTheme.colorScheme.error else LingoPrimary,
                        modifier = Modifier.padding(bottom = 8.dp)
                    )

                    // Format Validation Notice
                    val trimmedKey = apiKeyText.value.trim()
                    val isSuspiciousKey = trimmedKey.isNotEmpty() && !trimmedKey.startsWith("AIzaSy")
                    if (isSuspiciousKey) {
                        Card(
                            colors = CardDefaults.cardColors(containerColor = Color(0xFFFFF3E0)),
                            shape = RoundedCornerShape(10.dp),
                            border = BorderStroke(1.dp, Color(0xFFFFB74D)),
                            modifier = Modifier
                                .fillMaxWidth()
                                .padding(bottom = 10.dp)
                        ) {
                            Row(
                                modifier = Modifier.padding(10.dp),
                                horizontalArrangement = Arrangement.spacedBy(8.dp),
                                verticalAlignment = Alignment.CenterVertically
                            ) {
                                Icon(
                                    imageVector = Icons.Default.Warning,
                                    contentDescription = null,
                                    tint = Color(0xFFE65100),
                                    modifier = Modifier.size(18.dp)
                                )
                                Text(
                                    text = "Wskazówka: Klucze Google Gemini zaczynają się zazwyczaj od 'AIzaSy...'. Upewnij się, że wkleiłeś poprawny klucz Gemini z AI Studio.",
                                    fontSize = 11.sp,
                                    color = Color(0xFFE65100),
                                    lineHeight = 14.sp
                                )
                            }
                        }
                    }

                    OutlinedTextField(
                        value = apiKeyText.value,
                        onValueChange = { 
                            apiKeyText.value = it 
                            viewModel.clearTestConnectionResult()
                        },
                        label = { Text("Klucz API Gemini") },
                        placeholder = { Text("AIzaSy...") },
                        singleLine = true,
                        visualTransformation = if (isApiKeyVisible || apiKeyText.value.isEmpty()) VisualTransformation.None else PasswordVisualTransformation(),
                        trailingIcon = {
                            if (apiKeyText.value.isNotEmpty()) {
                                IconButton(onClick = { isApiKeyVisible = !isApiKeyVisible }) {
                                    Icon(
                                        imageVector = if (isApiKeyVisible) Icons.Default.VisibilityOff else Icons.Default.Visibility,
                                        contentDescription = if (isApiKeyVisible) "Ukryj klucz" else "Pokaż klucz",
                                        tint = MaterialTheme.colorScheme.onSurfaceVariant
                                    )
                                }
                            }
                        },
                        modifier = Modifier
                            .fillMaxWidth()
                            .testTag("api_key_input"),
                        shape = RoundedCornerShape(12.dp),
                        colors = OutlinedTextFieldDefaults.colors(
                            focusedBorderColor = LingoPrimary,
                            focusedLabelColor = LingoPrimary,
                            unfocusedBorderColor = MaterialTheme.colorScheme.outlineVariant
                        )
                    )

                    if (apiKeyText.value.isNotEmpty()) {
                        Spacer(modifier = Modifier.height(8.dp))
                        OutlinedButton(
                            onClick = {
                                apiKeyText.value = ""
                                viewModel.clearApiKey()
                                Toast.makeText(context, "Klucz usunięty. Przywrócono domyślny klucz systemowy.", Toast.LENGTH_SHORT).show()
                            },
                            modifier = Modifier.fillMaxWidth(),
                            shape = RoundedCornerShape(12.dp),
                            colors = ButtonDefaults.outlinedButtonColors(contentColor = MaterialTheme.colorScheme.error),
                            border = BorderStroke(1.dp, MaterialTheme.colorScheme.error.copy(alpha = 0.5f))
                        ) {
                            Icon(
                                imageVector = Icons.Default.DeleteOutline,
                                contentDescription = null,
                                modifier = Modifier.size(16.dp)
                            )
                            Spacer(modifier = Modifier.width(6.dp))
                            Text(
                                text = "Wyczyść klucz i przywróć systemowy",
                                fontSize = 11.sp,
                                fontWeight = FontWeight.SemiBold
                            )
                        }
                    }

                    Spacer(modifier = Modifier.height(12.dp))

                    Row(
                        modifier = Modifier.fillMaxWidth(),
                        horizontalArrangement = Arrangement.spacedBy(8.dp)
                    ) {
                        // Get Key Button
                        Button(
                            onClick = { uriHandler.openUri("https://aistudio.google.com/app/apikey") },
                            colors = ButtonDefaults.buttonColors(
                                containerColor = MaterialTheme.colorScheme.secondaryContainer,
                                contentColor = MaterialTheme.colorScheme.onSecondaryContainer
                            ),
                            modifier = Modifier.weight(1.5f),
                            shape = RoundedCornerShape(12.dp),
                            contentPadding = PaddingValues(vertical = 12.dp)
                        ) {
                            Icon(
                                imageVector = Icons.Default.OpenInNew,
                                contentDescription = null,
                                modifier = Modifier.size(16.dp)
                            )
                            Spacer(modifier = Modifier.width(6.dp))
                            Text(
                                text = "Wygeneruj klucz",
                                fontSize = 11.sp,
                                fontWeight = FontWeight.SemiBold
                            )
                        }

                        // Test Connection Button
                        Button(
                            onClick = { viewModel.testConnection(apiKeyText.value) },
                            enabled = !isTesting,
                            colors = ButtonDefaults.buttonColors(
                                containerColor = if (isTesting) MaterialTheme.colorScheme.surfaceVariant else MaterialTheme.colorScheme.primaryContainer,
                                contentColor = if (isTesting) MaterialTheme.colorScheme.onSurfaceVariant else MaterialTheme.colorScheme.onPrimaryContainer
                            ),
                            modifier = Modifier.weight(1.8f),
                            shape = RoundedCornerShape(12.dp),
                            contentPadding = PaddingValues(vertical = 12.dp)
                        ) {
                            if (isTesting) {
                                CircularProgressIndicator(
                                    modifier = Modifier.size(16.dp),
                                    strokeWidth = 2.dp,
                                    color = MaterialTheme.colorScheme.primary
                                )
                            } else {
                                Icon(
                                    imageVector = Icons.Default.NetworkCheck,
                                    contentDescription = null,
                                    modifier = Modifier.size(16.dp)
                                )
                            }
                            Spacer(modifier = Modifier.width(6.dp))
                            Text(
                                text = if (isTesting) "Łączenie..." else "Testuj połączenie",
                                fontSize = 11.sp,
                                fontWeight = FontWeight.SemiBold
                            )
                        }
                    }

                    // Test Results Display
                    if (testResult != null) {
                        Spacer(modifier = Modifier.height(12.dp))
                        val isSuccess = testResult!!.startsWith("SUCCESS:")
                        val displayMsg = testResult!!.substringAfter("SUCCESS:").substringAfter("ERROR:")

                        Card(
                            modifier = Modifier.fillMaxWidth(),
                            colors = CardDefaults.cardColors(
                                containerColor = if (isSuccess) Color(0xFFE8F5E9) else Color(0xFFFFEBEE)
                            ),
                            shape = RoundedCornerShape(12.dp),
                            border = BorderStroke(
                                1.dp,
                                if (isSuccess) Color(0xFF81C784) else Color(0xFFE57373)
                            )
                        ) {
                            Row(
                                modifier = Modifier.padding(12.dp),
                                horizontalArrangement = Arrangement.spacedBy(8.dp),
                                verticalAlignment = Alignment.CenterVertically
                            ) {
                                Icon(
                                    imageVector = if (isSuccess) Icons.Default.CheckCircle else Icons.Default.Error,
                                    contentDescription = null,
                                    tint = if (isSuccess) Color(0xFF2E7D32) else Color(0xFFC62828),
                                    modifier = Modifier.size(20.dp)
                                )
                                Text(
                                    text = displayMsg,
                                    fontSize = 12.sp,
                                    color = if (isSuccess) Color(0xFF2E7D32) else Color(0xFFC62828),
                                    fontWeight = FontWeight.Medium,
                                    lineHeight = 16.sp,
                                    modifier = Modifier.weight(1f)
                                )
                                IconButton(
                                    onClick = { viewModel.clearTestConnectionResult() },
                                    modifier = Modifier.size(20.dp)
                                ) {
                                    Icon(
                                        imageVector = Icons.Default.Close,
                                        contentDescription = "Clear",
                                        tint = if (isSuccess) Color(0xFF2E7D32) else Color(0xFFC62828),
                                        modifier = Modifier.size(14.dp)
                                    )
                                }
                            }
                        }
                    }
                }
            }
        }

        // Save preferences
        item {
            Button(
                onClick = {
                    viewModel.updateGoal(
                        targetLanguage = targetLanguage.value,
                        cefrLevel = cefrLevel.value,
                        focusArea = focusArea.value,
                        dailyMinutes = dailyMinutes.value
                    )
                    viewModel.saveModel(modelText.value)
                    viewModel.saveApiKey(apiKeyText.value)
                    Toast.makeText(context, "Zapisano preferencje, model oraz klucz API!", Toast.LENGTH_SHORT).show()
                },
                modifier = Modifier
                    .fillMaxWidth()
                    .height(50.dp)
                    .testTag("goals_save_btn"),
                colors = ButtonDefaults.buttonColors(containerColor = LingoPrimary),
                shape = RoundedCornerShape(16.dp)
            ) {
                Text("Save Preferences, Model & API Key", fontWeight = FontWeight.Bold, fontSize = 15.sp)
            }
        }

        // App Version, Metadata, and Minimal Footer Section
        item {
            var isChangelogExpanded by remember { mutableStateOf(false) }

            Spacer(modifier = Modifier.height(8.dp))
            Card(
                modifier = Modifier.fillMaxWidth(),
                colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.25f)),
                shape = RoundedCornerShape(12.dp),
                border = BorderStroke(1.dp, MaterialTheme.colorScheme.outlineVariant.copy(alpha = 0.35f))
            ) {
                Column(modifier = Modifier.padding(horizontal = 12.dp, vertical = 10.dp)) {
                    Row(
                        modifier = Modifier.fillMaxWidth(),
                        horizontalArrangement = Arrangement.SpaceBetween,
                        verticalAlignment = Alignment.CenterVertically
                    ) {
                        Row(
                            verticalAlignment = Alignment.CenterVertically,
                            horizontalArrangement = Arrangement.spacedBy(6.dp)
                        ) {
                            Icon(
                                imageVector = Icons.Default.Info,
                                contentDescription = null,
                                tint = LingoPrimary,
                                modifier = Modifier.size(16.dp)
                            )
                            Text(
                                text = "Lingo AI Tutor v${com.example.BuildConfig.VERSION_NAME}",
                                fontWeight = FontWeight.Bold,
                                fontSize = 12.sp,
                                color = MaterialTheme.colorScheme.onSurface
                            )
                            Surface(
                                color = LingoPrimary.copy(alpha = 0.12f),
                                shape = RoundedCornerShape(4.dp)
                            ) {
                                Text(
                                    text = "STABLE",
                                    fontSize = 8.5.sp,
                                    fontWeight = FontWeight.Bold,
                                    color = LingoPrimary,
                                    modifier = Modifier.padding(horizontal = 4.dp, vertical = 1.dp)
                                )
                            }
                        }

                        IconButton(
                            onClick = { isChangelogExpanded = !isChangelogExpanded },
                            modifier = Modifier.size(24.dp)
                        ) {
                            Icon(
                                imageVector = if (isChangelogExpanded) Icons.Default.ExpandLess else Icons.Default.ExpandMore,
                                contentDescription = "Pokaż szczegóły",
                                tint = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.6f),
                                modifier = Modifier.size(16.dp)
                            )
                        }
                    }

                    Spacer(modifier = Modifier.height(2.dp))

                    Row(
                        modifier = Modifier.fillMaxWidth(),
                        horizontalArrangement = Arrangement.SpaceBetween,
                        verticalAlignment = Alignment.CenterVertically
                    ) {
                        Text(
                            text = "Twórca: Paweł Pogoda • Podpis Zweryfikowany",
                            fontSize = 10.sp,
                            color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.6f)
                        )
                        Text(
                            text = if (isChangelogExpanded) "Ukryj historię" else "Historia zmian",
                            fontSize = 10.sp,
                            fontWeight = FontWeight.SemiBold,
                            color = LingoPrimary,
                            modifier = Modifier.clickable { isChangelogExpanded = !isChangelogExpanded }
                        )
                    }

                    AnimatedVisibility(visible = isChangelogExpanded) {
                        Column(modifier = Modifier.padding(top = 10.dp)) {
                            Divider(color = MaterialTheme.colorScheme.outlineVariant.copy(alpha = 0.3f))
                            Spacer(modifier = Modifier.height(8.dp))
                            Text(
                                text = "v2.5.0 — Goals Hub & Slavic Engine Update",
                                fontWeight = FontWeight.Bold,
                                fontSize = 11.sp,
                                color = LingoPrimary
                            )
                            Spacer(modifier = Modifier.height(2.dp))
                            Text(
                                text = "• Wsparcie dla cyrylicy (ru-RU)\n• Podgląd zachowania CEFR A1-C2\n• Odizolowane bazy słownictwa i historii",
                                fontSize = 10.sp,
                                color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.7f),
                                lineHeight = 14.sp
                            )
                        }
                    }
                }
            }
            Spacer(modifier = Modifier.height(16.dp))
        }
    }
}

@OptIn(ExperimentalLayoutApi::class)
@Composable
fun FlowRow(
    horizontalArrangement: Arrangement.Horizontal = Arrangement.Start,
    verticalArrangement: Arrangement.Vertical = Arrangement.Top,
    modifier: Modifier = Modifier,
    content: @Composable () -> Unit
) {
    androidx.compose.foundation.layout.FlowRow(
        modifier = modifier,
        horizontalArrangement = horizontalArrangement,
        verticalArrangement = verticalArrangement,
        content = { content() }
    )
}

@Composable
fun ConnectionStatusBanner(status: com.example.data.api.ConnectionStatus) {
    if (status == com.example.data.api.ConnectionStatus.CONNECTED) return

    val (bg, text, icon) = when (status) {
        com.example.data.api.ConnectionStatus.RECONNECTING -> Triple(
            Color(0xFFFFF3CD),
            "Przywracanie połączenia... (Zachowano stan sesji)",
            Icons.Default.Refresh
        )
        com.example.data.api.ConnectionStatus.DISCONNECTED -> Triple(
            Color(0xFFF8D7DA),
            "Brak połączenia z internetem. Twoje wiadomości zostaną wysłane automatycznie.",
            Icons.Default.CloudOff
        )
        else -> Triple(Color.Transparent, "", Icons.Default.Info)
    }

    val textColor = when (status) {
        com.example.data.api.ConnectionStatus.RECONNECTING -> Color(0xFF856404)
        com.example.data.api.ConnectionStatus.DISCONNECTED -> Color(0xFF721C24)
        else -> Color.Black
    }

    Box(
        modifier = Modifier
            .fillMaxWidth()
            .background(bg)
            .padding(horizontal = 16.dp, vertical = 8.dp),
        contentAlignment = Alignment.Center
    ) {
        Row(
            verticalAlignment = Alignment.CenterVertically,
            horizontalArrangement = Arrangement.spacedBy(8.dp)
        ) {
            Icon(
                imageVector = icon,
                contentDescription = null,
                tint = textColor,
                modifier = Modifier.size(16.dp)
            )
            Text(
                text = text,
                color = textColor,
                fontSize = 11.sp,
                fontWeight = FontWeight.Bold,
                textAlign = androidx.compose.ui.text.style.TextAlign.Center
            )
        }
    }
}

// ==========================================
// 5. DIALOGUE CONVERSATION SCREEN (Voice & Text)
// ==========================================
@Composable
fun ConversationScreen(
    session: Session,
    viewModel: TutorViewModel,
    isAiLoading: Boolean,
    speechHelper: TutorSpeechHelper
) {
    val context = LocalContext.current
    val messageText = remember { mutableStateOf("") }
    val showDictInChat = remember { mutableStateOf(false) }
    val showAcceleratorDialogInChat = remember { mutableStateOf(false) }
    val isVoiceMode = remember { mutableStateOf(true) } // Defaults to Voice mode for premium voice-first immersion
    val showOnlyCorrections = remember { mutableStateOf(false) }
    val currentPlaybackSpeed by viewModel.playbackSpeed.collectAsStateWithLifecycle()
    val speechSpeedMultiplier = remember { mutableStateOf(1.0f) }
    
    val isLongScenario = remember(session.title) { session.title.length > 35 || session.title.contains("\n") }
    var isMissionBriefingExpanded by remember { mutableStateOf(false) }

    val displayTitle = remember(session.title) {
        if (isLongScenario) {
            val firstSentence = session.title.split(".", "\n", "?", "!").firstOrNull()?.trim() ?: session.title
            if (firstSentence.length > 32) firstSentence.take(30).trim() + "..." else firstSentence
        } else {
            session.title
        }
    }
    
    LaunchedEffect(currentPlaybackSpeed) {
        speechSpeedMultiplier.value = currentPlaybackSpeed
    }
    
    val messages by viewModel.activeSessionMessages.collectAsStateWithLifecycle()
    val connectionStatus by viewModel.connectionStatus.collectAsStateWithLifecycle()
    val kbController = LocalSoftwareKeyboardController.current

    val listState = rememberLazyListState()
    val isLiveCallActive = remember { mutableStateOf(false) }
    val isMuted = remember { mutableStateOf(false) }
    val scope = rememberCoroutineScope()
    val liveAiLoading by viewModel.isAiLoading.collectAsStateWithLifecycle()

    var activeShadowMessageText by remember { mutableStateOf<String?>(null) }
    var activeShadowMessageTranslation by remember { mutableStateOf<String?>(null) }
    var activeShadowRecognizedText by remember { mutableStateOf<String?>(null) }
    var activeShadowRecognizerErrorText by remember { mutableStateOf<String?>(null) }

    var onSpeechErrorRestart by remember { mutableStateOf<(() -> Unit)?>(null) }
    var autoListenJob by remember { mutableStateOf<Job?>(null) }

    // 1. Build our custom quiet background SpeechRecognizer first in Compose memory
    val speechRecognizer = remember {
        TutorSpeechRecognizer(
            context = context,
            onResults = { spokenText ->
                if (activeShadowMessageText != null) {
                    activeShadowRecognizedText = spokenText
                    activeShadowRecognizerErrorText = null
                } else {
                    if (!spokenText.isNullOrBlank()) {
                        speechHelper.playTurnEndEarcon()
                        viewModel.submitUserMessage(spokenText)
                    }
                }
            },
            onErrorCallback = { errorMsg, errorCode ->
                Log.d("TutorSpeechRecognizer", "Error callback: $errorMsg ($errorCode)")
                if (activeShadowMessageText != null) {
                    activeShadowRecognizerErrorText = errorMsg
                } else {
                    // Continuous hands-free mode: If timeout or no match occurs, automatically restart listening if voice is active
                    val isVoiceSessionActive = (isLiveCallActive.value || isVoiceMode.value) && !isMuted.value
                    if (isVoiceSessionActive && !viewModel.isAiLoading.value && !speechHelper.isSpeaking) {
                        autoListenJob?.cancel()
                        autoListenJob = scope.launch {
                            delay(300L)
                            val stillActive = (isLiveCallActive.value || isVoiceMode.value) && !isMuted.value && !viewModel.isAiLoading.value && !speechHelper.isSpeaking
                            if (stillActive) {
                                onSpeechErrorRestart?.invoke()
                            }
                        }
                    }
                }
            }
        )
    }

    // 2. Dynamic permission request launcher for microphone recording
    val permissionLauncher = rememberLauncherForActivityResult(
        contract = ActivityResultContracts.RequestPermission()
    ) { isGranted ->
        if (isGranted) {
            val languageCode = when (session.language.lowercase()) {
                "spanish" -> "es-ES"
                "french" -> "fr-FR"
                "german" -> "de-DE"
                "italian" -> "it-IT"
                "japanese" -> "ja-JP"
                "chinese" -> "zh-CN"
                "portuguese" -> "pt-PT"
                "korean" -> "ko-KR"
                "english" -> "en-US"
                else -> Locale.getDefault().language
            }
            speechRecognizer.startListening(languageCode)
        } else {
            Toast.makeText(context, "Uprawnienie do mikrofonu jest wymagane do rozmowy na żywo bez klikania.", Toast.LENGTH_LONG).show()
        }
    }

    // Shut down speech recognizer cleanly when leaving ConversationScreen
    DisposableEffect(Unit) {
        onDispose {
            speechRecognizer.shutdown()
        }
    }

    fun startVoiceListening(force: Boolean = false) {
        if (isMuted.value) {
            speechRecognizer.stop()
            return
        }
        if (!force && (speechHelper.isSpeaking || viewModel.isAiLoading.value)) {
            Log.d("MainActivity", "startVoiceListening: Tutor is speaking or generating, deferring microphone activation")
            return
        }
        if (force) {
            speechHelper.stop()
        }

        val languageCode = when (session.language.lowercase()) {
            "spanish" -> "es-ES"
            "french" -> "fr-FR"
            "german" -> "de-DE"
            "italian" -> "it-IT"
            "japanese" -> "ja-JP"
            "chinese" -> "zh-CN"
            "portuguese" -> "pt-PT"
            "korean" -> "ko-KR"
            "english" -> "en-US"
            else -> Locale.getDefault().language
        }

        val hasMicPermission = ContextCompat.checkSelfPermission(
            context,
            android.Manifest.permission.RECORD_AUDIO
        ) == PackageManager.PERMISSION_GRANTED

        if (hasMicPermission) {
            speechRecognizer.startListening(languageCode)
        } else {
            permissionLauncher.launch(android.Manifest.permission.RECORD_AUDIO)
        }
    }

    fun triggerAutoListen(delayMs: Long = 150L) {
        autoListenJob?.cancel()
        autoListenJob = scope.launch {
            delay(delayMs)
            val stillActive = (isLiveCallActive.value || isVoiceMode.value) && !isMuted.value && !viewModel.isAiLoading.value && !speechHelper.isSpeaking
            if (stillActive && !speechRecognizer.isListening) {
                startVoiceListening(force = false)
            }
        }
    }

    // Bind the restart action cleanly
    LaunchedEffect(Unit) {
        onSpeechErrorRestart = {
            startVoiceListening(force = false)
        }
    }

    // Hands-free continuous voice-to-voice conversation loop
    LaunchedEffect(isLiveCallActive.value, isVoiceMode.value, isMuted.value, liveAiLoading, speechHelper.isSpeaking, activeShadowMessageText) {
        val isVoiceSessionActive = (isLiveCallActive.value || isVoiceMode.value) && !isMuted.value && (activeShadowMessageText == null)
        if (isVoiceSessionActive) {
            speechHelper.onSpeechFinished = {
                triggerAutoListen(delayMs = 150L)
            }
            if (!liveAiLoading && !speechHelper.isSpeaking && !speechRecognizer.isListening) {
                triggerAutoListen(delayMs = 200L)
            } else if (liveAiLoading || speechHelper.isSpeaking) {
                autoListenJob?.cancel()
                speechRecognizer.stop()
            }
        } else {
            speechHelper.onSpeechFinished = null
            autoListenJob?.cancel()
            if (activeShadowMessageText != null || isMuted.value) {
                speechRecognizer.stop()
            }
        }
    }

    // Smooth scroll to bottom when messages or loading status changes
    LaunchedEffect(messages.size, isAiLoading) {
        if (messages.isNotEmpty()) {
            listState.animateScrollToItem(messages.size)
        }
    }

    Box(modifier = Modifier.fillMaxSize()) {
        if (isVoiceMode.value && isLiveCallActive.value) {
            LiveCallView(
                session = session,
                viewModel = viewModel,
                isAiLoading = isAiLoading,
                messages = messages,
                speechHelper = speechHelper,
                isMicListening = speechRecognizer.isListening,
                rmsLevel = speechRecognizer.rmsLevel,
                isMuted = isMuted,
                isSpeechAvailable = speechRecognizer.isAvailable,
                onCloseCall = { isLiveCallActive.value = false },
                startVoiceListening = { startVoiceListening() }
            )
    } else {
        Column(
            modifier = Modifier
                .fillMaxSize()
                .statusBarsPadding()
                .navigationBarsPadding()
        ) {
            ConnectionStatusBanner(connectionStatus)
            
            // Header Row
        Row(
            modifier = Modifier
                .fillMaxWidth()
                .padding(horizontal = 16.dp, vertical = 10.dp),
            verticalAlignment = Alignment.CenterVertically,
            horizontalArrangement = Arrangement.SpaceBetween
        ) {
            Row(
                verticalAlignment = Alignment.CenterVertically,
                modifier = Modifier.weight(1f)
            ) {
                IconButton(onClick = {
                    speechHelper.stop()
                    speechRecognizer.stop()
                    viewModel.endActiveSession()
                }) {
                    Icon(Icons.Default.ArrowBack, contentDescription = "Back")
                }
                Spacer(modifier = Modifier.width(4.dp))
                Column(modifier = Modifier.weight(1f)) {
                    Text(
                        text = displayTitle,
                        fontWeight = FontWeight.Bold,
                        fontSize = 15.sp,
                        maxLines = 1,
                        overflow = TextOverflow.Ellipsis,
                        color = MaterialTheme.colorScheme.onBackground
                    )
                    Row(
                        verticalAlignment = Alignment.CenterVertically,
                        horizontalArrangement = Arrangement.spacedBy(6.dp)
                    ) {
                        Text(
                            text = "${session.language} • Lvl ${session.cefrLevel}",
                            fontSize = 11.5.sp,
                            color = MaterialTheme.colorScheme.onBackground.copy(alpha = 0.6f)
                        )
                        
                        // Stress Level Badge
                        val (badgeText, badgeBg, badgeTint) = when (session.stressLevel) {
                            1 -> Triple("Real-life ⚡", LingoSecondary.copy(alpha = 0.15f), LingoSecondary)
                            2 -> Triple("Chaos 🔥", LingoStreakOrange.copy(alpha = 0.15f), LingoStreakOrange)
                            else -> Triple("Spokojny 🍃", LingoSuccessGreen.copy(alpha = 0.15f), LingoSuccessGreen)
                        }
                        
                        Box(
                            modifier = Modifier
                                .clip(RoundedCornerShape(6.dp))
                                .background(badgeBg)
                                .padding(horizontal = 5.dp, vertical = 2.dp)
                        ) {
                            Text(
                                text = badgeText,
                                fontSize = 9.sp,
                                fontWeight = FontWeight.Bold,
                                color = badgeTint
                            )
                        }

                        if (isLongScenario) {
                            Box(
                                modifier = Modifier
                                    .clip(RoundedCornerShape(6.dp))
                                    .background(LingoPrimary.copy(alpha = 0.12f))
                                    .clickable { isMissionBriefingExpanded = !isMissionBriefingExpanded }
                                    .padding(horizontal = 6.dp, vertical = 2.dp)
                            ) {
                                Row(verticalAlignment = Alignment.CenterVertically) {
                                    Icon(
                                        imageVector = if (isMissionBriefingExpanded) Icons.Default.KeyboardArrowUp else Icons.Default.Info,
                                        contentDescription = null,
                                        tint = LingoPrimary,
                                        modifier = Modifier.size(11.dp)
                                    )
                                    Spacer(modifier = Modifier.width(3.dp))
                                    Text(
                                        text = if (isMissionBriefingExpanded) "Ukryj 🎯" else "Rola 🎯",
                                        fontSize = 9.sp,
                                        fontWeight = FontWeight.Bold,
                                        color = LingoPrimary
                                    )
                                }
                            }
                        }
                    }
                }
            }

            Row(verticalAlignment = Alignment.CenterVertically) {
                // Floating bubble button (System Overlay)
                IconButton(
                    onClick = {
                        if (!android.provider.Settings.canDrawOverlays(context)) {
                            val intent = android.content.Intent(
                                android.provider.Settings.ACTION_MANAGE_OVERLAY_PERMISSION,
                                android.net.Uri.parse("package:${context.packageName}")
                            )
                            context.startActivity(intent)
                        } else {
                            var needRequestNotification = false
                            if (android.os.Build.VERSION.SDK_INT >= 33) {
                                val hasNotificationPermission = androidx.core.content.ContextCompat.checkSelfPermission(
                                    context,
                                    "android.permission.POST_NOTIFICATIONS"
                                ) == android.content.pm.PackageManager.PERMISSION_GRANTED
                                if (!hasNotificationPermission) {
                                    needRequestNotification = true
                                }
                            }

                            if (needRequestNotification) {
                                (context as? android.app.Activity)?.requestPermissions(
                                    arrayOf("android.permission.POST_NOTIFICATIONS"),
                                    102
                                )
                            } else {
                                val serviceIntent = android.content.Intent(context, com.example.ui.speech.ForegroundService::class.java)
                                context.startForegroundService(serviceIntent)
                                android.widget.Toast.makeText(context, "Dymek czatu uruchomiony w tle! 💬", android.widget.Toast.LENGTH_SHORT).show()
                            }
                        }
                    },
                    modifier = Modifier.size(34.dp).testTag("start_overlay_bubble_btn")
                ) {
                    Icon(
                        imageVector = androidx.compose.material.icons.Icons.Default.Chat,
                        contentDescription = "Dymek czatu",
                        tint = LingoPrimary,
                        modifier = Modifier.size(20.dp)
                    )
                }

                // Finish button
                Button(
                    onClick = {
                        speechHelper.stop()
                        speechRecognizer.stop()
                        viewModel.endActiveSession()
                    },
                    colors = ButtonDefaults.buttonColors(containerColor = LingoErrorRed),
                    shape = RoundedCornerShape(12.dp),
                    contentPadding = PaddingValues(horizontal = 10.dp, vertical = 4.dp),
                    modifier = Modifier.height(32.dp).testTag("end_session_btn")
                ) {
                    Text("Koniec", fontSize = 11.sp, fontWeight = FontWeight.Bold)
                }
            }
        }

        // Expandable Mission Briefing Card
        AnimatedVisibility(
            visible = isMissionBriefingExpanded,
            enter = fadeIn() + expandVertically(),
            exit = fadeOut() + shrinkVertically()
        ) {
            Card(
                modifier = Modifier
                    .fillMaxWidth()
                    .padding(horizontal = 16.dp, vertical = 4.dp),
                shape = RoundedCornerShape(12.dp),
                colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.6f)),
                border = BorderStroke(1.dp, LingoPrimary.copy(alpha = 0.25f))
            ) {
                Column(modifier = Modifier.padding(12.dp)) {
                    Row(
                        modifier = Modifier.fillMaxWidth(),
                        horizontalArrangement = Arrangement.SpaceBetween,
                        verticalAlignment = Alignment.CenterVertically
                    ) {
                        Row(verticalAlignment = Alignment.CenterVertically) {
                            Icon(Icons.Default.Flag, contentDescription = null, tint = LingoPrimary, modifier = Modifier.size(16.dp))
                            Spacer(modifier = Modifier.width(6.dp))
                            Text(
                                text = "🎯 Scenariusz i Rola w Konwersacji:",
                                fontSize = 12.sp,
                                fontWeight = FontWeight.Bold,
                                color = LingoPrimary
                            )
                        }
                        IconButton(
                            onClick = { isMissionBriefingExpanded = false },
                            modifier = Modifier.size(24.dp)
                        ) {
                            Icon(Icons.Default.Close, contentDescription = "Zamknij", modifier = Modifier.size(14.dp))
                        }
                    }
                    Spacer(modifier = Modifier.height(4.dp))
                    Text(
                        text = session.title,
                        fontSize = 12.5.sp,
                        lineHeight = 18.sp,
                        color = MaterialTheme.colorScheme.onSurface
                    )
                }
            }
        }

        Divider(color = MaterialTheme.colorScheme.onBackground.copy(alpha = 0.05f))

        // Toggle Modes: Spoken Voice vs Text Chat
        Row(
            modifier = Modifier
                .fillMaxWidth()
                .padding(horizontal = 16.dp, vertical = 4.dp)
                .clip(RoundedCornerShape(10.dp))
                .background(MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.4f))
                .padding(2.dp),
            horizontalArrangement = Arrangement.Center
        ) {
            Button(
                onClick = { isVoiceMode.value = true },
                colors = ButtonDefaults.buttonColors(
                    containerColor = if (isVoiceMode.value) LingoPrimary else Color.Transparent,
                    contentColor = if (isVoiceMode.value) Color.White else MaterialTheme.colorScheme.onSurfaceVariant
                ),
                shape = RoundedCornerShape(8.dp),
                modifier = Modifier.weight(1f).height(32.dp),
                contentPadding = PaddingValues(0.dp)
            ) {
                Icon(Icons.Default.Mic, contentDescription = null, modifier = Modifier.size(14.dp))
                Spacer(modifier = Modifier.width(4.dp))
                Text("Voice Mode", fontSize = 11.5.sp, fontWeight = FontWeight.Bold)
            }

            Button(
                onClick = { isVoiceMode.value = false },
                colors = ButtonDefaults.buttonColors(
                    containerColor = if (!isVoiceMode.value) LingoPrimary else Color.Transparent,
                    contentColor = if (!isVoiceMode.value) Color.White else MaterialTheme.colorScheme.onSurfaceVariant
                ),
                shape = RoundedCornerShape(8.dp),
                modifier = Modifier.weight(1f).height(32.dp),
                contentPadding = PaddingValues(0.dp)
            ) {
                Icon(Icons.Default.List, contentDescription = null, modifier = Modifier.size(14.dp))
                Spacer(modifier = Modifier.width(4.dp))
                Text("Text Mode", fontSize = 11.5.sp, fontWeight = FontWeight.Bold)
            }
        }

        val currentVibe by viewModel.activeSessionVibe.collectAsStateWithLifecycle()
        val currentTurnLength by viewModel.turnLengthMode.collectAsStateWithLifecycle()
        val sessionMistakes = messages.filter { !it.sender.equals("tutor", ignoreCase = true) && it.isCorrected }

        // Styl/Nastrój Rozmowy Selector
        val vibesList = listOf(
            Pair("normal", "🍃 Standard"),
            Pair("gossip", "💬 Plotkowanie"),
            Pair("deeptalk", "🧠 Głęboka"),
            Pair("humor", "🎭 Humor"),
            Pair("survival", "🎒 Survival")
        )

        Row(
            modifier = Modifier
                .fillMaxWidth()
                .padding(horizontal = 16.dp, vertical = 2.dp),
            verticalAlignment = Alignment.CenterVertically
        ) {
            Text(
                text = "Nastrój:",
                style = MaterialTheme.typography.labelSmall,
                fontWeight = FontWeight.Bold,
                color = MaterialTheme.colorScheme.onBackground.copy(alpha = 0.6f),
                modifier = Modifier.padding(end = 6.dp)
            )
            LazyRow(
                horizontalArrangement = Arrangement.spacedBy(6.dp),
                modifier = Modifier.fillMaxWidth()
            ) {
                items(vibesList) { item ->
                    val vibeKey = item.first
                    val vibeLabel = item.second
                    val isSelected = currentVibe == vibeKey
                    Box(
                        modifier = Modifier
                            .clip(RoundedCornerShape(8.dp))
                            .background(
                                if (isSelected) LingoPrimary.copy(alpha = 0.18f)
                                else MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.45f)
                            )
                            .border(
                                width = 1.dp,
                                color = if (isSelected) LingoPrimary else Color.Transparent,
                                shape = RoundedCornerShape(8.dp)
                            )
                            .clickable {
                                viewModel.changeSessionVibe(vibeKey)
                            }
                            .padding(horizontal = 8.dp, vertical = 4.dp),
                        contentAlignment = Alignment.Center
                    ) {
                        Text(
                            text = vibeLabel,
                            color = if (isSelected) LingoPrimary else MaterialTheme.colorScheme.onSurface,
                            fontSize = 10.5.sp,
                            fontWeight = if (isSelected) FontWeight.Bold else FontWeight.Medium
                        )
                    }
                }
            }
        }

        // PRĘDKOŚĆ ODTWARZANIA AUDIO
        Row(
            modifier = Modifier
                .fillMaxWidth()
                .padding(horizontal = 16.dp, vertical = 2.dp),
            verticalAlignment = Alignment.CenterVertically
        ) {
            Row(
                verticalAlignment = Alignment.CenterVertically,
                modifier = Modifier.padding(end = 6.dp)
            ) {
                Icon(
                    imageVector = Icons.Default.VolumeUp,
                    contentDescription = null,
                    tint = LingoPrimary,
                    modifier = Modifier.size(13.dp)
                )
                Spacer(modifier = Modifier.width(3.dp))
                Text(
                    text = "Tempo:",
                    style = MaterialTheme.typography.labelSmall,
                    fontWeight = FontWeight.Bold,
                    color = MaterialTheme.colorScheme.onBackground.copy(alpha = 0.6f)
                )
            }
            
            val speedOptions = listOf(
                Pair(0.65f, "🐢 0.65x"),
                Pair(0.75f, "🚶 0.75x"),
                Pair(0.85f, "🐇 0.85x"),
                Pair(1.0f, "🍃 1.0x")
            )
            
            Row(
                horizontalArrangement = Arrangement.spacedBy(6.dp),
                modifier = Modifier.fillMaxWidth()
            ) {
                speedOptions.forEach { option ->
                    val speedVal = option.first
                    val speedLabel = option.second
                    val isSelected = currentPlaybackSpeed == speedVal || speechSpeedMultiplier.value == speedVal
                    
                    Box(
                        modifier = Modifier
                            .weight(1f)
                            .clip(RoundedCornerShape(8.dp))
                            .background(
                                if (isSelected) LingoPrimary.copy(alpha = 0.18f)
                                else MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.45f)
                            )
                            .border(
                                width = 1.dp,
                                color = if (isSelected) LingoPrimary else Color.Transparent,
                                shape = RoundedCornerShape(8.dp)
                            )
                            .clickable {
                                speechSpeedMultiplier.value = speedVal
                                viewModel.setPlaybackSpeed(speedVal)
                            }
                            .padding(vertical = 4.dp),
                        contentAlignment = Alignment.Center
                    ) {
                        Text(
                            text = speedLabel,
                            color = if (isSelected) LingoPrimary else MaterialTheme.colorScheme.onSurface,
                            fontSize = 10.5.sp,
                            fontWeight = if (isSelected) FontWeight.Bold else FontWeight.Medium
                        )
                    }
                }
            }
        }

        // DŁUGOŚĆ WYPOWIEDZI / DYNAMIKA LEKTORA
        Row(
            modifier = Modifier
                .fillMaxWidth()
                .padding(horizontal = 16.dp, vertical = 2.dp),
            verticalAlignment = Alignment.CenterVertically
        ) {
            Row(
                verticalAlignment = Alignment.CenterVertically,
                modifier = Modifier.padding(end = 6.dp)
            ) {
                Icon(
                    imageVector = Icons.Default.Chat,
                    contentDescription = null,
                    tint = LingoPrimary,
                    modifier = Modifier.size(13.dp)
                )
                Spacer(modifier = Modifier.width(3.dp))
                Text(
                    text = "Lektor:",
                    style = MaterialTheme.typography.labelSmall,
                    fontWeight = FontWeight.Bold,
                    color = MaterialTheme.colorScheme.onBackground.copy(alpha = 0.6f)
                )
            }
            
            val lengthOptions = listOf(
                Pair("fast", "⚡ Szybki (1-2 zd.)"),
                Pair("balanced", "💬 Średni (2-3 zd.)"),
                Pair("detailed", "📖 Długi (4+ zd.)")
            )
            
            Row(
                horizontalArrangement = Arrangement.spacedBy(6.dp),
                modifier = Modifier.fillMaxWidth()
            ) {
                lengthOptions.forEach { option ->
                    val modeKey = option.first
                    val modeLabel = option.second
                    val isSelected = currentTurnLength == modeKey
                    
                    Box(
                        modifier = Modifier
                            .weight(1f)
                            .clip(RoundedCornerShape(8.dp))
                            .background(
                                if (isSelected) LingoPrimary.copy(alpha = 0.18f)
                                else MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.45f)
                            )
                            .border(
                                width = 1.dp,
                                color = if (isSelected) LingoPrimary else Color.Transparent,
                                shape = RoundedCornerShape(8.dp)
                            )
                            .clickable {
                                viewModel.changeTurnLengthMode(modeKey)
                            }
                            .padding(vertical = 4.dp),
                        contentAlignment = Alignment.Center
                    ) {
                        Text(
                            text = modeLabel,
                            color = if (isSelected) LingoPrimary else MaterialTheme.colorScheme.onSurface,
                            fontSize = 10.sp,
                            fontWeight = if (isSelected) FontWeight.Bold else FontWeight.Medium
                        )
                    }
                }
            }
        }

        // Tryb Korekty / Pełny czat Toggle (tylko w Text Mode)
        if (!isVoiceMode.value) {
            Row(
                modifier = Modifier
                    .fillMaxWidth()
                    .padding(horizontal = 16.dp, vertical = 2.dp),
                horizontalArrangement = Arrangement.SpaceBetween,
                verticalAlignment = Alignment.CenterVertically
            ) {
                Row(
                    verticalAlignment = Alignment.CenterVertically,
                    modifier = Modifier
                        .clip(RoundedCornerShape(8.dp))
                        .background(if (showOnlyCorrections.value) LingoGold.copy(alpha = 0.15f) else LingoPrimary.copy(alpha = 0.08f))
                        .border(
                            1.dp,
                            if (showOnlyCorrections.value) LingoGold else LingoPrimary.copy(alpha = 0.3f),
                            RoundedCornerShape(8.dp)
                        )
                        .clickable { showOnlyCorrections.value = !showOnlyCorrections.value }
                        .padding(horizontal = 8.dp, vertical = 4.dp)
                ) {
                    Icon(
                        imageVector = if (showOnlyCorrections.value) Icons.Default.Warning else Icons.Default.Check,
                        contentDescription = null,
                        tint = if (showOnlyCorrections.value) LingoGold else LingoPrimary,
                        modifier = Modifier.size(13.dp)
                    )
                    Spacer(modifier = Modifier.width(4.dp))
                    Text(
                        text = "Tryb Korekty",
                        fontSize = 11.sp,
                        fontWeight = FontWeight.Bold,
                        color = if (showOnlyCorrections.value) LingoGold else LingoPrimary
                    )
                    Spacer(modifier = Modifier.width(6.dp))
                    Box(
                        modifier = Modifier
                            .clip(RoundedCornerShape(6.dp))
                            .background(if (sessionMistakes.isNotEmpty()) LingoErrorRed.copy(alpha = 0.15f) else MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.5f))
                            .padding(horizontal = 5.dp, vertical = 1.dp)
                    ) {
                        Text(
                            text = "Błędy: ${sessionMistakes.size}",
                            fontSize = 9.5.sp,
                            fontWeight = FontWeight.Bold,
                            color = if (sessionMistakes.isNotEmpty()) LingoErrorRed else MaterialTheme.colorScheme.onSurface.copy(alpha = 0.7f)
                        )
                    }
                }

                Row(verticalAlignment = Alignment.CenterVertically) {
                    Text(
                        text = if (showOnlyCorrections.value) "Tylko błędy" else "Pełny czat",
                        fontSize = 11.sp,
                        fontWeight = FontWeight.Medium,
                        color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.7f)
                    )
                    Spacer(modifier = Modifier.width(4.dp))
                    Switch(
                        checked = !showOnlyCorrections.value,
                        onCheckedChange = { isFullChat -> showOnlyCorrections.value = !isFullChat },
                        modifier = Modifier.scale(0.75f)
                    )
                }
            }
        }

        // Active Modes Content
        Box(
            modifier = Modifier
                .fillMaxWidth()
                .weight(1f)
        ) {
            if (isVoiceMode.value) {
                // PREMIUM VOICE ONLY SCREEN
                val latestTutorMessage = messages.lastOrNull { it.sender == "tutor" }
                val showTutorTranslation = remember { mutableStateOf(false) }

                Column(
                    modifier = Modifier
                        .fillMaxSize()
                        .padding(horizontal = 16.dp, vertical = 8.dp)
                        .verticalScroll(rememberScrollState()),
                    horizontalAlignment = Alignment.CenterHorizontally,
                    verticalArrangement = Arrangement.spacedBy(10.dp)
                ) {
                    // Live Call Invite Card (Compact)
                    Card(
                        modifier = Modifier.fillMaxWidth(),
                        shape = RoundedCornerShape(12.dp),
                        colors = CardDefaults.cardColors(
                            containerColor = LingoPrimary.copy(alpha = 0.08f)
                        ),
                        border = BorderStroke(1.dp, LingoPrimary.copy(alpha = 0.25f))
                    ) {
                        Row(
                            modifier = Modifier
                                .fillMaxWidth()
                                .padding(horizontal = 12.dp, vertical = 8.dp),
                            verticalAlignment = Alignment.CenterVertically,
                            horizontalArrangement = Arrangement.SpaceBetween
                        ) {
                            Row(
                                verticalAlignment = Alignment.CenterVertically,
                                modifier = Modifier.weight(1f).padding(end = 8.dp)
                            ) {
                                Box(
                                    modifier = Modifier
                                        .size(8.dp)
                                        .clip(CircleShape)
                                        .background(Color(0xFF4CAF50))
                                )
                                Spacer(modifier = Modifier.width(6.dp))
                                Column {
                                    Text(
                                        text = "Tryb Na Żywo (Hands-free)",
                                        fontWeight = FontWeight.Bold,
                                        fontSize = 12.sp,
                                        color = LingoPrimary
                                    )
                                    Text(
                                        text = "Rozmawiaj płynnie bez klikania",
                                        fontSize = 10.sp,
                                        color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.65f)
                                    )
                                }
                            }
                            Button(
                                onClick = { 
                                    isLiveCallActive.value = true 
                                    startVoiceListening()
                                },
                                colors = ButtonDefaults.buttonColors(containerColor = LingoPrimary),
                                shape = RoundedCornerShape(8.dp),
                                contentPadding = PaddingValues(horizontal = 10.dp, vertical = 4.dp),
                                modifier = Modifier.height(30.dp)
                            ) {
                                Icon(
                                    imageVector = Icons.Default.Phone,
                                    contentDescription = null,
                                    modifier = Modifier.size(12.dp),
                                    tint = Color.White
                                )
                                Spacer(modifier = Modifier.width(4.dp))
                                Text("Połącz", fontSize = 11.sp, fontWeight = FontWeight.Bold)
                            }
                        }
                    }

                    // Real-Time Speech Correction Card (Voice feedback)
                    val lastUserMessage = messages.lastOrNull { !it.sender.equals("tutor", ignoreCase = true) }
                    if (lastUserMessage != null) {
                        Card(
                            modifier = Modifier.fillMaxWidth(),
                            shape = RoundedCornerShape(16.dp),
                            colors = CardDefaults.cardColors(
                                containerColor = if (lastUserMessage.isCorrected) LingoGold.copy(alpha = 0.08f) else MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.2f)
                            ),
                            border = if (lastUserMessage.isCorrected) BorderStroke(1.dp, LingoGold.copy(alpha = 0.3f)) else null
                        ) {
                            Column(modifier = Modifier.padding(12.dp)) {
                                Row(
                                    modifier = Modifier.fillMaxWidth(),
                                    horizontalArrangement = Arrangement.SpaceBetween,
                                    verticalAlignment = Alignment.CenterVertically
                                ) {
                                    Text(
                                        text = "Powiedziałeś (You said):",
                                        fontSize = 11.sp,
                                        fontWeight = FontWeight.Bold,
                                        color = if (lastUserMessage.isCorrected) LingoGold else MaterialTheme.colorScheme.onSurfaceVariant
                                    )
                                    if (lastUserMessage.isCorrected) {
                                        Row(verticalAlignment = Alignment.CenterVertically) {
                                            Icon(
                                                imageVector = Icons.Default.Warning,
                                                contentDescription = null,
                                                tint = LingoGold,
                                                modifier = Modifier.size(12.dp)
                                            )
                                            Spacer(modifier = Modifier.width(4.dp))
                                            Text(
                                                text = "Wykryto błąd!",
                                                fontSize = 11.sp,
                                                fontWeight = FontWeight.Bold,
                                                color = LingoGold
                                            )
                                        }
                                    } else {
                                        Row(verticalAlignment = Alignment.CenterVertically) {
                                            Icon(
                                                imageVector = Icons.Default.CheckCircle,
                                                contentDescription = null,
                                                tint = LingoSuccessGreen,
                                                modifier = Modifier.size(12.dp)
                                            )
                                            Spacer(modifier = Modifier.width(4.dp))
                                            Text(
                                                text = "Poprawnie!",
                                                fontSize = 11.sp,
                                                fontWeight = FontWeight.Bold,
                                                color = LingoSuccessGreen
                                            )
                                        }
                                    }
                                }
                                Spacer(modifier = Modifier.height(4.dp))
                                if (lastUserMessage.isCorrected && lastUserMessage.correctedText != null) {
                                    Text(
                                        text = lastUserMessage.originalText,
                                        fontSize = 13.sp,
                                        textDecoration = TextDecoration.LineThrough,
                                        color = LingoErrorRed.copy(alpha = 0.7f)
                                    )
                                    Spacer(modifier = Modifier.height(4.dp))
                                    Text(
                                        text = lastUserMessage.correctedText,
                                        fontSize = 14.sp,
                                        fontWeight = FontWeight.Bold,
                                        color = LingoSuccessGreen
                                    )
                                    if (!lastUserMessage.correctionExplanation.isNullOrBlank()) {
                                        Spacer(modifier = Modifier.height(6.dp))
                                        Text(
                                            text = lastUserMessage.correctionExplanation,
                                            fontSize = 11.sp,
                                            color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.8f),
                                            lineHeight = 15.sp
                                        )
                                    }
                                } else {
                                    Text(
                                        text = lastUserMessage.originalText,
                                        fontSize = 14.sp,
                                        color = MaterialTheme.colorScheme.onSurface
                                    )
                                }
                            }
                        }
                    }

                    // Big glowing orb
                    Column(
                        horizontalAlignment = Alignment.CenterHorizontally,
                        modifier = Modifier.padding(vertical = 8.dp)
                    ) {
                        VoiceOrbVisualizer(
                            isAiSpeaking = isAiLoading,
                            modifier = Modifier.clickable { startVoiceListening() }
                        )
                        Spacer(modifier = Modifier.height(12.dp))
                        Text(
                            text = if (isAiLoading) "Lingo is processing..." else "Lingo is listening",
                            fontSize = 14.sp,
                            fontWeight = FontWeight.Bold,
                            color = LingoPrimaryLight
                        )
                    }

                    // Transcription area
                    if (latestTutorMessage != null) {
                        Card(
                            modifier = Modifier.fillMaxWidth(),
                            shape = RoundedCornerShape(16.dp),
                            colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surface),
                            elevation = CardDefaults.cardElevation(defaultElevation = 2.dp)
                        ) {
                            Column(modifier = Modifier.padding(16.dp)) {
                                Row(
                                    modifier = Modifier.fillMaxWidth(),
                                    horizontalArrangement = Arrangement.SpaceBetween,
                                    verticalAlignment = Alignment.CenterVertically
                                ) {
                                    Text("Lingo says:", fontSize = 12.sp, fontWeight = FontWeight.Bold, color = LingoPrimary)
                                    Row(verticalAlignment = Alignment.CenterVertically) {
                                        TextButton(
                                            onClick = { showTutorTranslation.value = !showTutorTranslation.value },
                                            contentPadding = PaddingValues(0.dp),
                                            modifier = Modifier.height(24.dp)
                                        ) {
                                            Text(if (showTutorTranslation.value) "Hide translation" else "See translation", fontSize = 11.sp)
                                        }
                                        IconButton(
                                            onClick = { speechHelper.speak(latestTutorMessage.originalText, session.language, session.cefrLevel, speedMultiplier = speechSpeedMultiplier.value) },
                                            modifier = Modifier.size(24.dp)
                                        ) {
                                            Icon(Icons.Default.VolumeUp, contentDescription = "Odsłuchaj", modifier = Modifier.size(16.dp), tint = LingoPrimary)
                                        }
                                        IconButton(
                                            onClick = {
                                                activeShadowMessageText = latestTutorMessage.originalText
                                                activeShadowMessageTranslation = latestTutorMessage.translatedText
                                            },
                                            modifier = Modifier.size(24.dp)
                                        ) {
                                            Text("🗣️", fontSize = 12.sp)
                                        }
                                    }
                                }
                                Spacer(modifier = Modifier.height(8.dp))
                                Text(
                                    text = latestTutorMessage.originalText,
                                    fontSize = 15.sp,
                                    fontWeight = FontWeight.SemiBold,
                                    color = MaterialTheme.colorScheme.onSurface
                                )
                                if (showTutorTranslation.value && latestTutorMessage.translatedText != null) {
                                    Spacer(modifier = Modifier.height(6.dp))
                                    Text(
                                        text = latestTutorMessage.translatedText!!,
                                        fontSize = 13.sp,
                                        color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.6f)
                                    )
                                }
                            }
                        }
                    }

                    // Dynamic Hands-Free Voice Control Indicator
                    val voiceBtnColor = when {
                        isMuted.value -> Color.Gray
                        isAiLoading -> Color(0xFFFFC107)
                        speechHelper.isSpeaking -> Color(0xFF3A7BD5)
                        speechRecognizer.isListening -> Color(0xFF4CAF50)
                        else -> LingoPrimary
                    }
                    val voiceBtnText = when {
                        isMuted.value -> "Wyciszony • Dotknij, aby włączyć mikrofon"
                        isAiLoading -> "Lingo myśli... 🧠"
                        speechHelper.isSpeaking -> "Lingo mówi... 🗣️ (Odsłuchaj)"
                        speechRecognizer.isListening -> "Słucham Cię... Mów śmiało (Hands-free) 🎙️"
                        else -> "Rozmawiaj na żywo (Hands-free) 🎙️"
                    }

                    Button(
                        onClick = {
                            if (isMuted.value) {
                                isMuted.value = false
                            }
                            startVoiceListening(force = true)
                        },
                        colors = ButtonDefaults.buttonColors(containerColor = voiceBtnColor),
                        modifier = Modifier
                            .fillMaxWidth()
                            .height(52.dp)
                            .testTag("voice_mic_tap"),
                        shape = RoundedCornerShape(16.dp)
                    ) {
                        Icon(
                            imageVector = if (isMuted.value) Icons.Default.MicOff else Icons.Default.Mic,
                            contentDescription = null
                        )
                        Spacer(modifier = Modifier.width(8.dp))
                        Text(voiceBtnText, fontWeight = FontWeight.Bold, fontSize = 14.sp)
                    }
                }
            } else {
                // TEXT DIALOGUE FEED SCREEN
                Column(modifier = Modifier.fillMaxSize()) {
                    val filteredMessages = if (showOnlyCorrections.value) {
                        messages.filter { !it.sender.equals("tutor", ignoreCase = true) && it.isCorrected }
                    } else {
                        messages
                    }

                    LazyColumn(
                        state = listState,
                        modifier = Modifier
                            .weight(1f)
                            .padding(horizontal = 16.dp),
                        verticalArrangement = Arrangement.spacedBy(14.dp),
                        contentPadding = PaddingValues(vertical = 16.dp)
                    ) {
                        if (showOnlyCorrections.value && filteredMessages.isEmpty()) {
                            item {
                                Card(
                                    modifier = Modifier
                                        .fillMaxWidth()
                                        .padding(vertical = 24.dp),
                                    shape = RoundedCornerShape(16.dp),
                                    colors = CardDefaults.cardColors(
                                        containerColor = LingoSuccessGreen.copy(alpha = 0.08f)
                                    ),
                                    border = BorderStroke(1.dp, LingoSuccessGreen.copy(alpha = 0.3f))
                                ) {
                                    Column(
                                        modifier = Modifier.padding(20.dp),
                                        horizontalAlignment = Alignment.CenterHorizontally
                                    ) {
                                        Box(
                                            modifier = Modifier
                                                .size(56.dp)
                                                .clip(CircleShape)
                                                .background(LingoSuccessGreen),
                                            contentAlignment = Alignment.Center
                                        ) {
                                            Icon(
                                                imageVector = Icons.Default.CheckCircle,
                                                contentDescription = null,
                                                tint = Color.White,
                                                modifier = Modifier.size(32.dp)
                                            )
                                        }
                                        Spacer(modifier = Modifier.height(16.dp))
                                        Text(
                                            text = "Brak błędów! Świetna robota!",
                                            fontWeight = FontWeight.Bold,
                                            fontSize = 16.sp,
                                            color = MaterialTheme.colorScheme.onSurface
                                        )
                                        Spacer(modifier = Modifier.height(6.dp))
                                        Text(
                                            text = "Tutor Lingo nie wykrył jeszcze żadnych błędów gramatycznych ani leksykalnych w Twojej wypowiedzi w tej sesji. Rozmawiaj dalej!",
                                            fontSize = 12.sp,
                                            color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.65f),
                                            textAlign = TextAlign.Center,
                                            lineHeight = 17.sp
                                        )
                                    }
                                }
                            }
                        } else {
                            items(filteredMessages, key = { it.id }) { msg ->
                                if (msg.sender == "tutor") {
                                    com.example.ui.components.AiMessageBubble(
                                        message = msg,
                                        language = session.language,
                                        speechHelper = speechHelper,
                                        cefrLevel = session.cefrLevel,
                                        stressLevel = session.stressLevel,
                                        speedMultiplier = speechSpeedMultiplier.value,
                                        onDictionaryClick = {
                                            viewModel.searchDictionary(msg.originalText, session.language)
                                            showDictInChat.value = true
                                        },
                                        onAcceleratorClick = {
                                            viewModel.clearAcceleratorElements()
                                            showAcceleratorDialogInChat.value = true
                                        }
                                    )
                                } else {
                                    ChatBubble(
                                        message = msg,
                                        language = session.language,
                                        speechHelper = speechHelper,
                                        cefrLevel = session.cefrLevel,
                                        stressLevel = session.stressLevel,
                                        speedMultiplier = speechSpeedMultiplier.value,
                                        onShadowClick = { text, translation ->
                                            activeShadowMessageText = text
                                            activeShadowMessageTranslation = translation
                                        }
                                    )
                                }
                            }
                        }

                        if (isAiLoading && !showOnlyCorrections.value) {
                            item {
                                Box(
                                    modifier = Modifier
                                        .fillMaxWidth()
                                        .padding(8.dp),
                                    contentAlignment = Alignment.CenterStart
                                ) {
                                    Row(
                                        verticalAlignment = Alignment.CenterVertically,
                                        modifier = Modifier
                                            .clip(RoundedCornerShape(12.dp))
                                            .background(MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.5f))
                                            .padding(horizontal = 12.dp, vertical = 8.dp)
                                    ) {
                                        CircularProgressIndicator(modifier = Modifier.size(14.dp), strokeWidth = 2.dp, color = LingoPrimary)
                                        Spacer(modifier = Modifier.width(8.dp))
                                        Text("Lingo is typing...", fontSize = 12.sp, color = MaterialTheme.colorScheme.onSurfaceVariant)
                                    }
                                }
                            }
                        }
                    }

                    // SUGGESTIONS FOR TEXT MODE
                    val suggestions by viewModel.latestSuggestions.collectAsStateWithLifecycle()
                    if (suggestions.isNotEmpty() && !showOnlyCorrections.value) {
                        Column(
                            modifier = Modifier
                                .fillMaxWidth()
                                .padding(horizontal = 16.dp, vertical = 2.dp),
                            verticalArrangement = Arrangement.spacedBy(2.dp)
                        ) {
                            Text(
                                text = "💡 Sufler AI:",
                                color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.5f),
                                fontSize = 10.sp,
                                fontWeight = FontWeight.Bold
                            )
                            LazyRow(
                                horizontalArrangement = Arrangement.spacedBy(6.dp),
                                modifier = Modifier.fillMaxWidth()
                            ) {
                                items(suggestions) { sugg ->
                                    val parts = sugg.split(" [")
                                    val original = parts.getOrNull(0) ?: sugg
                                    val polish = parts.getOrNull(1)?.replace("]", "") ?: ""
                                    
                                    Box(
                                        modifier = Modifier
                                            .clip(RoundedCornerShape(8.dp))
                                            .background(MaterialTheme.colorScheme.primary.copy(alpha = 0.08f))
                                            .border(
                                                width = 1.dp,
                                                color = MaterialTheme.colorScheme.primary.copy(alpha = 0.2f),
                                                shape = RoundedCornerShape(8.dp)
                                            )
                                            .clickable {
                                                messageText.value = original
                                            }
                                            .padding(horizontal = 8.dp, vertical = 4.dp)
                                    ) {
                                        Column {
                                            Text(
                                                text = original,
                                                color = MaterialTheme.colorScheme.primary,
                                                fontSize = 11.sp,
                                                fontWeight = FontWeight.Bold
                                            )
                                            if (polish.isNotEmpty()) {
                                                Text(
                                                    text = polish,
                                                    color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.6f),
                                                    fontSize = 8.5.sp
                                                )
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    }

                    if (showAcceleratorDialogInChat.value) {
                        AcceleratorDialog(
                            viewModel = viewModel,
                            targetLanguage = session.language,
                            cefrLevel = session.cefrLevel,
                            speechHelper = speechHelper,
                            onDismiss = { showAcceleratorDialogInChat.value = false; viewModel.clearAcceleratorElements() },
                            onPasteToChat = { block ->
                                messageText.value = if (messageText.value.isEmpty()) block else messageText.value + " " + block
                                showAcceleratorDialogInChat.value = false
                            }
                        )
                    }
                    com.example.ui.components.ChatInputBar(
                        messageText = messageText,
                        language = session.language,
                        onDictionaryClick = { showDictInChat.value = true },
                        onSubmit = {
                            viewModel.submitUserMessage(messageText.value)
                            messageText.value = ""
                        }
                    )

                    if (showDictInChat.value) {
                        FullDictionarySearchDialog(
                            viewModel = viewModel,
                            activeLangCode = session.language,
                            onPasteToChat = { word ->
                                messageText.value = if (messageText.value.isEmpty()) word else messageText.value + " " + word
                            },
                            onDismiss = { showDictInChat.value = false }
                        )
                    }
                }
            }
        }

        // Inline Shadowing Practice Card Overlay
        if (activeShadowMessageText != null) {
            val sentence = activeShadowMessageText!!
            val translation = activeShadowMessageTranslation ?: ""
            val language = session.language
            
            var aiTip by remember { mutableStateOf<String?>(null) }
            var isGeneratingTip by remember { mutableStateOf(false) }

            // Reset AI tips when sentence changes
            LaunchedEffect(sentence) {
                aiTip = null
            }

            Box(
                modifier = Modifier
                    .fillMaxSize()
                    .background(Color.Black.copy(alpha = 0.5f))
                    .clickable(enabled = true, onClick = {
                        activeShadowMessageText = null
                        activeShadowMessageTranslation = null
                        activeShadowRecognizedText = null
                        activeShadowRecognizerErrorText = null
                        speechRecognizer.stop()
                    }),
                contentAlignment = Alignment.BottomCenter
            ) {
                Card(
                    modifier = Modifier
                        .fillMaxWidth()
                        .clickable(enabled = false, onClick = {}) // prevent click-through
                        .padding(16.dp)
                        .navigationBarsPadding(),
                    shape = RoundedCornerShape(24.dp),
                    colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surface),
                    elevation = CardDefaults.cardElevation(defaultElevation = 16.dp)
                ) {
                    Column(
                        modifier = Modifier
                            .fillMaxWidth()
                            .padding(20.dp),
                        horizontalAlignment = Alignment.CenterHorizontally,
                        verticalArrangement = Arrangement.spacedBy(14.dp)
                    ) {
                        // Title and Close
                        Row(
                            modifier = Modifier.fillMaxWidth(),
                            horizontalArrangement = Arrangement.SpaceBetween,
                            verticalAlignment = Alignment.CenterVertically
                        ) {
                            Text(
                                text = "SHADOWING PRACTICE (CIEŃ) 🗣️",
                                fontSize = 11.sp,
                                fontWeight = FontWeight.Bold,
                                color = LingoPrimary,
                                letterSpacing = 1.sp
                            )
                            IconButton(
                                onClick = {
                                    activeShadowMessageText = null
                                    activeShadowMessageTranslation = null
                                    activeShadowRecognizedText = null
                                    activeShadowRecognizerErrorText = null
                                    speechRecognizer.stop()
                                },
                                modifier = Modifier.size(28.dp)
                            ) {
                                Icon(Icons.Default.Close, contentDescription = "Close", modifier = Modifier.size(18.dp))
                            }
                        }

                        // The sentence
                        Text(
                            text = sentence,
                            fontSize = 18.sp,
                            fontWeight = FontWeight.Bold,
                            color = MaterialTheme.colorScheme.onSurface,
                            textAlign = TextAlign.Center,
                            lineHeight = 24.sp
                        )

                        // The translation
                        if (translation.isNotEmpty()) {
                            Text(
                                text = translation,
                                fontSize = 13.sp,
                                color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.6f),
                                textAlign = TextAlign.Center
                            )
                        }

                        // Speak and AI tips controls
                        Row(
                            horizontalArrangement = Arrangement.spacedBy(10.dp),
                            verticalAlignment = Alignment.CenterVertically
                        ) {
                            Button(
                                onClick = {
                                    speechHelper.speak(sentence, language, session.cefrLevel, customSpeechRate = 0.75f)
                                },
                                colors = ButtonDefaults.buttonColors(containerColor = LingoPrimary),
                                shape = RoundedCornerShape(10.dp),
                                contentPadding = PaddingValues(horizontal = 12.dp, vertical = 6.dp),
                                modifier = Modifier.height(36.dp)
                            ) {
                                Icon(Icons.Default.VolumeUp, contentDescription = null, modifier = Modifier.size(16.dp), tint = Color.White)
                                Spacer(modifier = Modifier.width(4.dp))
                                Text("Odsłuchaj", fontSize = 12.sp, fontWeight = FontWeight.Bold)
                            }

                            Button(
                                onClick = {
                                    if (!isGeneratingTip) {
                                        isGeneratingTip = true
                                        aiTip = null
                                        scope.launch {
                                            try {
                                                aiTip = viewModel.getPronunciationTip(sentence, language)
                                            } catch (e: Exception) {
                                                aiTip = "Nie udało się pobrać wskazówek."
                                            } finally {
                                                isGeneratingTip = false
                                            }
                                        }
                                    }
                                },
                                enabled = !isGeneratingTip,
                                colors = ButtonDefaults.buttonColors(containerColor = LingoSecondary),
                                shape = RoundedCornerShape(10.dp),
                                contentPadding = PaddingValues(horizontal = 12.dp, vertical = 6.dp),
                                modifier = Modifier.height(36.dp)
                            ) {
                                if (isGeneratingTip) {
                                    CircularProgressIndicator(modifier = Modifier.size(14.dp), color = Color.White, strokeWidth = 2.dp)
                                    Spacer(modifier = Modifier.width(4.dp))
                                    Text("Analiza...", fontSize = 12.sp)
                                } else {
                                    Icon(Icons.Default.Lightbulb, contentDescription = null, modifier = Modifier.size(16.dp), tint = Color.White)
                                    Spacer(modifier = Modifier.width(4.dp))
                                    Text("Wskazówki AI", fontSize = 12.sp, fontWeight = FontWeight.Bold)
                                }
                            }
                        }

                        // Display AI tip if available
                        aiTip?.let { tip ->
                            Card(
                                colors = CardDefaults.cardColors(containerColor = LingoPrimary.copy(alpha = 0.05f)),
                                shape = RoundedCornerShape(12.dp),
                                border = BorderStroke(1.dp, LingoPrimary.copy(alpha = 0.15f)),
                                modifier = Modifier.fillMaxWidth()
                            ) {
                                Text(
                                    text = tip,
                                    fontSize = 12.sp,
                                    color = MaterialTheme.colorScheme.onSurface,
                                    modifier = Modifier.padding(10.dp),
                                    lineHeight = 16.sp
                                )
                            }
                        }

                        Divider(color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.08f))

                        // Microphone user trial area
                        val isListeningState = speechRecognizer.isListening
                        Column(
                            horizontalAlignment = Alignment.CenterHorizontally,
                            verticalArrangement = Arrangement.spacedBy(8.dp)
                        ) {
                            Text(
                                text = if (isListeningState) "Słucham... powiedz to zdanie głośno! 🎙️" else "Naciśnij i mów do mikrofonu",
                                fontSize = 11.sp,
                                fontWeight = FontWeight.Bold,
                                color = if (isListeningState) LingoPrimary else MaterialTheme.colorScheme.onSurface.copy(alpha = 0.5f)
                            )

                            // 5-bar RMS Waveform
                            if (isListeningState) {
                                val animScale = animateFloatAsState(
                                    targetValue = (speechRecognizer.rmsLevel + 2f).coerceIn(1f, 15f),
                                    animationSpec = spring(stiffness = Spring.StiffnessLow),
                                    label = "shadow_rms"
                                )
                                Row(
                                    modifier = Modifier.height(20.dp),
                                    horizontalArrangement = Arrangement.spacedBy(4.dp),
                                    verticalAlignment = Alignment.CenterVertically
                                ) {
                                    repeat(5) { i ->
                                        val factor = when (i) {
                                            0, 4 -> 0.4f
                                            1, 3 -> 0.7f
                                            else -> 1.0f
                                        }
                                        Box(
                                            modifier = Modifier
                                                .width(3.dp)
                                                .height((animScale.value * 1.5 * factor).dp.coerceAtLeast(3.dp))
                                                .background(LingoPrimary, RoundedCornerShape(1.5.dp))
                                        )
                                    }
                                }
                            }

                            Button(
                                onClick = {
                                    if (isListeningState) {
                                        speechRecognizer.stop()
                                    } else {
                                        activeShadowRecognizedText = null
                                        activeShadowRecognizerErrorText = null
                                        val languageCode = when (language.lowercase()) {
                                            "spanish" -> "es-ES"
                                            "french" -> "fr-FR"
                                            "german" -> "de-DE"
                                            "italian" -> "it-IT"
                                            "japanese" -> "ja-JP"
                                            "chinese" -> "zh-CN"
                                            "portuguese" -> "pt-PT"
                                            "korean" -> "ko-KR"
                                            "english" -> "en-US"
                                            else -> Locale.getDefault().language
                                        }
                                        speechRecognizer.startListening(languageCode)
                                    }
                                },
                                colors = ButtonDefaults.buttonColors(containerColor = if (isListeningState) Color.Red else LingoPrimary),
                                modifier = Modifier.size(56.dp),
                                shape = CircleShape,
                                contentPadding = PaddingValues(0.dp)
                            ) {
                                Icon(
                                    imageVector = if (isListeningState) Icons.Default.Stop else Icons.Default.Mic,
                                    contentDescription = null,
                                    tint = Color.White,
                                    modifier = Modifier.size(28.dp)
                                )
                            }
                        }

                        // Similarity Results
                        activeShadowRecognizedText?.let { heard ->
                            val cleanedHeard = heard.lowercase().replace(Regex("[^a-zA-Z0-9ąęćłńóśźżäöüßñíóúáé]"), "")
                            val cleanedTarget = sentence.lowercase().replace(Regex("[^a-zA-Z0-9ąęćłńóśźżäöüßñíóúáé]"), "")
                            
                            val heardTokens = cleanedHeard.chunked(1).toSet()
                            val targetTokens = cleanedTarget.chunked(1).toSet()
                            val intersection = heardTokens.intersect(targetTokens).size
                            val union = heardTokens.union(targetTokens).size
                            val score = if (union > 0) ((intersection.toFloat() / union.toFloat()) * 100).toInt() else 0

                            Column(
                                modifier = Modifier.fillMaxWidth(),
                                horizontalAlignment = Alignment.CenterHorizontally,
                                verticalArrangement = Arrangement.spacedBy(6.dp)
                            ) {
                                Text(
                                    text = "Usłyszałem: \"$heard\"",
                                    fontSize = 13.sp,
                                    fontWeight = FontWeight.Medium,
                                    color = MaterialTheme.colorScheme.onSurface,
                                    textAlign = TextAlign.Center
                                )

                                Row(
                                    verticalAlignment = Alignment.CenterVertically,
                                    horizontalArrangement = Arrangement.spacedBy(8.dp),
                                    modifier = Modifier.fillMaxWidth().padding(horizontal = 16.dp)
                                ) {
                                    Box(
                                        modifier = Modifier
                                            .weight(1f)
                                            .height(8.dp)
                                            .background(MaterialTheme.colorScheme.surfaceVariant, RoundedCornerShape(4.dp))
                                    ) {
                                        Box(
                                            modifier = Modifier
                                                .fillMaxHeight()
                                                .fillMaxWidth(fraction = (score / 100f).coerceIn(0f, 1f))
                                                .background(
                                                    if (score >= 80) Color(0xFF4CAF50)
                                                    else if (score >= 50) Color(0xFFFFC107)
                                                    else Color(0xFFF44336),
                                                    RoundedCornerShape(4.dp)
                                                )
                                        )
                                    }
                                    Text(
                                        text = "$score%",
                                        fontWeight = FontWeight.Bold,
                                        fontSize = 12.sp,
                                        color = if (score >= 80) Color(0xFF4CAF50) else if (score >= 50) Color(0xFFFFC107) else Color(0xFFF44336)
                                    )
                                }

                                val statusMsg = when {
                                    score >= 85 -> "Wspaniały shadowing! Twoja wymowa jest idealna! 🌟"
                                    score >= 65 -> "Świetny wynik! Prawie idealnie, próbuj dalej! 👍"
                                    else -> "Dobra próba! Posłuchaj lektora i spróbuj jeszcze raz! 💪"
                                }
                                Text(
                                    text = statusMsg,
                                    fontSize = 12.sp,
                                    fontWeight = FontWeight.Bold,
                                    color = if (score >= 65) LingoSuccessGreen else MaterialTheme.colorScheme.onSurface.copy(alpha = 0.7f),
                                    textAlign = TextAlign.Center
                                )
                            }
                        }

                        // Display errors
                        activeShadowRecognizerErrorText?.let { err ->
                            Text(
                                text = "Błąd mikrofonu: $err. Spróbuj ponownie.",
                                color = MaterialTheme.colorScheme.error,
                                fontSize = 12.sp,
                                fontWeight = FontWeight.Bold,
                                textAlign = TextAlign.Center
                            )
                        }
                    }
                }
            }
        }
    }
}
}
}

// Glowing Pulsating Orb Composable
@Composable
fun VoiceOrbVisualizer(isAiSpeaking: Boolean, modifier: Modifier = Modifier) {
    val infiniteTransition = rememberInfiniteTransition()
    
    val pulseScale1 by infiniteTransition.animateFloat(
        initialValue = 1f,
        targetValue = if (isAiSpeaking) 1.6f else 1.1f,
        animationSpec = infiniteRepeatable(
            animation = tween(1200, easing = LinearOutSlowInEasing),
            repeatMode = RepeatMode.Reverse
        )
    )
    
    val pulseScale2 by infiniteTransition.animateFloat(
        initialValue = 1f,
        targetValue = if (isAiSpeaking) 2.2f else 1.3f,
        animationSpec = infiniteRepeatable(
            animation = tween(1800, easing = LinearOutSlowInEasing),
            repeatMode = RepeatMode.Reverse
        )
    )

    Box(
        contentAlignment = Alignment.Center,
        modifier = modifier.size(180.dp)
    ) {
        // Outer glow layers
        Box(
            modifier = Modifier
                .size(100.dp)
                .scale(pulseScale2)
                .clip(CircleShape)
                .background(LingoPrimaryLight.copy(alpha = 0.15f))
        )
        Box(
            modifier = Modifier
                .size(120.dp)
                .scale(pulseScale1)
                .clip(CircleShape)
                .background(LingoPrimary.copy(alpha = 0.3f))
        )
        // Main Orb core
        Box(
            modifier = Modifier
                .size(80.dp)
                .clip(CircleShape)
                .background(
                    Brush.radialGradient(
                        colors = listOf(LingoPrimaryLight, LingoPrimary, LingoSecondary)
                    )
                )
        ) {
            Icon(
                imageVector = Icons.Default.Mic,
                contentDescription = null,
                tint = Color.White,
                modifier = Modifier
                    .size(36.dp)
                    .align(Alignment.Center)
            )
        }
    }
}

// Dialog feedback chat bubbles with Real-time corrections
@Composable
fun ChatBubble(
    message: ChatMessage,
    language: String,
    speechHelper: TutorSpeechHelper,
    cefrLevel: String = "B1",
    stressLevel: Int = 0,
    speedMultiplier: Float = 1.0f,
    onShadowClick: ((String, String?) -> Unit)? = null
) {
    val isTutor = message.sender == "tutor"
    val showTranslation = remember { mutableStateOf(false) }
    val showCorrectionDetails = remember { mutableStateOf(false) }

    // Dynamic styles based on stress level:
    // 0 = Oaza Spokoju (greenish, relaxed)
    // 1 = Presja Czasu (warm orange, warning)
    // 2 = Ekstremalny Chaos & Gwar (red/fire, chaotic)
    val cardBg = when (stressLevel) {
        1 -> if (isTutor) Color(0xFFFFFDF5) else LingoSecondary.copy(alpha = 0.15f)
        2 -> if (isTutor) Color(0xFFFFF8F8) else LingoStreakOrange.copy(alpha = 0.15f)
        else -> if (isTutor) Color(0xFFF9FBF9) else LingoPrimary.copy(alpha = 0.10f)
    }
    
    val cardBorder = when (stressLevel) {
        1 -> BorderStroke(1.dp, Color(0xFFFFD54F).copy(alpha = 0.6f))
        2 -> BorderStroke(1.5.dp, Color(0xFFE53935).copy(alpha = 0.7f))
        else -> BorderStroke(1.dp, Color(0xFF81C784).copy(alpha = 0.25f))
    }

    val stressBadgeText = when (stressLevel) {
        1 -> "⚡ Szybka Reakcja"
        2 -> "🔥 Ekstremalny Chaos"
        else -> "🍃 Oaza Spokoju"
    }
    val stressBadgeColor = when (stressLevel) {
        1 -> Color(0xFFFFB300)
        2 -> Color(0xFFD32F2F)
        else -> Color(0xFF4CAF50)
    }

    // Extract ambient/sound interjections so they look like professional overlays and don't ruin reading flow
    val bracketRegex = Regex("\\[(.*?)\\]")
    val parenRegex = Regex("\\((.*?)\\)")
    val ambientEvents = mutableListOf<String>()
    bracketRegex.findAll(message.originalText).forEach { ambientEvents.add(it.groupValues[1]) }
    parenRegex.findAll(message.originalText).forEach { match ->
        val content = match.groupValues[1]
        if (content.length > 3 && (content.first().isUpperCase() || content.contains("gwar") || content.contains("szum") || content.contains("głos"))) {
            ambientEvents.add(content)
        }
    }
    val cleanDialogue = message.originalText
        .replace(bracketRegex, "")
        .replace(parenRegex, "")
        .replace(Regex("\\s+"), " ")
        .trim()
        .ifEmpty { message.originalText }

    Box(
        modifier = Modifier.fillMaxWidth(),
        contentAlignment = if (isTutor) Alignment.CenterStart else Alignment.CenterEnd
    ) {
        Column(
            modifier = Modifier.fillMaxWidth(0.85f),
            horizontalAlignment = if (isTutor) Alignment.Start else Alignment.End
        ) {
            Card(
                shape = RoundedCornerShape(
                    topStart = 16.dp,
                    topEnd = 16.dp,
                    bottomStart = if (isTutor) 4.dp else 16.dp,
                    bottomEnd = if (isTutor) 16.dp else 4.dp
                ),
                colors = CardDefaults.cardColors(containerColor = cardBg),
                border = cardBorder
            ) {
                Column(modifier = Modifier.padding(12.dp)) {
                    // Bubble header toolbar for translation & play sound
                    Row(
                        modifier = Modifier.fillMaxWidth(),
                        horizontalArrangement = Arrangement.SpaceBetween,
                        verticalAlignment = Alignment.CenterVertically
                    ) {
                        Row(verticalAlignment = Alignment.CenterVertically) {
                            Text(
                                text = if (isTutor) "Lingo Tutor" else "You",
                                fontSize = 10.sp,
                                fontWeight = FontWeight.Bold,
                                color = if (isTutor) LingoPrimary else LingoSecondary
                            )
                            Spacer(modifier = Modifier.width(6.dp))
                            // Small elegant pill representing the stress environment context
                            Box(
                                modifier = Modifier
                                    .clip(RoundedCornerShape(4.dp))
                                    .background(stressBadgeColor.copy(alpha = 0.12f))
                                    .padding(horizontal = 4.dp, vertical = 1.dp)
                            ) {
                                Text(
                                    text = stressBadgeText,
                                    color = stressBadgeColor,
                                    fontSize = 7.5.sp,
                                    fontWeight = FontWeight.Bold
                                )
                            }
                        }

                        Row(verticalAlignment = Alignment.CenterVertically) {
                            if (isTutor && message.translatedText != null) {
                                TextButton(
                                    onClick = { showTranslation.value = !showTranslation.value },
                                    contentPadding = PaddingValues(0.dp),
                                    modifier = Modifier.height(24.dp)
                                ) {
                                    Text(if (showTranslation.value) "Hide translation" else "Translate", fontSize = 10.sp, color = LingoPrimary)
                                }
                            }
                            if (isTutor) {
                                IconButton(
                                    onClick = { speechHelper.speak(message.originalText, language, cefrLevel, stressLevel = stressLevel, speedMultiplier = speedMultiplier) },
                                    modifier = Modifier.size(24.dp)
                                ) {
                                    Icon(Icons.Default.VolumeUp, contentDescription = "Odsłuchaj", modifier = Modifier.size(16.dp), tint = LingoPrimary)
                                }
                                if (onShadowClick != null) {
                                    IconButton(
                                        onClick = { onShadowClick(cleanDialogue, message.translatedText) },
                                        modifier = Modifier.size(24.dp)
                                    ) {
                                        Text("🗣️", fontSize = 11.sp)
                                    }
                                }
                                IconButton(
                                    onClick = {
                                        com.example.ui.shadowing.ShadowingEngine.launchEngine(
                                            com.example.ui.shadowing.ShadowingInputContent(
                                                source = com.example.ui.shadowing.ShadowingSource.LiveChatMessage(
                                                    messageText = cleanDialogue,
                                                    contextTopic = "Czat Lektora AI",
                                                    speakerName = "Lingo Tutor"
                                                ),
                                                targetLanguage = language
                                            )
                                        )
                                    },
                                    modifier = Modifier.size(24.dp)
                                ) {
                                    Text("⚡", fontSize = 11.sp)
                                }
                            }
                        }
                    }

                    Spacer(modifier = Modifier.height(4.dp))

                    // Ambient / Background Noise simulation block
                    if (isTutor && ambientEvents.isNotEmpty()) {
                        ambientEvents.forEach { event ->
                            Row(
                                modifier = Modifier
                                    .fillMaxWidth()
                                    .padding(vertical = 3.dp)
                                    .clip(RoundedCornerShape(6.dp))
                                    .background(Color(0xFFFFEBEE))
                                    .border(1.dp, Color(0xFFFFCDD2), RoundedCornerShape(6.dp))
                                    .padding(horizontal = 8.dp, vertical = 4.dp),
                                verticalAlignment = Alignment.CenterVertically
                            ) {
                                Icon(
                                    imageVector = Icons.Default.Warning,
                                    contentDescription = "Gwar",
                                    tint = Color(0xFFD32F2F),
                                    modifier = Modifier.size(11.dp)
                                )
                                Spacer(modifier = Modifier.width(6.dp))
                                Text(
                                    text = "DŹWIĘK W TLE: ${event.uppercase()}",
                                    color = Color(0xFFC62828),
                                    fontSize = 8.sp,
                                    fontWeight = FontWeight.ExtraBold,
                                    letterSpacing = 0.5.sp
                                )
                            }
                        }
                        Spacer(modifier = Modifier.height(4.dp))
                    }

                    // Text Content with highlights if corrected
                    if (!isTutor && message.isCorrected && message.correctedText != null) {
                        Column {
                            // original sentence with strikeout
                            Text(
                                text = cleanDialogue,
                                fontSize = 14.sp,
                                textDecoration = TextDecoration.LineThrough,
                                color = LingoErrorRed.copy(alpha = 0.8f)
                            )
                            Spacer(modifier = Modifier.height(4.dp))
                            // corrected sentence in green
                            Text(
                                text = message.correctedText,
                                fontSize = 15.sp,
                                fontWeight = FontWeight.Bold,
                                color = LingoSuccessGreen
                            )
                        }
                    } else {
                        Text(
                            text = cleanDialogue,
                            fontSize = 15.sp,
                            color = MaterialTheme.colorScheme.onSurface
                        )
                    }

                    if (showTranslation.value && message.translatedText != null) {
                        Spacer(modifier = Modifier.height(6.dp))
                        Text(
                            text = message.translatedText,
                            fontSize = 13.sp,
                            color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.6f)
                        )
                    }
                }
            }

            // Real-Time grammar/mistake explanation expander
            if (!isTutor && message.isCorrected && !message.correctionExplanation.isNullOrBlank()) {
                Spacer(modifier = Modifier.height(4.dp))
                Row(
                    verticalAlignment = Alignment.CenterVertically,
                    modifier = Modifier
                        .clickable { showCorrectionDetails.value = !showCorrectionDetails.value }
                        .padding(horizontal = 4.dp)
                ) {
                    Icon(Icons.Default.Warning, contentDescription = null, tint = LingoGold, modifier = Modifier.size(12.dp))
                    Spacer(modifier = Modifier.width(4.dp))
                    Text(
                        text = if (showCorrectionDetails.value) "Hide Correction details" else "See Correction details",
                        fontSize = 11.sp,
                        fontWeight = FontWeight.Bold,
                        color = LingoGold
                    )
                }

                if (showCorrectionDetails.value) {
                    val showExplanationTranslation = remember { mutableStateOf(false) }
                    val translatedExplanation = remember { mutableStateOf<String?>(null) }
                    val isTranslating = remember { mutableStateOf(false) }
                    val scope = rememberCoroutineScope()

                    Card(
                        shape = RoundedCornerShape(12.dp),
                        colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surface),
                        border = BorderStroke(1.dp, LingoGold.copy(alpha = 0.4f)),
                        modifier = Modifier
                            .fillMaxWidth(0.95f)
                            .padding(top = 4.dp)
                    ) {
                        Column(modifier = Modifier.padding(12.dp)) {
                            Row(
                                modifier = Modifier.fillMaxWidth(),
                                horizontalArrangement = Arrangement.SpaceBetween,
                                verticalAlignment = Alignment.CenterVertically
                            ) {
                                Text("COACH CORRECTION TIP", fontSize = 10.sp, fontWeight = FontWeight.Bold, color = LingoGold)
                                
                                TextButton(
                                    onClick = {
                                        if (translatedExplanation.value == null && !isTranslating.value) {
                                            isTranslating.value = true
                                            scope.launch {
                                                try {
                                                    translatedExplanation.value = com.example.data.api.TutorAiService.translateSentenceToPolish(
                                                        message.correctionExplanation,
                                                        language
                                                    )
                                                } catch (e: Exception) {
                                                    translatedExplanation.value = "Błąd tłumaczenia: ${e.localizedMessage}"
                                                } finally {
                                                    isTranslating.value = false
                                                }
                                            }
                                        }
                                        showExplanationTranslation.value = !showExplanationTranslation.value
                                    },
                                    contentPadding = PaddingValues(0.dp),
                                    modifier = Modifier.height(24.dp)
                                ) {
                                    Text(
                                        text = if (isTranslating.value) "Tłumaczenie..." else if (showExplanationTranslation.value) "Pokaż oryginał" else "Tłumacz na PL 🇵🇱",
                                        fontSize = 10.sp,
                                        color = LingoGold
                                    )
                                }
                            }
                            Spacer(modifier = Modifier.height(4.dp))
                            Text(
                                text = if (showExplanationTranslation.value && translatedExplanation.value != null) translatedExplanation.value!! else message.correctionExplanation,
                                fontSize = 12.sp,
                                color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.8f)
                            )
                        }
                    }
                }
            }
        }
    }
}

// ==========================================
// 6. POST-SESSION DETAILED FEEDBACK REPORT
// ==========================================
@Composable
fun EvaluationScreen(
    evaluation: SessionEvaluationResponse,
    viewModel: TutorViewModel,
    sessionTitle: String,
    onClose: (() -> Unit)? = null
) {
    Card(
        modifier = Modifier
            .fillMaxSize()
            .statusBarsPadding()
            .navigationBarsPadding()
            .padding(16.dp),
        shape = RoundedCornerShape(24.dp),
        colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surface),
        elevation = CardDefaults.cardElevation(defaultElevation = 8.dp)
    ) {
        Column(
            modifier = Modifier
                .fillMaxSize()
                .padding(24.dp),
            verticalArrangement = Arrangement.SpaceBetween
        ) {
            Column(modifier = Modifier.weight(1f)) {
                Row(
                    modifier = Modifier.fillMaxWidth(),
                    horizontalArrangement = Arrangement.SpaceBetween,
                    verticalAlignment = Alignment.CenterVertically
                ) {
                    Text(
                        text = "Session Coaching Report",
                        fontSize = 20.sp,
                        fontWeight = FontWeight.Bold,
                        color = MaterialTheme.colorScheme.onSurface
                    )
                    IconButton(onClick = {
                        if (onClose != null) onClose() else viewModel.dismissFeedback()
                    }) {
                        Icon(Icons.Default.Close, contentDescription = "Close Report")
                    }
                }

                Text(
                    text = "Dialogue: $sessionTitle",
                    fontSize = 14.sp,
                    color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.6f)
                )

                Spacer(modifier = Modifier.height(20.dp))

                // Score dial
                Row(
                    verticalAlignment = Alignment.CenterVertically,
                    horizontalArrangement = Arrangement.spacedBy(16.dp),
                    modifier = Modifier
                        .fillMaxWidth()
                        .clip(RoundedCornerShape(16.dp))
                        .background(LingoPrimary.copy(alpha = 0.1f))
                        .padding(16.dp)
                ) {
                    Box(
                        modifier = Modifier
                            .size(60.dp)
                            .clip(CircleShape)
                            .background(
                                Brush.radialGradient(
                                    colors = listOf(LingoPrimaryLight, LingoPrimary)
                                )
                            ),
                        contentAlignment = Alignment.Center
                    ) {
                        Text(
                            text = "${evaluation.fluencyScore}",
                            fontWeight = FontWeight.Bold,
                            color = Color.White,
                            fontSize = 20.sp
                        )
                    }

                    Column {
                        Text("Speaking Fluency Score", fontWeight = FontWeight.Bold, fontSize = 15.sp)
                        Text(
                            text = when {
                                evaluation.fluencyScore >= 85 -> "Outstanding dialogue fluidity!"
                                evaluation.fluencyScore >= 70 -> "Great interaction, keep active"
                                else -> "Building solid speech coordination."
                            },
                            fontSize = 12.sp,
                            color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.7f)
                        )
                    }
                }

                Spacer(modifier = Modifier.height(20.dp))

                // Scrollable coaching content
                Column(
                    modifier = Modifier
                        .weight(1f)
                        .verticalScroll(rememberScrollState()),
                    verticalArrangement = Arrangement.spacedBy(16.dp)
                ) {
                    CoachingSection(
                        title = "Your Strengths",
                        body = evaluation.strengths,
                        icon = Icons.Default.CheckCircle,
                        iconColor = LingoSuccessGreen
                    )

                    CoachingSection(
                        title = "Areas of Improvement",
                        body = evaluation.improvements,
                        icon = Icons.Default.Warning,
                        iconColor = LingoGold
                    )

                    CoachingSection(
                        title = "Grammar Coach Tips",
                        body = evaluation.grammarTips,
                        icon = Icons.Default.Face,
                        iconColor = LingoSecondaryLight
                    )

                    CoachingSection(
                        title = "Personal study Plan",
                        body = evaluation.studyPlan,
                        icon = Icons.Default.Info,
                        iconColor = LingoPrimary
                    )
                }
            }

            Spacer(modifier = Modifier.height(16.dp))

            Button(
                onClick = {
                    if (onClose != null) onClose() else viewModel.dismissFeedback()
                },
                modifier = Modifier
                    .fillMaxWidth()
                    .height(50.dp)
                    .testTag("feedback_dismiss_btn"),
                colors = ButtonDefaults.buttonColors(containerColor = LingoPrimary),
                shape = RoundedCornerShape(16.dp)
            ) {
                Text("Back to dashboard", fontWeight = FontWeight.Bold, fontSize = 15.sp)
            }
        }
    }
}

