@Composable
fun SiriLikeWaveform(
    isSpeaking: Boolean,
    isListening: Boolean,
    rmsLevel: Float = 0f,
    modifier: Modifier = Modifier
) {
    val transition = rememberInfiniteTransition(label = "wave")
    val phase by transition.animateFloat(
        initialValue = 0f,
        targetValue = (2f * Math.PI).toFloat(),
        animationSpec = infiniteRepeatable(
            animation = tween(1400, easing = LinearEasing),
            repeatMode = RepeatMode.Restart
        ),
        label = "phase"
    )

    // Map rmsLevel (normally ranges from -2 to 12+) to a beautiful responsive amplitude
    val liveMicAmplitude = if (isListening) {
        val normalizedRms = (rmsLevel + 2f).coerceAtLeast(0f)
        12f + (normalizedRms * 4f).coerceAtMost(35f)
    } else {
        0f
    }

    val maxAmplitude = if (isSpeaking) 24f else if (isListening) liveMicAmplitude else 5f
    val speedMultiplier = if (isSpeaking) 1.8f else if (isListening) (1.2f + (rmsLevel.coerceAtLeast(0f) / 8f)) else 0.5f

    Canvas(
        modifier = modifier
            .fillMaxWidth()
            .height(55.dp)
    ) {
        val width = size.width
        val height = size.height
        val centerY = height / 2

        // Draw EXACTLY 2 overlapping curves with beautiful high-contrast custom colors
        val waves = listOf(
            Triple(Color(0xFF00D2FF), 1.3f, 0.0f),
            Triple(Color(0xFF3A7BD5), 1.8f, (Math.PI / 2f).toFloat())
        )

        waves.forEach { (color, frequency, phaseShift) ->
            val path = androidx.compose.ui.graphics.Path()
            path.moveTo(0f, centerY)

            for (x in 0..width.toInt() step 4) {
                val normalizedX = x.toFloat() / width
                val envelope = kotlin.math.sin(normalizedX * Math.PI.toFloat())
                val y = centerY + envelope * maxAmplitude * kotlin.math.sin(
                    normalizedX * frequency * 2f * Math.PI.toFloat() * speedMultiplier + phase + phaseShift
                )
                path.lineTo(x.toFloat(), y)
            }

            drawPath(
                path = path,
                color = color.copy(alpha = 0.65f),
                style = androidx.compose.ui.graphics.drawscope.Stroke(
                    width = 2.dp.toPx(), 
                    cap = androidx.compose.ui.graphics.StrokeCap.Round
                )
            )
        }
    }
}

@Composable
fun LiveCallView(
    session: Session,
    viewModel: TutorViewModel,
    isAiLoading: Boolean,
    messages: List<ChatMessage>,
    speechHelper: TutorSpeechHelper,
    isMicListening: Boolean,
    rmsLevel: Float,
    isMuted: MutableState<Boolean>,
    isSpeechAvailable: Boolean,
    onCloseCall: () -> Unit,
    startVoiceListening: () -> Unit
) {
    val lastUserMessage = messages.lastOrNull { !it.sender.equals("tutor", ignoreCase = true) }
    val isSpeakerOn = remember { mutableStateOf(true) }
    val manualInputText = remember { mutableStateOf("") }
    val currentPlaybackSpeed by viewModel.playbackSpeed.collectAsStateWithLifecycle()
    val showDictInCall = remember { mutableStateOf(false) }
    val showAcceleratorDialog = remember { mutableStateOf(false) }
    val showManualInput = remember { mutableStateOf(false) }
    val coroutineScope = rememberCoroutineScope()
    val connectionStatus by viewModel.connectionStatus.collectAsStateWithLifecycle()

    val bgColors = when (session.stressLevel) {
        1 -> listOf(Color(0xFF1E1B0E), Color(0xFF2C2411), Color(0xFF3B2F16)) // Warm alert / time pressure
        2 -> listOf(Color(0xFF240C0C), Color(0xFF351212), Color(0xFF451919)) // Chaotic red / warning
        else -> listOf(Color(0xFF0F2027), Color(0xFF203A43), Color(0xFF2C5364)) // Standard beautiful gradient
    }

    Box(
        modifier = Modifier
            .fillMaxSize()
            .background(Brush.verticalGradient(colors = bgColors))
            .statusBarsPadding()
            .navigationBarsPadding()
            .padding(horizontal = 16.dp, vertical = 6.dp)
    ) {
        Column(
            modifier = Modifier.fillMaxSize(),
            horizontalAlignment = Alignment.CenterHorizontally,
            verticalArrangement = Arrangement.SpaceBetween
        ) {
            // 1. COMPACT HEADER ROW
            Column(
                horizontalAlignment = Alignment.CenterHorizontally,
                modifier = Modifier.padding(top = 4.dp)
            ) {
                Row(
                    verticalAlignment = Alignment.CenterVertically,
                    horizontalArrangement = Arrangement.spacedBy(8.dp)
                ) {
                    Text(
                        text = "Tutor Lingo",
                        color = Color.White,
                        fontSize = 18.sp,
                        fontWeight = FontWeight.Bold
                    )
                    Text(
                        text = "•",
                        color = Color.White.copy(alpha = 0.5f),
                        fontSize = 14.sp
                    )
                    Text(
                        text = "${session.language} (${session.cefrLevel})",
                        color = Color.White.copy(alpha = 0.8f),
                        fontSize = 13.sp,
                        fontWeight = FontWeight.Medium
                    )

                    Spacer(modifier = Modifier.width(4.dp))

                    // Status Dot Indicator
                    Box(
                        modifier = Modifier
                            .clip(RoundedCornerShape(12.dp))
                            .background(Color.White.copy(alpha = 0.12f))
                            .padding(horizontal = 8.dp, vertical = 4.dp)
                    ) {
                        Row(
                            verticalAlignment = Alignment.CenterVertically,
                            horizontalArrangement = Arrangement.spacedBy(4.dp)
                        ) {
                            Box(
                                modifier = Modifier
                                    .size(6.dp)
                                    .clip(CircleShape)
                                    .background(
                                        if (connectionStatus == com.example.data.api.ConnectionStatus.RECONNECTING) Color(0xFFFF9800)
                                        else if (connectionStatus == com.example.data.api.ConnectionStatus.DISCONNECTED) Color(0xFFF44336)
                                        else if (isAiLoading) Color(0xFFFFC107)
                                        else if (speechHelper.isSpeaking) Color(0xFFE52D27)
                                        else if (isMuted.value) Color.Gray
                                        else if (isMicListening) Color(0xFF4CAF50)
                                        else Color.White.copy(alpha = 0.4f)
                                    )
                            )
                            Text(
                                text = if (connectionStatus == com.example.data.api.ConnectionStatus.RECONNECTING) "Reconnecting..."
                                       else if (connectionStatus == com.example.data.api.ConnectionStatus.DISCONNECTED) "Offline"
                                       else if (isAiLoading) "Myśli..." 
                                       else if (speechHelper.isSpeaking) "Mówi..." 
                                       else if (isMuted.value) "Mute"
                                       else if (isMicListening) "Słucha"
                                       else "Czeka",
                                color = Color.White,
                                fontSize = 9.sp,
                                fontWeight = FontWeight.Bold
                            )
                        }
                    }
                }

                // 1.5 VIBE SELECTOR
                Spacer(modifier = Modifier.height(6.dp))
                val currentVibe by viewModel.activeSessionVibe.collectAsStateWithLifecycle()
                val vibesList = listOf(
                    Triple("normal", "🍃 Standard", "Zrównoważony"),
                    Triple("gossip", "💬 Plotki", "Small talk"),
                    Triple("deeptalk", "🧠 Głęboka", "Filozofia"),
                    Triple("humor", "🎭 Żarty", "Banter"),
                    Triple("survival", "🎒 Survival", "Sytuacje")
                )
                LazyRow(
                    horizontalArrangement = Arrangement.spacedBy(6.dp),
                    contentPadding = PaddingValues(horizontal = 4.dp),
                    modifier = Modifier.fillMaxWidth()
                ) {
                    items(vibesList) { item ->
                        val vibeKey = item.first
                        val vibeLabel = item.second
                        val vibeDesc = item.third
                        val isSelected = currentVibe == vibeKey
                        Box(
                            modifier = Modifier
                                .clip(RoundedCornerShape(10.dp))
                                .background(
                                    if (isSelected) Color(0xFF00D2FF).copy(alpha = 0.22f)
                                    else Color.White.copy(alpha = 0.06f)
                                )
                                .border(
                                    width = 1.dp,
                                    color = if (isSelected) Color(0xFF00D2FF) else Color.White.copy(alpha = 0.12f),
                                    shape = RoundedCornerShape(10.dp)
                                )
                                .clickable {
                                    viewModel.changeSessionVibe(vibeKey)
                                }
                                .padding(horizontal = 8.dp, vertical = 4.dp),
                            contentAlignment = Alignment.Center
                        ) {
                            Column(horizontalAlignment = Alignment.CenterHorizontally) {
                                Text(
                                    text = vibeLabel,
                                    color = if (isSelected) Color(0xFF00D2FF) else Color.White,
                                    fontSize = 10.sp,
                                    fontWeight = FontWeight.Bold
                                )
                                Text(
                                    text = vibeDesc,
                                    color = Color.White.copy(alpha = 0.5f),
                                    fontSize = 7.sp
                                )
                            }
                        }
                    }
                }
            }
            
            if (connectionStatus != com.example.data.api.ConnectionStatus.CONNECTED) {
                Spacer(modifier = Modifier.height(8.dp))
                Card(
                    colors = CardDefaults.cardColors(
                        containerColor = if (connectionStatus == com.example.data.api.ConnectionStatus.RECONNECTING) 
                            Color(0xFFFFB74D).copy(alpha = 0.2f) 
                        else 
                            Color(0xFFE57373).copy(alpha = 0.2f)
                    ),
                    shape = RoundedCornerShape(8.dp),
                    modifier = Modifier.fillMaxWidth().padding(horizontal = 8.dp)
                ) {
                    Row(
                        modifier = Modifier.padding(8.dp),
                        verticalAlignment = Alignment.CenterVertically,
                        horizontalArrangement = Arrangement.Center
                    ) {
                        Icon(
                            imageVector = if (connectionStatus == com.example.data.api.ConnectionStatus.RECONNECTING) 
                                Icons.Default.Refresh 
                            else 
                                Icons.Default.CloudOff,
                            contentDescription = null,
                            tint = Color.White,
                            modifier = Modifier.size(14.dp)
                        )
                        Spacer(modifier = Modifier.width(6.dp))
                        Text(
                            text = if (connectionStatus == com.example.data.api.ConnectionStatus.RECONNECTING) 
                                "Przywracanie połączenia... Zachowano stan." 
                            else 
                                "Brak połączenia. Spróbuj mówić ponownie po przywróceniu sieci.",
                            color = Color.White,
                            fontSize = 10.sp,
                            fontWeight = FontWeight.Medium
                        )
                    }
                }
            }

            // 2. GLOWING WAVEFORM (Beautiful, compact, highly visible 60.dp height!)
            Box(
                modifier = Modifier
                    .fillMaxWidth()
                    .height(60.dp),
                contentAlignment = Alignment.Center
            ) {
                SiriLikeWaveform(
                    isSpeaking = speechHelper.isSpeaking,
                    isListening = !isAiLoading && !speechHelper.isSpeaking && !isMuted.value,
                    rmsLevel = rmsLevel
                )
            }

            // ENVIRONMENTAL SIMULATION STATUS CARD
            val envStatusTitle = when (session.stressLevel) {
                1 -> "⚡ POZIOM STRESU: REALISTYCZNA PRESJA CZASU"
                2 -> "🔥 POZIOM STRESU: EKSTREMALNY CHAOS I GWAR"
                else -> "🍃 POZIOM STRESU: OAZA SPOKOJU"
            }
            val envStatusDesc = when (session.stressLevel) {
                1 -> "Szybkie tempo rozmowy! Odpowiedz krótko i bez zbędnej zwłoki."
                2 -> "Głośne otoczenie i zakłócenia! Skup się i mów głośno, pewnie i wyraźnie."
                else -> "Całkowicie bezstresowy tryb. Spokojne tempo, sprzyjające przemyśleniu zdań."
            }
            val envStatusColor = when (session.stressLevel) {
                1 -> Color(0xFFFFB300)
                2 -> Color(0xFFE53935)
                else -> Color(0xFF4CAF50)
            }
            
            Card(
                modifier = Modifier
                    .fillMaxWidth()
                    .padding(vertical = 4.dp),
                shape = RoundedCornerShape(10.dp),
                colors = CardDefaults.cardColors(containerColor = envStatusColor.copy(alpha = 0.08f)),
                border = BorderStroke(1.dp, envStatusColor.copy(alpha = 0.25f))
            ) {
                Row(
                    modifier = Modifier.padding(horizontal = 10.dp, vertical = 6.dp),
                    verticalAlignment = Alignment.CenterVertically
                ) {
                    Box(
                        modifier = Modifier
                            .size(6.dp)
                            .clip(CircleShape)
                            .background(envStatusColor)
                    )
                    Spacer(modifier = Modifier.width(8.dp))
                    Column {
                        Text(
                            text = envStatusTitle,
                            color = envStatusColor,
                            fontSize = 9.5.sp,
                            fontWeight = FontWeight.Bold,
                            letterSpacing = 0.5.sp
                        )
                        Text(
                            text = envStatusDesc,
                            color = Color.White.copy(alpha = 0.75f),
                            fontSize = 8.5.sp,
                            lineHeight = 11.sp
                        )
                    }
                }
            }

            // MIDDLE SCROLLABLE PANEL (SUBTITLES, ACTIVE COACHING & SUFLER)
            val selectedCoachingTab = remember { mutableStateOf(0) }
            val showTranslation = remember { mutableStateOf(true) }
            val latestTutorMessage = messages.lastOrNull { it.sender.equals("tutor", ignoreCase = true) }

            Column(
                modifier = Modifier
                    .weight(1f)
                    .fillMaxWidth()
                    .verticalScroll(rememberScrollState())
                    .padding(vertical = 4.dp),
                verticalArrangement = Arrangement.spacedBy(10.dp)
            ) {
                // 2.5 REAL-TIME AI SUBTITLES / TRANSCRIPT CARD
                if (latestTutorMessage != null) {
                    val bracketRegex = Regex("\\[(.*?)\\]")
                    val parenRegex = Regex("\\((.*?)\\)")
                    val ambientEvents = mutableListOf<String>()
                    bracketRegex.findAll(latestTutorMessage.originalText).forEach { ambientEvents.add(it.groupValues[1]) }
                    parenRegex.findAll(latestTutorMessage.originalText).forEach { match ->
                        val content = match.groupValues[1]
                        if (content.length > 3 && (content.first().isUpperCase() || content.contains("gwar") || content.contains("szum") || content.contains("głos"))) {
                            ambientEvents.add(content)
                        }
                    }
                    val cleanDialogue = latestTutorMessage.originalText
                        .replace(bracketRegex, "")
                        .replace(parenRegex, "")
                        .replace(Regex("\\s+"), " ")
                        .trim()
                        .ifEmpty { latestTutorMessage.originalText }

                    Card(
                        modifier = Modifier.fillMaxWidth(),
                        shape = RoundedCornerShape(14.dp),
                        colors = CardDefaults.cardColors(containerColor = Color.White.copy(alpha = 0.08f)),
                        border = BorderStroke(1.dp, Color.White.copy(alpha = 0.15f))
                    ) {
                        Column(modifier = Modifier.padding(10.dp)) {
                            Row(
                                modifier = Modifier.fillMaxWidth(),
                                horizontalArrangement = Arrangement.SpaceBetween,
                                verticalAlignment = Alignment.CenterVertically
                            ) {
                                Row(verticalAlignment = Alignment.CenterVertically) {
                                    Icon(
                                        imageVector = if (speechHelper.isSpeaking) Icons.Default.VolumeUp else Icons.Default.VolumeDown,
                                        contentDescription = null,
                                        tint = Color(0xFF00D2FF),
                                        modifier = Modifier.size(14.dp)
                                    )
                                    Spacer(modifier = Modifier.width(6.dp))
                                    Text(
                                        text = if (speechHelper.isSpeaking) "Napisy: Lektor mówi" else "Ostatnia wypowiedź lektora:",
                                        color = Color.White,
                                        fontWeight = FontWeight.Bold,
                                        fontSize = 10.sp
                                    )
                                }
                                Text(
                                    text = if (showTranslation.value) "Ukryj tłum." else "Pokaż tłum.",
                                    color = Color(0xFF00D2FF),
                                    fontSize = 9.sp,
                                    fontWeight = FontWeight.Bold,
                                    modifier = Modifier.clickable { showTranslation.value = !showTranslation.value }
                                )
                            }

                            // Subtitles Ambient event indicators
                            if (ambientEvents.isNotEmpty()) {
                                Spacer(modifier = Modifier.height(4.dp))
                                ambientEvents.forEach { event ->
                                    Row(
                                        modifier = Modifier
                                            .fillMaxWidth()
                                            .clip(RoundedCornerShape(6.dp))
                                            .background(Color(0xFFD32F2F).copy(alpha = 0.15f))
                                            .border(1.dp, Color(0xFFE53935).copy(alpha = 0.3f), RoundedCornerShape(6.dp))
                                            .padding(horizontal = 8.dp, vertical = 4.dp),
                                        verticalAlignment = Alignment.CenterVertically
                                    ) {
                                        Icon(
                                            imageVector = Icons.Default.Warning,
                                            contentDescription = "Chaos",
                                            tint = Color(0xFFFF5252),
                                            modifier = Modifier.size(11.dp)
                                        )
                                        Spacer(modifier = Modifier.width(6.dp))
                                        Text(
                                            text = "ZAKŁÓCENIE W TLE: ${event.uppercase()}",
                                            color = Color(0xFFFF8A80),
                                            fontSize = 8.5.sp,
                                            fontWeight = FontWeight.Bold
                                        )
                                    }
                                }
                            }

                            Spacer(modifier = Modifier.height(4.dp))
                            Row(
                                modifier = Modifier.fillMaxWidth(),
                                verticalAlignment = Alignment.CenterVertically,
                                horizontalArrangement = Arrangement.SpaceBetween
                            ) {
                                Column(modifier = Modifier.weight(1f)) {
                                    Text(
                                        text = cleanDialogue,
                                        color = Color.White,
                                        fontSize = 13.sp,
                                        fontWeight = FontWeight.SemiBold,
                                        lineHeight = 17.sp
                                    )
                                    if (showTranslation.value && !latestTutorMessage.translatedText.isNullOrBlank()) {
                                        Spacer(modifier = Modifier.height(4.dp))
                                        Text(
                                            text = latestTutorMessage.translatedText!!,
                                            color = Color.White.copy(alpha = 0.6f),
                                            fontSize = 11.sp,
                                            fontStyle = FontStyle.Italic,
                                            lineHeight = 15.sp
                                        )
                                    }
                                }
                                IconButton(
                                    onClick = {
                                        speechHelper.speak(
                                            latestTutorMessage.originalText,
                                            session.language,
                                            session.cefrLevel,
                                            stressLevel = session.stressLevel,
                                            speedMultiplier = currentPlaybackSpeed
                                        )
                                    },
                                    modifier = Modifier
                                        .padding(start = 8.dp)
                                        .size(36.dp)
                                ) {
                                    Icon(
                                        imageVector = Icons.Default.Replay,
                                        contentDescription = "Powtórz",
                                        tint = Color(0xFF00D2FF),
                                        modifier = Modifier.size(22.dp)
                                    )
                                }
                            }

                            Divider(color = Color.White.copy(alpha = 0.1f), modifier = Modifier.padding(vertical = 8.dp))
                            // Combined Row: Playback Speeds, Słow AI, Accel
                            Row(
                                modifier = Modifier.fillMaxWidth(),
                                verticalAlignment = Alignment.CenterVertically,
                                horizontalArrangement = Arrangement.SpaceBetween
                            ) {
                                // Playback speeds selector (Left side)
                                Row(
                                    verticalAlignment = Alignment.CenterVertically,
                                    horizontalArrangement = Arrangement.spacedBy(3.dp)
                                ) {
                                    val speeds = listOf(0.65f, 0.75f, 0.85f, 1.0f)
                                    speeds.forEach { speed ->
                                        val isSelected = currentPlaybackSpeed == speed
                                        Box(
                                            modifier = Modifier
                                                .clip(RoundedCornerShape(6.dp))
                                                .background(if (isSelected) Color(0xFF00D2FF).copy(alpha = 0.25f) else Color.Transparent)
                                                .border(
                                                    width = 1.dp,
                                                    color = if (isSelected) Color(0xFF00D2FF) else Color.White.copy(alpha = 0.15f),
                                                    shape = RoundedCornerShape(6.dp)
                                                )
                                                .clickable { viewModel.setPlaybackSpeed(speed) }
                                                .padding(horizontal = 6.dp, vertical = 4.dp)
                                        ) {
                                            Text(
                                                text = "${speed}x",
                                                color = if (isSelected) Color(0xFF00D2FF) else Color.White,
                                                fontSize = 10.sp,
                                                fontWeight = FontWeight.Bold
                                            )
                                        }
                                    }
                                }

                                // Actions (Right side: Słow AI and Accel)
                                Row(
                                    verticalAlignment = Alignment.CenterVertically,
                                    horizontalArrangement = Arrangement.spacedBy(4.dp)
                                ) {
                                    // Słownik AI Button
                                    Button(
                                        onClick = { showDictInCall.value = true },
                                        colors = ButtonDefaults.buttonColors(containerColor = Color(0xFF4CAF50)),
                                        shape = RoundedCornerShape(6.dp),
                                        contentPadding = PaddingValues(horizontal = 6.dp, vertical = 0.dp),
                                        modifier = Modifier.height(28.dp)
                                    ) {
                                        Icon(
                                            imageVector = Icons.Default.Translate,
                                            contentDescription = "Słownik AI",
                                            tint = Color.White,
                                            modifier = Modifier.size(10.dp)
                                        )
                                        Spacer(modifier = Modifier.width(3.dp))
                                        Text(
                                            text = "Słow AI",
                                            color = Color.White,
                                            fontSize = 10.sp,
                                            fontWeight = FontWeight.Bold
                                        )
                                    }

                                    // AI Accelerator Button
                                    Button(
                                        onClick = { 
                                            viewModel.clearAcceleratorElements()
                                            showAcceleratorDialog.value = true
                                        },
                                        colors = ButtonDefaults.buttonColors(containerColor = Color(0xFFFFF8E1)),
                                        shape = RoundedCornerShape(6.dp),
                                        contentPadding = PaddingValues(horizontal = 6.dp, vertical = 0.dp),
                                        modifier = Modifier
                                            .height(28.dp)
                                            .border(1.dp, Color(0xFFFFB300).copy(alpha = 0.6f), RoundedCornerShape(6.dp))
                                    ) {
                                        Text(
                                            text = "⚡ Accel",
                                            color = Color(0xFFFF8F00),
                                            fontSize = 10.sp,
                                            fontWeight = FontWeight.Bold
                                        )
                                    }
                                }
                            }
                        }
                    }
                } else {
                    Card(
                        modifier = Modifier.fillMaxWidth(),
                        shape = RoundedCornerShape(14.dp),
                        colors = CardDefaults.cardColors(containerColor = Color.White.copy(alpha = 0.05f)),
                        border = BorderStroke(1.dp, Color.White.copy(alpha = 0.10f))
                    ) {
                        Box(
                            modifier = Modifier
                                .fillMaxWidth()
                                .padding(12.dp),
                            contentAlignment = Alignment.Center
                        ) {
                            Text(
                                text = "Połączono. Powiedz coś w języku ${session.language}, aby rozpocząć!",
                                color = Color.White.copy(alpha = 0.5f),
                                fontSize = 11.sp,
                                fontStyle = FontStyle.Italic,
                                textAlign = TextAlign.Center
                            )
                        }
                    }
                }

                // 3.5 SUFLER AI / ADVANCED INTERACTIVE SUGGESTIONS
                val suggestions by viewModel.latestSuggestions.collectAsStateWithLifecycle()
                if (suggestions.isNotEmpty()) {
                    Column(
                        modifier = Modifier.fillMaxWidth(),
                        verticalArrangement = Arrangement.spacedBy(6.dp)
                    ) {
                        Row(
                            modifier = Modifier.fillMaxWidth(),
                            horizontalArrangement = Arrangement.SpaceBetween,
                            verticalAlignment = Alignment.CenterVertically
                        ) {
                            Text(
                                text = "💡 Sufler AI (Podpowiedzi):",
                                color = Color.White.copy(alpha = 0.7f),
                                fontSize = 11.sp,
                                fontWeight = FontWeight.Bold,
                                modifier = Modifier.padding(start = 4.dp)
                            )
                            Text(
                                text = "Kliknij, aby odpowiedzieć",
                                color = Color(0xFF00D2FF),
                                fontSize = 10.sp,
                                fontWeight = FontWeight.SemiBold
                            )
                        }
                        LazyRow(
                            horizontalArrangement = Arrangement.spacedBy(8.dp),
                            modifier = Modifier.fillMaxWidth()
                        ) {
                            items(suggestions) { sugg ->
                                val parts = sugg.split(" [")
                                val original = parts.getOrNull(0) ?: sugg
                                val polish = parts.getOrNull(1)?.replace("]", "") ?: ""
                                
                                val isQuestion = original.trim().endsWith("?")
                                val isShort = original.split(" ").size <= 3
                                val isEmotional = original.contains("!") || original.contains("¡") || original.contains("oh", ignoreCase = true) || original.contains("wow", ignoreCase = true)
                                
                                val (badgeText, badgeColor) = when {
                                    isQuestion -> Pair("❓ Pytanie", Color(0xFF00D2FF))
                                    isEmotional -> Pair("🔥 Reakcja", Color(0xFFFF9800))
                                    isShort -> Pair("🍃 Szybka", Color(0xFF4CAF50))
                                    else -> Pair("💡 Kreatywna", Color(0xFF9C27B0))
                                }

                                Card(
                                    modifier = Modifier
                                        .widthIn(max = 220.dp)
                                        .clip(RoundedCornerShape(12.dp))
                                        .border(
                                            width = 1.dp,
                                            color = badgeColor.copy(alpha = 0.3f),
                                            shape = RoundedCornerShape(12.dp)
                                        ),
                                    colors = CardDefaults.cardColors(containerColor = Color.White.copy(alpha = 0.08f))
                                ) {
                                    Column(
                                        modifier = Modifier.padding(10.dp)
                                    ) {
                                        Row(
                                            modifier = Modifier.fillMaxWidth(),
                                            horizontalArrangement = Arrangement.SpaceBetween,
                                            verticalAlignment = Alignment.CenterVertically
                                        ) {
                                            Box(
                                                modifier = Modifier
                                                    .clip(RoundedCornerShape(6.dp))
                                                    .background(badgeColor.copy(alpha = 0.15f))
                                                    .padding(horizontal = 6.dp, vertical = 2.dp)
                                            ) {
                                                Text(
                                                    text = badgeText,
                                                    color = badgeColor,
                                                    fontSize = 8.sp,
                                                    fontWeight = FontWeight.Bold
                                                )
                                            }
                                            
                                            Icon(
                                                imageVector = Icons.Default.VolumeUp,
                                                contentDescription = "Odsłuchaj wymowę",
                                                tint = Color.White.copy(alpha = 0.5f),
                                                modifier = Modifier
                                                    .size(15.dp)
                                                    .clickable {
                                                        speechHelper.speak(original, session.language, session.cefrLevel)
                                                    }
                                            )
                                        }
                                        
                                        Spacer(modifier = Modifier.height(4.dp))
                                        
                                        Column(
                                            modifier = Modifier
                                                .fillMaxWidth()
                                                .clickable {
                                                    viewModel.submitUserMessage(original)
                                                }
                                        ) {
                                            Text(
                                                text = original,
                                                color = Color.White,
                                                fontSize = 12.sp,
                                                fontWeight = FontWeight.Bold,
                                                lineHeight = 15.sp
                                            )
                                            if (polish.isNotEmpty()) {
                                                Spacer(modifier = Modifier.height(2.dp))
                                                Text(
                                                    text = polish,
                                                    color = Color.White.copy(alpha = 0.6f),
                                                    fontSize = 9.sp,
                                                    fontStyle = FontStyle.Italic,
                                                    lineHeight = 12.sp
                                                )
                                            }
                                            Spacer(modifier = Modifier.height(4.dp))
                                            Text(
                                                text = "Kliknij, aby wysłać ➔",
                                                color = Color(0xFF00D2FF).copy(alpha = 0.8f),
                                                fontSize = 9.sp,
                                                fontWeight = FontWeight.Bold
                                            )
                                        }
                                    }
                                }
                            }
                        }
                    }
                }

                // 3. ACTIVE COACHING PANEL WITH TABS (🎙️ WYMOWA vs ✍️ GRAMATYKA)
                Card(
                    modifier = Modifier.fillMaxWidth(),
                    shape = RoundedCornerShape(14.dp),
                    colors = CardDefaults.cardColors(containerColor = Color.White.copy(alpha = 0.06f)),
                    border = BorderStroke(1.dp, Color.White.copy(alpha = 0.15f))
                ) {
                    Column(modifier = Modifier.padding(10.dp)) {
                        // TABS HEADER Row
                        Row(
                            modifier = Modifier
                                .fillMaxWidth()
                                .background(Color.White.copy(alpha = 0.05f), RoundedCornerShape(10.dp))
                                .padding(3.dp),
                            horizontalArrangement = Arrangement.SpaceEvenly
                        ) {
                            val isTab0 = selectedCoachingTab.value == 0
                            val isTab1 = selectedCoachingTab.value == 1
                            
                            // TAB 0: PRONUNCIATION
                            Box(
                                modifier = Modifier
                                    .weight(1f)
                                    .clip(RoundedCornerShape(8.dp))
                                    .background(if (isTab0) Color.White.copy(alpha = 0.12f) else Color.Transparent)
                                    .clickable { selectedCoachingTab.value = 0 }
                                    .padding(vertical = 5.dp),
                                contentAlignment = Alignment.Center
                            ) {
                                Row(verticalAlignment = Alignment.CenterVertically) {
                                    Icon(
                                        imageVector = Icons.Default.Mic, 
                                        contentDescription = null, 
                                        tint = if (isTab0) Color(0xFF00D2FF) else Color.White.copy(alpha = 0.6f), 
                                        modifier = Modifier.size(13.dp)
                                    )
                                    Spacer(modifier = Modifier.width(4.dp))
                                    Text(
                                        text = "🎙️ Wymowa", 
                                        color = if (isTab0) Color.White else Color.White.copy(alpha = 0.6f), 
                                        fontSize = 10.sp, 
                                        fontWeight = FontWeight.Bold
                                    )
                                }
                            }

                            // TAB 1: GRAMMAR & STYLE
                            val hasCorrection = lastUserMessage != null && lastUserMessage.isCorrected
                            Box(
                                modifier = Modifier
                                    .weight(1f)
                                    .clip(RoundedCornerShape(8.dp))
                                    .background(if (isTab1) Color.White.copy(alpha = 0.12f) else Color.Transparent)
                                    .clickable { selectedCoachingTab.value = 1 }
                                    .padding(vertical = 5.dp),
                                contentAlignment = Alignment.Center
                            ) {
                                Row(verticalAlignment = Alignment.CenterVertically) {
                                    Icon(
                                        imageVector = Icons.Default.CheckCircle, 
                                        contentDescription = null, 
                                        tint = if (isTab1) Color(0xFF4CAF50) else Color.White.copy(alpha = 0.6f), 
                                        modifier = Modifier.size(13.dp)
                                    )
                                    Spacer(modifier = Modifier.width(4.dp))
                                    Text(
                                        text = "✍️ Korekta", 
                                        color = if (isTab1) Color.White else Color.White.copy(alpha = 0.6f), 
                                        fontSize = 10.sp, 
                                        fontWeight = FontWeight.Bold
                                    )
                                    if (hasCorrection) {
                                        Spacer(modifier = Modifier.width(3.dp))
                                        Box(
                                            modifier = Modifier
                                                .size(5.dp)
                                                .clip(CircleShape)
                                                .background(Color(0xFFE52D27))
                                        )
                                    }
                                }
                            }
                        }

                        Spacer(modifier = Modifier.height(14.dp))

                        // TAB CONTENT RENDER
                        if (selectedCoachingTab.value == 0) {
                            // TAB 0 CONTENT: PRONUNCIATION ANALYSIS
                            Row(
                                modifier = Modifier.fillMaxWidth(),
                                horizontalArrangement = Arrangement.SpaceBetween,
                                verticalAlignment = Alignment.CenterVertically
                            ) {
                                Row(verticalAlignment = Alignment.CenterVertically) {
                                    Icon(
                                        imageVector = Icons.Default.Info,
                                        contentDescription = null,
                                        tint = Color(0xFF00D2FF),
                                        modifier = Modifier.size(16.dp)
                                    )
                                    Spacer(modifier = Modifier.width(8.dp))
                                    Text(
                                        text = "Ocena fonetyczna wypowiedzi",
                                        color = Color.White.copy(alpha = 0.7f),
                                        fontSize = 12.sp,
                                        fontWeight = FontWeight.SemiBold
                                    )
                                }
                                
                                if (lastUserMessage != null && lastUserMessage.pronunciationScore > 0) {
                                    Box(
                                        modifier = Modifier
                                            .clip(RoundedCornerShape(8.dp))
                                            .background(
                                                if (lastUserMessage.pronunciationScore >= 80) Color(0xFF4CAF50).copy(alpha = 0.2f)
                                                else Color(0xFFFFC107).copy(alpha = 0.2f)
                                            )
                                            .padding(horizontal = 8.dp, vertical = 4.dp)
                                    ) {
                                        Text(
                                            text = "${lastUserMessage.pronunciationScore}% poprawności",
                                            color = if (lastUserMessage.pronunciationScore >= 80) Color(0xFF81C784) else Color(0xFFFFD54F),
                                            fontSize = 10.sp,
                                            fontWeight = FontWeight.Bold
                                        )
                                    }
                                }
                            }

                            Spacer(modifier = Modifier.height(10.dp))

                            if (lastUserMessage != null) {
                                Column(verticalArrangement = Arrangement.spacedBy(8.dp)) {
                                    Text(
                                        text = "\"${lastUserMessage.originalText}\"",
                                        color = Color.White.copy(alpha = 0.9f),
                                        fontStyle = FontStyle.Italic,
                                        fontSize = 13.sp,
                                        lineHeight = 16.sp
                                    )

                                    if (!lastUserMessage.phoneticGuide.isNullOrBlank()) {
                                        Row(
                                            verticalAlignment = Alignment.CenterVertically,
                                            horizontalArrangement = Arrangement.spacedBy(6.dp)
                                        ) {
                                            Text(
                                                text = "Zapis fonetyczny:",
                                                color = Color.White.copy(alpha = 0.5f),
                                                fontSize = 11.sp,
                                                fontWeight = FontWeight.SemiBold
                                            )
                                            Text(
                                                text = lastUserMessage.phoneticGuide!!,
                                                color = Color(0xFF00D2FF),
                                                fontSize = 12.sp,
                                                fontWeight = FontWeight.Bold,
                                                fontFamily = FontFamily.Monospace
                                            )
                                        }
                                    }

                                    if (!lastUserMessage.pronunciationFeedback.isNullOrBlank()) {
                                        Text(
                                            text = lastUserMessage.pronunciationFeedback!!,
                                            color = Color.White.copy(alpha = 0.8f),
                                            fontSize = 12.sp,
                                            lineHeight = 17.sp
                                        )
                                    } else {
                                        Text(
                                            text = "Świetna próba! Kontynuuj mówienie w języku obcym. Lektor na bieżąco analizuje akcent, intonację i budowę zgłosek.",
                                            color = Color.White.copy(alpha = 0.6f),
                                            fontSize = 12.sp,
                                            lineHeight = 17.sp
                                        )
                                    }
                                }
                            } else {
                                Text(
                                    text = "Powiedz coś w języku ${session.language}. Twój lektor przeanalizuje akcent, ułożenie języka/ust oraz przedstawi uproszczoną transkrypcję fonetyczną.",
                                    color = Color.White.copy(alpha = 0.6f),
                                    fontSize = 12.sp,
                                    lineHeight = 17.sp
                                )
                            }

                            Spacer(modifier = Modifier.height(14.dp))

                            // INTERACTIVE MICROPHONE (Directly inside Tab 0 - always visible!)
                            val pulseTransition = rememberInfiniteTransition(label = "mic_pulse")
                            val micScale by pulseTransition.animateFloat(
                                initialValue = 1f,
                                targetValue = if (isMicListening) 1.08f else 1.03f,
                                animationSpec = infiniteRepeatable(
                                    animation = tween(1000, easing = FastOutSlowInEasing),
                                    repeatMode = RepeatMode.Reverse
                                ),
                                label = "scale"
                            )
                            val micGlowAlpha by pulseTransition.animateFloat(
                                initialValue = 0.2f,
                                targetValue = if (isMicListening) 0.6f else 0.3f,
                                animationSpec = infiniteRepeatable(
                                    animation = tween(1000, easing = FastOutSlowInEasing),
                                    repeatMode = RepeatMode.Reverse
                                ),
                                label = "glow"
                            )

                            val micBgColor = when {
                                isMuted.value -> Color.Gray
                                isAiLoading -> Color(0xFFFFC107) // Lingo thinking
                                speechHelper.isSpeaking -> Color(0xFF3A7BD5) // Lingo speaking
                                isMicListening -> Color(0xFF4CAF50) // Listening
                                else -> Color(0xFF00D2FF) // Ready to talk
                            }

                            val micStatusText = when {
                                isMuted.value -> "Wyciszony • Dotknij, aby włączyć"
                                isAiLoading -> "Lingo myśli... 🧠"
                                speechHelper.isSpeaking -> "Lingo mówi... 🗣️"
                                isMicListening -> "Słucham Cię! Mów śmiało 🎙️"
                                else -> "Rozmowa na żywo aktywna 🎙️"
                            }

                            Card(
                                modifier = Modifier
                                    .fillMaxWidth()
                                    .padding(top = 8.dp),
                                shape = RoundedCornerShape(16.dp),
                                colors = CardDefaults.cardColors(containerColor = Color.White.copy(alpha = 0.08f)),
                                border = BorderStroke(1.dp, Color.White.copy(alpha = 0.2f))
                            ) {
                                Column(
                                    modifier = Modifier
                                        .fillMaxWidth()
                                        .padding(14.dp),
                                    horizontalAlignment = Alignment.CenterHorizontally,
                                    verticalArrangement = Arrangement.Center
                                ) {
                                    Text(
                                        text = "TRYB AUTOMATYCZNY (HANDS-FREE)",
                                        color = Color(0xFF00D2FF),
                                        fontSize = 9.sp,
                                        fontWeight = FontWeight.Bold,
                                        letterSpacing = 1.sp
                                    )
                                    Spacer(modifier = Modifier.height(10.dp))

                                    if (isSpeechAvailable) {
                                        // Real Speech Mode layout
                                        Row(
                                            modifier = Modifier.fillMaxWidth(),
                                            horizontalArrangement = Arrangement.Center,
                                            verticalAlignment = Alignment.CenterVertically
                                        ) {
                                            Box(
                                                contentAlignment = Alignment.Center,
                                                modifier = Modifier
                                                    .scale(micScale)
                                                    .size(54.dp)
                                                    .clip(CircleShape)
                                                    .background(micBgColor.copy(alpha = micGlowAlpha))
                                                    .clickable {
                                                        if (isMuted.value) {
                                                            isMuted.value = false
                                                        }
                                                        startVoiceListening()
                                                    }
                                            ) {
                                                Box(
                                                    contentAlignment = Alignment.Center,
                                                    modifier = Modifier
                                                        .size(42.dp)
                                                        .clip(CircleShape)
                                                        .background(micBgColor)
                                                ) {
                                                    Icon(
                                                        imageVector = if (isMuted.value) Icons.Default.MicOff else Icons.Default.Mic,
                                                        contentDescription = "Mikrofon",
                                                        tint = Color.White,
                                                        modifier = Modifier.size(22.dp)
                                                    )
                                                }
                                            }
                                            Spacer(modifier = Modifier.width(16.dp))
                                            Column {
                                                Text(
                                                    text = micStatusText,
                                                    color = Color.White,
                                                    fontSize = 12.sp,
                                                    fontWeight = FontWeight.Bold
                                                )
                                                Text(
                                                    text = "Mikrofon aktywuje się automatycznie bez klikania",
                                                    color = Color.White.copy(alpha = 0.65f),
                                                    fontSize = 10.sp
                                                )
                                            }
                                        }

                                        Spacer(modifier = Modifier.height(8.dp))

                                        // Option to type text as fallback
                                        Row(
                                            modifier = Modifier.fillMaxWidth(),
                                            horizontalArrangement = Arrangement.SpaceBetween,
                                            verticalAlignment = Alignment.CenterVertically
                                        ) {
                                            Text(
                                                text = if (showManualInput.value) "❌ Ukryj klawiaturę" else "⌨️ Napisz zamiast mówić",
                                                color = Color(0xFF00D2FF),
                                                fontSize = 11.sp,
                                                fontWeight = FontWeight.Bold,
                                                modifier = Modifier
                                                    .clickable { showManualInput.value = !showManualInput.value }
                                                    .padding(vertical = 4.dp)
                                            )

                                        }
                                    } else {
                                        // Speech Not Available fallback layout (for emulator!)
                                        Column(
                                            modifier = Modifier.fillMaxWidth(),
                                            horizontalAlignment = Alignment.CenterHorizontally
                                        ) {
                                            Box(
                                                contentAlignment = Alignment.Center,
                                                modifier = Modifier
                                                    .size(44.dp)
                                                    .clip(CircleShape)
                                                    .background(Color.White.copy(alpha = 0.1f))
                                            ) {
                                                Icon(
                                                    imageVector = Icons.Default.Keyboard,
                                                    contentDescription = "Keyboard",
                                                    tint = Color(0xFF00D2FF),
                                                    modifier = Modifier.size(20.dp)
                                                )
                                            }
                                            Spacer(modifier = Modifier.height(6.dp))
                                            Text(
                                                text = "Mikrofon systemowy niedostępny w emulatorze",
                                                color = Color(0xFFFFC107),
                                                fontSize = 11.sp,
                                                fontWeight = FontWeight.Bold,
                                                textAlign = TextAlign.Center
                                            )
                                            Text(
                                                text = "Użyj klawiatury poniżej, aby napisać wypowiedź. Lektor Lingo odpowie na głos!",
                                                color = Color.White.copy(alpha = 0.6f),
                                                fontSize = 10.sp,
                                                textAlign = TextAlign.Center,
                                                modifier = Modifier.padding(horizontal = 10.dp, vertical = 2.dp),
                                                lineHeight = 14.sp
                                            )
                                        }
                                        // Always show typing for emulator fallback
                                        showManualInput.value = true
                                    }

                                    if (showManualInput.value) {
                                        Spacer(modifier = Modifier.height(10.dp))
                                        OutlinedTextField(
                                            value = manualInputText.value,
                                            onValueChange = { manualInputText.value = it },
                                            placeholder = { Text("Wpisz swoją wypowiedź po ${session.language}...", color = Color.White.copy(alpha = 0.5f), fontSize = 11.sp) },
                                            modifier = Modifier.fillMaxWidth(),
                                            shape = RoundedCornerShape(12.dp),
                                            textStyle = androidx.compose.ui.text.TextStyle(color = Color.White, fontSize = 12.sp),
                                            colors = OutlinedTextFieldDefaults.colors(
                                                focusedBorderColor = Color(0xFF00D2FF),
                                                unfocusedBorderColor = Color.White.copy(alpha = 0.2f),
                                                focusedContainerColor = Color.Black.copy(alpha = 0.2f),
                                                unfocusedContainerColor = Color.Black.copy(alpha = 0.1f)
                                            ),
                                            keyboardOptions = KeyboardOptions(imeAction = ImeAction.Send),
                                            keyboardActions = KeyboardActions(onSend = {
                                                if (manualInputText.value.isNotBlank()) {
                                                    viewModel.submitUserMessage(manualInputText.value)
                                                    manualInputText.value = ""
                                                }
                                            }),
                                            trailingIcon = {
                                                if (manualInputText.value.isNotBlank()) {
                                                    IconButton(onClick = {
                                                        viewModel.submitUserMessage(manualInputText.value)
                                                        manualInputText.value = ""
                                                    }) {
                                                        Icon(Icons.Default.Send, contentDescription = "Wyślij", tint = Color(0xFF00D2FF), modifier = Modifier.size(16.dp))
                                                    }
                                                }
                                            }
                                        )
                                    }
                                }
                            }

                        } else if (selectedCoachingTab.value == 1) {
                            // TAB 1 CONTENT: GRAMMAR & SYSTEM COACHING CORRECTION
                            if (lastUserMessage != null) {
                                if (lastUserMessage.isCorrected && !lastUserMessage.correctedText.isNullOrBlank()) {
                                    Column(verticalArrangement = Arrangement.spacedBy(10.dp)) {
                                        // Comparison layout
                                        Column(
                                            modifier = Modifier
                                                .fillMaxWidth()
                                                .background(Color(0xFFE52D27).copy(alpha = 0.1f), RoundedCornerShape(12.dp))
                                                .border(1.dp, Color(0xFFE52D27).copy(alpha = 0.25f), RoundedCornerShape(12.dp))
                                                .padding(10.dp)
                                        ) {
                                            Text(
                                                text = "❌ Twoja wersja:",
                                                color = Color(0xFFEF5350),
                                                fontSize = 10.sp,
                                                fontWeight = FontWeight.Bold
                                            )
                                            Spacer(modifier = Modifier.height(2.dp))
                                            Text(
                                                text = lastUserMessage.originalText,
                                                color = Color.White.copy(alpha = 0.8f),
                                                fontSize = 12.sp,
                                                lineHeight = 16.sp
                                            )
                                        }

                                        Column(
                                            modifier = Modifier
                                                .fillMaxWidth()
                                                .background(Color(0xFF4CAF50).copy(alpha = 0.1f), RoundedCornerShape(12.dp))
                                                .border(1.dp, Color(0xFF4CAF50).copy(alpha = 0.25f), RoundedCornerShape(12.dp))
                                                .padding(10.dp)
                                        ) {
                                            Row(
                                                verticalAlignment = Alignment.CenterVertically,
                                                horizontalArrangement = Arrangement.spacedBy(6.dp)
                                            ) {
                                                Text(
                                                    text = "✨ Rekomendowana korekta:",
                                                    color = Color(0xFF81C784),
                                                    fontSize = 10.sp,
                                                    fontWeight = FontWeight.Bold
                                                )
                                                Icon(
                                                    imageVector = Icons.Default.VolumeUp,
                                                    contentDescription = "Odsłuchaj poprawną wersję",
                                                    tint = Color(0xFF81C784),
                                                    modifier = Modifier
                                                        .size(14.dp)
                                                        .clickable {
                                                            speechHelper.speak(
                                                                lastUserMessage.correctedText!!,
                                                                session.language,
                                                                session.cefrLevel
                                                            )
                                                        }
                                                )
                                            }
                                            Spacer(modifier = Modifier.height(2.dp))
                                            Text(
                                                text = lastUserMessage.correctedText!!,
                                                color = Color.White,
                                                fontSize = 13.sp,
                                                fontWeight = FontWeight.Bold,
                                                lineHeight = 17.sp
                                            )
                                        }

                                        if (!lastUserMessage.correctionExplanation.isNullOrBlank()) {
                                            val showExplanationTranslation = remember(lastUserMessage.id) { mutableStateOf(false) }
                                            val translatedExplanation = remember(lastUserMessage.id) { mutableStateOf<String?>(null) }
                                            val isTranslating = remember(lastUserMessage.id) { mutableStateOf(false) }

                                            Column(
                                                modifier = Modifier
                                                    .fillMaxWidth()
                                                    .background(Color.White.copy(alpha = 0.04f), RoundedCornerShape(12.dp))
                                                    .padding(10.dp)
                                            ) {
                                                Row(
                                                    modifier = Modifier.fillMaxWidth(),
                                                    horizontalArrangement = Arrangement.SpaceBetween,
                                                    verticalAlignment = Alignment.CenterVertically
                                                ) {
                                                    Text(
                                                        text = "💡 Wyjaśnienie lektora:",
                                                        color = Color(0xFF00D2FF),
                                                        fontSize = 10.sp,
                                                        fontWeight = FontWeight.Bold
                                                    )
                                                    TextButton(
                                                        onClick = {
                                                            if (translatedExplanation.value == null && !isTranslating.value) {
                                                                isTranslating.value = true
                                                                coroutineScope.launch {
                                                                    try {
                                                                        translatedExplanation.value = com.example.data.api.TutorAiService.translateSentenceToPolish(
                                                                            lastUserMessage.correctionExplanation!!,
                                                                            session.language
                                                                        )
                                                                    } catch (e: Exception) {
                                                                        translatedExplanation.value = "Błąd tłumaczenia: ${e.localizedMessage}"
                                                                    } finally {
                                                                        isTranslating.value = false
                                                                    }
                                                                }
                                                            }
                                                            showExplanationTranslation.value = !showExplanationTranslation.value
                                                        },
                                                        contentPadding = PaddingValues(0.dp),
                                                        modifier = Modifier.height(20.dp)
                                                    ) {
                                                        Text(
                                                            text = if (isTranslating.value) "Tłumaczenie..." else if (showExplanationTranslation.value) "Pokaż oryginał" else "Tłumacz na PL 🇵🇱",
                                                            fontSize = 9.sp,
                                                            color = Color(0xFFFFD700)
                                                        )
                                                    }
                                                }
                                                Spacer(modifier = Modifier.height(4.dp))
                                                Text(
                                                    text = if (showExplanationTranslation.value && translatedExplanation.value != null) translatedExplanation.value!! else lastUserMessage.correctionExplanation!!,
                                                    color = Color.White.copy(alpha = 0.9f),
                                                    fontSize = 12.sp,
                                                    lineHeight = 16.sp
                                                )
                                            }
                                        }
                                    }
                                } else {
                                    // Perfect grammar success display
                                    Column(
                                        modifier = Modifier
                                            .fillMaxWidth()
                                            .background(Color(0xFF4CAF50).copy(alpha = 0.08f), RoundedCornerShape(14.dp))
                                            .border(1.dp, Color(0xFF4CAF50).copy(alpha = 0.2f), RoundedCornerShape(14.dp))
                                            .padding(14.dp),
                                        horizontalAlignment = Alignment.CenterHorizontally,
                                        verticalArrangement = Arrangement.spacedBy(6.dp)
                                    ) {
                                        Icon(
                                            imageVector = Icons.Default.CheckCircle,
                                            contentDescription = null,
                                            tint = Color(0xFF81C784),
                                            modifier = Modifier.size(36.dp)
                                        )
                                        Text(
                                            text = "Gramatyka 100% Poprawna!",
                                            color = Color.White,
                                            fontWeight = FontWeight.Bold,
                                            fontSize = 14.sp
                                        )
                                        Text(
                                            text = "Świetna robota! Twoje ostatnie zdanie nie zawierało żadnych błędów gramatycznych ani stylistycznych.",
                                            color = Color.White.copy(alpha = 0.7f),
                                            fontSize = 11.sp,
                                            textAlign = TextAlign.Center,
                                            lineHeight = 15.sp
                                        )
                                    }
                                }
                            } else {
                                Text(
                                    text = "Powiedz coś w języku ${session.language}. Lektor natychmiast wychwyci błędy gramatyczne, złą odmianę czasowników czy literówki i wyświetli poprawioną wersję.",
                                    color = Color.White.copy(alpha = 0.6f),
                                    fontSize = 12.sp,
                                    lineHeight = 17.sp
                                )
                            }
                        }
                    }
                }
            }

            // 4. CALL BUTTONS PANEL
            Row(
                modifier = Modifier
                    .fillMaxWidth()
                    .padding(bottom = 24.dp),
                horizontalArrangement = Arrangement.SpaceEvenly,
                verticalAlignment = Alignment.CenterVertically
            ) {
                IconButton(
                    onClick = { isMuted.value = !isMuted.value },
                    modifier = Modifier
                        .size(56.dp)
                        .clip(CircleShape)
                        .background(if (isMuted.value) Color.White.copy(alpha = 0.25f) else Color.White.copy(alpha = 0.1f))
                ) {
                    Icon(
                        imageVector = if (isMuted.value) Icons.Default.MicOff else Icons.Default.Mic,
                        contentDescription = "Mute Microphone",
                        tint = Color.White,
                        modifier = Modifier.size(24.dp)
                    )
                }

                IconButton(
                    onClick = { 
                        speechHelper.stop()
                        onCloseCall() 
                    },
                    modifier = Modifier
                        .size(72.dp)
                        .clip(CircleShape)
                        .background(Color(0xFFE52D27))
                ) {
                    Icon(
                        imageVector = Icons.Default.Phone,
                        contentDescription = "End Call",
                        tint = Color.White,
                        modifier = Modifier.size(32.dp)
                    )
                }

                IconButton(
                    onClick = { 
                        isSpeakerOn.value = !isSpeakerOn.value
                        if (!isSpeakerOn.value) speechHelper.stop()
                    },
                    modifier = Modifier
                        .size(56.dp)
                        .clip(CircleShape)
                        .background(if (isSpeakerOn.value) Color.White.copy(alpha = 0.25f) else Color.White.copy(alpha = 0.1f))
                ) {
                    Icon(
                        imageVector = if (isSpeakerOn.value) Icons.Default.VolumeUp else Icons.Default.VolumeMute,
                        contentDescription = "Toggle Speaker",
                        tint = Color.White,
                        modifier = Modifier.size(24.dp)
                    )
                }
            }
        }

        if (showDictInCall.value) {
            FullDictionarySearchDialog(
                viewModel = viewModel,
                activeLangCode = session.language,
                onPasteToChat = { word ->
                    manualInputText.value = if (manualInputText.value.isEmpty()) word else manualInputText.value + " " + word
                    showManualInput.value = true
                },
                onDismiss = { showDictInCall.value = false }
            )
        }

        if (showAcceleratorDialog.value) {
            AcceleratorDialog(
                viewModel = viewModel,
                targetLanguage = session.language,
                                cefrLevel = session.cefrLevel,
                speechHelper = speechHelper,
                onDismiss = { showAcceleratorDialog.value = false },
                onPasteToChat = { block ->
                    manualInputText.value = if (manualInputText.value.isEmpty()) block else manualInputText.value + " " + block
                    showManualInput.value = true
                    showAcceleratorDialog.value = false
                }
            )
        }
    }
}

// ==========================================
// AI COMMUNICATION ACCELERATOR DIALOG
// ==========================================
fun fullCleanSentence(core: String, branch: String): String {
    val c = core.trim()
    val b = branch.trim().substringBefore("\n").trim()
    
    val cClean = c.replace(Regex("[^a-zA-Z0-9]"), "").lowercase()
    val bClean = b.replace(Regex("[^a-zA-Z0-9]"), "").lowercase()
    
    if (b.startsWith(c, ignoreCase = true) || bClean.startsWith(cClean)) {
        return b
    }
    return "$c $b"
}

fun cleanBranchDisplay(core: String, branch: String): String {
    val c = core.trim()
    val b = branch.trim()
    
    val cClean = c.replace(Regex("[^a-zA-Z0-9]"), "").lowercase()
    val bClean = b.replace(Regex("[^a-zA-Z0-9]"), "").lowercase()
    
    if (b.startsWith(c, ignoreCase = true)) {
        return "+ " + b.substring(c.length).trim()
    } else if (bClean.startsWith(cClean) && cClean.isNotEmpty()) {
        val bWords = b.split(Regex("\\s+"))
        val cWords = c.split(Regex("\\s+"))
        if (bWords.size >= cWords.size) { 
             val remaining = bWords.drop(cWords.size).joinToString(" ")
             return "+ $remaining"
        }
        return "+ $b"
    }
    return "+ $b"
}
@Composable
fun AcceleratorDialog(
