// ==========================================
// MNEMONICS HELPER & RICH MNEMONIC VIEW COMPONENT
// ==========================================
fun parseMnemonic(associationStr: String?): com.example.data.api.RichMnemonicResponse? {
    if (associationStr.isNullOrBlank()) return null
    val trimmed = associationStr.trim()
    if (trimmed.startsWith("{")) {
        try {
            val moshi = com.squareup.moshi.Moshi.Builder()
                .addLast(com.squareup.moshi.kotlin.reflect.KotlinJsonAdapterFactory())
                .build()
            val adapter = moshi.adapter(com.example.data.api.RichMnemonicResponse::class.java)
            val parsed = adapter.fromJson(trimmed)
            if (parsed != null && (parsed.association.isNotBlank() || parsed.word.isNotBlank())) {
                return parsed
            }
        } catch (e: Exception) {
            // fallback to markdown/plain text extraction
        }
    }

    // Fallback: Parse markdown format (**Znaczenie**, **Skojarzenie**, **Zabawna historyjka**, **Jak to zapamiętać**)
    if (trimmed.contains("**") || trimmed.contains("Znaczenie") || trimmed.contains("Skojarzenie")) {
        val znRegex = Regex("""\*\*Znaczenie(?: i Wymowa)?\*\*:\s*([^\n\r*]+)""", RegexOption.IGNORE_CASE)
        val skRegex = Regex("""\*\*Skojarzenie(?: dźwiękowe)?\*\*:\s*([^\n\r*]+)""", RegexOption.IGNORE_CASE)
        val histRegex = Regex("""\*\*Zabawna historyjka(?: / Wizualizacja)?\*\*:\s*([^\n\r*]+)""", RegexOption.IGNORE_CASE)
        val zapRegex = Regex("""\*\*Jak to zapamiętać\*\*:\s*([^\n\r*]+)""", RegexOption.IGNORE_CASE)

        val znMatch = znRegex.find(trimmed)?.groupValues?.get(1)?.trim()
        val skMatch = skRegex.find(trimmed)?.groupValues?.get(1)?.trim()
        val histMatch = histRegex.find(trimmed)?.groupValues?.get(1)?.trim()
        val zapMatch = zapRegex.find(trimmed)?.groupValues?.get(1)?.trim()

        val assocBuilder = StringBuilder()
        if (!skMatch.isNullOrBlank()) assocBuilder.append(skMatch).append(" ")
        if (!histMatch.isNullOrBlank()) assocBuilder.append(histMatch)
        if (assocBuilder.isEmpty() && !zapMatch.isNullOrBlank()) assocBuilder.append(zapMatch)

        val finalAssoc = if (assocBuilder.isNotBlank()) assocBuilder.toString().trim() else trimmed.replace("**", "").trim()
        val visualText = histMatch ?: zapMatch ?: "Wyobraź sobie scenę łączącą to słowo z polskim znaczeniem."
        val situationText = znMatch ?: zapMatch ?: "Używane w codziennej komunikacji."

        return com.example.data.api.RichMnemonicResponse(
            word = "",
            translation = znMatch ?: "",
            contextSentence = "",
            contextTranslation = "",
            situation = situationText,
            association = finalAssoc,
            emojis = "🧠 💡 ✨ 🎯",
            visualScene = visualText
        )
    }

    if (trimmed.length > 5 && !trimmed.contains("Generowanie") && !trimmed.contains("Wystąpił błąd") && !trimmed.contains("Błąd połączenia")) {
        return com.example.data.api.RichMnemonicResponse(
            word = "",
            translation = "",
            contextSentence = "",
            contextTranslation = "",
            situation = "",
            association = trimmed,
            emojis = "🧠 💡 ✨",
            visualScene = "Wyobraź sobie to skojarzenie w pamięci."
        )
    }

    return null
}

@Composable
fun RichMnemonicDisplayView(
    richMnemonic: com.example.data.api.RichMnemonicResponse,
    targetLanguage: String = "Spanish",
    speechHelper: TutorSpeechHelper? = null,
    modifier: Modifier = Modifier
) {
    Surface(
        modifier = modifier.fillMaxWidth(),
        shape = RoundedCornerShape(14.dp),
        color = MaterialTheme.colorScheme.primaryContainer.copy(alpha = 0.22f),
        border = BorderStroke(1.dp, MaterialTheme.colorScheme.primary.copy(alpha = 0.25f))
    ) {
        Column(modifier = Modifier.padding(14.dp)) {
            // Header: Foreign Word + Audio Playback + Polish Translation badge
            Row(
                verticalAlignment = Alignment.CenterVertically,
                horizontalArrangement = Arrangement.SpaceBetween,
                modifier = Modifier.fillMaxWidth().padding(bottom = 8.dp)
            ) {
                Row(
                    verticalAlignment = Alignment.CenterVertically,
                    horizontalArrangement = Arrangement.spacedBy(6.dp)
                ) {
                    if (richMnemonic.word.isNotBlank()) {
                        Text(
                            text = richMnemonic.word,
                            fontSize = 17.sp,
                            fontWeight = FontWeight.Black,
                            color = LingoPrimary
                        )
                        if (speechHelper != null) {
                            IconButton(
                                onClick = { speechHelper.speak(richMnemonic.word, targetLanguage) },
                                modifier = Modifier.size(30.dp)
                            ) {
                                Icon(
                                    imageVector = Icons.Default.VolumeUp,
                                    contentDescription = "Odsłuchaj słówko",
                                    tint = LingoPrimary,
                                    modifier = Modifier.size(18.dp)
                                )
                            }
                        }
                    }
                }

                if (richMnemonic.translation.isNotBlank()) {
                    Surface(
                        shape = RoundedCornerShape(8.dp),
                        color = LingoSuccessGreen.copy(alpha = 0.15f),
                        border = BorderStroke(1.dp, LingoSuccessGreen.copy(alpha = 0.35f))
                    ) {
                        Text(
                            text = "🇵🇱 ${richMnemonic.translation}",
                            fontSize = 12.sp,
                            fontWeight = FontWeight.Bold,
                            color = LingoSuccessGreen,
                            modifier = Modifier.padding(horizontal = 8.dp, vertical = 4.dp)
                        )
                    }
                }
            }

            // Visual Emojis + Scene
            if (richMnemonic.emojis.isNotBlank() || richMnemonic.visualScene.isNotBlank()) {
                Row(
                    verticalAlignment = Alignment.CenterVertically,
                    horizontalArrangement = Arrangement.spacedBy(8.dp),
                    modifier = Modifier
                        .fillMaxWidth()
                        .clip(RoundedCornerShape(8.dp))
                        .background(MaterialTheme.colorScheme.primary.copy(alpha = 0.08f))
                        .padding(8.dp)
                ) {
                    if (richMnemonic.emojis.isNotBlank()) {
                        Text(text = richMnemonic.emojis, fontSize = 24.sp)
                    }
                    if (richMnemonic.visualScene.isNotBlank()) {
                        Text(
                            text = richMnemonic.visualScene,
                            fontSize = 12.sp,
                            fontStyle = FontStyle.Italic,
                            color = MaterialTheme.colorScheme.onSurface,
                            lineHeight = 16.sp
                        )
                    }
                }
                Spacer(modifier = Modifier.height(8.dp))
            }

            // Hak Pamięciowy (Association)
            if (richMnemonic.association.isNotBlank()) {
                Text(
                    text = "🧠 Hak Pamięciowy (Keyword Method):",
                    fontSize = 11.sp,
                    fontWeight = FontWeight.Bold,
                    color = MaterialTheme.colorScheme.primary
                )
                Spacer(modifier = Modifier.height(2.dp))
                Text(
                    text = richMnemonic.association,
                    fontSize = 13.sp,
                    fontWeight = FontWeight.SemiBold,
                    lineHeight = 18.sp,
                    color = MaterialTheme.colorScheme.onSurface
                )
            }

            // Situation
            if (richMnemonic.situation.isNotBlank()) {
                Spacer(modifier = Modifier.height(6.dp))
                Text(
                    text = "💡 Sytuacja: ${richMnemonic.situation}",
                    fontSize = 11.sp,
                    color = MaterialTheme.colorScheme.onSurfaceVariant,
                    lineHeight = 15.sp
                )
            }

            // Example Sentence
            if (richMnemonic.contextSentence.isNotBlank()) {
                Spacer(modifier = Modifier.height(6.dp))
                Row(
                    verticalAlignment = Alignment.CenterVertically,
                    horizontalArrangement = Arrangement.spacedBy(4.dp)
                ) {
                    Text(
                        text = "💬 Przykład: ${richMnemonic.contextSentence} (🇵🇱 ${richMnemonic.contextTranslation})",
                        fontSize = 11.sp,
                        fontStyle = FontStyle.Italic,
                        color = MaterialTheme.colorScheme.onSurfaceVariant,
                        lineHeight = 15.sp,
                        modifier = Modifier.weight(1f)
                    )
                    if (speechHelper != null) {
                        IconButton(
                            onClick = { speechHelper.speak(richMnemonic.contextSentence, targetLanguage) },
                            modifier = Modifier.size(24.dp)
                        ) {
                            Icon(
                                imageVector = Icons.Default.VolumeUp,
                                contentDescription = "Odsłuchaj przykład",
                                tint = LingoPrimary,
                                modifier = Modifier.size(14.dp)
                            )
                        }
                    }
                }
            }
        }
    }
}

