@Composable
fun MnemonicsScreen(
    viewModel: TutorViewModel,
    currentTab: MutableState<TutorTab>,
    speechHelper: TutorSpeechHelper
) {
    val mnemonics by viewModel.allMnemonics.collectAsStateWithLifecycle()
    val isGeneratingMnemonic by viewModel.isGeneratingMnemonic.collectAsStateWithLifecycle()
    val generatedMnemonic by viewModel.generatedMnemonic.collectAsStateWithLifecycle()
    val goal by viewModel.goal.collectAsStateWithLifecycle()

    val subTabSelected = remember { mutableStateOf(0) } // Defaults to 0 (Talia Mnemofiszek)

    Column(modifier = Modifier.fillMaxSize()) {
        // Sticky Header / Tab selector
        TabRow(
            selectedTabIndex = subTabSelected.value,
            containerColor = MaterialTheme.colorScheme.surface,
            contentColor = LingoPrimary
        ) {
            Tab(
                selected = subTabSelected.value == 0,
                onClick = { subTabSelected.value = 0 },
                text = { Text("🎨 Talia Mnemofiszek (SRS)", fontWeight = FontWeight.Bold, fontSize = 11.sp) }
            )
            Tab(
                selected = subTabSelected.value == 1,
                onClick = { subTabSelected.value = 1 },
                text = { Text("🧠 Generator Mnemotechnik", fontWeight = FontWeight.Bold, fontSize = 11.sp) }
            )
        }

        when (subTabSelected.value) {
            0 -> {
                // --- Redesigned Interactive Talia Mnemofiszek ---
                MnemoCardsTab(viewModel = viewModel, speechHelper = speechHelper)
            }
            1 -> {
                // --- Mnemonic Generator Screen ---
                MnemonicGeneratorTab(
                    viewModel = viewModel,
                    mnemonics = mnemonics,
                    isGenerating = isGeneratingMnemonic,
                    generatedResult = generatedMnemonic,
                    goal = goal,
                    speechHelper = speechHelper
                )
            }
        }
    }
}

fun parseStoryGrammarData(rawText: String, defaultStory: Story): StoryGrammarLesson {
    val trimmed = rawText.trim()
    
    // Fallback lexical nuances extracted from key vocabulary if missing in JSON or fallback
    val fallbackNuances: List<com.example.data.api.LexicalNuance> = try {
        if (defaultStory.keyVocabulary.isNotBlank()) {
            val moshi = com.squareup.moshi.Moshi.Builder()
                .addLast(com.squareup.moshi.kotlin.reflect.KotlinJsonAdapterFactory())
                .build()
            val type = com.squareup.moshi.Types.newParameterizedType(List::class.java, com.example.data.api.StoryVocabularyItem::class.java)
            val adapter: com.squareup.moshi.JsonAdapter<List<com.example.data.api.StoryVocabularyItem>> = moshi.adapter(type)
            val rawList: List<com.example.data.api.StoryVocabularyItem> = adapter.fromJson(defaultStory.keyVocabulary) ?: emptyList()
            rawList.take(5).map { item ->
                com.example.data.api.LexicalNuance(
                    phrase = item.word,
                    translation = item.translation,
                    whyUsedInStory = if (item.contextSentence.isNotBlank()) "Użyto w kontekście opowiadania: \"${item.contextSentence}\"" else "Kluczowy zwrot fabularny",
                    register = "Słownictwo kluczowe",
                    alternativePhrases = emptyList()
                )
            }
        } else emptyList()
    } catch (e: Exception) {
        emptyList()
    }

    if (trimmed.startsWith("{") && trimmed.endsWith("}")) {
        try {
            val parsed = TutorAiService.storyGrammarLessonAdapter.fromJson(trimmed)
            if (parsed != null && (parsed.rules.isNotEmpty() || parsed.coreInsight.isNotBlank())) {
                val finalNuances = if (!parsed.lexicalNuances.isNullOrEmpty()) parsed.lexicalNuances else fallbackNuances
                return parsed.copy(lexicalNuances = finalNuances)
            }
        } catch (e: Exception) {
            Log.e("StoryGrammar", "Error parsing grammar JSON", e)
        }
    }

    val lines = rawText.split("\n").map { it.trim() }.filter { it.isNotBlank() }
    val rules = mutableListOf<StoryGrammarRule>()
    var currentRuleName = ""
    var currentOneLiner = ""
    var currentMentalHook = ""
    var currentQuote = ""
    var currentQuoteTr = ""
    val currentContrasts = mutableListOf<GrammarContrast>()
    val currentVoiceExamples = mutableListOf<GrammarVoiceExample>()
    var currentPolishTrap = ""

    fun flushRule() {
        if (currentRuleName.isNotBlank() || currentOneLiner.isNotBlank() || currentContrasts.isNotEmpty() || currentVoiceExamples.isNotEmpty() || currentQuote.isNotBlank()) {
            rules.add(
                StoryGrammarRule(
                    ruleName = if (currentRuleName.isNotBlank()) currentRuleName else "Kluczowa Zasada Gramatyczna",
                    oneLiner = currentOneLiner.ifBlank { "Intuicja gramatyczna z kontekstu opowiadania." },
                    mentalHook = currentMentalHook.ifBlank { "🧠 Zwróć uwagę na melodię i kontekst tej formy w fabule." },
                    storyQuote = currentQuote,
                    storyQuoteTranslation = currentQuoteTr,
                    contrasts = currentContrasts.toList(),
                    voicePracticeExamples = if (currentVoiceExamples.isNotEmpty()) currentVoiceExamples.toList() else if (currentQuote.isNotBlank()) listOf(GrammarVoiceExample(sentence = currentQuote, translation = currentQuoteTr, speechTip = "Powtórz płynnie ze skupieniem na akcencie")) else emptyList(),
                    polishTrap = currentPolishTrap
                )
            )
            currentRuleName = ""
            currentOneLiner = ""
            currentMentalHook = ""
            currentQuote = ""
            currentQuoteTr = ""
            currentContrasts.clear()
            currentVoiceExamples.clear()
            currentPolishTrap = ""
        }
    }

    for (line in lines) {
        when {
            line.startsWith("###") || line.startsWith("##") || line.startsWith("#") -> {
                val header = line.replace(Regex("^#+\\s*"), "").replace("**", "").trim()
                flushRule()
                currentRuleName = header
            }
            line.contains("🧠") || line.contains("Hak", ignoreCase = true) || line.contains("Mnemotechnik", ignoreCase = true) || line.contains("Metafor", ignoreCase = true) -> {
                currentMentalHook = line.replace("**", "").trim()
            }
            line.contains("⚠️") || line.contains("Pułapk", ignoreCase = true) || line.contains("Błąd", ignoreCase = true) -> {
                currentPolishTrap = line.replace("**", "").trim()
            }
            line.contains("\"") || line.contains("„") || line.contains("“") -> {
                if (currentQuote.isBlank()) {
                    currentQuote = line.replace("\"", "").replace("„", "").replace("“", "").trim()
                } else {
                    currentVoiceExamples.add(
                        GrammarVoiceExample(
                            sentence = line.replace("\"", "").replace("„", "").replace("“", "").trim(),
                            translation = "Zdanie przykładowe z kontekstu",
                            speechTip = "Zwróć uwagę na płynne łączenie słów"
                        )
                    )
                }
            }
            line.startsWith("-") || line.startsWith("*") -> {
                val bullet = line.replace(Regex("^[-*]\\s*"), "").trim()
                if (bullet.contains(" vs ", ignoreCase = true) || bullet.contains("zamiast", ignoreCase = true)) {
                    val parts = bullet.split(Regex(" vs | zamiast "), 2)
                    currentContrasts.add(
                        GrammarContrast(
                            title = "Porównanie form",
                            correctForm = parts.getOrNull(0)?.trim() ?: bullet,
                            correctTranslation = "",
                            commonMistakeOrLiteral = parts.getOrNull(1)?.trim() ?: "",
                            explanation = bullet
                        )
                    )
                } else if (currentOneLiner.isBlank()) {
                    currentOneLiner = bullet
                } else {
                    currentVoiceExamples.add(
                        GrammarVoiceExample(
                            sentence = bullet,
                            translation = "",
                            speechTip = "Akcentuj kluczowe słowa w zdaniu"
                        )
                    )
                }
            }
            else -> {
                if (currentOneLiner.isBlank()) {
                    currentOneLiner = line
                }
            }
        }
    }
    flushRule()

    if (rules.isEmpty()) {
        rules.add(
            StoryGrammarRule(
                ruleName = "Gramatyka w Kontekście Opowiadania",
                oneLiner = "StoryLearning® uczy struktur naturalnie z tekstu.",
                mentalHook = "🧠 Zauważaj wzorce gramatyczne w ich naturalnym środowisku.",
                storyQuote = "",
                voicePracticeExamples = listOf(
                    GrammarVoiceExample(
                        sentence = defaultStory.title,
                        translation = "Tytuł opowiadania",
                        speechTip = "Ćwicz regularnie na głos"
                    )
                )
            )
        )
    }

    return StoryGrammarLesson(
        lessonTitle = "🎓 3. Gramatyka w Kontekście (StoryLearning®)",
        coreInsight = "Analiza żywych struktur językowych i mechanizmów gramatycznych występujących w opowiadaniu '${defaultStory.title}'.",
        rules = rules,
        lexicalNuances = fallbackNuances
    )
}

@Composable
fun StoryGrammarProStageView(
    viewModel: TutorViewModel,
    activeStory: Story,
    speechHelper: TutorSpeechHelper
) {
    val context = LocalContext.current
    val isGeneratingGrammar by viewModel.isGeneratingGrammar.collectAsStateWithLifecycle()
    val grammarLesson = remember(activeStory.grammarExplanation) {
        parseStoryGrammarData(activeStory.grammarExplanation, activeStory)
    }

    val selectedFilter = remember { mutableIntStateOf(0) }
    var activeVoiceSentence by remember { mutableStateOf<String?>(null) }
    var isListening by remember { mutableStateOf(false) }
    val speechEvaluationMap = remember { mutableStateMapOf<String, String>() }
    val speechScoreMap = remember { mutableStateMapOf<String, Int>() }

    val speechRecognizer = remember {
        TutorSpeechRecognizer(
            context = context,
            onResults = { spokenText ->
                isListening = false
                val target = activeVoiceSentence ?: return@TutorSpeechRecognizer
                val cleanTarget = target.lowercase().replace(Regex("[^a-z0-9áéíóúüñäößàèìòùç]"), " ").trim()
                val cleanSpoken = spokenText.lowercase().replace(Regex("[^a-z0-9áéíóúüñäößàèìòùç]"), " ").trim()

                val targetWords = cleanTarget.split("\\s+".toRegex()).filter { it.isNotBlank() }
                val spokenWords = cleanSpoken.split("\\s+".toRegex()).filter { it.isNotBlank() }
                val matchedWords = targetWords.count { word -> spokenWords.contains(word) }
                val score = if (targetWords.isNotEmpty()) ((matchedWords.toFloat() / targetWords.size) * 100).toInt().coerceIn(0, 100) else 100

                speechScoreMap[target] = score
                if (score >= 80 || cleanSpoken == cleanTarget) {
                    speechEvaluationMap[target] = "🎯 Doskonale! Świetna dykcja i intonacja (${score}%)"
                } else if (score >= 50) {
                    speechEvaluationMap[target] = "👍 Dobrze! (${score}%) • Usłyszano: \"$spokenText\""
                } else {
                    speechEvaluationMap[target] = "🎙️ Usłyszano: \"$spokenText\" • Spróbuj powtórzyć płynniej"
                }
            },
            onErrorCallback = { _, _ ->
                isListening = false
                activeVoiceSentence?.let { target ->
                    speechEvaluationMap[target] = "⚠️ Nie usłyszano głosu. Spróbuj ponownie!"
                }
            }
        )
    }

    DisposableEffect(Unit) {
        onDispose {
            speechRecognizer.shutdown()
        }
    }

    val permissionLauncher = rememberLauncherForActivityResult(
        contract = ActivityResultContracts.RequestPermission()
    ) { isGranted ->
        if (isGranted) {
            activeVoiceSentence?.let {
                isListening = true
                speechRecognizer.startListening(activeStory.language)
            }
        } else {
            Toast.makeText(context, "Wymagane uprawnienie do mikrofonu", Toast.LENGTH_SHORT).show()
        }
    }

    val challengeAnswers = remember { mutableStateMapOf<Int, Int>() }
    val activeSubstitutionIndex = remember { mutableStateMapOf<Int, Int>() }
    val outputBuiltTokens = remember { mutableStateMapOf<Int, MutableList<String>>() }
    val outputVerifiedMap = remember { mutableStateMapOf<Int, Boolean>() }

    LazyColumn(
        modifier = Modifier
            .fillMaxWidth()
            .fillMaxHeight(),
        contentPadding = PaddingValues(bottom = 120.dp),
        verticalArrangement = Arrangement.spacedBy(16.dp)
    ) {
        item {
            Card(
                modifier = Modifier.fillMaxWidth(),
                shape = RoundedCornerShape(20.dp),
                colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surface),
                border = BorderStroke(1.dp, LingoPrimary.copy(alpha = 0.25f)),
                elevation = CardDefaults.cardElevation(defaultElevation = 2.dp)
            ) {
                Column(
                    modifier = Modifier.padding(18.dp),
                    verticalArrangement = Arrangement.spacedBy(10.dp)
                ) {
                    Row(
                        modifier = Modifier.fillMaxWidth(),
                        horizontalArrangement = Arrangement.SpaceBetween,
                        verticalAlignment = Alignment.CenterVertically
                    ) {
                        Surface(
                            shape = RoundedCornerShape(8.dp),
                            color = LingoPrimary.copy(alpha = 0.12f)
                        ) {
                            Row(
                                modifier = Modifier.padding(horizontal = 8.dp, vertical = 4.dp),
                                verticalAlignment = Alignment.CenterVertically,
                                horizontalArrangement = Arrangement.spacedBy(4.dp)
                            ) {
                                Text("🎓 StoryLearning® Neuro-Gramatyka", fontSize = 11.sp, fontWeight = FontWeight.Bold, color = LingoPrimary)
                            }
                        }

                        IconButton(
                            onClick = { viewModel.upgradeStoryGrammarToPro(activeStory) },
                            enabled = !isGeneratingGrammar,
                            modifier = Modifier.size(36.dp)
                        ) {
                            if (isGeneratingGrammar) {
                                CircularProgressIndicator(modifier = Modifier.size(20.dp), strokeWidth = 2.dp, color = LingoPrimary)
                            } else {
                                Icon(Icons.Default.Refresh, contentDescription = "Generuj ponownie z AI", tint = LingoPrimary)
                            }
                        }
                    }

                    Text(
                        text = grammarLesson.lessonTitle.ifBlank { "Gramatyka w Kontekście Opowiadania" },
                        fontSize = 18.sp,
                        fontWeight = FontWeight.Black,
                        color = MaterialTheme.colorScheme.onSurface,
                        lineHeight = 24.sp
                    )

                    if (grammarLesson.coreInsight.isNotBlank()) {
                        Surface(
                            shape = RoundedCornerShape(12.dp),
                            color = MaterialTheme.colorScheme.primaryContainer.copy(alpha = 0.35f),
                            border = BorderStroke(1.dp, MaterialTheme.colorScheme.primary.copy(alpha = 0.2f))
                        ) {
                            Row(
                                modifier = Modifier.padding(12.dp),
                                verticalAlignment = Alignment.Top,
                                horizontalArrangement = Arrangement.spacedBy(10.dp)
                            ) {
                                Text("💡", fontSize = 16.sp)
                                Column {
                                    Text(
                                        text = "Złota Intuicja Opowiadania:",
                                        fontSize = 11.sp,
                                        fontWeight = FontWeight.Bold,
                                        color = MaterialTheme.colorScheme.primary
                                    )
                                    Spacer(modifier = Modifier.height(2.dp))
                                    Text(
                                        text = grammarLesson.coreInsight,
                                        fontSize = 13.sp,
                                        lineHeight = 18.sp,
                                        color = MaterialTheme.colorScheme.onSurface
                                    )
                                }
                            }
                        }
                    }

                    if (grammarLesson.rules.none { it.contrasts.isNotEmpty() || it.voicePracticeExamples.isNotEmpty() }) {
                        Button(
                            onClick = { viewModel.upgradeStoryGrammarToPro(activeStory) },
                            enabled = !isGeneratingGrammar,
                            modifier = Modifier.fillMaxWidth(),
                            colors = ButtonDefaults.buttonColors(containerColor = LingoPrimary),
                            shape = RoundedCornerShape(12.dp)
                        ) {
                            if (isGeneratingGrammar) {
                                CircularProgressIndicator(modifier = Modifier.size(18.dp), color = Color.White, strokeWidth = 2.dp)
                                Spacer(modifier = Modifier.width(8.dp))
                                Text("AI buduje haki i pojedynki struktur...", fontSize = 13.sp)
                            } else {
                                Icon(Icons.Default.Bolt, contentDescription = null, modifier = Modifier.size(18.dp))
                                Spacer(modifier = Modifier.width(6.dp))
                                Text("🚀 Przebuduj Lekcję do Metody StoryLearning® PRO", fontSize = 13.sp, fontWeight = FontWeight.Bold)
                            }
                        }
                    }
                }
            }
        }

        val rules = grammarLesson.rules
        if (rules.isEmpty()) {
            item {
                Card(
                    modifier = Modifier.fillMaxWidth().padding(vertical = 12.dp),
                    shape = RoundedCornerShape(16.dp),
                    colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.5f))
                ) {
                    Column(
                        modifier = Modifier.padding(24.dp),
                        horizontalAlignment = Alignment.CenterHorizontally,
                        verticalArrangement = Arrangement.spacedBy(10.dp)
                    ) {
                        Text("✨ Gotowy na wejście w gramatykę?", fontSize = 15.sp, fontWeight = FontWeight.Bold)
                        Text(
                            "Kliknij poniżej, aby AI wyodrębniło z tej historii mnemotechniki gramatyczne, pojedynki struktur i frazy do treningu głosem!",
                            fontSize = 13.sp,
                            textAlign = TextAlign.Center,
                            color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.7f)
                        )
                        Button(
                            onClick = { viewModel.upgradeStoryGrammarToPro(activeStory) },
                            colors = ButtonDefaults.buttonColors(containerColor = LingoPrimary)
                        ) {
                            Text("Generuj Lekcję Gramatyki PRO 🚀")
                        }
                    }
                }
            }
        } else {
            item {
                Text(
                    text = "🧠 Mnemokarty Neuro-Gramatyki PRO:",
                    fontSize = 15.sp,
                    fontWeight = FontWeight.ExtraBold,
                    color = LingoPrimary,
                    modifier = Modifier.padding(top = 4.dp, bottom = 2.dp)
