                                                        border = BorderStroke(
                                                            1.5.dp,
                                                            if (token.isGrammarCore) LingoPrimary else MaterialTheme.colorScheme.outlineVariant.copy(alpha = 0.4f)
                                                        )
                                                    ) {
                                                        Column(
                                                            modifier = Modifier.padding(horizontal = 10.dp, vertical = 6.dp),
                                                            horizontalAlignment = Alignment.CenterHorizontally
                                                        ) {
                                                            Text(
                                                                text = token.text,
                                                                fontSize = 14.sp,
                                                                fontWeight = if (token.isGrammarCore) FontWeight.Black else FontWeight.Bold,
                                                                color = if (token.isGrammarCore) LingoPrimary else MaterialTheme.colorScheme.onSurface
                                                            )
                                                            Text(
                                                                text = token.role,
                                                                fontSize = 10.sp,
                                                                fontWeight = FontWeight.SemiBold,
                                                                color = if (token.isGrammarCore) LingoPrimary else MaterialTheme.colorScheme.onSurface.copy(alpha = 0.6f)
                                                            )
                                                        }
                                                    }
                                                }
                                            }

                                            // Descriptions of Roles
                                            Column(verticalArrangement = Arrangement.spacedBy(3.dp)) {
                                                deconstruction.tokens.filter { it.roleDescription.isNotBlank() }.forEach { token ->
                                                    Row(
                                                        verticalAlignment = Alignment.Top,
                                                        horizontalArrangement = Arrangement.spacedBy(6.dp)
                                                    ) {
                                                        Text(
                                                            text = "• [${token.role}]:",
                                                            fontSize = 11.sp,
                                                            fontWeight = FontWeight.Bold,
                                                            color = if (token.isGrammarCore) LingoPrimary else MaterialTheme.colorScheme.onSurface.copy(alpha = 0.7f)
                                                        )
                                                        Text(
                                                            text = token.roleDescription,
                                                            fontSize = 11.sp,
                                                            lineHeight = 15.sp,
                                                            color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.85f)
                                                        )
                                                    }
                                                }
                                            }
                                        }
                                    }
                                }
                            }

                            if (rule.mentalHook.isNotBlank()) {
                                val cleanHookText = rule.mentalHook
                                    .replace(Regex("^🧠\\s*Hak Pamięciowy\\s*:\\s*"), "")
                                    .replace(Regex("^Hak Pamięciowy\\s*:\\s*"), "")
                                    .trim()
                                Surface(
                                    shape = RoundedCornerShape(14.dp),
                                    color = Color(0xFFF3E8FF),
                                    border = BorderStroke(1.dp, Color(0xFFC084FC).copy(alpha = 0.5f)),
                                    modifier = Modifier.fillMaxWidth()
                                ) {
                                    Column(
                                        modifier = Modifier.padding(14.dp),
                                        verticalArrangement = Arrangement.spacedBy(4.dp)
                                    ) {
                                        Row(
                                            verticalAlignment = Alignment.CenterVertically,
                                            horizontalArrangement = Arrangement.spacedBy(6.dp)
                                        ) {
                                            Text("🧠", fontSize = 16.sp)
                                            Text(
                                                "Mnemotechnika & Obraz Wizualny:",
                                                fontSize = 12.sp,
                                                fontWeight = FontWeight.Black,
                                                color = Color(0xFF6B21A8)
                                            )
                                        }
                                        Text(
                                            text = cleanHookText,
                                            fontSize = 13.sp,
                                            fontWeight = FontWeight.SemiBold,
                                            lineHeight = 19.sp,
                                            color = Color(0xFF3B0764)
                                        )
                                    }
                                }
                            }

                            if (rule.contrasts.isNotEmpty()) {
                                Column(verticalArrangement = Arrangement.spacedBy(8.dp)) {
                                    Text(
                                        text = "⚔️ Pojedynek Struktur (Jak mówią Native Speakerzy):",
                                        fontSize = 12.sp,
                                        fontWeight = FontWeight.Bold,
                                        color = LingoPrimary
                                    )
                                    rule.contrasts.forEach { contrast ->
                                        Surface(
                                            shape = RoundedCornerShape(12.dp),
                                            color = MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.35f),
                                            border = BorderStroke(1.dp, MaterialTheme.colorScheme.outlineVariant.copy(alpha = 0.25f)),
                                            modifier = Modifier.fillMaxWidth()
                                        ) {
                                            Column(
                                                modifier = Modifier.padding(12.dp),
                                                verticalArrangement = Arrangement.spacedBy(8.dp)
                                            ) {
                                                if (contrast.title.isNotBlank()) {
                                                    Text(
                                                        text = contrast.title,
                                                        fontSize = 11.sp,
                                                        fontWeight = FontWeight.Bold,
                                                        color = MaterialTheme.colorScheme.primary
                                                    )
                                                }

                                                Row(
                                                    modifier = Modifier
                                                        .fillMaxWidth()
                                                        .background(Color(0xFFDCFCE7), RoundedCornerShape(8.dp))
                                                        .padding(8.dp),
                                                    verticalAlignment = Alignment.CenterVertically,
                                                    horizontalArrangement = Arrangement.spacedBy(8.dp)
                                                ) {
                                                    Text("✅", fontSize = 14.sp)
                                                    Column(modifier = Modifier.weight(1f)) {
                                                        Text(
                                                            text = contrast.correctForm,
                                                            fontSize = 13.sp,
                                                            fontWeight = FontWeight.Bold,
                                                            color = Color(0xFF14532D)
                                                        )
                                                        if (contrast.correctTranslation.isNotBlank()) {
                                                            Text(
                                                                text = contrast.correctTranslation,
                                                                fontSize = 11.sp,
                                                                color = Color(0xFF166534)
                                                            )
                                                        }
                                                    }
                                                    IconButton(
                                                        onClick = { speechHelper.speak(contrast.correctForm, activeStory.language, activeStory.difficulty) },
                                                        modifier = Modifier.size(28.dp)
                                                    ) {
                                                        Icon(Icons.Default.VolumeUp, contentDescription = "Odsłuchaj", tint = Color(0xFF15803D), modifier = Modifier.size(16.dp))
                                                    }
                                                }

                                                if (contrast.commonMistakeOrLiteral.isNotBlank()) {
                                                    Row(
                                                        modifier = Modifier
                                                            .fillMaxWidth()
                                                            .background(Color(0xFFFEE2E2), RoundedCornerShape(8.dp))
                                                            .padding(8.dp),
                                                        verticalAlignment = Alignment.CenterVertically,
                                                        horizontalArrangement = Arrangement.spacedBy(8.dp)
                                                    ) {
                                                        Text("❌", fontSize = 14.sp)
                                                        Column(modifier = Modifier.weight(1f)) {
                                                            Text(
                                                                text = contrast.commonMistakeOrLiteral,
                                                                fontSize = 12.sp,
                                                                fontWeight = FontWeight.Medium,
                                                                color = Color(0xFF991B1B),
                                                                textDecoration = TextDecoration.LineThrough
                                                            )
                                                            Text(
                                                                text = "Kalka z polskiego / sztywna forma",
                                                                fontSize = 10.sp,
                                                                color = Color(0xFFB91C1C)
                                                            )
                                                        }
                                                    }
                                                }

                                                if (contrast.explanation.isNotBlank()) {
                                                    Text(
                                                        text = "💡 ${contrast.explanation}",
                                                        fontSize = 12.sp,
                                                        color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.8f),
                                                        lineHeight = 16.sp
                                                    )
                                                }
                                            }
                                        }
                                    }
                                }
                            }

                            if (rule.voicePracticeExamples.isNotEmpty()) {
                                Column(verticalArrangement = Arrangement.spacedBy(8.dp)) {
                                    Row(
                                        verticalAlignment = Alignment.CenterVertically,
                                        horizontalArrangement = Arrangement.spacedBy(6.dp)
                                    ) {
                                        Text("🎙️", fontSize = 14.sp)
                                        Text(
                                            "Trening Wokalny & Komendy Głosowe:",
                                            fontSize = 12.sp,
                                            fontWeight = FontWeight.Bold,
                                            color = LingoSecondary
                                        )
                                    }

                                    rule.voicePracticeExamples.forEach { voiceEx ->
                                        val isCurrentSentenceListening = isListening && activeVoiceSentence == voiceEx.sentence
                                        val evalResult = speechEvaluationMap[voiceEx.sentence]
                                        val evalScore = speechScoreMap[voiceEx.sentence]

                                        Surface(
                                            shape = RoundedCornerShape(12.dp),
                                            color = MaterialTheme.colorScheme.secondaryContainer.copy(alpha = 0.2f),
                                            border = BorderStroke(1.dp, MaterialTheme.colorScheme.secondary.copy(alpha = 0.25f)),
                                            modifier = Modifier.fillMaxWidth()
                                        ) {
                                            Column(
                                                modifier = Modifier.padding(12.dp),
                                                verticalArrangement = Arrangement.spacedBy(6.dp)
                                            ) {
                                                Row(
                                                    modifier = Modifier.fillMaxWidth(),
                                                    verticalAlignment = Alignment.CenterVertically,
                                                    horizontalArrangement = Arrangement.spacedBy(8.dp)
                                                ) {
                                                    Column(modifier = Modifier.weight(1f)) {
                                                        Text(
                                                            text = voiceEx.sentence,
                                                            fontSize = 14.sp,
                                                            fontWeight = FontWeight.Bold,
                                                            color = MaterialTheme.colorScheme.onSurface
                                                        )
                                                        if (voiceEx.translation.isNotBlank()) {
                                                            Text(
                                                                text = voiceEx.translation,
                                                                fontSize = 12.sp,
                                                                color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.7f)
                                                            )
                                                        }
                                                    }

                                                    IconButton(
                                                        onClick = {
                                                            val cleanSentenceToSpeak = voiceEx.sentence
                                                                .replace(Regex("\\(.*?\\)"), "")
                                                                .replace(Regex("^[^a-zA-ZáéíóúüñäößàèìòùçÁÉÍÓÚÜÑÄÖßÀÈÌÒÙÇ]*:"), "")
                                                                .trim()
                                                            speechHelper.speak(cleanSentenceToSpeak.ifBlank { voiceEx.sentence }, activeStory.language, activeStory.difficulty, customSpeechRate = 0.85f)
                                                        },
                                                        modifier = Modifier.size(32.dp)
                                                    ) {
                                                        Icon(Icons.Default.VolumeUp, contentDescription = "Odsłuchaj wzorzec", tint = LingoPrimary)
                                                    }

                                                    IconButton(
                                                        onClick = {
                                                            if (isCurrentSentenceListening) {
                                                                speechRecognizer.stop()
                                                                isListening = false
                                                            } else {
                                                                activeVoiceSentence = voiceEx.sentence
                                                                if (ContextCompat.checkSelfPermission(context, android.Manifest.permission.RECORD_AUDIO) == PackageManager.PERMISSION_GRANTED) {
                                                                    isListening = true
                                                                    speechRecognizer.startListening(activeStory.language)
                                                                } else {
                                                                    permissionLauncher.launch(android.Manifest.permission.RECORD_AUDIO)
                                                                }
                                                            }
                                                        },
                                                        modifier = Modifier.size(32.dp)
                                                    ) {
                                                        Icon(
                                                            imageVector = if (isCurrentSentenceListening) Icons.Default.MicOff else Icons.Default.Mic,
                                                            contentDescription = "Powtórz na głos",
                                                            tint = if (isCurrentSentenceListening) MaterialTheme.colorScheme.error else LingoSecondary
                                                        )
                                                    }
                                                }

                                                if (voiceEx.speechTip.isNotBlank()) {
                                                    Text(
                                                        text = "🎵 Wskazówka intonacyjna: ${voiceEx.speechTip}",
                                                        fontSize = 11.sp,
                                                        fontStyle = FontStyle.Italic,
                                                        color = MaterialTheme.colorScheme.onSurfaceVariant
                                                    )
                                                }

                                                if (isCurrentSentenceListening) {
                                                    Row(
                                                        modifier = Modifier
                                                            .fillMaxWidth()
                                                            .background(MaterialTheme.colorScheme.errorContainer.copy(alpha = 0.3f), RoundedCornerShape(6.dp))
                                                            .padding(6.dp),
                                                        verticalAlignment = Alignment.CenterVertically,
                                                        horizontalArrangement = Arrangement.spacedBy(6.dp)
                                                    ) {
                                                        CircularProgressIndicator(modifier = Modifier.size(12.dp), strokeWidth = 2.dp, color = MaterialTheme.colorScheme.error)
                                                        Text("Słucham... Wypowiedz zdanie do mikrofonu", fontSize = 11.sp, color = MaterialTheme.colorScheme.error, fontWeight = FontWeight.Bold)
                                                    }
                                                } else if (evalResult != null) {
                                                    Surface(
                                                        shape = RoundedCornerShape(6.dp),
                                                        color = if ((evalScore ?: 0) >= 80) Color(0xFFDCFCE7) else Color(0xFFFEF3C7),
                                                        modifier = Modifier.fillMaxWidth()
                                                    ) {
                                                        Text(
                                                            text = evalResult,
                                                            fontSize = 11.sp,
                                                            fontWeight = FontWeight.SemiBold,
                                                            color = if ((evalScore ?: 0) >= 80) Color(0xFF166534) else Color(0xFF92400E),
                                                            modifier = Modifier.padding(6.dp)
                                                        )
                                                    }
                                                }
                                            }
                                        }
                                    }
                                }
                            }

                            if (rule.polishTrap.isNotBlank()) {
                                Surface(
                                    shape = RoundedCornerShape(12.dp),
                                    color = Color(0xFFFEF3C7),
                                    border = BorderStroke(1.dp, Color(0xFFF59E0B).copy(alpha = 0.4f)),
                                    modifier = Modifier.fillMaxWidth()
                                ) {
                                    Column(
                                        modifier = Modifier.padding(12.dp),
                                        verticalArrangement = Arrangement.spacedBy(4.dp)
                                    ) {
                                        Row(
                                            verticalAlignment = Alignment.CenterVertically,
                                            horizontalArrangement = Arrangement.spacedBy(6.dp)
                                        ) {
                                            Text("⚠️", fontSize = 14.sp)
                                            Text(
                                                "Pułapka dla Polaków:",
                                                fontSize = 12.sp,
                                                fontWeight = FontWeight.Bold,
                                                color = Color(0xFF92400E)
                                            )
                                        }
                                        Text(
                                            text = rule.polishTrap,
                                            fontSize = 12.sp,
                                            lineHeight = 17.sp,
                                            color = Color(0xFF78350F)
                                        )
                                    }
                                }
                            }

                            // --- METODA PODSTAWIEŃ (SUBSTITUTION DRILLS ENGINE) ---
                            rule.substitutionDrill?.let { drill ->
                                if (drill.variations.isNotEmpty()) {
                                    val currentVariationIdx = activeSubstitutionIndex[index] ?: 0
                                    val activeVariation = drill.variations.getOrNull(currentVariationIdx) ?: drill.variations.first()

                                    Surface(
                                        shape = RoundedCornerShape(14.dp),
                                        color = Color(0xFFEFF6FF),
                                        border = BorderStroke(1.dp, Color(0xFF3B82F6).copy(alpha = 0.4f)),
                                        modifier = Modifier.fillMaxWidth()
                                    ) {
                                        Column(
                                            modifier = Modifier.padding(14.dp),
                                            verticalArrangement = Arrangement.spacedBy(10.dp)
                                        ) {
                                            // Header: Title and Slot Badge with responsive layout
                                            Row(
                                                modifier = Modifier.fillMaxWidth(),
                                                horizontalArrangement = Arrangement.SpaceBetween,
                                                verticalAlignment = Alignment.CenterVertically
                                            ) {
                                                Row(
                                                    modifier = Modifier.weight(1f, fill = false),
                                                    verticalAlignment = Alignment.CenterVertically,
                                                    horizontalArrangement = Arrangement.spacedBy(6.dp)
                                                ) {
                                                    Text("⚡", fontSize = 16.sp)
                                                    Text(
                                                        "Trening Podstawień (Substitution Drill):",
                                                        fontSize = 12.sp,
                                                        fontWeight = FontWeight.Black,
                                                        color = Color(0xFF1D4ED8)
                                                    )
                                                }
                                                Spacer(modifier = Modifier.width(8.dp))
                                                Surface(
                                                    shape = RoundedCornerShape(6.dp),
                                                    color = Color(0xFFDBEAFE)
                                                ) {
                                                    Text(
                                                        text = "Slot: ${drill.variableSlotName}",
                                                        fontSize = 10.sp,
                                                        fontWeight = FontWeight.Bold,
                                                        color = Color(0xFF1E40AF),
                                                        maxLines = 1,
                                                        modifier = Modifier.padding(horizontal = 8.dp, vertical = 3.dp)
                                                    )
                                                }
                                            }

                                            // Template formula badge
                                            if (drill.templatePattern.isNotBlank()) {
                                                Surface(
                                                    shape = RoundedCornerShape(8.dp),
                                                    color = Color.White.copy(alpha = 0.8f),
                                                    border = BorderStroke(1.dp, Color(0xFFBFDBFE)),
                                                    modifier = Modifier.fillMaxWidth()
                                                ) {
                                                    Column(modifier = Modifier.padding(8.dp)) {
                                                        Text(
                                                            text = "Szkielet: ${drill.templatePattern}",
                                                            fontSize = 12.sp,
                                                            fontWeight = FontWeight.Bold,
                                                            color = Color(0xFF1E3A8A)
                                                        )
                                                        if (drill.templateTranslation.isNotBlank()) {
                                                            Text(
                                                                text = drill.templateTranslation,
                                                                fontSize = 11.sp,
                                                                color = Color(0xFF475569)
                                                            )
                                                        }
                                                    }
                                                }
                                            }

                                            // Interactive Variable Slots Selector
                                            Text(
                                                text = "Wybierz wariant podstawienia:",
                                                fontSize = 11.sp,
                                                fontWeight = FontWeight.Bold,
                                                color = Color(0xFF1E40AF)
                                            )
                                            FlowRow(
                                                modifier = Modifier.fillMaxWidth(),
                                                horizontalArrangement = Arrangement.spacedBy(6.dp),
                                                verticalArrangement = Arrangement.spacedBy(6.dp)
                                            ) {
                                                drill.variations.forEachIndexed { varIdx, variation ->
                                                    val isSelected = currentVariationIdx == varIdx
                                                    Surface(
                                                        shape = RoundedCornerShape(8.dp),
                                                        color = if (isSelected) Color(0xFF2563EB) else Color.White,
                                                        border = BorderStroke(
                                                            1.5.dp,
                                                            if (isSelected) Color(0xFF1D4ED8) else Color(0xFF93C5FD)
                                                        ),
                                                        modifier = Modifier.clickable {
                                                            activeSubstitutionIndex[index] = varIdx
                                                        }
                                                    ) {
                                                        Text(
                                                            text = "🔁 ${variation.slotValue}",
                                                            fontSize = 12.sp,
                                                            fontWeight = if (isSelected) FontWeight.Black else FontWeight.Medium,
                                                            color = if (isSelected) Color.White else Color(0xFF1E40AF),
                                                            modifier = Modifier.padding(horizontal = 10.dp, vertical = 6.dp)
                                                        )
                                                    }
                                                }
                                            }

                                            // Resulting Live Sentence Card with TTS
                                            Surface(
                                                shape = RoundedCornerShape(10.dp),
                                                color = Color.White,
                                                border = BorderStroke(1.dp, Color(0xFF60A5FA).copy(alpha = 0.5f)),
                                                modifier = Modifier.fillMaxWidth()
                                            ) {
                                                Row(
                                                    modifier = Modifier.padding(12.dp),
                                                    verticalAlignment = Alignment.CenterVertically,
                                                    horizontalArrangement = Arrangement.spacedBy(8.dp)
                                                ) {
                                                    Column(modifier = Modifier.weight(1f)) {
                                                        Text(
                                                            text = activeVariation.resultingSentence,
                                                            fontSize = 14.sp,
                                                            fontWeight = FontWeight.ExtraBold,
                                                            color = Color(0xFF0F172A)
                                                        )
                                                        Text(
                                                            text = activeVariation.translation,
                                                            fontSize = 12.sp,
                                                            color = Color(0xFF475569)
                                                        )
                                                        if (activeVariation.whyFormChanged.isNotBlank()) {
                                                            Spacer(modifier = Modifier.height(2.dp))
                                                            Text(
                                                                text = "💡 ${activeVariation.whyFormChanged}",
                                                                fontSize = 11.sp,
                                                                color = Color(0xFF2563EB)
                                                            )
                                                        }
                                                    }
                                                    IconButton(
                                                        onClick = {
                                                            speechHelper.speak(
                                                                activeVariation.resultingSentence,
                                                                activeStory.language,
                                                                activeStory.difficulty
                                                            )
                                                        },
                                                        modifier = Modifier.size(32.dp)
                                                    ) {
                                                        Icon(Icons.Default.VolumeUp, contentDescription = "Odsłuchaj", tint = Color(0xFF2563EB))
                                                    }
                                                }
                                            }
                                        }
                                    }
                                }
                            }

                            // --- AKTYWNA PRODUKCJA (OUTPUT CHALLENGE) ---
                            rule.activeOutputChallenge?.let { outputChallenge ->
                                if (outputChallenge.polishPrompt.isNotBlank() && outputChallenge.scrambledTokens.isNotEmpty()) {
                                    val currentBuiltList = outputBuiltTokens.getOrPut(index) { mutableListOf() }
                                    val isVerified = outputVerifiedMap[index] == true
                                    val targetNormalized = outputChallenge.targetSentence.lowercase().replace(Regex("[^a-z0-9áéíóúüñäößàèìòùç]"), " ").trim()
                                    val builtSentence = currentBuiltList.joinToString(" ")
                                    val builtNormalized = builtSentence.lowercase().replace(Regex("[^a-z0-9áéíóúüñäößàèìòùç]"), " ").trim()
                                    val isCorrect = isVerified && (builtNormalized == targetNormalized)

                                    Surface(
                                        shape = RoundedCornerShape(14.dp),
                                        color = Color(0xFFF0FDF4),
                                        border = BorderStroke(1.dp, Color(0xFF22C55E).copy(alpha = 0.5f)),
                                        modifier = Modifier.fillMaxWidth()
                                    ) {
                                        Column(
                                            modifier = Modifier.padding(14.dp),
                                            verticalArrangement = Arrangement.spacedBy(10.dp)
                                        ) {
                                            Row(
                                                verticalAlignment = Alignment.CenterVertically,
                                                horizontalArrangement = Arrangement.spacedBy(6.dp)
                                            ) {
                                                Text("🎙️", fontSize = 16.sp)
                                                Text(
                                                    "Aktywny Output (Zbuduj i Wypowiedz):",
                                                    fontSize = 12.sp,
                                                    fontWeight = FontWeight.Black,
                                                    color = Color(0xFF15803D)
                                                )
                                            }

                                            Text(
                                                text = "Przełóż intencję na język obcy: „${outputChallenge.polishPrompt}”",
                                                fontSize = 13.sp,
                                                fontWeight = FontWeight.Bold,
                                                color = Color(0xFF14532D)
                                            )

                                            if (outputChallenge.hintStructure.isNotBlank()) {
                                                Text(
                                                    text = "💡 Podpowiedź szkieletu: ${outputChallenge.hintStructure}",
                                                    fontSize = 11.sp,
                                                    color = Color(0xFF166534)
                                                )
                                            }

                                            // Strefa ułożonych klocków
                                            Surface(
                                                shape = RoundedCornerShape(10.dp),
                                                color = Color.White,
                                                border = BorderStroke(
                                                    1.5.dp,
                                                    if (isVerified && isCorrect) Color(0xFF16A34A)
                                                    else if (isVerified && !isCorrect) Color(0xFFDC2626)
                                                    else Color(0xFF86EFAC)
                                                ),
                                                modifier = Modifier.fillMaxWidth()
                                            ) {
                                                Column(modifier = Modifier.padding(10.dp)) {
                                                    if (currentBuiltList.isEmpty()) {
                                                        Text(
                                                            text = "Dotknij klocków poniżej, aby ułożyć zdanie...",
                                                            fontSize = 12.sp,
                                                            fontStyle = FontStyle.Italic,
                                                            color = Color(0xFF94A3B8)
                                                        )
                                                    } else {
                                                        FlowRow(
                                                            modifier = Modifier.fillMaxWidth(),
                                                            horizontalArrangement = Arrangement.spacedBy(4.dp),
                                                            verticalArrangement = Arrangement.spacedBy(4.dp)
                                                        ) {
                                                            currentBuiltList.forEachIndexed { wordIdx, word ->
                                                                Surface(
                                                                    shape = RoundedCornerShape(6.dp),
                                                                    color = Color(0xFFDCFCE7),
                                                                    border = BorderStroke(1.dp, Color(0xFF86EFAC)),
                                                                    modifier = Modifier.clickable {
                                                                        val updated = currentBuiltList.toMutableList()
                                                                        updated.removeAt(wordIdx)
                                                                        outputBuiltTokens[index] = updated
                                                                        outputVerifiedMap[index] = false
                                                                    }
                                                                ) {
                                                                    Text(
                                                                        text = "$word ✕",
                                                                        fontSize = 12.sp,
                                                                        fontWeight = FontWeight.Bold,
                                                                        color = Color(0xFF166534),
                                                                        modifier = Modifier.padding(horizontal = 6.dp, vertical = 4.dp)
                                                                    )
                                                                }
                                                            }
                                                        }
                                                    }
                                                }
                                            }

                                            // Dostępne klocki (Scrambled Tokens)
                                            val availableTokens = outputChallenge.scrambledTokens.filterIndexed { tokenIdx, token ->
                                                val countInScrambled = outputChallenge.scrambledTokens.take(tokenIdx + 1).count { it == token }
                                                val countInBuilt = currentBuiltList.count { it == token }
                                                countInScrambled > countInBuilt
                                            }

                                            if (availableTokens.isNotEmpty()) {
                                                FlowRow(
                                                    modifier = Modifier.fillMaxWidth(),
                                                    horizontalArrangement = Arrangement.spacedBy(6.dp),
                                                    verticalArrangement = Arrangement.spacedBy(6.dp)
                                                ) {
                                                    availableTokens.forEach { token ->
                                                        Surface(
                                                            shape = RoundedCornerShape(8.dp),
                                                            color = Color.White,
                                                            border = BorderStroke(1.dp, Color(0xFF4ADE80)),
                                                            modifier = Modifier.clickable {
                                                                val updated = currentBuiltList.toMutableList()
                                                                updated.add(token)
                                                                outputBuiltTokens[index] = updated
                                                                outputVerifiedMap[index] = false
                                                            }
                                                        ) {
                                                            Text(
                                                                text = "+ $token",
                                                                fontSize = 12.sp,
                                                                fontWeight = FontWeight.SemiBold,
                                                                color = Color(0xFF15803D),
                                                                modifier = Modifier.padding(horizontal = 8.dp, vertical = 6.dp)
                                                            )
                                                        }
                                                    }
                                                }
                                            }

                                            // Przyciski akcji (Sprawdź / Wymów / Odsłuchaj)
                                            val isOutputChallengeListening = isListening && activeVoiceSentence == outputChallenge.targetSentence
                                            val outputEvalResult = speechEvaluationMap[outputChallenge.targetSentence]
                                            val outputEvalScore = speechScoreMap[outputChallenge.targetSentence]

                                            Row(
                                                modifier = Modifier.fillMaxWidth(),
                                                horizontalArrangement = Arrangement.spacedBy(8.dp),
                                                verticalAlignment = Alignment.CenterVertically
                                            ) {
                                                Button(
                                                    onClick = { outputVerifiedMap[index] = true },
                                                    enabled = currentBuiltList.isNotEmpty(),
                                                    colors = ButtonDefaults.buttonColors(containerColor = Color(0xFF16A34A)),
                                                    shape = RoundedCornerShape(8.dp),
                                                    modifier = Modifier.weight(1f)
                                                ) {
                                                    Text("Sprawdź Ułożenie 🎯", fontSize = 12.sp, fontWeight = FontWeight.Bold)
                                                }

                                                IconButton(
                                                    onClick = {
                                                        if (isOutputChallengeListening) {
                                                            speechRecognizer.stop()
                                                            isListening = false
                                                        } else {
                                                            activeVoiceSentence = outputChallenge.targetSentence
                                                            if (ContextCompat.checkSelfPermission(context, android.Manifest.permission.RECORD_AUDIO) == PackageManager.PERMISSION_GRANTED) {
                                                                isListening = true
                                                                speechRecognizer.startListening(activeStory.language)
                                                            } else {
                                                                permissionLauncher.launch(android.Manifest.permission.RECORD_AUDIO)
                                                            }
                                                        }
                                                    },
                                                    modifier = Modifier.size(36.dp)
                                                ) {
                                                    Icon(
                                                        imageVector = if (isOutputChallengeListening) Icons.Default.MicOff else Icons.Default.Mic,
                                                        contentDescription = "Wypowiedz na głos",
                                                        tint = if (isOutputChallengeListening) MaterialTheme.colorScheme.error else Color(0xFF15803D)
                                                    )
                                                }

                                                if (isVerified) {
                                                    IconButton(
                                                        onClick = {
                                                            speechHelper.speak(
                                                                outputChallenge.targetSentence,
                                                                activeStory.language,
                                                                activeStory.difficulty
                                                            )
                                                        },
                                                        modifier = Modifier.size(36.dp)
                                                    ) {
                                                        Icon(Icons.Default.VolumeUp, contentDescription = "Wzorzec audio", tint = Color(0xFF15803D))
                                                    }
                                                }
                                            }

                                            if (isOutputChallengeListening) {
                                                Row(
                                                    modifier = Modifier
                                                        .fillMaxWidth()
                                                        .background(MaterialTheme.colorScheme.errorContainer.copy(alpha = 0.3f), RoundedCornerShape(6.dp))
                                                        .padding(6.dp),
                                                    verticalAlignment = Alignment.CenterVertically,
                                                    horizontalArrangement = Arrangement.spacedBy(6.dp)
                                                ) {
                                                    CircularProgressIndicator(modifier = Modifier.size(12.dp), strokeWidth = 2.dp, color = MaterialTheme.colorScheme.error)
                                                    Text("Słucham... Wypowiedz zdanie do mikrofonu", fontSize = 11.sp, color = MaterialTheme.colorScheme.error, fontWeight = FontWeight.Bold)
                                                }
                                            } else if (outputEvalResult != null) {
                                                Surface(
                                                    shape = RoundedCornerShape(6.dp),
                                                    color = if ((outputEvalScore ?: 0) >= 80) Color(0xFFDCFCE7) else Color(0xFFFEF3C7),
                                                    modifier = Modifier.fillMaxWidth()
                                                ) {
                                                    Text(
                                                        text = outputEvalResult,
                                                        fontSize = 11.sp,
                                                        fontWeight = FontWeight.SemiBold,
                                                        color = if ((outputEvalScore ?: 0) >= 80) Color(0xFF166534) else Color(0xFF92400E),
                                                        modifier = Modifier.padding(6.dp)
                                                    )
                                                }
                                            }

                                            if (isVerified) {
                                                Surface(
                                                    shape = RoundedCornerShape(8.dp),
                                                    color = if (isCorrect) Color(0xFFDCFCE7) else Color(0xFFFEE2E2),
                                                    modifier = Modifier.fillMaxWidth()
                                                ) {
                                                    Column(modifier = Modifier.padding(8.dp)) {
                                                        Text(
                                                            text = if (isCorrect) "🎉 Brawo! Zdanie złożone idealnie!" else "⚠️ Prawidłowa forma: „${outputChallenge.targetSentence}”",
                                                            fontSize = 12.sp,
                                                            fontWeight = FontWeight.Bold,
                                                            color = if (isCorrect) Color(0xFF166534) else Color(0xFF991B1B)
                                                        )
                                                    }
                                                }
                                            }
                                        }
                                    }
                                }
                            }

                            rule.interactiveChallenge?.let { challenge ->
                                if (challenge.question.isNotBlank() && challenge.options.isNotEmpty()) {
                                    val userChoice = challengeAnswers[index]
                                    Surface(
                                        shape = RoundedCornerShape(12.dp),
                                        color = MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.5f),
                                        border = BorderStroke(1.dp, MaterialTheme.colorScheme.outlineVariant.copy(alpha = 0.3f)),
                                        modifier = Modifier.fillMaxWidth()
                                    ) {
                                        Column(
                                            modifier = Modifier.padding(12.dp),
                                            verticalArrangement = Arrangement.spacedBy(8.dp)
                                        ) {
                                            Row(
                                                verticalAlignment = Alignment.CenterVertically,
                                                horizontalArrangement = Arrangement.spacedBy(6.dp)
                                            ) {
                                                Text("🎯", fontSize = 14.sp)
                                                Text(
                                                    "Sprawdź intuicję w nowym zdaniu:",
                                                    fontSize = 12.sp,
                                                    fontWeight = FontWeight.Bold,
                                                    color = LingoPrimary
                                                )
                                            }
                                            Text(
                                                text = challenge.question,
                                                fontSize = 13.sp,
                                                fontWeight = FontWeight.Bold,
                                                color = MaterialTheme.colorScheme.onSurface
                                            )

                                            challenge.options.forEachIndexed { optIdx, optText ->
                                                val isSelected = userChoice == optIdx
                                                val isCorrect = optIdx == challenge.answerIndex
                                                val containerColor = when {
                                                    userChoice == null -> MaterialTheme.colorScheme.surface
                                                    isSelected && isCorrect -> Color(0xFFDCFCE7)
                                                    isSelected && !isCorrect -> Color(0xFFFEE2E2)
                                                    isCorrect && userChoice != null -> Color(0xFFDCFCE7).copy(alpha = 0.6f)
                                                    else -> MaterialTheme.colorScheme.surface.copy(alpha = 0.6f)
                                                }

                                                Surface(
                                                    shape = RoundedCornerShape(8.dp),
                                                    color = containerColor,
                                                    border = BorderStroke(1.dp, if (isSelected) LingoPrimary else MaterialTheme.colorScheme.outlineVariant.copy(alpha = 0.3f)),
                                                    modifier = Modifier
                                                        .fillMaxWidth()
                                                        .clickable { challengeAnswers[index] = optIdx }
                                                ) {
                                                    Row(
                                                        modifier = Modifier.padding(10.dp),
                                                        verticalAlignment = Alignment.CenterVertically,
                                                        horizontalArrangement = Arrangement.spacedBy(8.dp)
                                                    ) {
                                                        Text(
                                                            text = when {
                                                                userChoice != null && isCorrect -> "✓"
                                                                userChoice == optIdx && !isCorrect -> "✗"
                                                                else -> "${('A' + optIdx)}."
                                                            },
                                                            fontWeight = FontWeight.Bold,
                                                            fontSize = 12.sp,
                                                            color = if (userChoice != null && isCorrect) Color(0xFF166534) else if (userChoice == optIdx) Color(0xFF991B1B) else MaterialTheme.colorScheme.onSurface
                                                        )
                                                        Text(
                                                            text = optText,
                                                            fontSize = 13.sp,
                                                            color = MaterialTheme.colorScheme.onSurface,
                                                            modifier = Modifier.weight(1f)
                                                        )
                                                    }
                                                }
                                            }

                                            if (userChoice != null && challenge.explanation.isNotBlank()) {
                                                Surface(
                                                    shape = RoundedCornerShape(8.dp),
                                                    color = if (userChoice == challenge.answerIndex) Color(0xFFDCFCE7) else Color(0xFFFEF3C7),
                                                    modifier = Modifier.fillMaxWidth()
                                                ) {
                                                    Text(
                                                        text = "💡 ${challenge.explanation}",
                                                        fontSize = 11.sp,
                                                        color = if (userChoice == challenge.answerIndex) Color(0xFF14532D) else Color(0xFF92400E),
                                                        modifier = Modifier.padding(8.dp)
                                                    )
                                                }
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    }
            }
        }

        val showLexical = grammarLesson.lexicalNuances.isNotEmpty()
        if (showLexical) {
            item {
                Text(
                    text = "💎 Głęboki Kontekst Leksykalny & Niuanse Słów:",
                    fontSize = 15.sp,
                    fontWeight = FontWeight.ExtraBold,
                    color = LingoPrimary,
                    modifier = Modifier.padding(top = 8.dp)
                )
            }

            items(grammarLesson.lexicalNuances) { nuance ->
                Card(
                    modifier = Modifier.fillMaxWidth(),
                    shape = RoundedCornerShape(14.dp),
                    colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surface),
                    border = BorderStroke(1.dp, MaterialTheme.colorScheme.outlineVariant.copy(alpha = 0.3f))
                ) {
                    Column(
                        modifier = Modifier.padding(14.dp),
                        verticalArrangement = Arrangement.spacedBy(6.dp)
                    ) {
                        Row(
                            modifier = Modifier.fillMaxWidth(),
                            verticalAlignment = Alignment.CenterVertically,
                            horizontalArrangement = Arrangement.SpaceBetween
                        ) {
                            Row(verticalAlignment = Alignment.CenterVertically, horizontalArrangement = Arrangement.spacedBy(8.dp)) {
                                Text(
                                    text = nuance.phrase,
                                    fontSize = 15.sp,
                                    fontWeight = FontWeight.Bold,
                                    color = LingoPrimary
                                )
                                if (nuance.register.isNotBlank()) {
                                    Surface(
                                        shape = RoundedCornerShape(6.dp),
                                        color = LingoSecondary.copy(alpha = 0.12f)
                                    ) {
                                        Text(
                                            text = nuance.register,
                                            fontSize = 10.sp,
                                            fontWeight = FontWeight.Bold,
                                            color = LingoSecondary,
                                            modifier = Modifier.padding(horizontal = 6.dp, vertical = 2.dp)
                                        )
                                    }
                                }
                            }
                            IconButton(
                                onClick = { speechHelper.speak(nuance.phrase, activeStory.language, activeStory.difficulty) },
                                modifier = Modifier.size(28.dp)
                            ) {
                                Icon(Icons.Default.VolumeUp, contentDescription = "Wymowa", tint = LingoPrimary, modifier = Modifier.size(18.dp))
                            }
                        }

                        Text(
                            text = nuance.translation,
                            fontSize = 13.sp,
                            fontWeight = FontWeight.SemiBold,
                            color = MaterialTheme.colorScheme.onSurface
                        )

                        if (nuance.whyUsedInStory.isNotBlank()) {
                            Text(
                                text = "📖 Dlaczego w tej historii: ${nuance.whyUsedInStory}",
                                fontSize = 12.sp,
                                lineHeight = 16.sp,
                                color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.75f)
                            )
                        }

                        if (nuance.alternativePhrases.isNotEmpty()) {
                            Text(
                                text = "Alternatywy: " + nuance.alternativePhrases.joinToString(" • "),
                                fontSize = 11.sp,
                                fontStyle = FontStyle.Italic,
                                color = MaterialTheme.colorScheme.secondary
                            )
                        }
                    }
                }
            }
        }

        item {
            Spacer(modifier = Modifier.height(70.dp))
        }
    }
}

@OptIn(ExperimentalLayoutApi::class)
@Composable
fun StoryReaderTab(
    viewModel: TutorViewModel,
    stories: List<Story>,
    isGeneratingStory: Boolean,
    activeStory: Story?,
    wordTranslation: WordTranslationResponse?,
    isTranslatingWord: Boolean,
    generatedMnemonic: String?,
    goal: UserGoal?,
    currentTab: MutableState<TutorTab>,
    speechHelper: TutorSpeechHelper
) {
    val context = LocalContext.current
    val mnemonics by viewModel.allMnemonics.collectAsStateWithLifecycle(emptyList())
    val isGeneratingMnemonic by viewModel.isGeneratingMnemonic.collectAsStateWithLifecycle()
    val isExtractingUrl by viewModel.isExtractingUrl.collectAsStateWithLifecycle()
    val urlExtractionError by viewModel.urlExtractionError.collectAsStateWithLifecycle()
    val showFullTranslation = remember { mutableStateOf(false) }
    val generationMode = remember { mutableStateOf(0) } // 0 = Temat, 1 = Z Linku WWW, 2 = Importer (Tekst/Foto)
    val urlInput = remember { mutableStateOf("") }
    val rawTextInput = remember { mutableStateOf("") }
    val imageUri = remember { mutableStateOf<android.net.Uri?>(null) }
    val imageBase64 = remember { mutableStateOf<String?>(null) }
    val imageMimeType = remember { mutableStateOf<String?>(null) }
    
    val imagePickerLauncher = androidx.activity.compose.rememberLauncherForActivityResult(
        contract = androidx.activity.result.contract.ActivityResultContracts.GetContent()
    ) { uri: android.net.Uri? ->
        if (uri != null) {
            imageUri.value = uri
            imageMimeType.value = context.contentResolver.getType(uri) ?: "image/jpeg"
            try {
                context.contentResolver.openInputStream(uri)?.use { inputStream ->
                    val bytes = inputStream.readBytes()
                    imageBase64.value = android.util.Base64.encodeToString(bytes, android.util.Base64.NO_WRAP)
                }
            } catch (e: Exception) {
                e.printStackTrace()
                android.widget.Toast.makeText(context, "Błąd wczytywania obrazu", android.widget.Toast.LENGTH_SHORT).show()
            }
        }
    }

    val clickedWord = remember { mutableStateOf("") }
    val clickedSentence = remember { mutableStateOf("") }
    
    val selectedParagraphIndex = remember { mutableStateOf<Int?>(null) }
    val selectedWordIndices = remember { mutableStateOf<List<Int>>(emptyList()) }
    val coroutineScope = rememberCoroutineScope()

    val moshi = remember {
        com.squareup.moshi.Moshi.Builder()
            .addLast(com.squareup.moshi.kotlin.reflect.KotlinJsonAdapterFactory())
            .build()
    }

    val vocabList = remember(activeStory?.keyVocabulary) {
        if (activeStory == null || activeStory.keyVocabulary.isBlank()) {
            emptyList<com.example.data.api.StoryVocabularyItem>()
        } else {
            try {
                val type = com.squareup.moshi.Types.newParameterizedType(List::class.java, com.example.data.api.StoryVocabularyItem::class.java)
                val adapter = moshi.adapter<List<com.example.data.api.StoryVocabularyItem>>(type)
                val rawList = adapter.fromJson(activeStory.keyVocabulary) ?: emptyList()
                
                // ZASADA UNIKALNOŚCI: Filtrujemy, aby nie powtarzać tych samych zdań przykładowych dla słów
                val uniqueSentences = mutableSetOf<String>()
                val filteredList = mutableListOf<com.example.data.api.StoryVocabularyItem>()
                for (item in rawList) {
                    val cleanSentence = item.contextSentence.trim().lowercase()
                    if (cleanSentence.isNotEmpty()) {
                        if (!uniqueSentences.contains(cleanSentence)) {
                            uniqueSentences.add(cleanSentence)
                            filteredList.add(item)
                        }
                    } else {
                        filteredList.add(item)
                    }
                }
                filteredList
            } catch (e: Exception) {
                emptyList()
            }
        }
    }

    val translationParagraphs = remember(activeStory?.translation) {
        if (activeStory == null || activeStory.translation.isBlank()) {
            emptyList<String>()
        } else {
            activeStory.translation.split("\n\n").map { it.trim() }.filter { it.isNotEmpty() }
        }
    }

    val questionsList = remember(activeStory?.comprehensionQuestions) {
        if (activeStory == null || activeStory.comprehensionQuestions.isBlank()) {
            emptyList<com.example.data.api.StoryComprehensionQuestion>()
        } else {
            try {
                val type = com.squareup.moshi.Types.newParameterizedType(List::class.java, com.example.data.api.StoryComprehensionQuestion::class.java)
                val adapter = moshi.adapter<List<com.example.data.api.StoryComprehensionQuestion>>(type)
                adapter.fromJson(activeStory.comprehensionQuestions) ?: emptyList()
            } catch (e: Exception) {
                emptyList()
            }
        }
    }

    val scenariosList: List<com.example.data.api.StoryScenario> = remember(activeStory?.scenariosJson) {
        if (activeStory == null || activeStory.scenariosJson.isNullOrBlank()) {
            emptyList()
        } else {
            try {
                val type = com.squareup.moshi.Types.newParameterizedType(List::class.java, com.example.data.api.StoryScenario::class.java)
                val adapter = moshi.adapter<List<com.example.data.api.StoryScenario>>(type)
                adapter.fromJson(activeStory.scenariosJson) ?: emptyList()
            } catch (e: Exception) {
                emptyList()
            }
        }
    }

    val activeStoryStep = remember { mutableStateOf(0) }
    val currentQuestionIndex = remember { mutableStateOf(0) }
    val selectedOptionIndex = remember { mutableStateOf<Int?>(null) }
    val isAnswerSubmitted = remember { mutableStateOf(false) }
    val score = remember { mutableStateOf(0) }

    LaunchedEffect(activeStory) {
        activeStoryStep.value = 0
        currentQuestionIndex.value = 0
        selectedOptionIndex.value = null
        isAnswerSubmitted.value = false
        score.value = 0
    }

    if (activeStory == null) {
        // --- Library Mode ---
        val topicInput = remember { mutableStateOf("") }
        val selectedDifficulty = remember { mutableStateOf(goal?.cefrLevel ?: "B1") }
        val selectedLang = remember { mutableStateOf(goal?.targetLanguage ?: "Spanish") }

        LaunchedEffect(goal?.targetLanguage, goal?.cefrLevel) {
            if (!goal?.targetLanguage.isNullOrBlank()) {
                selectedLang.value = goal.targetLanguage
            }
            if (!goal?.cefrLevel.isNullOrBlank()) {
                selectedDifficulty.value = goal.cefrLevel
            }
        }

        val difficultyLevels = listOf("A1", "A2", "B1", "B2", "C1", "C2")
        val languages = listOf("English", "Spanish", "German", "French", "Italian", "Polish")

        val libraryScrollState = rememberScrollState()
        Column(
            modifier = Modifier
                .fillMaxSize()
                .verticalScroll(libraryScrollState)
                .padding(16.dp),
            verticalArrangement = Arrangement.spacedBy(16.dp)
        ) {
            // Header Banner
            Card(
                    modifier = Modifier.fillMaxWidth(),
                    shape = RoundedCornerShape(16.dp),
                    colors = CardDefaults.cardColors(containerColor = LingoPrimary.copy(alpha = 0.08f))
                ) {
                    Column(modifier = Modifier.padding(16.dp)) {
                        Row(verticalAlignment = Alignment.CenterVertically) {
                            Icon(
                                imageVector = Icons.Default.Book,
                                contentDescription = null,
                                tint = LingoPrimary,
                                modifier = Modifier.size(28.dp)
                            )
                            Spacer(modifier = Modifier.width(8.dp))
                            Text(
                                text = "Czytelnia AI (StoryLearning®)",
                                fontSize = 18.sp,
                                fontWeight = FontWeight.Bold,
                                color = LingoPrimary
                            )
                        }
                        Spacer(modifier = Modifier.height(6.dp))
                        Text(
                            text = "Wygeneruj unikalne opowiadania w pełni realizujące naukową metodologię StoryLearning® Olly'ego Richardsa! Ucz się języka naturalnie poprzez wciągające historie, interaktywny słownik kontekstowy, gramatykę bez regułek, konwersacje AI i quizy utrwalające.",
                            fontSize = 12.sp,
                            color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.7f),
                            lineHeight = 16.sp
                        )
                    }
                }

                // Generation Form Card with Multimedia Importer switcher
                Card(
                    modifier = Modifier.fillMaxWidth(),
                    shape = RoundedCornerShape(16.dp),
                    colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surface),
                    elevation = CardDefaults.cardElevation(defaultElevation = 2.dp)
                ) {
                    Column(modifier = Modifier.padding(16.dp)) {
                        Text(
                            text = "Nowe Opowiadanie StoryLearning®",
                            fontSize = 14.sp,
                            fontWeight = FontWeight.Bold,
                            color = MaterialTheme.colorScheme.onSurface
                        )
                        Spacer(modifier = Modifier.height(12.dp))

                        // Modern 3-tab Selector: Temat AI, Z Linku WWW, Importer (Tekst/Foto)
                        TabRow(
                            selectedTabIndex = generationMode.value,
                            modifier = Modifier.fillMaxWidth().clip(RoundedCornerShape(8.dp)),
                            containerColor = MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.4f),
                            contentColor = LingoPrimary,
                            indicator = {}
                        ) {
                            Tab(
                                selected = generationMode.value == 0,
                                onClick = { generationMode.value = 0 },
                                text = { Text("Temat AI 📝", fontSize = 11.sp, fontWeight = FontWeight.Bold, maxLines = 1) }
                            )
                            Tab(
                                selected = generationMode.value == 1,
                                onClick = { generationMode.value = 1 },
                                text = { Text("Z Linku WWW 🔗", fontSize = 11.sp, fontWeight = FontWeight.Bold, maxLines = 1) }
                            )
                            Tab(
                                selected = generationMode.value == 2,
                                onClick = { generationMode.value = 2 },
                                text = { Text("Tekst / Foto 📸", fontSize = 11.sp, fontWeight = FontWeight.Bold, maxLines = 1) }
                            )
                        }

                        Spacer(modifier = Modifier.height(16.dp))

                        if (generationMode.value == 0) {
                            OutlinedTextField(
                                value = topicInput.value,
                                onValueChange = { topicInput.value = it },
                                label = { Text("O czym ma być opowiadanie?") },
                                placeholder = { Text("np. Przygoda w kawiarni, lot balonem...") },
                                modifier = Modifier
                                    .fillMaxWidth()
                                    .testTag("story_topic_input"),
                                shape = RoundedCornerShape(12.dp),
                                singleLine = true
                            )
                        } else if (generationMode.value == 1) {
                            // --- Tryb Linku WWW ---
                            Column(verticalArrangement = Arrangement.spacedBy(8.dp)) {
                                Surface(
                                    shape = RoundedCornerShape(10.dp),
                                    color = LingoPrimary.copy(alpha = 0.08f),
                                    modifier = Modifier.fillMaxWidth()
                                ) {
                                    Row(
                                        modifier = Modifier.padding(10.dp),
                                        verticalAlignment = Alignment.CenterVertically,
                                        horizontalArrangement = Arrangement.spacedBy(8.dp)
                                    ) {
                                        Icon(
                                            imageVector = Icons.Default.Info,
                                            contentDescription = null,
                                            tint = LingoPrimary,
                                            modifier = Modifier.size(18.dp)
                                        )
                                        Text(
                                            text = "System stworzy rzetelne Streszczenie i Syntezę Wiedzy z artykułu WWW w języku obcym, zamiast fikcyjnego opowiadania. Czerp prawdziwą wiedzę ze świata!",
                                            fontSize = 11.sp,
                                            fontWeight = FontWeight.Medium,
                                            color = MaterialTheme.colorScheme.onSurface
                                        )
                                    }
                                }

                                OutlinedTextField(
                                    value = urlInput.value,
                                    onValueChange = {
                                        urlInput.value = it
                                        if (urlExtractionError != null) viewModel.clearUrlExtractionError()
                                    },
                                    label = { Text("Wklej link do artykułu lub strony") },
                                    placeholder = { Text("np. https://www.rtve.es/... lub https://pl.wikipedia.org/...") },
                                    leadingIcon = {
                                        Icon(
                                            imageVector = Icons.Default.Language,
                                            contentDescription = null,
                                            tint = LingoPrimary
                                        )
                                    },
                                    trailingIcon = {
                                        if (urlInput.value.isNotBlank()) {
                                            IconButton(onClick = {
                                                urlInput.value = ""
                                                viewModel.clearUrlExtractionError()
                                            }) {
                                                Icon(imageVector = Icons.Default.Close, contentDescription = "Wyczyść")
                                            }
                                        }
                                    },
                                    modifier = Modifier
                                        .fillMaxWidth()
                                        .testTag("story_url_input"),
                                    shape = RoundedCornerShape(12.dp),
                                    singleLine = true
                                )

                                // Szybkie presety popularnych i sprawdzonych źródeł (News / Wikipedia)
                                Column(modifier = Modifier.fillMaxWidth()) {
                                    Text(
                                        text = "Przykładowe uniwersalne źródła:",
                                        fontSize = 10.sp,
                                        fontWeight = FontWeight.SemiBold,
                                        color = MaterialTheme.colorScheme.onSurfaceVariant
                                    )
                                    Spacer(modifier = Modifier.height(4.dp))
                                    Row(
                                        modifier = Modifier.fillMaxWidth(),
                                        horizontalArrangement = Arrangement.spacedBy(6.dp)
                                    ) {
                                        Surface(
                                            shape = RoundedCornerShape(6.dp),
                                            color = Color(0xFFEFF6FF),
                                            modifier = Modifier.clickable {
                                                urlInput.value = "https://pl.wikipedia.org/wiki/Malaga"
                                            }
                                        ) {
                                            Text(
                                                text = "🏛️ Wiki: Malaga",
                                                fontSize = 10.sp,
                                                fontWeight = FontWeight.Bold,
                                                color = Color(0xFF1D4ED8),
                                                modifier = Modifier.padding(horizontal = 6.dp, vertical = 3.dp)
                                            )
                                        }
                                        Surface(
                                            shape = RoundedCornerShape(6.dp),
                                            color = Color(0xFFF0FDF4),
                                            modifier = Modifier.clickable {
                                                urlInput.value = "https://www.bbc.com/news/world"
                                            }
                                        ) {
                                            Text(
                                                text = "🌍 BBC News",
                                                fontSize = 10.sp,
                                                fontWeight = FontWeight.Bold,
                                                color = Color(0xFF15803D),
                                                modifier = Modifier.padding(horizontal = 6.dp, vertical = 3.dp)
                                            )
                                        }
                                        Surface(
                                            shape = RoundedCornerShape(6.dp),
                                            color = Color(0xFFFFFBEB),
                                            modifier = Modifier.clickable {
                                                urlInput.value = "https://www.rtve.es/noticias/"
                                            }
                                        ) {
                                            Text(
                                                text = "🇪🇸 RTVE Noticias",
                                                fontSize = 10.sp,
                                                fontWeight = FontWeight.Bold,
                                                color = Color(0xFFB45309),
                                                modifier = Modifier.padding(horizontal = 6.dp, vertical = 3.dp)
                                            )
                                        }
                                    }
                                }

                                if (urlExtractionError != null) {
                                    Surface(
                                        shape = RoundedCornerShape(8.dp),
                                        color = MaterialTheme.colorScheme.errorContainer.copy(alpha = 0.6f),
                                        modifier = Modifier.fillMaxWidth()
                                    ) {
                                        Row(
                                            modifier = Modifier.padding(8.dp),
                                            verticalAlignment = Alignment.CenterVertically,
                                            horizontalArrangement = Arrangement.spacedBy(6.dp)
                                        ) {
                                            Icon(
                                                imageVector = Icons.Default.Warning,
                                                contentDescription = null,
                                                tint = MaterialTheme.colorScheme.error,
                                                modifier = Modifier.size(16.dp)
                                            )
                                            Text(
                                                text = urlExtractionError ?: "",
                                                fontSize = 11.sp,
                                                color = MaterialTheme.colorScheme.onErrorContainer
                                            )
                                        }
                                    }
                                }
                            }
                        } else {
                            OutlinedTextField(
                                value = rawTextInput.value,
                                onValueChange = { rawTextInput.value = it },
                                label = { Text("Wklej surowy tekst (artykuł, post, notatka)") },
                                placeholder = { Text("Wklej tutaj dowolną treść artykułu prasowego, posta lub notatki...") },
                                modifier = Modifier
                                    .fillMaxWidth()
                                    .height(110.dp)
                                    .testTag("story_raw_text_input"),
                                shape = RoundedCornerShape(12.dp),
                                maxLines = 6
                            )

                            Spacer(modifier = Modifier.height(10.dp))

                            Row(
                                modifier = Modifier.fillMaxWidth(),
                                horizontalArrangement = Arrangement.spacedBy(8.dp),
                                verticalAlignment = Alignment.CenterVertically
                            ) {
                                OutlinedButton(
                                    onClick = { imagePickerLauncher.launch("image/*") },
                                    shape = RoundedCornerShape(10.dp),
                                    modifier = Modifier.weight(1.5f),
                                    contentPadding = PaddingValues(horizontal = 8.dp, vertical = 6.dp)
                                ) {
                                    Icon(imageVector = Icons.Default.Add, contentDescription = null, modifier = Modifier.size(16.dp))
                                    Spacer(modifier = Modifier.width(4.dp))
                                    Text("Dodaj Zdjęcie (OCR) 📸", fontSize = 11.sp)
                                }

                                if (imageUri.value != null) {
                                    OutlinedButton(
                                        onClick = {
                                            imageUri.value = null
                                            imageBase64.value = null
                                            imageMimeType.value = null
                                        },
                                        shape = RoundedCornerShape(10.dp),
                                        modifier = Modifier.weight(1f),
                                        colors = ButtonDefaults.outlinedButtonColors(contentColor = MaterialTheme.colorScheme.error),
                                        contentPadding = PaddingValues(horizontal = 8.dp, vertical = 6.dp)
                                    ) {
                                        Icon(imageVector = Icons.Default.Delete, contentDescription = null, modifier = Modifier.size(14.dp))
                                        Spacer(modifier = Modifier.width(4.dp))
                                        Text("Usuń", fontSize = 11.sp)
                                    }
                                }
                            }

                            imageUri.value?.let {
                                Spacer(modifier = Modifier.height(8.dp))
                                Row(
                                    modifier = Modifier
                                        .fillMaxWidth()
                                        .background(MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.3f), RoundedCornerShape(8.dp))
                                        .padding(8.dp),
                                    verticalAlignment = Alignment.CenterVertically,
                                    horizontalArrangement = Arrangement.spacedBy(8.dp)
                                ) {
                                    Icon(imageVector = Icons.Default.Info, contentDescription = null, tint = LingoPrimary, modifier = Modifier.size(16.dp))
                                    Text(
                                        text = "Załączono zdjęcie do odczytu OCR i analizy kognitywnej.",
                                        fontSize = 11.sp,
                                        color = MaterialTheme.colorScheme.onSurfaceVariant,
                                        modifier = Modifier.weight(1f)
                                    )
                                }
                            }
                        }

                        Spacer(modifier = Modifier.height(12.dp))

                        Row(
                            modifier = Modifier.fillMaxWidth(),
                            horizontalArrangement = Arrangement.spacedBy(10.dp)
                        ) {
                            // Language Dropdown
                            Box(modifier = Modifier.weight(1f)) {
                                val expandedLang = remember { mutableStateOf(false) }
                                OutlinedButton(
                                    onClick = { expandedLang.value = true },
                                    modifier = Modifier.fillMaxWidth(),
                                    shape = RoundedCornerShape(12.dp)
                                ) {
                                    Text("Język: ${selectedLang.value}", fontSize = 12.sp)
                                }
                                DropdownMenu(
                                    expanded = expandedLang.value,
                                    onDismissRequest = { expandedLang.value = false }
                                ) {
                                    languages.forEach { lang ->
                                        DropdownMenuItem(
                                            text = { Text(lang) },
                                            onClick = {
                                                selectedLang.value = lang
                                                expandedLang.value = false
                                            }
                                        )
                                    }
                                }
                            }

                            // Difficulty Dropdown
                            Box(modifier = Modifier.weight(1f)) {
                                val expandedDiff = remember { mutableStateOf(false) }
                                OutlinedButton(
                                    onClick = { expandedDiff.value = true },
                                    modifier = Modifier.fillMaxWidth(),
                                    shape = RoundedCornerShape(12.dp)
                                ) {
                                    Text("Poziom: ${selectedDifficulty.value}", fontSize = 12.sp)
                                }
                                DropdownMenu(
                                    expanded = expandedDiff.value,
                                    onDismissRequest = { expandedDiff.value = false }
                                ) {
                                    difficultyLevels.forEach { lvl ->
                                        DropdownMenuItem(
                                            text = { Text(lvl) },
                                            onClick = {
                                                selectedDifficulty.value = lvl
                                                expandedDiff.value = false
                                            }
                                        )
                                    }
                                }
                            }
                        }

                        Spacer(modifier = Modifier.height(16.dp))

                        Button(
                            onClick = {
                                when (generationMode.value) {
                                    0 -> {
                                        if (topicInput.value.isBlank()) {
                                            android.widget.Toast.makeText(context, "Podaj temat opowiadania!", android.widget.Toast.LENGTH_SHORT).show()
                                        } else {
                                            viewModel.generateReadingStory(topicInput.value, selectedLang.value, selectedDifficulty.value)
                                        }
                                    }
                                    1 -> {
                                        if (urlInput.value.isBlank()) {
                                            android.widget.Toast.makeText(context, "Wklej poprawny adres strony internetowej lub artykułu!", android.widget.Toast.LENGTH_SHORT).show()
                                        } else {
                                            viewModel.generateStoryFromUrl(
                                                url = urlInput.value,
                                                language = selectedLang.value,
                                                difficulty = selectedDifficulty.value,
                                                onExtractionFailure = { err ->
                                                    android.widget.Toast.makeText(context, err, android.widget.Toast.LENGTH_LONG).show()
                                                }
                                            )
                                        }
                                    }
                                    else -> {
                                        if (rawTextInput.value.isBlank() && imageBase64.value == null) {
                                            android.widget.Toast.makeText(context, "Wklej tekst lub dodaj zdjęcie do analizy!", android.widget.Toast.LENGTH_SHORT).show()
                                        } else {
                                            viewModel.generateStoryFromExternalContext(
                                                rawText = rawTextInput.value,
                                                imageBase64 = imageBase64.value,
                                                imageMimeType = imageMimeType.value,
                                                language = selectedLang.value,
                                                difficulty = selectedDifficulty.value
                                            )
                                        }
                                    }
                                }
                            },
                            modifier = Modifier
                                .fillMaxWidth()
                                .testTag("generate_story_button"),
                            colors = ButtonDefaults.buttonColors(containerColor = LingoPrimary),
                            shape = RoundedCornerShape(12.dp),
                            enabled = !isGeneratingStory && !isExtractingUrl
                        ) {
                            if (isExtractingUrl) {
                                CircularProgressIndicator(
                                    modifier = Modifier.size(18.dp),
                                    color = Color.White,
                                    strokeWidth = 2.dp
                                )
                                Spacer(modifier = Modifier.width(8.dp))
                                Text("Pobieram treść artykułu ze strony...", fontSize = 13.sp)
                            } else if (isGeneratingStory) {
                                CircularProgressIndicator(
                                    modifier = Modifier.size(18.dp),
                                    color = Color.White,
                                    strokeWidth = 2.dp
                                )
                                Spacer(modifier = Modifier.width(8.dp))
                                Text("AI adaptuje artykuł do StoryLearning®...", fontSize = 13.sp)
                            } else {
                                Text(
                                    text = when (generationMode.value) {
                                        0 -> "Wygeneruj Opowiadanie 📝"
                                        1 -> "Pobierz i Stwórz z Linku 🔗"
                                        else -> "Importuj i Stwórz Historię 📸"
                                    },
                                    fontSize = 14.sp
                                )
                            }
                        }
                    }
                }

                val selectedFilterLang = remember { mutableStateOf("ALL") }

                val availableLanguages = remember(stories) {
                    stories.map { it.language.ifBlank { it.language_code } }.distinct().filter { it.isNotBlank() }
                }

                val filteredStories = remember(stories, selectedFilterLang.value) {
                    if (selectedFilterLang.value == "ALL") {
                        stories
                    } else {
                        stories.filter { story ->
                            val lang = story.language.ifBlank { story.language_code }
                            lang.equals(selectedFilterLang.value, ignoreCase = true)
                        }
                    }
                }

                // Stories List Header
                Row(
                    modifier = Modifier.fillMaxWidth(),
                    horizontalArrangement = Arrangement.SpaceBetween,
                    verticalAlignment = Alignment.CenterVertically
                ) {
                    Text(
                        text = "Moja Biblioteka Opowiadań (${filteredStories.size})",
                        fontSize = 16.sp,
                        fontWeight = FontWeight.Bold,
                        color = MaterialTheme.colorScheme.onBackground
                    )
                    if (stories.isNotEmpty()) {
                        Text(
                            text = "Łącznie: ${stories.size}",
                            fontSize = 12.sp,
                            color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.6f)
                        )
                    }
                }

                if (availableLanguages.size > 1) {
                    LazyRow(
                        horizontalArrangement = Arrangement.spacedBy(6.dp),
                        modifier = Modifier.fillMaxWidth()
                    ) {
                        item {
                            FilterChip(
                                selected = selectedFilterLang.value == "ALL",
                                onClick = { selectedFilterLang.value = "ALL" },
                                label = { Text("Wszystkie (${stories.size})", fontSize = 11.sp) }
                            )
                        }
                        items(availableLanguages) { lang ->
                            val count = stories.count { (it.language.ifBlank { it.language_code }).equals(lang, ignoreCase = true) }
                            FilterChip(
                                selected = selectedFilterLang.value.equals(lang, ignoreCase = true),
                                onClick = { selectedFilterLang.value = lang },
                                label = { Text("$lang ($count)", fontSize = 11.sp) }
                            )
                        }
                    }
                }

            if (filteredStories.isEmpty()) {
                Card(
                    modifier = Modifier.fillMaxWidth(),
                    shape = RoundedCornerShape(16.dp),
                    colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.3f))
                ) {
                    Column(
                        modifier = Modifier
                            .fillMaxWidth()
                            .padding(24.dp),
                        horizontalAlignment = Alignment.CenterHorizontally,
                        verticalArrangement = Arrangement.spacedBy(8.dp)
                    ) {
                        Text(
                            text = "📚 Brak wygenerowanych tekstów",
                            fontWeight = FontWeight.Bold,
                            fontSize = 14.sp,
                            color = MaterialTheme.colorScheme.onSurfaceVariant
                        )
                        Text(
                            text = "Wpisz ciekawy temat lub użyj Importera u góry, aby stworzyć opowiadanie w tym języku!",
                            fontSize = 12.sp,
                            color = MaterialTheme.colorScheme.onSurfaceVariant.copy(alpha = 0.7f),
                            textAlign = androidx.compose.ui.text.style.TextAlign.Center
                        )
                    }
                }
            } else {
                filteredStories.forEach { story ->
                    Card(
                        modifier = Modifier
                            .fillMaxWidth()
                            .clickable { viewModel.selectStory(story) },
                        shape = RoundedCornerShape(16.dp),
                        colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surface),
                        elevation = CardDefaults.cardElevation(defaultElevation = 2.dp)
                    ) {
                        Row(
                            modifier = Modifier
                                .fillMaxWidth()
                                .padding(16.dp),
                            verticalAlignment = Alignment.CenterVertically,
                            horizontalArrangement = Arrangement.SpaceBetween
                        ) {
                            Column(modifier = Modifier.weight(1f)) {
                                Text(
                                    text = story.title,
                                    fontSize = 15.sp,
                                    fontWeight = FontWeight.Bold,
                                    color = MaterialTheme.colorScheme.onSurface
                                )
                                Spacer(modifier = Modifier.height(6.dp))
                                Row(horizontalArrangement = Arrangement.spacedBy(6.dp)) {
                                    Surface(
                                        shape = RoundedCornerShape(6.dp),
                                        color = LingoPrimary.copy(alpha = 0.12f)
                                    ) {
                                        Text(
                                            text = story.language,
                                            fontSize = 10.sp,
                                            fontWeight = FontWeight.Bold,
                                            color = LingoPrimary,
                                            modifier = Modifier.padding(horizontal = 6.dp, vertical = 2.dp)
                                        )
                                    }
                                    Surface(
                                        shape = RoundedCornerShape(6.dp),
                                        color = LingoSecondary.copy(alpha = 0.12f)
                                    ) {
                                        Text(
                                            text = story.difficulty,
                                            fontSize = 10.sp,
                                            fontWeight = FontWeight.Bold,
                                            color = LingoSecondary,
                                            modifier = Modifier.padding(horizontal = 6.dp, vertical = 2.dp)
                                        )
                                    }
                                }
                            }
                            IconButton(
                                onClick = { viewModel.deleteStory(story.id) },
                                modifier = Modifier.size(36.dp)
                            ) {
                                Icon(
                                    imageVector = Icons.Default.Delete,
                                    contentDescription = "Usuń",
                                    tint = MaterialTheme.colorScheme.error.copy(alpha = 0.8f)
                                )
                            }
                        }
                    }
                }
            }
        }
    } else {
        // --- Story Active Reader Mode ---
        Box(modifier = Modifier.fillMaxSize()) {
            Column(
                modifier = Modifier
                    .fillMaxSize()
                    .padding(16.dp)
            ) {
                // Reader Top Navigation
                Row(
                    modifier = Modifier.fillMaxWidth(),
                    horizontalArrangement = Arrangement.SpaceBetween,
                    verticalAlignment = Alignment.CenterVertically
                ) {
                    OutlinedButton(
                        onClick = { viewModel.selectStory(null) },
                        shape = RoundedCornerShape(10.dp),
                        contentPadding = PaddingValues(horizontal = 12.dp, vertical = 4.dp)
                    ) {
                        Icon(imageVector = Icons.Default.ArrowBack, contentDescription = "Powrót", modifier = Modifier.size(16.dp))
                        Spacer(modifier = Modifier.width(4.dp))
                        Text("Biblioteka", fontSize = 12.sp)
                    }

                    Row(horizontalArrangement = Arrangement.spacedBy(6.dp)) {
                        Surface(
                            shape = RoundedCornerShape(6.dp),
                            color = LingoPrimary.copy(alpha = 0.12f)
                        ) {
                            Text(
                                text = activeStory.language,
                                fontSize = 10.sp,
                                fontWeight = FontWeight.Bold,
                                color = LingoPrimary,
                                modifier = Modifier.padding(horizontal = 6.dp, vertical = 2.dp)
                            )
                        }
                        Surface(
                            shape = RoundedCornerShape(6.dp),
                            color = LingoSecondary.copy(alpha = 0.12f)
                        ) {
                            Text(
                                text = activeStory.difficulty,
                                fontSize = 10.sp,
                                fontWeight = FontWeight.Bold,
                                color = LingoSecondary,
                                modifier = Modifier.padding(horizontal = 6.dp, vertical = 2.dp)
                            )
                        }
                    }
                }

                Spacer(modifier = Modifier.height(10.dp))

                // Scrollable 5-Stage StoryLearning TabRow
                ScrollableTabRow(
                    selectedTabIndex = activeStoryStep.value,
                    containerColor = Color.Transparent,
                    contentColor = LingoPrimary,
                    edgePadding = 0.dp,
                    modifier = Modifier.fillMaxWidth()
                ) {
                    Tab(
                        selected = activeStoryStep.value == 0,
                        onClick = { activeStoryStep.value = 0 },
                        text = { Text("📖 1. Odkrycie", fontSize = 11.sp, fontWeight = FontWeight.Bold) }
                    )
                    Tab(
                        selected = activeStoryStep.value == 1,
                        onClick = { activeStoryStep.value = 1 },
                        text = { Text("🔑 2. Słownictwo", fontSize = 11.sp, fontWeight = FontWeight.Bold) }
                    )
                    Tab(
                        selected = activeStoryStep.value == 2,
                        onClick = { activeStoryStep.value = 2 },
                        text = { Text("🎓 3. Gramatyka", fontSize = 11.sp, fontWeight = FontWeight.Bold) }
                    )
                    Tab(
                        selected = activeStoryStep.value == 3,
                        onClick = { activeStoryStep.value = 3 },
                        text = { Text("💬 4. Praktyka", fontSize = 11.sp, fontWeight = FontWeight.Bold) }
                    )
                    Tab(
                        selected = activeStoryStep.value == 4,
                        onClick = { activeStoryStep.value = 4 },
                        text = { Text("🏆 5. Konsolidacja", fontSize = 11.sp, fontWeight = FontWeight.Bold) }
                    )
                }

                Spacer(modifier = Modifier.height(16.dp))

                if (activeStoryStep.value == 0) {
                    // --- STAGE 1: ODKRYCIE (THE STORY) ---
                    LazyColumn(
                        modifier = Modifier
                            .weight(1f)
                            .fillMaxWidth(),
                        verticalArrangement = Arrangement.spacedBy(16.dp)
                    ) {
                        // Story Title
                        item {
                            Text(
                                text = activeStory.title,
                                fontSize = 22.sp,
                                fontWeight = FontWeight.Black,
                                color = MaterialTheme.colorScheme.onBackground,
                                lineHeight = 28.sp
                            )
                            Spacer(modifier = Modifier.height(6.dp))
                            
                            Row(
                                modifier = Modifier.fillMaxWidth(),
                                horizontalArrangement = Arrangement.SpaceBetween,
                                verticalAlignment = Alignment.CenterVertically
                            ) {
                                Surface(
                                    shape = RoundedCornerShape(8.dp),
                                    color = LingoSuccessGreen.copy(alpha = 0.1f),
                                    modifier = Modifier.weight(1f)
                                ) {
                                    Row(
                                        modifier = Modifier.padding(horizontal = 8.dp, vertical = 4.dp),
                                        verticalAlignment = Alignment.CenterVertically
                                    ) {
                                        Icon(
                                            imageVector = Icons.Default.Lightbulb,
                                            contentDescription = null,
                                            tint = LingoSuccessGreen,
                                            modifier = Modifier.size(14.dp)
                                        )
                                        Spacer(modifier = Modifier.width(4.dp))
                                        Text(
                                            text = "Dotknij słowa, by przetłumaczyć. Dotknij drugiego, by zaznaczyć całą frazę!",
                                            fontSize = 11.sp,
                                            color = LingoSuccessGreen,
                                            fontWeight = FontWeight.Medium
                                        )
                                    }
                                }
                                
                                Spacer(modifier = Modifier.width(8.dp))

                                val isSpeakingActive = remember { mutableStateOf(false) }
                                FilledTonalButton(
                                    onClick = {
                                        if (isSpeakingActive.value) {
                                            speechHelper.stop()
                                            isSpeakingActive.value = false
                                        } else {
                                            isSpeakingActive.value = true
                                            speechHelper.speak(activeStory.content, activeStory.language, activeStory.difficulty)
                                        }
                                    },
                                    shape = RoundedCornerShape(8.dp),
                                    colors = ButtonDefaults.filledTonalButtonColors(containerColor = LingoPrimary.copy(alpha = 0.1f), contentColor = LingoPrimary),
                                    contentPadding = PaddingValues(horizontal = 8.dp, vertical = 4.dp)
                                ) {
                                    Icon(
                                        imageVector = if (isSpeakingActive.value) Icons.Default.VolumeOff else Icons.Default.VolumeUp,
                                        contentDescription = "Audio lektora",
                                        modifier = Modifier.size(14.dp)
                                    )
                                    Spacer(modifier = Modifier.width(4.dp))
                                    Text(if (isSpeakingActive.value) "Stop" else "Czytaj", fontSize = 10.sp)
                                }
                            }
                        }

                        // Clickable Interactive Paragraphs
                        val paragraphs = activeStory.content.split("\n\n")
                        items(paragraphs.size) { pIndex ->
                            val paragraphText = paragraphs[pIndex]
                            if (paragraphText.isNotBlank()) {
                                Card(
                                    modifier = Modifier.fillMaxWidth(),
                                    shape = RoundedCornerShape(14.dp),
                                    colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surface),
                                    border = BorderStroke(1.dp, MaterialTheme.colorScheme.outlineVariant.copy(alpha = 0.3f))
                                ) {
                                    Column {
                                        // Header with Paragraph index and Speaker Button for immediate playback
                                        Row(
                                            modifier = Modifier
                                                .fillMaxWidth()
                                                .padding(horizontal = 14.dp, vertical = 8.dp),
                                            horizontalArrangement = Arrangement.SpaceBetween,
                                            verticalAlignment = Alignment.CenterVertically
                                        ) {
                                            Text(
                                                text = "Akapit ${pIndex + 1}",
                                                fontSize = 11.sp,
                                                fontWeight = FontWeight.Bold,
                                                color = LingoPrimary.copy(alpha = 0.7f)
                                            )
                                            Row(
                                                verticalAlignment = Alignment.CenterVertically,
                                                horizontalArrangement = Arrangement.spacedBy(4.dp)
                                            ) {
                                                val isParagraphSpeaking = remember { mutableStateOf(false) }
                                                IconButton(
                                                    onClick = {
                                                        if (isParagraphSpeaking.value) {
                                                            speechHelper.stop()
                                                            isParagraphSpeaking.value = false
                                                        } else {
                                                            isParagraphSpeaking.value = true
                                                            speechHelper.speak(paragraphText, activeStory.language, activeStory.difficulty)
                                                        }
                                                    },
                                                    modifier = Modifier.size(28.dp)
                                                ) {
                                                    Icon(
                                                        imageVector = if (isParagraphSpeaking.value) Icons.Default.VolumeOff else Icons.Default.VolumeUp,
                                                        contentDescription = "Odsłuchaj akapit",
                                                        tint = LingoPrimary,
                                                        modifier = Modifier.size(16.dp)
                                                    )
                                                }
                                                IconButton(
                                                    onClick = {
                                                        com.example.ui.shadowing.ShadowingEngine.launchEngine(
                                                            com.example.ui.shadowing.ShadowingInputContent(
                                                                source = com.example.ui.shadowing.ShadowingSource.StoryParagraph(
                                                                    paragraphText = paragraphText,
                                                                    storyTitle = activeStory.title,
                                                                    storyId = activeStory.id.toString()
                                                                ),
                                                                targetLanguage = activeStory.language
                                                            )
                                                        )
                                                    },
                                                    modifier = Modifier.size(28.dp)
                                                ) {
                                                    Text("⚡", fontSize = 12.sp)
                                                }
                                            }
                                        }
                                        HorizontalDivider(color = MaterialTheme.colorScheme.outlineVariant.copy(alpha = 0.3f))
                                        
                                                                                 Column(modifier = Modifier.padding(14.dp)) {
                                             val words = paragraphText.split(Regex("\\s+"))
                                             val wordBounds = remember { mutableStateMapOf<Int, Rect>() }
                                             var parentLayoutCoordinates by remember { mutableStateOf<LayoutCoordinates?>(null) }

                                             fun findWordIndexAtOffset(offset: Offset): Int? {
                                                 if (wordBounds.isEmpty()) return null
                                                 for ((index, rect) in wordBounds) {
                                                     if (rect.contains(offset)) {
                                                         return index
                                                     }
                                                 }
                                                 val wordsInSameRow = wordBounds.filter { (_, rect) ->
                                                     offset.y >= rect.top - 16f && offset.y <= rect.bottom + 16f
                                                 }
                                                 if (wordsInSameRow.isNotEmpty()) {
                                                     return wordsInSameRow.minByOrNull { (_, rect) ->
                                                         if (offset.x < rect.left) rect.left - offset.x
                                                         else if (offset.x > rect.right) offset.x - rect.right
                                                         else 0f
                                                     }?.key
                                                 }
                                                 return wordBounds.minByOrNull { (_, rect) ->
                                                     val centerX = rect.left + rect.width / 2
                                                     val centerY = rect.top + rect.height / 2
                                                     val dx = offset.x - centerX
                                                     val dy = offset.y - centerY
                                                     dx * dx + dy * dy
                                                 }?.key
                                             }

                                             androidx.compose.foundation.layout.FlowRow(
                                                 modifier = Modifier
                                                     .fillMaxWidth()
                                                     .onGloballyPositioned { coords ->
                                                         parentLayoutCoordinates = coords
                                                     }
                                                     .pointerInput(paragraphText) {
                                                         awaitEachGesture {
                                                             val down = awaitFirstDown()
                                                             var dragStartIdx = findWordIndexAtOffset(down.position)
                                                             var currentDragIdx = dragStartIdx
                                                             var isDrag = false
                                                             var change = down
                                                             
                                                             while (true) {
                                                                 val event = awaitPointerEvent()
                                                                 val anyPressed = event.changes.any { it.pressed }
                                                                 if (!anyPressed) {
                                                                     if (isDrag) {
                                                                         val start = dragStartIdx
                                                                         val end = currentDragIdx
                                                                         if (start != null && end != null) {
                                                                             val min = minOf(start, end)
                                                                             val max = maxOf(start, end)
                                                                             val range = (min..max).toList()
                                                                             val phrase = range.map { words[it] }.joinToString(" ")
                                                                             val cleanPhrase = phrase.replace(Regex("[.,!?;:\"'()\\-\\[\\]]"), "").trim()
                                                                             if (cleanPhrase.isNotBlank()) {
                                                                                 selectedParagraphIndex.value = pIndex
                                                                                 selectedWordIndices.value = range
                                                                                 clickedWord.value = cleanPhrase
                                                                                 clickedSentence.value = paragraphText
                                                                                 viewModel.translateWordFromStory(cleanPhrase, paragraphText, activeStory.language)
                                                                             }
                                                                         }
                                                                     } else {
                                                                         val clickedIdx = findWordIndexAtOffset(change.position)
                                                                         if (clickedIdx != null) {
                                                                             selectedParagraphIndex.value = pIndex
                                                                             selectedWordIndices.value = listOf(clickedIdx)
                                                                             val cleanWord = words[clickedIdx].replace(Regex("[.,!?;:\"'()\\-\\[\\]]"), "").trim()
                                                                             clickedWord.value = cleanWord
                                                                             clickedSentence.value = paragraphText
                                                                             viewModel.translateWordFromStory(cleanWord, paragraphText, activeStory.language)
                                                                         }
                                                                     }
                                                                     break
                                                                 }
                                                                 
                                                                 val moveChange = event.changes.firstOrNull() ?: break
                                                                 if (moveChange.position != moveChange.previousPosition) {
                                                                     val distance = (moveChange.position - down.position).getDistance()
                                                                     if (distance > viewConfiguration.touchSlop || isDrag) {
                                                                         isDrag = true
                                                                         moveChange.consume()
                                                                         val currentOffset = moveChange.position
                                                                         val currentIdx = findWordIndexAtOffset(currentOffset)
                                                                         if (dragStartIdx != null && currentIdx != null) {
                                                                             currentDragIdx = currentIdx
                                                                             val min = minOf(dragStartIdx!!, currentIdx)
                                                                             val max = maxOf(dragStartIdx!!, currentIdx)
                                                                             selectedParagraphIndex.value = pIndex
                                                                             selectedWordIndices.value = (min..max).toList()
                                                                         }
                                                                     }
                                                                     change = moveChange
                                                                 }
                                                             }
                                                         }
                                                     },
                                                 horizontalArrangement = Arrangement.Start,
                                                 verticalArrangement = Arrangement.Top
                                             ) {
                                                 words.forEachIndexed { wIndex, rawWord ->
                                                     if (rawWord.isNotBlank()) {
                                                         val isSelected = selectedParagraphIndex.value == pIndex &&
                                                                 selectedWordIndices.value.contains(wIndex)
                                                         
                                                         Text(
                                                             text = rawWord + " ",
                                                             fontSize = 16.sp,
                                                             lineHeight = 24.sp,
                                                             fontWeight = if (isSelected) FontWeight.Bold else FontWeight.Normal,
                                                             color = if (isSelected) LingoPrimary else MaterialTheme.colorScheme.onSurface,
                                                             modifier = Modifier
                                                                 .clip(RoundedCornerShape(4.dp))
                                                                 .background(if (isSelected) LingoPrimary.copy(alpha = 0.15f) else Color.Transparent)
                                                                 .onGloballyPositioned { coords ->
                                                                     parentLayoutCoordinates?.let { parent ->
                                                                         wordBounds[wIndex] = parent.localBoundingBoxOf(coords)
                                                                     }
                                                                 }
                                                                 .padding(horizontal = 2.dp)
                                                         )
                                                     }
                                                 }
                                             }
                                         }
                                        // Wyświetlanie pełnego tłumaczenia na język polski bezpośrednio po akapicie
                                        val pTranslation = translationParagraphs.getOrNull(pIndex) ?: ""
                                        if (pTranslation.isNotBlank()) {
                                            HorizontalDivider(color = MaterialTheme.colorScheme.outlineVariant.copy(alpha = 0.2f))
                                            Column(
                                                modifier = Modifier
                                                    .fillMaxWidth()
                                                    .background(MaterialTheme.colorScheme.primary.copy(alpha = 0.04f))
                                                    .padding(14.dp)
                                            ) {
                                                Row(
                                                    verticalAlignment = Alignment.CenterVertically,
                                                    horizontalArrangement = Arrangement.spacedBy(4.dp)
                                                ) {
                                                    Icon(
                                                        imageVector = Icons.Default.Language,
                                                        contentDescription = null,
                                                        tint = LingoPrimary,
                                                        modifier = Modifier.size(14.dp)
                                                    )
                                                    Text(
                                                        text = "Tłumaczenie akapitu:",
                                                        fontSize = 11.sp,
                                                        fontWeight = FontWeight.Bold,
                                                        color = LingoPrimary
                                                    )
                                                }
                                                Spacer(modifier = Modifier.height(4.dp))
                                                Text(
                                                    text = pTranslation,
                                                    fontSize = 13.5.sp,
                                                    lineHeight = 19.sp,
                                                    color = MaterialTheme.colorScheme.onSurfaceVariant,
                                                    fontStyle = androidx.compose.ui.text.font.FontStyle.Italic
                                                )
                                            }
                                        }
                                    }
                                }
                            }
                        }

                        // Polish Translation Toggle Section
                        item {
                            Column {
                                OutlinedButton(
                                    onClick = { showFullTranslation.value = !showFullTranslation.value },
                                    modifier = Modifier.fillMaxWidth(),
                                    shape = RoundedCornerShape(12.dp)
                                ) {
                                    Text(if (showFullTranslation.value) "🙈 Ukryj Tłumaczenie PL" else "👁️ Pokaż Pełne Tłumaczenie PL")
                                }

                                if (showFullTranslation.value) {
                                    Spacer(modifier = Modifier.height(10.dp))
                                    Card(
                                        modifier = Modifier.fillMaxWidth(),
                                        shape = RoundedCornerShape(14.dp),
                                        colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.4f))
                                    ) {
                                        Text(
                                            text = activeStory.translation,
                                            fontSize = 14.sp,
                                            lineHeight = 20.sp,
                                            color = MaterialTheme.colorScheme.onSurfaceVariant,
                                            modifier = Modifier.padding(14.dp)
                                        )
                                    }
                                }
                            }
                        }

                        item {
                            Spacer(modifier = Modifier.height(60.dp))
                        }
                    }
                } else if (activeStoryStep.value == 1) {
                    // --- STAGE 2: SŁOWNICTWO (VOCABULARY) ---
                    if (vocabList.isEmpty()) {
                        LazyColumn(
                            modifier = Modifier.weight(1f).fillMaxWidth(),
