                                ) {
                                    Column(modifier = Modifier.padding(14.dp)) {
                                        Row(
                                            modifier = Modifier.fillMaxWidth(),
                                            horizontalArrangement = Arrangement.SpaceBetween,
                                            verticalAlignment = Alignment.CenterVertically
                                        ) {
                                            Column {
                                                Text(text = item.word, fontSize = 16.sp, fontWeight = FontWeight.Bold, color = LingoPrimary)
                                                Text(text = "${item.partOfSpeech} • ${item.translation}", fontSize = 12.sp, color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.7f))
                                            }
                                            IconButton(
                                                onClick = { speechHelper.speak(item.word, activeStory.language, activeStory.difficulty) },
