                                                    )
                                                    IconButton(
                                                        onClick = { speechHelper.speak(item.contextSentence, activeStory.language, activeStory.difficulty) },
                                                        modifier = Modifier.size(28.dp)
                                                    ) {
                                                        Icon(
                                                            imageVector = Icons.Default.VolumeUp,
                                                            contentDescription = "Odsłuchaj zdanie",
