                                                    Spacer(modifier = Modifier.height(6.dp))
                                                    Text(
                                                        text = "Polskie tłumaczenie: $sentenceTranslation",
                                                        fontSize = 11.sp,
                                                        color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.6f)
                                                    )
                                                } else {
                                                    // In case of old stories without translation, we allow translating the sentence on the fly using Gemini!
                                                    val isTranslatingSentence = remember { mutableStateOf(false) }
                                                    val loadedTranslation = remember { mutableStateOf("") }
                                                    
                                                    if (loadedTranslation.value.isNotBlank()) {
                                                        Spacer(modifier = Modifier.height(6.dp))
                                                        HorizontalDivider(color = MaterialTheme.colorScheme.outlineVariant.copy(alpha = 0.5f))
                                                        Spacer(modifier = Modifier.height(6.dp))
                                                        Text(
                                                            text = "Tłumaczenie PL: ${loadedTranslation.value}",
                                                            fontSize = 11.sp,
                                                            color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.6f)
                                                        )
                                                    } else {
                                                        Spacer(modifier = Modifier.height(4.dp))
                                                        TextButton(
                                                            onClick = {
                                                                isTranslatingSentence.value = true
                                                                coroutineScope.launch {
                                                                    try {
                                                                        val result = com.example.data.api.TutorAiService.translateSingleWord(
                                                                            item.contextSentence,
                                                                            item.contextSentence,
                                                                            activeStory.language
                                                                        )
                                                                        loadedTranslation.value = result.translation
                                                                    } catch (e: Exception) {
                                                                        loadedTranslation.value = "Nie udało się przetłumaczyć."
                                                                    } finally {
                                                                        isTranslatingSentence.value = false
                                                                    }
                                                                }
                                                            },
                                                            modifier = Modifier.align(Alignment.End),
                                                            contentPadding = PaddingValues(0.dp)
                                                        ) {
                                                            if (isTranslatingSentence.value) {
                                                                CircularProgressIndicator(modifier = Modifier.size(12.dp), strokeWidth = 1.dp)
                                                            } else {
                                                                Text("Tłumacz zdanie 🌐", fontSize = 10.sp)
                                                            }
                                                        }
                                                    }
                                                }
                                            }
                                        }
                                        
                                        val vocabMnem = mnemonics.find { m ->
                                            m.wordOrPhrase.equals(item.word, ignoreCase = true) ||
                                            parseMnemonic(m.association)?.word.equals(item.word, ignoreCase = true) ||
                                            m.wordOrPhrase.equals(item.translation, ignoreCase = true)
                                        }
                                        val richMnem = vocabMnem?.let { parseMnemonic(it.association) } ?: (if (!item.mnemonic.isNullOrBlank()) parseMnemonic(item.mnemonic) else null)

                                        if (richMnem != null) {
                                            Spacer(modifier = Modifier.height(10.dp))
                                            RichMnemonicDisplayView(
                                                richMnemonic = richMnem,
                                                targetLanguage = activeStory.language,
                                                speechHelper = speechHelper
                                            )
                                        } else if (!item.mnemonic.isNullOrBlank()) {
                                            Spacer(modifier = Modifier.height(10.dp))
                                            Surface(
                                                color = LingoSecondary.copy(alpha = 0.08f),
                                                shape = RoundedCornerShape(8.dp),
                                                modifier = Modifier.fillMaxWidth()
                                            ) {
