                            Card(
                                modifier = Modifier
                                    .fillMaxWidth()
                                    .clickable {
                                        viewModel.startNewSession("story_${activeStory.id}", activeStory.title, stressLevel = 0)
                                        currentTab.value = TutorTab.DASHBOARD
                                        Toast.makeText(context, "Rozpoczynanie ogólnej lekcji konwersacyjnej!", Toast.LENGTH_SHORT).show()
                                    }
                                    .testTag("start_story_chat_button"),
                                shape = RoundedCornerShape(16.dp),
                                colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.5f)),
                                border = BorderStroke(1.dp, MaterialTheme.colorScheme.outlineVariant.copy(alpha = 0.3f))
                            ) {
                                Row(
                                    modifier = Modifier.padding(16.dp),
                                    verticalAlignment = Alignment.CenterVertically
                                ) {
                                    Icon(
                                        imageVector = Icons.Default.Book,
                                        contentDescription = null,
                                        tint = LingoSecondary,
                                        modifier = Modifier.size(36.dp)
                                    )
                                    Spacer(modifier = Modifier.width(16.dp))
                                    Column(modifier = Modifier.weight(1f)) {
                                        Text(
                                            text = "Scenariusz Główny: Rozmowa Ogólna",
                                            fontWeight = FontWeight.Bold,
                                            fontSize = 14.sp,
                                            color = MaterialTheme.colorScheme.onSurface
                                        )
                                        Spacer(modifier = Modifier.height(4.dp))
                                        Text(
                                            text = "Omawiaj fabułę i słownictwo bezpośrednio z lektorem Lingo bez dodatkowego kontekstu ról czy dylematów.",
                                            fontSize = 12.sp,
                                            color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.7f),
                                            lineHeight = 16.sp
                                        )
                                    }
                                }
                            }
                        }

                        if (scenariosList.isEmpty()) {
                            item {
                                Card(
                                    modifier = Modifier.fillMaxWidth(),
                                    shape = RoundedCornerShape(16.dp),
                                    colors = CardDefaults.cardColors(containerColor = LingoPrimary.copy(alpha = 0.05f)),
                                    border = BorderStroke(1.dp, LingoPrimary.copy(alpha = 0.15f))
                                ) {
                                    Column(
                                        modifier = Modifier.padding(16.dp),
                                        horizontalAlignment = Alignment.CenterHorizontally
                                    ) {
                                        Text(
                                            text = "Chcesz więcej wyzwań? 🚀",
                                            fontWeight = FontWeight.Bold,
                                            fontSize = 14.sp,
                                            color = LingoPrimary
                                        )
                                        Spacer(modifier = Modifier.height(6.dp))
                                        Text(
                                            text = "Ulepsz to opowiadanie do pełnej wersji StoryLearning® (metodologia nowej generacji), aby odblokować unikalne scenariusze ról i dylematów moralnych!",
                                            fontSize = 12.sp,
                                            textAlign = TextAlign.Center,
                                            color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.8f),
                                            lineHeight = 16.sp
                                        )
                                        Spacer(modifier = Modifier.height(12.dp))
                                        Button(
                                            onClick = { viewModel.upgradeStoryToStoryLearning(activeStory) },
                                            colors = ButtonDefaults.buttonColors(containerColor = LingoPrimary)
                                        ) {
                                            Text("Ulepsz opowiadanie 🤖")
                                        }
                                    }
                                }
                            }
                        }
                    }
                } else if (activeStoryStep.value == 4) {
                    // --- STAGE 5: KONSOLIDACJA (QUIZ) ---
                    if (questionsList.isEmpty()) {
                        LazyColumn(
                            modifier = Modifier.weight(1f).fillMaxWidth(),
                            verticalArrangement = Arrangement.Center,
                            horizontalAlignment = Alignment.CenterHorizontally
                        ) {
                            item {
                                Card(
                                    modifier = Modifier.fillMaxWidth().padding(16.dp),
                                    shape = RoundedCornerShape(16.dp)
                                ) {
                                    Column(
                                        modifier = Modifier.padding(24.dp),
                                        horizontalAlignment = Alignment.CenterHorizontally,
                                        verticalArrangement = Arrangement.spacedBy(12.dp)
                                    ) {
                                        Text("✨ Metodologia StoryLearning®", fontWeight = FontWeight.Bold, fontSize = 16.sp)
                                        Text(
                                            "To opowiadanie nie ma jeszcze pytań utrwalających. Pozwól AI przeanalizować historię i stworzyć dla Ciebie quiz!",
                                            fontSize = 13.sp,
                                            color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.7f),
                                            textAlign = TextAlign.Center
                                        )
                                        Button(
                                            onClick = { viewModel.upgradeStoryToStoryLearning(activeStory) },
                                            colors = ButtonDefaults.buttonColors(containerColor = LingoPrimary)
                                        ) {
                                            Text("Wygeneruj Quiz 🚀")
                                        }
                                    }
                                }
                            }
                        }
                    } else {
                        LazyColumn(
                            modifier = Modifier.weight(1f).fillMaxWidth(),
                            verticalArrangement = Arrangement.spacedBy(16.dp)
                        ) {
                            item {
                                Row(
                                    modifier = Modifier.fillMaxWidth(),
                                    horizontalArrangement = Arrangement.SpaceBetween,
                                    verticalAlignment = Alignment.CenterVertically
                                ) {
                                    Column(modifier = Modifier.weight(1f)) {
                                        Text(
                                            text = "🏆 5. Konsolidacja wiedzy",
                                            fontSize = 16.sp,
                                            fontWeight = FontWeight.Bold,
                                            color = MaterialTheme.colorScheme.onBackground
                                        )
                                        Text(
                                            text = "Zweryfikuj swoje zrozumienie tekstu. Każda odpowiedź zawiera pełne wyjaśnienie gramatyczno-leksykalne.",
                                            fontSize = 12.sp,
                                            color = MaterialTheme.colorScheme.onBackground.copy(alpha = 0.6f)
                                        )
                                    }
                                    
                                    Button(
                                        onClick = {
                                            viewModel.generateDynamicScenariosAndQuestions(activeStory)
                                            Toast.makeText(context, "Generowanie dodatkowych pytań weryfikacyjnych...", Toast.LENGTH_SHORT).show()
                                        },
                                        colors = ButtonDefaults.buttonColors(containerColor = LingoPrimary.copy(alpha = 0.1f), contentColor = LingoPrimary),
                                        contentPadding = PaddingValues(horizontal = 8.dp, vertical = 2.dp),
                                        modifier = Modifier.testTag("generate_more_questions_btn")
                                    ) {
                                        Icon(imageVector = Icons.Default.Refresh, contentDescription = null, modifier = Modifier.size(16.dp))
                                        Spacer(modifier = Modifier.width(4.dp))
                                        Text("Więcej pytań 🪄", fontSize = 11.sp, fontWeight = FontWeight.Bold)
                                    }
                                }
                            }

                            if (currentQuestionIndex.value < questionsList.size) {
                                val questionItem = questionsList[currentQuestionIndex.value]
                                item {
                                    Card(
                                        modifier = Modifier.fillMaxWidth(),
                                        shape = RoundedCornerShape(16.dp),
                                        colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surface),
                                        border = BorderStroke(1.dp, MaterialTheme.colorScheme.outlineVariant.copy(alpha = 0.3f))
                                    ) {
                                        Column(modifier = Modifier.padding(16.dp)) {
                                            Text(
                                                text = "Pytanie ${currentQuestionIndex.value + 1} z ${questionsList.size}",
                                                fontSize = 12.sp,
                                                fontWeight = FontWeight.Bold,
                                                color = LingoPrimary
                                            )
                                            Spacer(modifier = Modifier.height(6.dp))
                                            Row(
                                                modifier = Modifier.fillMaxWidth(),
                                                horizontalArrangement = Arrangement.SpaceBetween,
                                                verticalAlignment = Alignment.CenterVertically
                                            ) {
                                                Text(
                                                    text = questionItem.question,
                                                    fontSize = 15.sp,
                                                    fontWeight = FontWeight.Bold,
                                                    color = MaterialTheme.colorScheme.onSurface,
                                                    modifier = Modifier.weight(1f)
                                                )
                                                IconButton(
                                                    onClick = { speechHelper.speak(questionItem.question, activeStory.language, activeStory.difficulty) },
                                                    modifier = Modifier.size(36.dp)
                                                ) {
                                                    Icon(
                                                        imageVector = Icons.Default.VolumeUp,
                                                        contentDescription = "Odsłuchaj pytanie",
                                                        tint = LingoPrimary,
                                                        modifier = Modifier.size(20.dp)
                                                    )
                                                }
                                            }
                                            Spacer(modifier = Modifier.height(16.dp))

                                            questionItem.options.forEachIndexed { optIndex, option ->
                                                val isSelected = selectedOptionIndex.value == optIndex
                                                val optionColor = if (isAnswerSubmitted.value) {
                                                    if (optIndex == questionItem.answerIndex) {
                                                        LingoSuccessGreen.copy(alpha = 0.15f)
                                                    } else if (isSelected) {
                                                        MaterialTheme.colorScheme.error.copy(alpha = 0.15f)
                                                    } else {
                                                        MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.4f)
                                                    }
                                                } else {
                                                    if (isSelected) LingoPrimary.copy(alpha = 0.1f) else MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.4f)
                                                }

                                                val optionBorderColor = if (isAnswerSubmitted.value) {
                                                    if (optIndex == questionItem.answerIndex) LingoSuccessGreen else if (isSelected) MaterialTheme.colorScheme.error else Color.Transparent
                                                } else {
                                                    if (isSelected) LingoPrimary else Color.Transparent
                                                }

                                                Card(
                                                    modifier = Modifier
                                                        .fillMaxWidth()
                                                        .padding(vertical = 4.dp)
                                                        .clickable(enabled = !isAnswerSubmitted.value) { selectedOptionIndex.value = optIndex },
                                                    shape = RoundedCornerShape(10.dp),
                                                    colors = CardDefaults.cardColors(containerColor = optionColor),
                                                    border = BorderStroke(1.dp, optionBorderColor)
                                                ) {
                                                    Row(
                                                        modifier = Modifier.padding(14.dp),
                                                        verticalAlignment = Alignment.CenterVertically
                                                    ) {
                                                        RadioButton(
                                                            selected = isSelected,
                                                            onClick = { if (!isAnswerSubmitted.value) selectedOptionIndex.value = optIndex },
                                                            enabled = !isAnswerSubmitted.value,
                                                            colors = RadioButtonDefaults.colors(selectedColor = LingoPrimary)
                                                        )
                                                        Spacer(modifier = Modifier.width(8.dp))
                                                        Text(text = option, fontSize = 14.sp)
                                                    }
                                                }
                                            }

                                            if (isAnswerSubmitted.value) {
                                                Spacer(modifier = Modifier.height(12.dp))
                                                Surface(
                                                    shape = RoundedCornerShape(10.dp),
                                                    color = LingoPrimary.copy(alpha = 0.05f),
                                                    modifier = Modifier.fillMaxWidth()
                                                ) {
                                                    Column(modifier = Modifier.padding(10.dp)) {
                                                        Text("Wyjasnienie PL:", fontSize = 11.sp, fontWeight = FontWeight.Bold, color = LingoPrimary)
                                                        Spacer(modifier = Modifier.height(4.dp))
                                                        Text(text = questionItem.explanation, fontSize = 12.sp, color = MaterialTheme.colorScheme.onSurface)
                                                    }
                                                }
                                            }
                                        }
                                    }
                                }

                                item {
                                    if (!isAnswerSubmitted.value) {
                                        Button(
                                            onClick = {
                                                if (selectedOptionIndex.value != null) {
                                                    isAnswerSubmitted.value = true
                                                    if (selectedOptionIndex.value == questionItem.answerIndex) {
                                                        score.value += 1
                                                    }
                                                }
                                            },
                                            modifier = Modifier.fillMaxWidth(),
                                            enabled = selectedOptionIndex.value != null,
                                            colors = ButtonDefaults.buttonColors(containerColor = LingoPrimary),
                                            shape = RoundedCornerShape(12.dp)
                                        ) {
                                            Text("Zatwierdź odpowiedź")
                                        }
                                    } else {
                                        Button(
                                            onClick = {
                                                currentQuestionIndex.value += 1
                                                selectedOptionIndex.value = null
                                                isAnswerSubmitted.value = false
                                            },
                                            modifier = Modifier.fillMaxWidth(),
                                            colors = ButtonDefaults.buttonColors(containerColor = LingoPrimary),
                                            shape = RoundedCornerShape(12.dp)
                                        ) {
                                            Text(if (currentQuestionIndex.value == questionsList.size - 1) "Zakończ quiz" else "Następne pytanie")
                                        }
                                    }
                                }
                            } else {
                                // Quiz Finished Results Card
                                item {
                                    Card(
                                        modifier = Modifier.fillMaxWidth(),
                                        shape = RoundedCornerShape(16.dp),
                                        colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surface),
                                        border = BorderStroke(1.dp, MaterialTheme.colorScheme.outlineVariant.copy(alpha = 0.3f))
                                    ) {
                                        Column(
                                            modifier = Modifier.padding(24.dp),
                                            horizontalAlignment = Alignment.CenterHorizontally,
                                            verticalArrangement = Arrangement.spacedBy(12.dp)
                                        ) {
                                            Text("🎉 Quiz Zakończony!", fontWeight = FontWeight.Bold, fontSize = 18.sp, color = LingoPrimary)
                                            Text(
                                                text = "Twój Wynik: ${score.value} / ${questionsList.size}",
                                                fontWeight = FontWeight.Black,
                                                fontSize = 24.sp,
                                                color = MaterialTheme.colorScheme.onSurface
                                            )
                                            Text(
                                                text = when {
                                                    score.value == questionsList.size -> "Genialnie! W pełni rozumiesz tekst i gramatykę tego opowiadania!"
                                                    score.value >= questionsList.size / 2 -> "Bardzo dobrze! Masz dobre wyczucie tekstu."
                                                    else -> "Dobry początek. Przeczytaj opowiadanie jeszcze raz (Krok 1) i przeanalizuj słówka (Krok 2)!"
                                                },
                                                fontSize = 13.sp,
                                                color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.7f),
                                                textAlign = TextAlign.Center
                                            )

                                            Button(
                                                onClick = {
                                                    currentQuestionIndex.value = 0
                                                    selectedOptionIndex.value = null
                                                    isAnswerSubmitted.value = false
                                                    score.value = 0
                                                },
                                                colors = ButtonDefaults.buttonColors(containerColor = LingoPrimary),
                                                shape = RoundedCornerShape(12.dp)
                                            ) {
                                                Text("Spróbuj ponownie 🔄")
                                            }
                                        }
                                    }
                                }
                            }

                            item {
                                Spacer(modifier = Modifier.height(60.dp))
                            }
                        }
                    }
                }
            }
            androidx.compose.foundation.layout.Box(modifier = androidx.compose.ui.Modifier.align(androidx.compose.ui.Alignment.BottomCenter).padding(bottom = 16.dp)) {
                GlobalAcceleratorWidget(viewModel = viewModel, activeLangCode = activeStory.language, cefrLevel = activeStory.difficulty, speechHelper = speechHelper)
            }


            if (isGeneratingStory) {
                Box(
                    modifier = Modifier
                        .fillMaxSize()
                        .background(Color.Black.copy(alpha = 0.4f))
                        .clickable(enabled = false) { /* stop propagation */ },
                    contentAlignment = Alignment.Center
                ) {
                    Card(
                        modifier = Modifier.padding(24.dp),
                        shape = RoundedCornerShape(16.dp),
                        colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surface),
                        elevation = CardDefaults.cardElevation(defaultElevation = 8.dp)
                    ) {
                        Column(
                            modifier = Modifier.padding(24.dp),
                            horizontalAlignment = Alignment.CenterHorizontally,
                            verticalArrangement = Arrangement.spacedBy(16.dp)
                        ) {
                            CircularProgressIndicator(
                                color = LingoPrimary,
                                modifier = Modifier.size(48.dp)
                            )
                            Text(
                                text = "Lingo AI pracuje... 🪄",
                                fontWeight = FontWeight.Bold,
                                fontSize = 16.sp,
                                color = MaterialTheme.colorScheme.onSurface
                            )
                            Text(
                                text = "Trwa dynamiczne generowanie oraz konsolidacja nowych pytań gramatycznych i immersyjnych scenariuszy ról osadzonych w realiach opowiadania. Zaraz rozpoczniemy!",
                                fontSize = 12.sp,
                                color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.7f),
                                textAlign = TextAlign.Center,
                                lineHeight = 16.sp
                            )
                        }
                    }
                }
            }
        }
    }

    // --- Floating Translator Panel overlay ---
    if (isTranslatingWord || wordTranslation != null) {
        Box(
            modifier = Modifier
                .fillMaxSize()
                .background(Color.Black.copy(alpha = 0.3f))
                .clickable { viewModel.clearWordTranslation() }
        ) {
            Card(
                modifier = Modifier
                    .fillMaxWidth()
                    .fillMaxHeight(0.85f)
                    .align(Alignment.BottomCenter)
                    .clickable(enabled = false) { /* stop propagation */ }
                    .padding(16.dp),
                shape = RoundedCornerShape(20.dp),
                colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surface),
                elevation = CardDefaults.cardElevation(defaultElevation = 8.dp)
            ) {
                Column(
                    modifier = Modifier
                        .fillMaxSize()
                        .verticalScroll(rememberScrollState())
                        .padding(20.dp)
                ) {
                    // Panel Header
                    Row(
                        modifier = Modifier.fillMaxWidth(),
                        horizontalArrangement = Arrangement.SpaceBetween,
                        verticalAlignment = Alignment.CenterVertically
                    ) {
                        Row(verticalAlignment = Alignment.CenterVertically) {
                            Icon(
                                imageVector = Icons.Default.Book,
                                contentDescription = null,
                                tint = LingoPrimary,
                                modifier = Modifier.size(20.dp)
                            )
                            Spacer(modifier = Modifier.width(6.dp))
                            Text(
                                text = "Tłumacz kontekstowy AI",
                                fontSize = 12.sp,
                                fontWeight = FontWeight.Bold,
                                color = LingoPrimary
                            )
                        }
                        IconButton(
                            onClick = { viewModel.clearWordTranslation() },
                            modifier = Modifier.size(28.dp)
                        ) {
                            Icon(imageVector = Icons.Default.Close, contentDescription = "Zamknij", modifier = Modifier.size(18.dp))
                        }
                    }

                    Spacer(modifier = Modifier.height(10.dp))

                    if (isTranslatingWord) {
                        Column(
                            modifier = Modifier
                                .fillMaxWidth()
                                .padding(vertical = 20.dp),
                            horizontalAlignment = Alignment.CenterHorizontally
                        ) {
                            CircularProgressIndicator(color = LingoPrimary, modifier = Modifier.size(32.dp))
                            Spacer(modifier = Modifier.height(12.dp))
                            Text("AI analizuje słowo w zdaniu...", fontSize = 12.sp, color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.6f))
                        }
                    } else if (wordTranslation != null) {
                        Column {
                            Row(
                                verticalAlignment = Alignment.CenterVertically,
                                horizontalArrangement = Arrangement.spacedBy(8.dp)
                            ) {
                                Text(
                                    text = clickedWord.value,
                                    fontSize = 18.sp,
                                    fontWeight = FontWeight.Black,
                                    color = MaterialTheme.colorScheme.onSurface
                                )
                                Surface(
                                    shape = RoundedCornerShape(6.dp),
                                    color = MaterialTheme.colorScheme.secondaryContainer
                                ) {
                                    Text(
                                        text = wordTranslation.partOfSpeech,
                                        fontSize = 10.sp,
                                        fontWeight = FontWeight.Bold,
                                        color = MaterialTheme.colorScheme.onSecondaryContainer,
                                        modifier = Modifier.padding(horizontal = 6.dp, vertical = 2.dp)
                                    )
                                }
                            }

                            Spacer(modifier = Modifier.height(8.dp))

                            // Main translation
                            Text(
                                text = wordTranslation.translation,
                                fontSize = 16.sp,
                                fontWeight = FontWeight.Bold,
                                color = LingoPrimary
                            )

                            Spacer(modifier = Modifier.height(6.dp))

                            // Context explanation
                            Text(
                                text = wordTranslation.polishExplanation,
                                fontSize = 12.sp,
                                color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.8f),
                                lineHeight = 16.sp
                            )

                            if (!wordTranslation.contextUsageExplanation.isNullOrBlank()) {
                                Spacer(modifier = Modifier.height(12.dp))
                                Card(
                                    modifier = Modifier.fillMaxWidth(),
                                    shape = RoundedCornerShape(12.dp),
                                    colors = CardDefaults.cardColors(containerColor = LingoPrimary.copy(alpha = 0.05f)),
                                    border = BorderStroke(1.dp, LingoPrimary.copy(alpha = 0.15f))
                                ) {
                                    Column(modifier = Modifier.padding(12.dp)) {
                                        Row(verticalAlignment = Alignment.CenterVertically) {
                                            Icon(
                                                imageVector = Icons.Default.School,
                                                contentDescription = null,
                                                tint = LingoPrimary,
                                                modifier = Modifier.size(16.dp)
                                            )
                                            Spacer(modifier = Modifier.width(6.dp))
                                            Text(
                                                text = "Dlaczego użyto w tym kontekście?",
                                                fontSize = 11.sp,
                                                fontWeight = FontWeight.ExtraBold,
                                                color = LingoPrimary
                                            )
                                        }
                                        Spacer(modifier = Modifier.height(6.dp))
                                        Text(
                                            text = wordTranslation.contextUsageExplanation,
                                            fontSize = 11.sp,
                                            lineHeight = 15.sp,
                                            color = MaterialTheme.colorScheme.onSurface
                                        )
                                    }
                                }
                            }

                            if (wordTranslation.alternativeMeanings.isNotEmpty()) {
                                Spacer(modifier = Modifier.height(10.dp))
                                Text(
                                    text = "Alternatywne znaczenia:",
                                    fontSize = 11.sp,
                                    fontWeight = FontWeight.Bold,
                                    color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.5f)
                                )
                                Spacer(modifier = Modifier.height(4.dp))
                                androidx.compose.foundation.layout.FlowRow(
                                    horizontalArrangement = Arrangement.spacedBy(6.dp),
                                    verticalArrangement = Arrangement.spacedBy(6.dp)
                                ) {
                                    wordTranslation.alternativeMeanings.forEach { alt ->
                                        Surface(
                                            shape = RoundedCornerShape(6.dp),
                                            color = MaterialTheme.colorScheme.surfaceVariant,
                                            border = BorderStroke(0.5.dp, MaterialTheme.colorScheme.outlineVariant)
                                        ) {
                                            Text(
                                                text = alt,
                                                fontSize = 10.sp,
                                                color = MaterialTheme.colorScheme.onSurfaceVariant,
                                                modifier = Modifier.padding(horizontal = 6.dp, vertical = 2.dp)
                                            )
                                        }
                                    }
                                }
                            }

                            Spacer(modifier = Modifier.height(16.dp))

                            // Check for existing mnemonic in user's dictionary
                            val existingStoryMnem = remember(clickedWord.value, wordTranslation.translation, mnemonics) {
                                mnemonics.find { m ->
                                    m.wordOrPhrase.equals(clickedWord.value, ignoreCase = true) ||
                                    m.wordOrPhrase.equals(wordTranslation.translation, ignoreCase = true) ||
                                    parseMnemonic(m.association)?.word.equals(clickedWord.value, ignoreCase = true) ||
                                    parseMnemonic(m.association)?.translation.equals(wordTranslation.translation, ignoreCase = true)
                                }
                            }

                            // Buttons: Save to Vocabulary and Generate Mnemonic
                            Row(
                                modifier = Modifier.fillMaxWidth(),
                                horizontalArrangement = Arrangement.spacedBy(8.dp)
                            ) {
                                // Save to Vocabulary button
                                val isSaved = remember { mutableStateOf(false) }
                                OutlinedButton(
                                    onClick = {
                                        viewModel.saveStoryWordToVocabulary(
                                            clickedWord.value,
                                            wordTranslation.translation,
                                            activeStory?.language ?: "",
                                            clickedSentence.value
                                        )
                                        isSaved.value = true
                                        android.widget.Toast.makeText(context, "Słówko zapisane w Twoim słowniku!", android.widget.Toast.LENGTH_SHORT).show()
                                    },
                                    modifier = Modifier.weight(1f),
                                    shape = RoundedCornerShape(12.dp),
                                    enabled = !isSaved.value
                                ) {
                                    Icon(
                                        imageVector = if (isSaved.value) Icons.Default.Check else Icons.Default.Add,
                                        contentDescription = null,
                                        modifier = Modifier.size(16.dp)
                                    )
                                    Spacer(modifier = Modifier.width(4.dp))
                                    Text(if (isSaved.value) "Zapisano" else "Do Słownika", fontSize = 11.sp)
                                }

                                // Mnemonic button
                                Button(
                                    onClick = {
                                        viewModel.generateAndSaveRichMnemonic(
                                            clickedWord.value,
                                            activeStory?.language ?: (goal?.targetLanguage ?: "Spanish"),
                                            clickedSentence.value
                                        )
                                        android.widget.Toast.makeText(context, "Generowanie mnemotechniki przez AI...", android.widget.Toast.LENGTH_SHORT).show()
                                    },
                                    modifier = Modifier.weight(1.2f),
                                    colors = ButtonDefaults.buttonColors(containerColor = LingoPrimary),
                                    shape = RoundedCornerShape(12.dp),
                                    enabled = !isGeneratingMnemonic
                                ) {
                                    if (isGeneratingMnemonic) {
                                        CircularProgressIndicator(modifier = Modifier.size(16.dp), color = Color.White, strokeWidth = 2.dp)
                                    } else {
                                        Text(if (existingStoryMnem != null || generatedMnemonic != null) "🔄 Nowe skojarzenie" else "🧠 Skojarzenie AI", fontSize = 11.sp)
                                    }
                                }
                            }

                            // Show Mnemonic: parsed rich view for either existing or newly generated mnemonic!
                            val activeMnemonicRich = remember(generatedMnemonic, existingStoryMnem) {
                                (generatedMnemonic?.let { parseMnemonic(it) })
                                    ?: (existingStoryMnem?.let { parseMnemonic(it.association) })
                            }

                            if (activeMnemonicRich != null) {
                                Spacer(modifier = Modifier.height(12.dp))
                                RichMnemonicDisplayView(
                                    richMnemonic = activeMnemonicRich,
                                    targetLanguage = activeStory?.language ?: (goal?.targetLanguage ?: "Spanish"),
                                    speechHelper = speechHelper
                                )
                            } else if (generatedMnemonic != null) {
                                Spacer(modifier = Modifier.height(12.dp))
                                Surface(
                                    shape = RoundedCornerShape(10.dp),
                                    color = LingoSecondary.copy(alpha = 0.08f),
                                    border = BorderStroke(1.dp, LingoSecondary.copy(alpha = 0.15f))
                                ) {
                                    Column(modifier = Modifier.padding(10.dp)) {
                                        Text(
                                            text = "Mnemotechnika dla słówka:",
                                            fontSize = 11.sp,
                                            fontWeight = FontWeight.Bold,
                                            color = LingoSecondary
                                        )
                                        Spacer(modifier = Modifier.height(4.dp))
                                        Text(
                                            text = generatedMnemonic,
                                            fontSize = 11.sp,
                                            lineHeight = 15.sp,
                                            color = MaterialTheme.colorScheme.onSurface
                                        )
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }
    }
}

@Composable
fun MnemonicGeneratorTab(
    viewModel: TutorViewModel,
    mnemonics: List<Mnemonic>,
    isGenerating: Boolean,
    generatedResult: String?,
    goal: UserGoal?,
    speechHelper: TutorSpeechHelper
) {
    val context = LocalContext.current
    val coroutineScope = rememberCoroutineScope()
    val wordInput = remember { mutableStateOf("") }
    val selectedLang = remember { mutableStateOf(goal?.targetLanguage ?: "Spanish") }
    LaunchedEffect(goal?.targetLanguage) {
        if (!goal?.targetLanguage.isNullOrBlank()) {
            selectedLang.value = goal.targetLanguage
        }
    }
    val languages = listOf("English", "Spanish", "German", "French", "Italian", "Polish")
    
    var liveTranslation by remember { mutableStateOf("") }
    var isTranslating by remember { mutableStateOf(false) }

    // Live search for existing mnemonic in user's dictionary
    val existingSaved = remember(wordInput.value, mnemonics) {
        if (wordInput.value.isBlank()) null
        else mnemonics.find { m ->
            m.wordOrPhrase.equals(wordInput.value.trim(), ignoreCase = true) ||
            parseMnemonic(m.association)?.let { r ->
                r.word.equals(wordInput.value.trim(), ignoreCase = true) ||
                r.translation.equals(wordInput.value.trim(), ignoreCase = true) ||
                r.translation.contains(wordInput.value.trim(), ignoreCase = true)
            } == true
        }
    }

    LazyColumn(
        modifier = Modifier
            .fillMaxSize()
            .padding(16.dp),
        verticalArrangement = Arrangement.spacedBy(16.dp)
    ) {
        // Title banner
        item {
            Row(
                modifier = Modifier.fillMaxWidth(),
                verticalAlignment = Alignment.CenterVertically,
                horizontalArrangement = Arrangement.spacedBy(10.dp)
            ) {
                Box(
                    modifier = Modifier
                        .size(40.dp)
                        .clip(RoundedCornerShape(10.dp))
                        .background(LingoSecondary.copy(alpha = 0.15f)),
                    contentAlignment = Alignment.Center
                ) {
                    Icon(
                        imageVector = Icons.Default.Memory,
                        contentDescription = null,
                        tint = LingoSecondary,
                        modifier = Modifier.size(24.dp)
                    )
                }
                Column {
                    Text(
                        text = "Generator Mnemotechnik",
                        fontSize = 18.sp,
                        fontWeight = FontWeight.Bold,
                        color = MaterialTheme.colorScheme.onBackground
                    )
                    Text(
                        text = "Zapamiętuj trudne słówka za pomocą skojarzeń i zabawnych historii",
                        fontSize = 12.sp,
                        color = MaterialTheme.colorScheme.onBackground.copy(alpha = 0.6f)
                    )
                }
            }
        }

        // Mnemonic Creator Form
        item {
            Card(
                modifier = Modifier.fillMaxWidth(),
                shape = RoundedCornerShape(16.dp),
                colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surface),
                elevation = CardDefaults.cardElevation(defaultElevation = 2.dp)
            ) {
                Column(modifier = Modifier.padding(16.dp)) {
                    Text(
                        text = "Stwórz nowe skojarzenie przez AI",
                        fontSize = 14.sp,
                        fontWeight = FontWeight.Bold,
                        color = MaterialTheme.colorScheme.onSurface
                    )
                    
                    Spacer(modifier = Modifier.height(12.dp))

                    OutlinedTextField(
                        value = wordInput.value,
                        onValueChange = { 
                            wordInput.value = it 
                            if (it.isBlank()) liveTranslation = ""
                        },
                        label = { Text("Wpisz słówko lub całe zdanie") },
                        placeholder = { Text("np. embarrassed lub embarazada") },
                        trailingIcon = {
                            if (wordInput.value.isNotBlank()) {
                                Row(verticalAlignment = Alignment.CenterVertically) {
                                    IconButton(
                                        onClick = { speechHelper.speak(wordInput.value.trim(), selectedLang.value) },
                                        modifier = Modifier.testTag("listen_input_word_btn")
                                    ) {
                                        Icon(
                                            imageVector = Icons.Default.VolumeUp,
                                            contentDescription = "Odsłuchaj wymowę",
                                            tint = LingoPrimary
                                        )
                                    }
                                }
                            }
                        },
                        modifier = Modifier
                            .fillMaxWidth()
                            .testTag("mnemonic_word_input"),
                        shape = RoundedCornerShape(12.dp),
                        singleLine = true
                    )

                    // Quick Polish Translation Lookup Row
                    if (wordInput.value.isNotBlank()) {
                        Spacer(modifier = Modifier.height(6.dp))
                        Row(
                            modifier = Modifier.fillMaxWidth(),
                            verticalAlignment = Alignment.CenterVertically,
                            horizontalArrangement = Arrangement.SpaceBetween
                        ) {
                            if (liveTranslation.isNotBlank()) {
                                Text(
                                    text = "🇵🇱 Tłumaczenie PL: $liveTranslation",
                                    fontSize = 12.sp,
                                    fontWeight = FontWeight.Bold,
                                    color = LingoSuccessGreen
                                )
                            } else {
                                TextButton(
                                    onClick = {
                                        if (wordInput.value.isNotBlank()) {
                                            isTranslating = true
                                            coroutineScope.launch {
                                                try {
                                                    val res = com.example.data.api.TutorAiService.translateSingleWord(
                                                        wordInput.value.trim(),
                                                        wordInput.value.trim(),
                                                        selectedLang.value
                                                    )
                                                    liveTranslation = res.translation
                                                } catch (e: Exception) {
                                                    liveTranslation = "Brak tłumaczenia"
                                                } finally {
                                                    isTranslating = false
                                                }
                                            }
                                        }
                                    },
                                    contentPadding = PaddingValues(0.dp)
                                ) {
                                    if (isTranslating) {
                                        CircularProgressIndicator(modifier = Modifier.size(12.dp), strokeWidth = 1.dp)
                                    } else {
                                        Text("🔍 Sprawdź tłumaczenie na polski", fontSize = 11.sp, color = LingoPrimary)
                                    }
                                }
                            }
                        }
                    }

                    Spacer(modifier = Modifier.height(12.dp))

                    Row(
                        modifier = Modifier.fillMaxWidth(),
                        horizontalArrangement = Arrangement.spacedBy(10.dp),
                        verticalAlignment = Alignment.CenterVertically
                    ) {
                        Box(modifier = Modifier.weight(1f)) {
                            val expanded = remember { mutableStateOf(false) }
                            OutlinedButton(
                                onClick = { expanded.value = true },
                                modifier = Modifier.fillMaxWidth(),
                                shape = RoundedCornerShape(12.dp)
                            ) {
                                Text("Język: ${selectedLang.value}", fontSize = 12.sp)
                            }
                            DropdownMenu(
                                expanded = expanded.value,
                                onDismissRequest = { expanded.value = false }
                            ) {
                                languages.forEach { lang ->
                                    DropdownMenuItem(
                                        text = { Text(lang) },
                                        onClick = {
                                            selectedLang.value = lang
                                            expanded.value = false
                                        }
                                    )
                                }
                            }
                        }

                        Button(
                            onClick = {
                                if (wordInput.value.isBlank()) {
                                    android.widget.Toast.makeText(context, "Najpierw wpisz słówko lub zdanie!", android.widget.Toast.LENGTH_SHORT).show()
                                } else {
                                    viewModel.generateAndSaveRichMnemonic(wordInput.value, selectedLang.value)
                                }
                            },
                            modifier = Modifier
                                .weight(1.2f)
                                .testTag("generate_mnemonic_button"),
                            colors = ButtonDefaults.buttonColors(containerColor = LingoPrimary),
                            shape = RoundedCornerShape(12.dp),
                            enabled = !isGenerating
                        ) {
                            if (isGenerating) {
                                CircularProgressIndicator(
                                    modifier = Modifier.size(18.dp),
                                    color = Color.White,
                                    strokeWidth = 2.dp
                                )
                            } else {
                                Text("Wygeneruj 🧠", fontSize = 12.sp)
                            }
                        }
                    }

                    // Show existing association from memory dictionary if already present
                    if (existingSaved != null && generatedResult == null) {
                        Spacer(modifier = Modifier.height(14.dp))
                        Surface(
                            modifier = Modifier.fillMaxWidth(),
                            shape = RoundedCornerShape(12.dp),
                            color = MaterialTheme.colorScheme.secondaryContainer.copy(alpha = 0.25f),
                            border = BorderStroke(1.dp, MaterialTheme.colorScheme.secondary.copy(alpha = 0.35f))
                        ) {
                            Column(modifier = Modifier.padding(12.dp)) {
                                Row(
                                    verticalAlignment = Alignment.CenterVertically,
                                    horizontalArrangement = Arrangement.spacedBy(6.dp)
                                ) {
                                    Icon(
                                        imageVector = Icons.Default.Lightbulb,
                                        contentDescription = null,
                                        tint = LingoSecondary,
                                        modifier = Modifier.size(16.dp)
                                    )
                                    Text(
                                        text = "Wcześniejsze skojarzenie w Twojej bazie:",
                                        fontSize = 12.sp,
                                        fontWeight = FontWeight.Bold,
                                        color = LingoSecondary
                                    )
                                }
                                Spacer(modifier = Modifier.height(8.dp))
                                val richExisting = remember(existingSaved.association) { parseMnemonic(existingSaved.association) }
                                if (richExisting != null) {
                                    RichMnemonicDisplayView(
                                        richMnemonic = richExisting,
                                        targetLanguage = existingSaved.language,
                                        speechHelper = speechHelper
                                    )
                                } else {
                                    Text(
                                        text = existingSaved.association,
                                        fontSize = 12.sp,
                                        lineHeight = 16.sp,
                                        color = MaterialTheme.colorScheme.onSurface
                                    )
                                }
                            }
                        }
                    }

                    if (generatedResult != null) {
                        Spacer(modifier = Modifier.height(16.dp))
                        val richGen = remember(generatedResult) { parseMnemonic(generatedResult) }
                        
                        Surface(
                            modifier = Modifier.fillMaxWidth(),
                            shape = RoundedCornerShape(12.dp),
                            color = MaterialTheme.colorScheme.primaryContainer.copy(alpha = 0.25f),
                            border = BorderStroke(1.dp, MaterialTheme.colorScheme.primary.copy(alpha = 0.15f))
                        ) {
                            Column(modifier = Modifier.padding(14.dp)) {
                                Row(
                                    modifier = Modifier.fillMaxWidth(),
                                    horizontalArrangement = Arrangement.SpaceBetween,
                                    verticalAlignment = Alignment.CenterVertically
                                ) {
                                    Text(
                                        text = "Wygenerowane Skojarzenie (Keyword Method):",
                                        fontSize = 12.sp,
                                        fontWeight = FontWeight.Bold,
                                        color = MaterialTheme.colorScheme.primary
                                    )
                                    IconButton(
                                        onClick = { viewModel.clearGeneratedMnemonic() },
                                        modifier = Modifier.size(24.dp)
                                    ) {
                                        Icon(
                                            imageVector = Icons.Default.Close,
                                            contentDescription = "Clear",
                                            modifier = Modifier.size(16.dp)
                                        )
                                    }
                                }
                                Spacer(modifier = Modifier.height(8.dp))

                                if (richGen != null) {
                                    RichMnemonicDisplayView(
                                        richMnemonic = richGen,
                                        targetLanguage = selectedLang.value,
                                        speechHelper = speechHelper
                                    )
                                } else {
                                    Text(
                                        text = generatedResult,
                                        fontSize = 13.sp,
                                        lineHeight = 18.sp,
                                        color = MaterialTheme.colorScheme.onSurface
                                    )
                                }
                            }
                        }
                    }
                }
            }
        }

        // Saved Mnemonics List Header
        item {
            Text(
                text = "Twój Słownik Skojarzeń (${mnemonics.size})",
                fontSize = 16.sp,
                fontWeight = FontWeight.Bold,
                color = MaterialTheme.colorScheme.onBackground
            )
        }

        if (mnemonics.isEmpty()) {
            item {
                Card(
                    modifier = Modifier
                        .fillMaxWidth()
                        .padding(vertical = 10.dp),
                    shape = RoundedCornerShape(16.dp),
                    colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.3f))
                ) {
                    Column(
                        modifier = Modifier
                            .fillMaxWidth()
                            .padding(24.dp),
                        horizontalAlignment = Alignment.CenterHorizontally,
                        verticalArrangement = Arrangement.spacedBy(8.dp)
                    ) {
                        Text(
                            text = "💡 Brak zapisanych skojarzeń",
                            fontWeight = FontWeight.Bold,
                            fontSize = 14.sp,
                            color = MaterialTheme.colorScheme.onSurfaceVariant
                        )
                        Text(
                            text = "Wpisz trudne słówko u góry i kliknij Wygeneruj, aby AI stworzyło dla Ciebie genialną mnemotechnikę!",
                            fontSize = 12.sp,
                            color = MaterialTheme.colorScheme.onSurfaceVariant.copy(alpha = 0.7f),
                            textAlign = androidx.compose.ui.text.style.TextAlign.Center,
                            lineHeight = 16.sp
                        )
                    }
                }
            }
        } else {
            items(mnemonics.size) { index ->
                val mnemonic = mnemonics[index]
                MnemonicItemCard(
                    mnemonic = mnemonic,
                    speechHelper = speechHelper,
                    onDelete = { viewModel.deleteMnemonic(mnemonic.id) }
                )
            }
        }
    }
}

@Composable
fun MnemonicItemCard(
    mnemonic: Mnemonic,
    speechHelper: TutorSpeechHelper,
    onDelete: () -> Unit
) {
    val isExpanded = remember { mutableStateOf(false) }
    val richMnem = remember(mnemonic.association) { parseMnemonic(mnemonic.association) }

    Card(
        modifier = Modifier
            .fillMaxWidth()
            .testTag("mnemonic_card_${mnemonic.id}"),
        shape = RoundedCornerShape(16.dp),
        colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surface),
        elevation = CardDefaults.cardElevation(defaultElevation = 2.dp)
    ) {
        Column(modifier = Modifier.padding(16.dp)) {
            Row(
                modifier = Modifier.fillMaxWidth(),
                horizontalArrangement = Arrangement.SpaceBetween,
                verticalAlignment = Alignment.CenterVertically
            ) {
                Column(modifier = Modifier.weight(1f)) {
                    Row(
                        verticalAlignment = Alignment.CenterVertically,
                        horizontalArrangement = Arrangement.spacedBy(6.dp)
                    ) {
                        Text(
                            text = mnemonic.wordOrPhrase,
                            fontSize = 16.sp,
                            fontWeight = FontWeight.Bold,
                            color = LingoPrimary
                        )
                        IconButton(
                            onClick = { speechHelper.speak(mnemonic.wordOrPhrase, mnemonic.language) },
                            modifier = Modifier.size(28.dp)
                        ) {
                            Icon(
                                imageVector = Icons.Default.VolumeUp,
                                contentDescription = "Odsłuchaj",
                                tint = LingoPrimary,
                                modifier = Modifier.size(16.dp)
                            )
                        }
                        Surface(
                            shape = RoundedCornerShape(6.dp),
                            color = MaterialTheme.colorScheme.secondaryContainer
                        ) {
                            Box(modifier = Modifier.padding(horizontal = 6.dp, vertical = 2.dp)) {
                                Text(
                                    text = mnemonic.language,
                                    fontSize = 10.sp,
                                    fontWeight = FontWeight.Bold,
                                    color = MaterialTheme.colorScheme.onSecondaryContainer
                                )
                            }
                        }
                    }
                    if (richMnem?.translation?.isNotBlank() == true) {
                        Text(
                            text = "🇵🇱 ${richMnem.translation}",
                            fontSize = 12.sp,
                            fontWeight = FontWeight.SemiBold,
                            color = LingoSuccessGreen
                        )
                    }
                }
                
                Row(
                    verticalAlignment = Alignment.CenterVertically,
                    horizontalArrangement = Arrangement.spacedBy(4.dp)
                ) {
                    IconButton(onClick = { isExpanded.value = !isExpanded.value }) {
                        Text(
                            text = if (isExpanded.value) "▲" else "▼",
                            color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.6f),
                            fontSize = 14.sp,
                            fontWeight = FontWeight.Bold
                        )
                    }
                    IconButton(onClick = onDelete) {
                        Icon(
                            imageVector = Icons.Default.Delete,
                            contentDescription = "Usuń skojarzenie",
                            tint = MaterialTheme.colorScheme.error.copy(alpha = 0.8f)
                        )
                    }
                }
            }

            if (isExpanded.value) {
                Spacer(modifier = Modifier.height(8.dp))
                Spacer(
                    modifier = Modifier
                        .fillMaxWidth()
                        .height(1.dp)
                        .background(MaterialTheme.colorScheme.onSurface.copy(alpha = 0.08f))
                )
                Spacer(modifier = Modifier.height(8.dp))

                if (richMnem != null) {
                    RichMnemonicDisplayView(
                        richMnemonic = richMnem,
                        targetLanguage = mnemonic.language,
                        speechHelper = speechHelper
                    )
                } else {
                    Text(
                        text = mnemonic.association,
                        fontSize = 13.sp,
                        lineHeight = 18.sp,
                        color = MaterialTheme.colorScheme.onSurface
                    )
                }
            } else {
                // Short preview of the association
                Spacer(modifier = Modifier.height(4.dp))
                val previewText = if (richMnem != null) {
                    "${richMnem.emojis} ${richMnem.association}"
                } else {
                    mnemonic.association
                }
                Text(
                    text = previewText.take(120) + if (previewText.length > 120) "..." else "",
                    fontSize = 12.sp,
                    lineHeight = 16.sp,
                    color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.6f)
                )
            }
        }
    }
}

// ==========================================
// INTERACTIVE TALIA MNEMOFISZEK COMPONENTS
// ==========================================

@Composable
fun MnemoCardsTab(viewModel: TutorViewModel, speechHelper: TutorSpeechHelper) {
    val context = LocalContext.current
    val coroutineScope = rememberCoroutineScope()
    
    val vocabulary by viewModel.allVocabulary.collectAsStateWithLifecycle(emptyList())
    val mnemonics by viewModel.allMnemonics.collectAsStateWithLifecycle(emptyList())
    val isGeneratingMnemonic by viewModel.isGeneratingMnemonic.collectAsStateWithLifecycle()
    
    var filterSelected by remember { mutableStateOf(0) } // 0 = Wszystkie, 1 = Posiada Mnemofiszkę, 2 = Brak Mnemofiszki
    var searchQuery by remember { mutableStateOf("") }
    
    // Memory Science Tips for loading state
    val memoryTips = listOf(
        "Mózg zapamiętuje absurdalne, dziwne i śmieszne obrazy o 400% szybciej niż suche fakty!",
        "Fiszki z kontekstem sytuacyjnym uczą Cię, kiedy użyć słowa, a nie tylko jak je przetłumaczyć.",
        "Aktywne przypominanie sobie odpowiedzi (Recall) zmusza mózg do budowania silniejszych ścieżek neuronowych.",
        "Metoda powtórek rozłożonych w czasie (SRS) podaje słowa tuż przed tym, jak zaczniesz je zapominać.",
        "Skojarzenia brzmieniowe (np. awkward -> 'A, kocur!') tworzą hak pamięciowy ułatwiający natychmiastowe odnalezienie słowa."
    )
    val activeMemoryTipIndex = remember { mutableStateOf(0) }
    
    LaunchedEffect(isGeneratingMnemonic) {
        if (isGeneratingMnemonic) {
            // Pick a random tip when generation starts
            activeMemoryTipIndex.value = (memoryTips.indices).random()
        }
    }
    
    // Filtered vocabulary list
    val filteredVocabulary = remember(vocabulary, mnemonics, filterSelected, searchQuery) {
        vocabulary.filter { vocab ->
            val hasMnemonic = mnemonics.any { m -> m.wordOrPhrase.equals(vocab.word, ignoreCase = true) }
            val matchesFilter = when (filterSelected) {
                1 -> hasMnemonic
                2 -> !hasMnemonic
                else -> true
            }
            val matchesSearch = vocab.word.contains(searchQuery, ignoreCase = true) || 
                                vocab.translation.contains(searchQuery, ignoreCase = true)
            matchesFilter && matchesSearch
        }
    }
    
    LazyColumn(
        modifier = Modifier
            .fillMaxSize()
            .padding(horizontal = 16.dp),
        verticalArrangement = Arrangement.spacedBy(16.dp),
        contentPadding = PaddingValues(bottom = 120.dp, top = 16.dp)
    ) {
        // --- Header Banner ---
        item {
            Card(
                modifier = Modifier.fillMaxWidth(),
                shape = RoundedCornerShape(16.dp),
                colors = CardDefaults.cardColors(containerColor = LingoPrimary.copy(alpha = 0.08f)),
                border = BorderStroke(1.dp, LingoPrimary.copy(alpha = 0.15f))
            ) {
                Column(modifier = Modifier.padding(16.dp)) {
                    Row(
                        verticalAlignment = Alignment.CenterVertically,
                        horizontalArrangement = Arrangement.spacedBy(8.dp)
                    ) {
                        Icon(
                            imageVector = Icons.Default.School,
                            contentDescription = null,
                            tint = LingoPrimary,
                            modifier = Modifier.size(24.dp)
                        )
                        Text(
                            text = "Interaktywna Talia Mnemofiszek (SRS)",
                            fontSize = 18.sp,
                            fontWeight = FontWeight.Bold,
                            color = LingoPrimary
                        )
                    }
                    Spacer(modifier = Modifier.height(8.dp))
                    Text(
                        text = "Suche tłumaczenia szybko uciekają z pamięci. Nasze Mnemofiszki łączą słowo z barwną, śmieszną sceną (Mnemobrazkiem), kontekstem sytuacyjnym i systemem inteligentnych powtórek rozłożonych w czasie.",
                        fontSize = 12.sp,
                        color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.8f),
                        lineHeight = 16.sp
                    )
                }
            }
        }
        
        if (vocabulary.isEmpty()) {
            // --- Onboarding / Empty State ---
            item {
                Card(
                    modifier = Modifier
                        .fillMaxWidth()
                        .padding(vertical = 12.dp),
                    shape = RoundedCornerShape(20.dp),
                    colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surface),
                    border = BorderStroke(1.5.dp, MaterialTheme.colorScheme.outlineVariant.copy(alpha = 0.5f))
                ) {
                    Column(
                        modifier = Modifier
                            .padding(24.dp)
                            .fillMaxWidth(),
                        horizontalAlignment = Alignment.CenterHorizontally,
                        verticalArrangement = Arrangement.spacedBy(16.dp)
                    ) {
                        Text("👋 Witaj w świecie efektywnej nauki!", fontSize = 18.sp, fontWeight = FontWeight.Bold, color = LingoPrimary, textAlign = TextAlign.Center)
                        
                        Text(
                            text = "Nie ucz się na pamięć nudnych słówek jak „awkward = niezręczny”. Zobacz, dlaczego nasza metoda działa:",
                            fontSize = 13.sp,
                            color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.7f),
                            textAlign = TextAlign.Center
                        )
                        
                        Column(
                            verticalArrangement = Arrangement.spacedBy(10.dp),
                            modifier = Modifier.fillMaxWidth()
                        ) {
                            Row(horizontalArrangement = Arrangement.spacedBy(8.dp)) {
                                Text("🧠", fontSize = 18.sp)
                                Text("Kontekst sytuacyjny — poznasz całe zdanie i prawdziwe użycie słowa.", fontSize = 12.sp, color = MaterialTheme.colorScheme.onSurface)
                            }
                            Row(horizontalArrangement = Arrangement.spacedBy(8.dp)) {
                                Text("🤪", fontSize = 18.sp)
                                Text("Skojarzenie — dziwne, absurdalne lub zabawne, idealnie dopasowane do polskiego brzmienia.", fontSize = 12.sp, color = MaterialTheme.colorScheme.onSurface)
                            }
                            Row(horizontalArrangement = Arrangement.spacedBy(8.dp)) {
                                Text("🖼️", fontSize = 18.sp)
                                Text("Mnemobrazki — kolorowe ikony ułatwiające natychmiastowe przywołanie słowa z głowy.", fontSize = 12.sp, color = MaterialTheme.colorScheme.onSurface)
                            }
                            Row(horizontalArrangement = Arrangement.spacedBy(8.dp)) {
                                Text("🔄", fontSize = 18.sp)
                                Text("Aktywne przypominanie i algorytm SRS — powtórki dopasowane do Twojej krzywej zapominania.", fontSize = 12.sp, color = MaterialTheme.colorScheme.onSurface)
                            }
                        }
                        
                        Spacer(modifier = Modifier.height(8.dp))
                        
                        Button(
                            onClick = {
                                viewModel.populateLegendarySamples()
                                Toast.makeText(context, "Załadowano 5 legendarnych mnemofiszek! 🎉", Toast.LENGTH_LONG).show()
                            },
                            shape = RoundedCornerShape(12.dp),
                            colors = ButtonDefaults.buttonColors(containerColor = LingoPrimary)
                        ) {
                            Icon(imageVector = Icons.Default.Add, contentDescription = null)
                            Spacer(modifier = Modifier.width(6.dp))
                            Text("Załaduj 5 Legendarnych Mnemofiszek")
                        }
                    }
                }
            }
        } else {
            // --- Deck Stats & Filters ---
            item {
                val wordsWithMnemonicCount = vocabulary.count { v -> 
                    mnemonics.any { m -> m.wordOrPhrase.equals(v.word, ignoreCase = true) } 
                }
                
                Card(
                    modifier = Modifier.fillMaxWidth(),
                    shape = RoundedCornerShape(12.dp),
                    colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.2f))
                ) {
                    Row(
                        modifier = Modifier
                            .fillMaxWidth()
                            .padding(12.dp),
                        horizontalArrangement = Arrangement.SpaceBetween,
                        verticalAlignment = Alignment.CenterVertically
                    ) {
                        Column {
                            Text("Postęp Twojej Talii", fontSize = 11.sp, color = MaterialTheme.colorScheme.onSurfaceVariant)
                            Text(
                                text = "$wordsWithMnemonicCount z ${vocabulary.size} słówek posiada Mnemofiszkę AI",
                                fontSize = 13.sp,
                                fontWeight = FontWeight.Bold,
                                color = MaterialTheme.colorScheme.onSurface
                            )
                        }
                        
                        // Small circular progress indicator
                        Box(contentAlignment = Alignment.Center, modifier = Modifier.size(40.dp)) {
                            CircularProgressIndicator(
                                progress = if (vocabulary.isNotEmpty()) wordsWithMnemonicCount.toFloat() / vocabulary.size else 0f,
                                modifier = Modifier.fillMaxSize(),
                                color = LingoSuccessGreen,
                                strokeWidth = 4.dp,
                                trackColor = MaterialTheme.colorScheme.outlineVariant.copy(alpha = 0.3f)
                            )
                            Text(
                                text = "${if (vocabulary.isNotEmpty()) (wordsWithMnemonicCount * 100 / vocabulary.size) else 0}%",
                                fontSize = 10.sp,
                                fontWeight = FontWeight.Bold,
                                color = MaterialTheme.colorScheme.onSurface
                            )
                        }
                    }
                }
            }
            
            // Filters row
            item {
                Column(verticalArrangement = Arrangement.spacedBy(8.dp)) {
                    // Search box
                    OutlinedTextField(
                        value = searchQuery,
                        onValueChange = { searchQuery = it },
                        modifier = Modifier.fillMaxWidth(),
                        placeholder = { Text("Szukaj słówka w słowniku...", fontSize = 13.sp) },
                        leadingIcon = { Icon(imageVector = Icons.Default.Search, contentDescription = null, modifier = Modifier.size(18.dp)) },
                        singleLine = true,
                        shape = RoundedCornerShape(10.dp),
                        textStyle = LocalTextStyle.current.copy(fontSize = 13.sp),
                        trailingIcon = {
                            if (searchQuery.isNotEmpty()) {
                                IconButton(onClick = { searchQuery = "" }, modifier = Modifier.size(24.dp)) {
                                    Icon(imageVector = Icons.Default.Close, contentDescription = null, modifier = Modifier.size(16.dp))
                                }
                            }
                        }
                    )
                    
                    // Filter Chips Row
                    Row(
                        horizontalArrangement = Arrangement.spacedBy(8.dp),
                        modifier = Modifier.fillMaxWidth()
                    ) {
                        listOf(
                            "Wszystkie" to 0,
                            "Z Mnemofiszką" to 1,
                            "Do zrobienia" to 2
                        ).forEach { (label, index) ->
                            val isSelected = filterSelected == index
                            Surface(
                                modifier = Modifier
                                    .weight(1f)
                                    .clickable { filterSelected = index },
                                shape = RoundedCornerShape(10.dp),
                                color = if (isSelected) LingoPrimary else MaterialTheme.colorScheme.surface,
                                border = BorderStroke(
                                    width = 1.dp,
                                    color = if (isSelected) LingoPrimary else MaterialTheme.colorScheme.outlineVariant
                                )
                            ) {
                                Text(
                                    text = label,
                                    fontSize = 11.sp,
                                    fontWeight = FontWeight.Bold,
                                    color = if (isSelected) Color.White else MaterialTheme.colorScheme.onSurface,
                                    modifier = Modifier.padding(vertical = 8.dp),
                                    textAlign = TextAlign.Center
                                )
                            }
                        }
                    }
                }
            }
            
            // Check if filtered list is empty
            if (filteredVocabulary.isEmpty()) {
                item {
                    Column(
                        modifier = Modifier
                            .fillMaxWidth()
                            .padding(vertical = 32.dp),
                        horizontalAlignment = Alignment.CenterHorizontally,
                        verticalArrangement = Arrangement.spacedBy(8.dp)
                    ) {
                        Text("🔍", fontSize = 32.sp)
                        Text(
                            text = "Brak słówek spełniających kryteria.",
                            fontSize = 14.sp,
                            fontWeight = FontWeight.Medium,
                            color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.5f)
                        )
                    }
                }
            } else {
                // Render vocabulary cards
                items(
                    count = filteredVocabulary.size,
                    key = { index -> filteredVocabulary[index].id }
                ) { index ->
                    val vocab = filteredVocabulary[index]
                    val mnem = mnemonics.find { it.wordOrPhrase.equals(vocab.word, ignoreCase = true) }
                    val richMnemonic = mnem?.let { parseMnemonic(it.association) }
                    
                    InteractiveMnemonicCard(
                        vocab = vocab,
                        mnemonic = mnem,
                        richMnemonic = richMnemonic,
                        viewModel = viewModel,
                        isGeneratingMnemonicGlobal = isGeneratingMnemonic,
                        memoryTip = memoryTips[activeMemoryTipIndex.value],
                        speechHelper = speechHelper
                    )
                }
            }
        }
    }
}

@Composable
fun InteractiveMnemonicCard(
    vocab: Vocabulary,
    mnemonic: Mnemonic?,
    richMnemonic: com.example.data.api.RichMnemonicResponse?,
    viewModel: TutorViewModel,
    isGeneratingMnemonicGlobal: Boolean,
    memoryTip: String,
    speechHelper: TutorSpeechHelper
) {
    val context = LocalContext.current
    val coroutineScope = rememberCoroutineScope()
    var isFlipped by remember { mutableStateOf(false) }
    var isGeneratingLocal by remember { mutableStateOf(false) }
    
    // Fluency Latency Engine (Inteligentny Zegar Decyzji Neuronowej)
    var cardStartTime by remember { mutableLongStateOf(System.currentTimeMillis()) }
    var recallLatencyMs by remember { mutableLongStateOf(0L) }
    
    LaunchedEffect(isFlipped) {
        if (!isFlipped) {
            cardStartTime = System.currentTimeMillis()
        }
    }
    
    // Auto reset flip if mnemonic becomes available
    LaunchedEffect(mnemonic) {
        if (mnemonic != null) {
            isGeneratingLocal = false
        }
    }
    
    Card(
        modifier = Modifier
            .fillMaxWidth()
            .testTag("mnemonic_card_${vocab.word.lowercase().replace(" ", "_")}"),
        shape = RoundedCornerShape(16.dp),
        colors = CardDefaults.cardColors(
            containerColor = if (isFlipped) MaterialTheme.colorScheme.surface else MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.3f)
        ),
        border = BorderStroke(
            width = if (isFlipped) 2.dp else 1.dp,
            color = if (isFlipped) LingoPrimary.copy(alpha = 0.6f) else MaterialTheme.colorScheme.outlineVariant.copy(alpha = 0.5f)
        ),
        elevation = CardDefaults.cardElevation(defaultElevation = if (isFlipped) 6.dp else 1.dp)
    ) {
        Column(modifier = Modifier.padding(16.dp)) {
            val flag = when (vocab.language.lowercase()) {
                "english", "angielski" -> "🇬🇧"
                "spanish", "hiszpański" -> "🇪🇸"
                "german", "niemiecki" -> "🇩🇪"
                "french", "francuski" -> "🇫🇷"
                "italian", "włoski" -> "🇮🇹"
                "polish", "polski" -> "🇵🇱"
                else -> "🌍"
            }
            // Card Header (Tags & Meta)
            Row(
                modifier = Modifier.fillMaxWidth(),
                horizontalArrangement = Arrangement.SpaceBetween,
                verticalAlignment = Alignment.CenterVertically
            ) {
                Row(horizontalArrangement = Arrangement.spacedBy(6.dp), verticalAlignment = Alignment.CenterVertically) {
                    Text(text = flag, fontSize = 16.sp)
                    Surface(
                        shape = RoundedCornerShape(6.dp),
                        color = LingoSecondary.copy(alpha = 0.12f)
                    ) {
                        Text(
                            text = vocab.language.uppercase(),
                            fontSize = 9.sp,
                            fontWeight = FontWeight.Bold,
                            color = LingoSecondary,
                            modifier = Modifier.padding(horizontal = 6.dp, vertical = 2.dp)
                        )
                    }
                    
                    // Mastery Level Indicator
                    val levelLabel = when (vocab.masteryLevel) {
                        0 -> "Nowy 🌱"
                        1 -> "W nauce 📈"
                        else -> "Opanowany 🏆"
                    }
                    val levelColor = when (vocab.masteryLevel) {
                        0 -> Color.Gray
                        1 -> LingoSecondary
                        else -> LingoSuccessGreen
                    }
                    Surface(
                        shape = RoundedCornerShape(6.dp),
                        color = levelColor.copy(alpha = 0.12f)
                    ) {
                        Text(
                            text = levelLabel,
                            fontSize = 9.sp,
                            fontWeight = FontWeight.Bold,
                            color = levelColor,
                            modifier = Modifier.padding(horizontal = 6.dp, vertical = 2.dp)
                        )
                    }
                }
                
                Row(
                    horizontalArrangement = Arrangement.spacedBy(6.dp),
                    verticalAlignment = Alignment.CenterVertically
                ) {
                    // Show rating warning if review is overdue
                    val isOverdue = vocab.nextReviewTimestamp <= System.currentTimeMillis()
                    if (isOverdue && mnemonic != null) {
                        Surface(
                            shape = RoundedCornerShape(6.dp),
                            color = Color.Red.copy(alpha = 0.1f)
                        ) {
                            Text(
                                text = "POWTÓRKA ⏳",
                                fontSize = 8.sp,
                                fontWeight = FontWeight.Black,
                                color = Color.Red,
                                modifier = Modifier.padding(horizontal = 5.dp, vertical = 2.dp)
                            )
                        }
                    }
                    
                    // QUICK TRASH CAN BUTTON
                    IconButton(
                        onClick = {
                            viewModel.deleteVocabulary(vocab.id)
                            Toast.makeText(context, "Słówko trwale usunięte z bazy", Toast.LENGTH_SHORT).show()
                        },
                        modifier = Modifier.size(28.dp)
                    ) {
                        Icon(
                            imageVector = Icons.Default.Delete,
                            contentDescription = "Trwale usuń",
                            tint = Color.Red.copy(alpha = 0.7f),
                            modifier = Modifier.size(18.dp)
                        )
                    }
                }
            }
            
            Spacer(modifier = Modifier.height(12.dp))
            
            if (isGeneratingMnemonicGlobal && isGeneratingLocal) {
                // --- LOADING STATE WITH SCIENTIFIC TIP ---
                Column(
                    modifier = Modifier
                        .fillMaxWidth()
                        .padding(vertical = 16.dp),
                    horizontalAlignment = Alignment.CenterHorizontally,
                    verticalArrangement = Arrangement.spacedBy(12.dp)
                ) {
                    CircularProgressIndicator(color = LingoPrimary, modifier = Modifier.size(36.dp))
                    Text(
                        text = "AI tworzy Mnemobrazek...",
                        fontSize = 14.sp,
                        fontWeight = FontWeight.Bold,
                        color = LingoPrimary
                    )
                    
                    Surface(
                        modifier = Modifier.fillMaxWidth(),
                        shape = RoundedCornerShape(10.dp),
                        color = LingoPrimary.copy(alpha = 0.05f),
                        border = BorderStroke(1.dp, LingoPrimary.copy(alpha = 0.1f))
                    ) {
                        Column(modifier = Modifier.padding(10.dp)) {
                            Text(
                                text = "💡 FAKT NAUKOWY O PAMIĘCI:",
                                fontSize = 9.sp,
                                fontWeight = FontWeight.Bold,
                                color = LingoPrimary
                            )
                            Spacer(modifier = Modifier.height(4.dp))
                            Text(
                                text = memoryTip,
                                fontSize = 11.sp,
                                color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.8f),
                                lineHeight = 15.sp
                            )
                        }
                    }
                }
            } else if (mnemonic == null) {
                // --- NO MNEMONIC STATE ("Dry Word") ---
                Column(verticalArrangement = Arrangement.spacedBy(8.dp)) {
                    Row(
                        verticalAlignment = Alignment.CenterVertically,
                        horizontalArrangement = Arrangement.spacedBy(6.dp)
                    ) {
                        Text(text = flag, fontSize = 18.sp)
                        Text(
                            text = vocab.word,
                            fontSize = 20.sp,
                            fontWeight = FontWeight.Black,
                            color = MaterialTheme.colorScheme.onSurface
                        )
                    }
                    
                    Text(
                        text = "Suche tłumaczenie: 🇵🇱 ${vocab.translation}",
                        fontSize = 13.sp,
                        fontWeight = FontWeight.Medium,
                        color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.6f)
                    )
                    
                    // Context (if any)
                    if (vocab.sentenceContext.isNotBlank()) {
                        Surface(
                            modifier = Modifier.fillMaxWidth(),
                            shape = RoundedCornerShape(8.dp),
                            color = MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.5f)
                        ) {
                            Text(
                                text = "Context: ${vocab.sentenceContext}",
                                fontSize = 11.sp,
                                color = MaterialTheme.colorScheme.onSurfaceVariant,
                                modifier = Modifier.padding(8.dp)
                            )
                        }
                    }
                    
                    Spacer(modifier = Modifier.height(4.dp))
                    
                    // Prompt advice block
                    Surface(
                        modifier = Modifier.fillMaxWidth(),
                        shape = RoundedCornerShape(10.dp),
                        color = Color(0xFFFEF3C7), // Light yellow warning card
                        border = BorderStroke(1.dp, Color(0xFFFCD34D))
                    ) {
                        Row(
                            modifier = Modifier.padding(10.dp),
                            horizontalArrangement = Arrangement.spacedBy(8.dp)
                        ) {
                            Text("⚠️", fontSize = 16.sp)
                            Column {
                                Text(
                                    text = "Uczysz się suchego słówka! Mózg nie wie:",
                                    fontSize = 11.sp,
                                    fontWeight = FontWeight.Bold,
                                    color = Color(0xFF92400E)
                                )
                                Text(
                                    text = "• Kiedy słowa użyć ani w jakiej sytuacji się pojawia.\n• Jak odnaleźć je w pamięci bez silnego skojarzenia.",
                                    fontSize = 10.sp,
                                    color = Color(0xFFB45309)
                                )
                            }
                        }
                    }
                    
                    Spacer(modifier = Modifier.height(6.dp))
                    
                    // Generate button
                    Button(
                        onClick = {
                            isGeneratingLocal = true
                            viewModel.generateAndSaveRichMnemonic(vocab.word, vocab.language) { success ->
                                if (!success) {
                                    isGeneratingLocal = false
                                    Toast.makeText(context, "Generowanie nie powiodło się. Sprawdź klucz API w Secrets.", Toast.LENGTH_LONG).show()
                                }
                            }
                        },
                        modifier = Modifier.fillMaxWidth(),
                        shape = RoundedCornerShape(10.dp),
                        colors = ButtonDefaults.buttonColors(containerColor = LingoPrimary)
                    ) {
                        Icon(imageVector = Icons.Default.Lightbulb, contentDescription = null, modifier = Modifier.size(16.dp))
                        Spacer(modifier = Modifier.width(6.dp))
                        Text("Generuj Mnemobrazek AI (PRO)", fontSize = 12.sp)
                    }
                }
            } else {
                // --- MNEMONIC EXISTS STATE ---
                if (!isFlipped) {
                    // --- CARD FRONT (ACTIVE RECALL TESTING) ---
                    Column(
                        horizontalAlignment = Alignment.CenterHorizontally,
                        verticalArrangement = Arrangement.spacedBy(12.dp),
                        modifier = Modifier.fillMaxWidth()
                    ) {
                        Text(
                            text = "Recall Challenge!",
                            fontSize = 10.sp,
                            fontWeight = FontWeight.Bold,
                            color = LingoSecondary
                        )
                        
                        Row(
                            verticalAlignment = Alignment.CenterVertically,
                            horizontalArrangement = Arrangement.Center,
                            modifier = Modifier.fillMaxWidth()
                        ) {
                            Text(
                                text = vocab.word,
                                fontSize = 24.sp,
                                fontWeight = FontWeight.Black,
                                color = LingoPrimary,
                                textAlign = TextAlign.Center,
                                modifier = Modifier.weight(1f, fill = false)
                            )
                            Spacer(modifier = Modifier.width(6.dp))
                            IconButton(
                                onClick = { speechHelper.speak(vocab.word, vocab.language, "B1") },
                                modifier = Modifier.size(36.dp)
                            ) {
                                Icon(
                                    imageVector = Icons.Default.VolumeUp,
                                    contentDescription = "Odsłuchaj",
                                    tint = LingoPrimary,
                                    modifier = Modifier.size(20.dp)
                                )
                            }
                        }
                        
                        // Active testing Cloze sentence context!
                        val clozeSentence = remember(vocab.sentenceContext, vocab.word) {
                            if (vocab.sentenceContext.isBlank()) "Brak kontekstu"
                            else {
                                // Replace vocab.word (case-insensitive) with a blank slot [ ______ ]
                                val regex = "(?i)\\b${Regex.escape(vocab.word)}\\b".toRegex()
                                if (vocab.sentenceContext.contains(regex)) {
                                    vocab.sentenceContext.replace(regex, "[ ______ ]")
                                } else {
                                    // Fallback replacement of any occurrence
                                    vocab.sentenceContext.replace(vocab.word, "[ ______ ]", ignoreCase = true)
                                }
                            }
                        }
                        
                        if (clozeSentence != "Brak kontekstu") {
                            Surface(
                                shape = RoundedCornerShape(12.dp),
                                color = MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.5f),
                                modifier = Modifier.fillMaxWidth()
                            ) {
                                Column(modifier = Modifier.padding(12.dp), horizontalAlignment = Alignment.CenterHorizontally) {
                                    Text(
                                        text = "Uzupełnij lukę w zdaniu:",
                                        fontSize = 10.sp,
                                        fontWeight = FontWeight.Bold,
                                        color = MaterialTheme.colorScheme.onSurfaceVariant.copy(alpha = 0.7f)
                                    )
                                    Spacer(modifier = Modifier.height(4.dp))
                                    Text(
                                        text = clozeSentence,
                                        fontSize = 13.sp,
                                        fontStyle = FontStyle.Italic,
                                        color = MaterialTheme.colorScheme.onSurface,
                                        textAlign = TextAlign.Center,
                                        lineHeight = 18.sp
                                    )
                                }
                            }
                        }
                        
                        // Show visual scene hints (emojis) if available to trigger recall!
                        val hintEmojis = richMnemonic?.emojis ?: "🧠"
                        Text(
                            text = "Wizualny impuls: $hintEmojis",
                            fontSize = 14.sp,
                            color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.5f)
                        )
                        
                        Spacer(modifier = Modifier.height(4.dp))
                        
                        Button(
                            onClick = {
                                recallLatencyMs = System.currentTimeMillis() - cardStartTime
                                isFlipped = true
                            },
                            modifier = Modifier.fillMaxWidth(),
                            shape = RoundedCornerShape(10.dp),
                            colors = ButtonDefaults.buttonColors(containerColor = LingoPrimary)
                        ) {
                            Icon(imageVector = Icons.Default.Visibility, contentDescription = null, modifier = Modifier.size(16.dp))
                            Spacer(modifier = Modifier.width(6.dp))
                            Text("Pokaż odpowiedź & Mnemobrazek", fontSize = 12.sp)
                        }
                    }
                } else {
                    // --- CARD BACK (REVEALED DETAILED MNEMO-CARD) ---
                    Column(verticalArrangement = Arrangement.spacedBy(12.dp)) {
                        // Word and translation header
                        Row(
                            modifier = Modifier.fillMaxWidth(),
                            horizontalArrangement = Arrangement.SpaceBetween,
                            verticalAlignment = Alignment.CenterVertically
                        ) {
                            Column(modifier = Modifier.weight(1f)) {
                                Row(
                                    verticalAlignment = Alignment.CenterVertically,
                                    horizontalArrangement = Arrangement.spacedBy(4.dp)
                                ) {
                                    Text(
                                        text = vocab.word,
                                        fontSize = 22.sp,
                                        fontWeight = FontWeight.Black,
                                        color = LingoPrimary,
                                        modifier = Modifier.weight(1f, fill = false)
                                    )
                                    IconButton(
                                        onClick = { speechHelper.speak(vocab.word, vocab.language, "B1") },
                                        modifier = Modifier.size(32.dp)
                                    ) {
                                        Icon(
                                            imageVector = Icons.Default.VolumeUp,
                                            contentDescription = "Odsłuchaj",
                                            tint = LingoPrimary,
                                            modifier = Modifier.size(18.dp)
                                        )
                                    }
                                }
                                Text(
                                    text = "🇵🇱 ${vocab.translation}",
                                    fontSize = 16.sp,
                                    fontWeight = FontWeight.Bold,
                                    color = LingoSuccessGreen
                                )
                            }
                            
                            IconButton(onClick = { isFlipped = false }, modifier = Modifier.size(28.dp)) {
                                Icon(imageVector = Icons.Default.Close, contentDescription = "Zwiń", tint = Color.Gray)
                            }
                        }

                        // Fluency Latency Engine Badge (Inteligentny Zegar Decyzji Neuronowej)
                        val latencySec = remember(recallLatencyMs) {
                            val sec = recallLatencyMs / 1000.0
                            String.format("%.1f", if (sec < 0.1) 0.1 else sec)
                        }
                        val latencyBadgeColor = when {
                            recallLatencyMs < 2000 -> Color(0xFF059669) // Emerald Green
                            recallLatencyMs in 2000..4500 -> Color(0xFFD97706) // Amber
                            else -> Color(0xFFDC2626) // Red
                        }
                        val latencyBadgeBg = when {
                            recallLatencyMs < 2000 -> Color(0xFFD1FAE5)
                            recallLatencyMs in 2000..4500 -> Color(0xFFFEF3C7)
                            else -> Color(0xFFFEE2E2)
                        }
                        val latencyLabel = when {
                            recallLatencyMs < 2000 -> "⚡ ${latencySec}s — Odruch neuronowy! (Płynny retrieval)"
                            recallLatencyMs in 2000..4500 -> "⏱️ ${latencySec}s — Płynny namysł (Ślad stabilny)"
                            else -> "🐢 ${latencySec}s — Wahanie kognitywne! (Algorytm SRS wzmocni powtórkę)"
                        }

                        Surface(
                            modifier = Modifier.fillMaxWidth(),
                            shape = RoundedCornerShape(8.dp),
                            color = latencyBadgeBg,
                            border = BorderStroke(1.dp, latencyBadgeColor.copy(alpha = 0.4f))
                        ) {
                            Row(
                                modifier = Modifier.padding(horizontal = 10.dp, vertical = 6.dp),
                                verticalAlignment = Alignment.CenterVertically,
                                horizontalArrangement = Arrangement.SpaceBetween
                            ) {
                                Text(
                                    text = "⚡ LATENCY ENGINE",
                                    fontSize = 9.sp,
                                    fontWeight = FontWeight.Black,
                                    color = latencyBadgeColor
                                )
                                Text(
                                    text = latencyLabel,
                                    fontSize = 10.5.sp,
                                    fontWeight = FontWeight.Bold,
                                    color = latencyBadgeColor
                                )
                            }
                        }
                        
                        Divider(color = MaterialTheme.colorScheme.outlineVariant.copy(alpha = 0.4f))
                        
                        if (richMnemonic != null) {
                            // --- PARSED RICH AI MNEMONIC LAYOUT ---
                            
                            // 1. Mnemobrazek (Large emojis + descriptive image prompt text)
                            Card(
                                modifier = Modifier.fillMaxWidth(),
                                shape = RoundedCornerShape(12.dp),
                                colors = CardDefaults.cardColors(containerColor = LingoPrimary.copy(alpha = 0.05f)),
                                border = BorderStroke(1.dp, LingoPrimary.copy(alpha = 0.12f))
                            ) {
                                Column(
                                    modifier = Modifier.padding(12.dp),
                                    horizontalAlignment = Alignment.CenterHorizontally
                                ) {
                                    // Huge emojis block
                                    Text(
                                        text = richMnemonic.emojis,
                                        fontSize = 32.sp,
                                        letterSpacing = 8.sp,
                                        modifier = Modifier.padding(bottom = 6.dp)
                                    )
                                    
                                    Text(
