sealed class MarkdownElement {
    data class Header(val level: Int, val text: String) : MarkdownElement()
    data class Paragraph(val text: String) : MarkdownElement()
    data class Quote(val text: String) : MarkdownElement()
    data class ListItem(val text: String) : MarkdownElement()
    data class Table(val rows: List<List<String>>) : MarkdownElement()
}

@Composable
fun MarkdownContent(
    text: String,
    modifier: Modifier = Modifier,
    onAddVocab: ((String, String, String) -> Unit)? = null
) {
    val lines = text.split("\n")
    val elements = remember(text) {
        val parsedElements = mutableListOf<MarkdownElement>()
        var currentTableRows = mutableListOf<List<String>>()
        var inTable = false

        for (line in lines) {
            val trimmed = line.trim()
            if (trimmed.startsWith("|")) {
                inTable = true
                val cells = trimmed.split("|").map { it.trim() }.filterIndexed { index, _ ->
                    index > 0 && index < trimmed.split("|").lastIndex
                }
                if (cells.isNotEmpty() && !cells.any { it.contains("---") }) {
                    currentTableRows.add(cells)
                }
            } else {
                if (inTable) {
                    if (currentTableRows.isNotEmpty()) {
                        parsedElements.add(MarkdownElement.Table(currentTableRows.toList()))
                        currentTableRows = mutableListOf()
                    }
                    inTable = false
                }
                if (trimmed.isEmpty()) continue
                if (trimmed.startsWith("## ")) {
                    parsedElements.add(MarkdownElement.Header(2, trimmed.removePrefix("## ")))
                } else if (trimmed.startsWith("### ")) {
                    parsedElements.add(MarkdownElement.Header(3, trimmed.removePrefix("### ")))
                } else if (trimmed.startsWith("- ") || trimmed.startsWith("* ")) {
                    parsedElements.add(MarkdownElement.ListItem(trimmed.substring(2)))
                } else if (trimmed.startsWith(">")) {
                    parsedElements.add(MarkdownElement.Quote(trimmed.removePrefix(">").trim()))
                } else {
                    parsedElements.add(MarkdownElement.Paragraph(trimmed))
                }
            }
        }
        if (inTable && currentTableRows.isNotEmpty()) {
            parsedElements.add(MarkdownElement.Table(currentTableRows.toList()))
        }
        parsedElements
    }

    Column(
        modifier = modifier.fillMaxWidth(),
        verticalArrangement = Arrangement.spacedBy(8.dp)
    ) {
        elements.forEach { element ->
            when (element) {
                is MarkdownElement.Header -> {
                    if (element.level == 2) {
                        Spacer(modifier = Modifier.height(12.dp))
                        Text(
                            text = element.text,
                            style = MaterialTheme.typography.titleLarge,
                            fontWeight = FontWeight.Bold,
                            color = LingoPrimary,
                            fontSize = 18.sp
                        )
                        Divider(color = LingoPrimary.copy(alpha = 0.3f), modifier = Modifier.padding(top = 4.dp, bottom = 8.dp))
                    } else {
                        Spacer(modifier = Modifier.height(8.dp))
                        val indicatorEmoji = when {
                            element.text.contains("Tło") || element.text.contains("Kontekst") -> "🏰"
                            element.text.contains("Cel") -> "🎯"
                            element.text.contains("Sytuacja") || element.text.contains("Tekst") -> "📖"
                            element.text.contains("Słownict") || element.text.contains("Analiz") -> "✍️"
                            element.text.contains("Zadani") -> "🧩"
                            else -> "⚡"
                        }
                        Text(
                            text = "$indicatorEmoji ${element.text}",
                            style = MaterialTheme.typography.titleMedium,
                            fontWeight = FontWeight.Bold,
                            color = LingoSecondary,
                            fontSize = 15.sp
                        )
                    }
                }
                is MarkdownElement.Paragraph -> {
                    Text(
                        text = element.text,
                        fontSize = 13.sp,
                        lineHeight = 18.sp,
                        color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.8f)
                    )
                }
                is MarkdownElement.Quote -> {
                    Card(
                        modifier = Modifier.fillMaxWidth().padding(vertical = 4.dp),
                        colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.primaryContainer.copy(alpha = 0.2f)),
                        border = BorderStroke(1.dp, LingoPrimary.copy(alpha = 0.2f))
                    ) {
                        Text(
                            text = element.text,
                            fontSize = 13.sp,
                            fontStyle = FontStyle.Italic,
                            lineHeight = 18.sp,
                            color = MaterialTheme.colorScheme.onSurface,
                            modifier = Modifier.padding(12.dp)
                        )
                    }
                }
                is MarkdownElement.ListItem -> {
                    Row(
                        modifier = Modifier.padding(start = 8.dp, top = 2.dp, bottom = 2.dp),
                        verticalAlignment = Alignment.Top
                    ) {
                        Text("• ", fontSize = 14.sp, fontWeight = FontWeight.Bold, color = LingoPrimary)
                        Text(
                            text = element.text,
                            fontSize = 13.sp,
                            lineHeight = 18.sp,
                            color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.85f)
                        )
                    }
                }
                is MarkdownElement.Table -> {
                    Card(
                        modifier = Modifier.fillMaxWidth().padding(vertical = 8.dp),
                        colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surface),
                        border = BorderStroke(1.dp, MaterialTheme.colorScheme.outlineVariant.copy(alpha = 0.5f))
                    ) {
                        Column {
                            element.rows.forEachIndexed { rowIndex, cells ->
                                val isHeader = rowIndex == 0
                                Row(
                                    modifier = Modifier
                                        .fillMaxWidth()
                                        .background(
                                            if (isHeader) MaterialTheme.colorScheme.primaryContainer.copy(alpha = 0.4f)
                                            else if (rowIndex % 2 == 0) MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.1f)
                                            else Color.Transparent
                                        )
                                        .padding(8.dp),
                                    horizontalArrangement = Arrangement.SpaceBetween
                                ) {
                                    cells.forEachIndexed { cellIndex, cell ->
                                        val cellText = cell.trim()
                                        val weight = when (cellIndex) {
                                            0 -> 0.22f
                                            1 -> 0.22f
                                            2 -> 0.22f
                                            else -> 0.34f
                                        }
                                        Box(
                                            modifier = Modifier.weight(weight).padding(horizontal = 4.dp)
                                        ) {
                                            Text(
                                                text = cellText,
                                                fontWeight = if (isHeader) FontWeight.Bold else if (cellIndex == 0) FontWeight.Bold else FontWeight.Normal,
                                                fontSize = if (isHeader) 11.sp else 12.sp,
                                                color = if (cellIndex == 0 && !isHeader) LingoPrimary else MaterialTheme.colorScheme.onSurface
                                            )
                                        }
                                    }
                                }
                                if (rowIndex < element.rows.size - 1) {
                                    Divider(color = MaterialTheme.colorScheme.outlineVariant.copy(alpha = 0.4f))
                                }
                            }
                        }
                    }
                    if (onAddVocab != null && element.rows.size > 1) {
                        Spacer(modifier = Modifier.height(4.dp))
                        Button(
                            onClick = {
                                element.rows.drop(1).forEach { cells ->
                                    if (cells.size >= 2) {
                                        val word = cells[0].trim().replace("`", "").replace("**", "")
                                        val trans = cells[1].trim()
                                        val expl = if (cells.size >= 4) cells[3].trim() else ""
                                        if (word.isNotBlank() && trans.isNotBlank() && !word.startsWith("-")) {
                                            onAddVocab(word, trans, expl)
                                        }
                                    }
                                }
                            },
                            colors = ButtonDefaults.buttonColors(containerColor = LingoSecondary),
                            shape = RoundedCornerShape(12.dp),
                            modifier = Modifier.fillMaxWidth()
                        ) {
                            Icon(Icons.Default.Book, contentDescription = null, modifier = Modifier.size(16.dp))
                            Spacer(modifier = Modifier.width(8.dp))
                            Text("Pobierz słownictwo z tabeli do bazy 📚", fontSize = 12.sp, fontWeight = FontWeight.Bold)
                        }
                    }
                }
            }
        }
    }
}

@Composable
fun ShadowingSection(
    viewModel: TutorViewModel,
    speechHelper: TutorSpeechHelper,
    vocabulary: List<Vocabulary>,
    mistakes: List<Mistake>
) {
    val context = LocalContext.current
    val coroutineScope = rememberCoroutineScope()
    
    // Select state: vocabulary or mistakes
    var mode by remember { mutableStateOf("vocab") } // "vocab" or "mistakes"
    
    // Currently active/practicing card item
    var activeSentence by remember { mutableStateOf<String?>(null) }
    var activeTranslation by remember { mutableStateOf("") }
    var activeLanguage by remember { mutableStateOf("") }
    
    // AI tips state
    var aiTip by remember { mutableStateOf<String?>(null) }
    var isGeneratingTip by remember { mutableStateOf(false) }
    
    // Speech recognizer state
    var recognizedText by remember { mutableStateOf<String?>(null) }
    var speechRecognizerError by remember { mutableStateOf<String?>(null) }
    
    // We instantiate speech recognizer
    val speechRecognizer = remember {
        TutorSpeechRecognizer(
            context = context,
            onResults = { result ->
                recognizedText = result
                speechRecognizerError = null
            },
            onErrorCallback = { errorMsg, _ ->
                speechRecognizerError = errorMsg
            }
        )
    }
    
    DisposableEffect(Unit) {
        onDispose {
            speechRecognizer.shutdown()
        }
    }
    
    Column(
        modifier = Modifier
            .fillMaxWidth()
            .padding(16.dp),
        verticalArrangement = Arrangement.spacedBy(16.dp)
    ) {
        if (activeSentence == null) {
            // Mode selector (Słówka / Moje Błędy)
            Row(
                modifier = Modifier.fillMaxWidth(),
                horizontalArrangement = Arrangement.spacedBy(8.dp)
            ) {
                Button(
                    onClick = { mode = "vocab" },
                    colors = ButtonDefaults.buttonColors(
                        containerColor = if (mode == "vocab") LingoPrimary else MaterialTheme.colorScheme.surfaceVariant,
                        contentColor = if (mode == "vocab") Color.White else MaterialTheme.colorScheme.onSurfaceVariant
                    ),
                    modifier = Modifier.weight(1f).height(48.dp),
                    shape = RoundedCornerShape(12.dp)
                ) {
                    Icon(Icons.Default.Book, contentDescription = null, modifier = Modifier.size(18.dp))
                    Spacer(modifier = Modifier.width(6.dp))
                    Text("Moje Słówka 📚", fontWeight = FontWeight.Bold)
                }
                
                Button(
                    onClick = { mode = "mistakes" },
                    colors = ButtonDefaults.buttonColors(
                        containerColor = if (mode == "mistakes") LingoPrimary else MaterialTheme.colorScheme.surfaceVariant,
                        contentColor = if (mode == "mistakes") Color.White else MaterialTheme.colorScheme.onSurfaceVariant
                    ),
                    modifier = Modifier.weight(1f).height(48.dp),
                    shape = RoundedCornerShape(12.dp)
                ) {
                    Icon(Icons.Default.Error, contentDescription = null, modifier = Modifier.size(18.dp))
                    Spacer(modifier = Modifier.width(6.dp))
                    Text("Moje Błędy ⚠️", fontWeight = FontWeight.Bold)
                }
            }
            
            // List of items
            if (mode == "vocab") {
                val vocabList = vocabulary.filter { it.word.isNotBlank() }
                if (vocabList.isEmpty()) {
                    Box(
                        modifier = Modifier
                            .fillMaxWidth()
                            .padding(vertical = 40.dp),
                        contentAlignment = Alignment.Center
                    ) {
                        Column(
                            horizontalAlignment = Alignment.CenterHorizontally,
                            verticalArrangement = Arrangement.spacedBy(8.dp)
                        ) {
                            Text("📚", fontSize = 48.sp)
                            Text(
                                "Brak słówek w bazie.",
                                fontWeight = FontWeight.Bold,
                                color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.6f)
                            )
                            Text(
                                "Rozmawiaj na czacie lub dodaj słówka ręcznie, aby poćwiczyć ich wymowę!",
                                fontSize = 12.sp,
                                textAlign = TextAlign.Center,
                                color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.5f)
                            )
                        }
                    }
                } else {
                    LazyColumn(
                        modifier = Modifier
                            .fillMaxWidth()
                            .heightIn(max = 400.dp),
                        verticalArrangement = Arrangement.spacedBy(8.dp)
                    ) {
                        items(vocabList.size) { index ->
                            val vocab = vocabList[index]
                            val textToShadow = if (vocab.sentenceContext.isNotBlank()) vocab.sentenceContext else vocab.word
                            val translationToShadow = if (vocab.polishContextTranslation.isNotBlank()) vocab.polishContextTranslation else vocab.translation
                            
                            Card(
                                modifier = Modifier
                                    .fillMaxWidth()
                                    .clickable {
                                        activeSentence = textToShadow
                                        activeTranslation = translationToShadow
                                        activeLanguage = vocab.language
                                        aiTip = null
                                        recognizedText = null
                                        speechRecognizerError = null
                                    },
                                colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surface),
                                border = BorderStroke(1.dp, MaterialTheme.colorScheme.outlineVariant.copy(alpha = 0.5f))
                            ) {
                                Row(
                                    modifier = Modifier
                                        .fillMaxWidth()
                                        .padding(16.dp),
                                    horizontalArrangement = Arrangement.SpaceBetween,
                                    verticalAlignment = Alignment.CenterVertically
                                ) {
                                    Column(modifier = Modifier.weight(1f)) {
                                        Text(
                                            text = textToShadow,
                                            fontWeight = FontWeight.Bold,
                                            fontSize = 15.sp,
                                            color = MaterialTheme.colorScheme.onSurface
                                        )
                                        Spacer(modifier = Modifier.height(4.dp))
                                        Text(
                                            text = translationToShadow,
                                            fontSize = 13.sp,
                                            color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.6f)
                                        )
                                    }
                                    
                                    Row(verticalAlignment = Alignment.CenterVertically) {
                                        IconButton(
                                            onClick = { viewModel.deleteVocabulary(vocab.id) }
                                        ) {
                                            Icon(
                                                imageVector = Icons.Default.Delete,
                                                contentDescription = "Usuń słówko",
                                                tint = MaterialTheme.colorScheme.error.copy(alpha = 0.7f)
                                            )
                                        }
                                        Icon(
                                            imageVector = Icons.Default.PlayArrow,
                                            contentDescription = "Trenuj",
                                            tint = LingoPrimary,
                                            modifier = Modifier.size(24.dp)
                                        )
                                    }
                                }
                            }
                        }
                    }
                }
            } else {
                // Mistakes mode
                // Focus ONLY on the correctedSentence, as required by the rules.
                val mistakesList = mistakes.filter { it.correctedSentence.isNotBlank() }
                if (mistakesList.isEmpty()) {
                    Box(
                        modifier = Modifier
                            .fillMaxWidth()
                            .padding(vertical = 40.dp),
                        contentAlignment = Alignment.Center
                    ) {
                        Column(
                            horizontalAlignment = Alignment.CenterHorizontally,
                            verticalArrangement = Arrangement.spacedBy(8.dp)
                        ) {
                            Text("✨", fontSize = 48.sp)
                            Text(
                                "Brak błędów do przećwiczenia!",
                                fontWeight = FontWeight.Bold,
                                color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.6f)
                            )
                            Text(
                                "Kiedy popełnisz błąd w rozmowie, poprawna wersja trafi tutaj automatycznie.",
                                fontSize = 12.sp,
                                textAlign = TextAlign.Center,
                                color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.5f)
                            )
                        }
                    }
                } else {
                    LazyColumn(
                        modifier = Modifier
                            .fillMaxWidth()
                            .heightIn(max = 400.dp),
                        verticalArrangement = Arrangement.spacedBy(8.dp)
                    ) {
                        items(mistakesList.size) { index ->
                            val mistake = mistakesList[index]
                            
                            Card(
                                modifier = Modifier
                                    .fillMaxWidth()
                                    .clickable {
                                        activeSentence = mistake.correctedSentence
                                        activeTranslation = mistake.explanation
                                        activeLanguage = viewModel.goal.value?.targetLanguage ?: "Spanish"
                                        aiTip = null
                                        recognizedText = null
                                        speechRecognizerError = null
                                    },
                                colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surface),
                                border = BorderStroke(1.dp, MaterialTheme.colorScheme.outlineVariant.copy(alpha = 0.5f))
                            ) {
                                Row(
                                    modifier = Modifier
                                        .fillMaxWidth()
                                        .padding(16.dp),
                                    horizontalArrangement = Arrangement.SpaceBetween,
                                    verticalAlignment = Alignment.CenterVertically
                                ) {
                                    Column(modifier = Modifier.weight(1f)) {
                                        Text(
                                            text = mistake.correctedSentence,
                                            fontWeight = FontWeight.Bold,
                                            fontSize = 15.sp,
                                            color = MaterialTheme.colorScheme.onSurface
                                        )
                                        Spacer(modifier = Modifier.height(4.dp))
                                        Text(
                                            text = mistake.explanation,
                                            fontSize = 13.sp,
                                            color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.6f),
                                            maxLines = 2,
                                            overflow = TextOverflow.Ellipsis
                                        )
                                    }
                                    
                                    Row(verticalAlignment = Alignment.CenterVertically) {
                                        IconButton(
                                            onClick = { viewModel.deleteMistake(mistake.id) }
                                        ) {
                                            Icon(
                                                imageVector = Icons.Default.Delete,
                                                contentDescription = "Usuń błąd",
                                                tint = MaterialTheme.colorScheme.error.copy(alpha = 0.7f)
                                            )
                                        }
                                        Icon(
                                            imageVector = Icons.Default.PlayArrow,
                                            contentDescription = "Trenuj",
                                            tint = LingoPrimary,
                                            modifier = Modifier.size(24.dp)
                                        )
                                    }
                                }
                            }
                        }
                    }
                }
            }
        } else {
            // Shadowing Practice Card view
            val sentence = activeSentence!!
            val translation = activeTranslation
            val language = activeLanguage
            
            // Back button
            Row(
                modifier = Modifier.fillMaxWidth(),
                verticalAlignment = Alignment.CenterVertically
            ) {
                IconButton(
                    onClick = {
                        activeSentence = null
                        aiTip = null
                        recognizedText = null
                        speechRecognizerError = null
                        speechRecognizer.stop()
                    }
                ) {
                    Icon(Icons.Default.ArrowBack, contentDescription = "Wróć")
                }
                Text("Wróć do listy", fontWeight = FontWeight.Bold, fontSize = 16.sp)
            }
            
            // Active sentence practice card
            Card(
                modifier = Modifier.fillMaxWidth(),
                colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.3f)),
                shape = RoundedCornerShape(16.dp),
                border = BorderStroke(1.dp, MaterialTheme.colorScheme.outlineVariant.copy(alpha = 0.4f))
            ) {
                Column(
                    modifier = Modifier
                        .fillMaxWidth()
                        .padding(20.dp),
                    horizontalAlignment = Alignment.CenterHorizontally,
                    verticalArrangement = Arrangement.spacedBy(16.dp)
                ) {
                    Text(
                        "POĆWICZ WYMOWĘ (SHADOWING) 🗣️",
                        fontSize = 12.sp,
                        fontWeight = FontWeight.Bold,
                        color = LingoPrimary,
                        letterSpacing = 1.2.sp
                    )
                    
                    // Foreign Sentence
                    Text(
                        text = sentence,
                        fontSize = 20.sp,
                        fontWeight = FontWeight.Bold,
                        textAlign = TextAlign.Center,
                        color = MaterialTheme.colorScheme.onSurface,
                        lineHeight = 26.sp
                    )
                    
                    // Translation
                    Text(
                        text = translation,
                        fontSize = 14.sp,
                        textAlign = TextAlign.Center,
                        color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.7f),
                        lineHeight = 18.sp
                    )
                    
                    // Controls Row (Odsłuchaj / Porada AI)
                    Row(
                        horizontalArrangement = Arrangement.spacedBy(12.dp),
                        verticalAlignment = Alignment.CenterVertically
                    ) {
                        Button(
                            onClick = {
                                speechHelper.speak(sentence, language, "B2", customSpeechRate = 0.75f)
                            },
                            colors = ButtonDefaults.buttonColors(containerColor = LingoPrimary),
                            shape = RoundedCornerShape(12.dp)
                        ) {
                            Icon(Icons.Default.VolumeUp, contentDescription = "Słuchaj", modifier = Modifier.size(18.dp))
                            Spacer(modifier = Modifier.width(6.dp))
                            Text("Odsłuchaj 🔊", fontSize = 13.sp, fontWeight = FontWeight.Bold)
                        }
                        
                        Button(
                            onClick = {
                                if (!isGeneratingTip) {
                                    isGeneratingTip = true
                                    aiTip = null
                                    coroutineScope.launch {
                                        try {
                                            val tip = viewModel.getPronunciationTip(sentence, language)
                                            aiTip = tip
                                        } catch (e: Exception) {
                                            aiTip = "Nie udało się pobrać wskazówek."
                                        } finally {
                                            isGeneratingTip = false
                                        }
                                    }
                                }
                            },
                            enabled = !isGeneratingTip,
                            colors = ButtonDefaults.buttonColors(containerColor = LingoSecondary),
                            shape = RoundedCornerShape(12.dp)
                        ) {
                            if (isGeneratingTip) {
                                CircularProgressIndicator(modifier = Modifier.size(16.dp), color = Color.White, strokeWidth = 2.dp)
                                Spacer(modifier = Modifier.width(6.dp))
                                Text("Analiza...", fontSize = 13.sp)
                            } else {
                                Icon(Icons.Default.Lightbulb, contentDescription = "Wskazówki", modifier = Modifier.size(18.dp))
                                Spacer(modifier = Modifier.width(6.dp))
                                Text("Wskazówki AI ✨", fontSize = 13.sp, fontWeight = FontWeight.Bold)
                            }
                        }
                    }
                    
                    // Display AI tips if generated
                    aiTip?.let { tip ->
                        Card(
                            colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.primaryContainer.copy(alpha = 0.15f)),
                            shape = RoundedCornerShape(12.dp),
                            modifier = Modifier.fillMaxWidth()
                        ) {
                            Column(modifier = Modifier.padding(12.dp)) {
                                Text(
                                    "Porada od trenera wymowy:",
                                    fontWeight = FontWeight.Bold,
                                    fontSize = 12.sp,
                                    color = LingoPrimary
                                )
                                Spacer(modifier = Modifier.height(4.dp))
                                Text(
                                    text = tip,
                                    fontSize = 13.sp,
                                    lineHeight = 18.sp,
                                    color = MaterialTheme.colorScheme.onSurface
                                )
                            }
                        }
                    }
                }
            }
            
            // Microphone Practice Card
            Card(
                modifier = Modifier.fillMaxWidth(),
                colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surface),
                shape = RoundedCornerShape(16.dp),
                border = BorderStroke(1.dp, MaterialTheme.colorScheme.outlineVariant.copy(alpha = 0.5f))
            ) {
                Column(
                    modifier = Modifier
                        .fillMaxWidth()
                        .padding(20.dp),
                    horizontalAlignment = Alignment.CenterHorizontally,
                    verticalArrangement = Arrangement.spacedBy(16.dp)
                ) {
                    Text(
                        "TWOJA PRÓBA 🎤",
                        fontSize = 12.sp,
                        fontWeight = FontWeight.Bold,
                        color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.6f),
                        letterSpacing = 1.2.sp
                    )
                    
                    // State feedback / RMS wave
                    if (speechRecognizer.isListening) {
                        Column(
                            horizontalAlignment = Alignment.CenterHorizontally,
                            verticalArrangement = Arrangement.spacedBy(8.dp)
                        ) {
                            Text("Słucham... powtórz zdanie powyżej!", fontSize = 13.sp, fontStyle = FontStyle.Italic, color = LingoPrimary)
                            
                            val rmsValue = speechRecognizer.rmsLevel
                            val animScale = animateFloatAsState(
                                targetValue = (rmsValue + 2f).coerceIn(1f, 15f),
                                animationSpec = spring(stiffness = Spring.StiffnessLow),
                                label = "rms"
                            )
                            
                            Row(
                                modifier = Modifier.height(30.dp),
                                horizontalArrangement = Arrangement.spacedBy(4.dp),
                                verticalAlignment = Alignment.CenterVertically
                            ) {
                                repeat(5) { i ->
                                    val heightFactor = when (i) {
                                        0, 4 -> 0.4f
                                        1, 3 -> 0.7f
                                        else -> 1.0f
                                    }
                                    Box(
                                        modifier = Modifier
                                            .width(4.dp)
                                            .height((animScale.value * 2 * heightFactor).dp.coerceAtLeast(4.dp))
                                            .background(LingoPrimary, RoundedCornerShape(2.dp))
                                    )
                                }
                            }
                        }
                    } else {
                        Text(
                            text = "Naciśnij przycisk poniżej, aby zacząć mówić.",
                            fontSize = 12.sp,
                            textAlign = TextAlign.Center,
                            color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.5f)
                        )
                    }
                    
                    // Big Recording Button
                    val isListeningState = speechRecognizer.isListening
                    Button(
                        onClick = {
                            if (isListeningState) {
                                speechRecognizer.stop()
                            } else {
                                recognizedText = null
                                speechRecognizerError = null
                                val code = when (language.lowercase()) {
                                    "spanish", "hiszpański" -> "es-ES"
                                    "german", "niemiecki" -> "de-DE"
                                    "french", "francuski" -> "fr-FR"
                                    "malaga" -> "es-ES"
                                    else -> "es-ES"
                                }
                                speechRecognizer.startListening(code)
                            }
                        },
                        colors = ButtonDefaults.buttonColors(
                            containerColor = if (isListeningState) Color.Red else LingoPrimary
                        ),
                        modifier = Modifier.size(72.dp),
                        shape = CircleShape,
                        contentPadding = PaddingValues(0.dp)
                    ) {
                        Icon(
                            imageVector = if (isListeningState) Icons.Default.Stop else Icons.Default.Mic,
                            contentDescription = if (isListeningState) "Zatrzymaj" else "Nagraj",
                            tint = Color.White,
                            modifier = Modifier.size(36.dp)
                        )
                    }
                    
                    // Display Recognized Text and Similarity Analysis
                    recognizedText?.let { heard ->
                        Divider(modifier = Modifier.padding(vertical = 8.dp))
                        
                        val cleanedHeard = heard.lowercase().replace(Regex("[^a-zA-Z0-9ąęćłńóśźżäöüßñíóúáé]"), "")
                        val cleanedTarget = sentence.lowercase().replace(Regex("[^a-zA-Z0-9ąęćłńóśźżäöüßñíóúáé]"), "")
                        
                        val heardTokens = cleanedHeard.chunked(1).toSet()
                        val targetTokens = cleanedTarget.chunked(1).toSet()
                        val intersection = heardTokens.intersect(targetTokens).size
                        val union = heardTokens.union(targetTokens).size
                        val score = if (union > 0) ((intersection.toFloat() / union.toFloat()) * 100).toInt() else 0
                        
                        Column(
                            horizontalAlignment = Alignment.CenterHorizontally,
                            verticalArrangement = Arrangement.spacedBy(8.dp),
                            modifier = Modifier.fillMaxWidth()
                        ) {
                            Text(
                                "USŁYSZAŁEM:",
                                fontWeight = FontWeight.Bold,
                                fontSize = 11.sp,
                                color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.5f)
                            )
                            Text(
                                text = heard,
                                fontSize = 16.sp,
                                fontWeight = FontWeight.SemiBold,
                                color = MaterialTheme.colorScheme.onSurface,
                                textAlign = TextAlign.Center
                            )
                            
                            Row(
                                verticalAlignment = Alignment.CenterVertically,
                                horizontalArrangement = Arrangement.spacedBy(8.dp)
                            ) {
                                Box(
                                    modifier = Modifier
                                        .weight(1f)
                                        .height(10.dp)
                                        .background(MaterialTheme.colorScheme.surfaceVariant, RoundedCornerShape(5.dp))
                                ) {
                                    Box(
                                        modifier = Modifier
                                            .fillMaxHeight()
                                            .fillMaxWidth(fraction = (score / 100f).coerceIn(0f, 1f))
                                            .background(
                                                if (score >= 80) Color(0xFF4CAF50)
                                                else if (score >= 50) Color(0xFFFFC107)
                                                else Color(0xFFF44336),
                                                RoundedCornerShape(5.dp)
                                            )
                                    )
                                }
                                Text(
                                    text = "$score%",
                                    fontWeight = FontWeight.Bold,
                                    fontSize = 14.sp,
                                    color = if (score >= 80) Color(0xFF4CAF50) else if (score >= 50) Color(0xFFFFC107) else Color(0xFFF44336)
                                )
                            }
                            
                            val statusMsg = when {
                                score >= 85 -> "Fantastycznie! Twoja wymowa jest idealna! 🌟"
                                score >= 65 -> "Bardzo dobrze! Jesteś bardzo blisko, ćwicz dalej! 👍"
                                else -> "Dobra próba! Odsłuchaj poprawną wersję i spróbuj jeszcze raz! 💪"
                            }
                            Text(
                                text = statusMsg,
                                fontSize = 13.sp,
                                fontWeight = FontWeight.Medium,
                                textAlign = TextAlign.Center,
                                color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.8f)
                            )
                        }
                    }
                    
                    speechRecognizerError?.let { err ->
                        Text(
                            text = "Błąd: $err. Spróbuj nagrać ponownie.",
                            color = MaterialTheme.colorScheme.error,
                            fontSize = 12.sp,
                            fontWeight = FontWeight.Bold,
                            textAlign = TextAlign.Center
                        )
                    }
                }
            }
        }
    }
}

