@OptIn(androidx.compose.material3.ExperimentalMaterial3Api::class)
@Composable
fun FullDictionarySearchDialog(

    viewModel: com.example.ui.viewmodel.TutorViewModel,
    activeLangCode: String,
    onPasteToChat: ((String) -> Unit)? = null,
    onDismiss: () -> Unit
) {
    val targetFlag = when (activeLangCode.lowercase()) {
        "english", "angielski" -> "🇬🇧"
        "spanish", "hiszpański" -> "🇪🇸"
        "german", "niemiecki" -> "🇩🇪"
        "french", "francuski" -> "🇫🇷"
        "italian", "włoski" -> "🇮🇹"
        "polish", "polski" -> "🇵🇱"
        else -> "🌍"
    }

    val queryState = remember { mutableStateOf("") }
    val isSearching by viewModel.isSearchingDictionary.collectAsState()
    val searchResult by viewModel.dictionaryResult.collectAsState()
    val recentSearches by viewModel.recentSearches.collectAsState()

    val context = androidx.compose.ui.platform.LocalContext.current
    val focusRequester = remember { androidx.compose.ui.focus.FocusRequester() }

    androidx.compose.runtime.LaunchedEffect(Unit) {
        viewModel.clearDictionaryResult()
        focusRequester.requestFocus()
    }

    androidx.compose.ui.window.Dialog(
        onDismissRequest = {
            viewModel.clearDictionaryResult()
            onDismiss()
        },
        properties = androidx.compose.ui.window.DialogProperties(usePlatformDefaultWidth = false)
    ) {
        Surface(
            modifier = Modifier
                .fillMaxSize()
                .background(MaterialTheme.colorScheme.background),
            color = MaterialTheme.colorScheme.background
        ) {
            Column(
                modifier = Modifier
                    .fillMaxSize()
                    .padding(16.dp)
            ) {
                // Header
                Row(
                    modifier = Modifier.fillMaxWidth(),
                    verticalAlignment = Alignment.CenterVertically,
                    horizontalArrangement = Arrangement.SpaceBetween
                ) {
                    Row(
                        verticalAlignment = Alignment.CenterVertically,
                        horizontalArrangement = Arrangement.spacedBy(8.dp)
                    ) {
                        Icon(
                            imageVector = Icons.Default.Translate,
                            contentDescription = null,
                            tint = LingoPrimary,
                            modifier = Modifier.size(24.dp)
                        )
                        Text(
                            text = "Kontekstowy Słownik Lingo-AI",
                            fontSize = 18.sp,
                            fontWeight = FontWeight.Bold,
                            color = MaterialTheme.colorScheme.onBackground
                        )
                    }
                    IconButton(
                        onClick = {
                            viewModel.clearDictionaryResult()
                            onDismiss()
                        }
                    ) {
                        Icon(
                            imageVector = Icons.Default.Close,
                            contentDescription = "Zamknij"
                        )
                    }
                }

                Spacer(modifier = Modifier.height(16.dp))

                // Search Bar Row
                Row(
                    modifier = Modifier.fillMaxWidth(),
                    verticalAlignment = Alignment.CenterVertically,
                    horizontalArrangement = Arrangement.spacedBy(8.dp)
                ) {
                    OutlinedTextField(
                        value = queryState.value,
                        onValueChange = { queryState.value = it },
                        placeholder = { Text("Wpisz słowo lub frazę...") },
                        modifier = Modifier
                            .weight(1f)
                            .focusRequester(focusRequester),
                        shape = RoundedCornerShape(12.dp),
                        singleLine = true,
                        leadingIcon = {
                            Icon(
                                imageVector = Icons.Default.Search,
                                contentDescription = null,
                                tint = MaterialTheme.colorScheme.onSurfaceVariant.copy(alpha = 0.6f)
                            )
                        },
                        trailingIcon = {
                            if (queryState.value.isNotEmpty()) {
                                IconButton(onClick = { queryState.value = "" }) {
                                    Icon(
                                        imageVector = Icons.Default.Clear,
                                        contentDescription = "Wyczyść"
                                    )
                                }
                            }
                        }
                    )

                    Button(
                        onClick = {
                            viewModel.searchDictionary(queryState.value, activeLangCode)
                        },
                        shape = RoundedCornerShape(12.dp),
                        enabled = queryState.value.isNotBlank() && !isSearching,
                        colors = ButtonDefaults.buttonColors(containerColor = LingoPrimary)
                    ) {
                        if (isSearching) {
                            CircularProgressIndicator(
                                modifier = Modifier.size(18.dp),
                                color = MaterialTheme.colorScheme.onPrimary,
                                strokeWidth = 2.dp
                            )
                        } else {
                            Text("Szukaj")
                        }
                    }
                }

                Spacer(modifier = Modifier.height(16.dp))

                // Scrollable Area
                LazyColumn(
                    modifier = Modifier
                        .fillMaxWidth()
                        .weight(1f),
                    verticalArrangement = Arrangement.spacedBy(12.dp)
                ) {
                    // Result Section
                    searchResult?.let { result ->
                        item {
                            Card(
                                modifier = Modifier.fillMaxWidth(),
                                shape = RoundedCornerShape(16.dp),
                                colors = CardDefaults.cardColors(
                                    containerColor = MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.4f)
                                ),
                                border = BorderStroke(1.dp, LingoPrimary.copy(alpha = 0.2f))
                            ) {
                                Column(
                                    modifier = Modifier.padding(16.dp),
                                    verticalArrangement = Arrangement.spacedBy(12.dp)
                                ) {
                                    // Główny Wpis: foreignWord + TTS Speaker Button [Język Docelowy]
                                    Row(
                                        modifier = Modifier.fillMaxWidth(),
                                        verticalAlignment = Alignment.CenterVertically,
                                        horizontalArrangement = Arrangement.SpaceBetween
                                    ) {
                                        Row(
                                            verticalAlignment = Alignment.CenterVertically,
                                            horizontalArrangement = Arrangement.spacedBy(8.dp)
                                        ) {
                                            Text(text = targetFlag, fontSize = 24.sp)
                                            Text(
                                                text = result.normalized_query,
                                                fontSize = 24.sp,
                                                fontWeight = FontWeight.Black,
                                                color = LingoPrimary
                                            )
                                            IconButton(
                                                onClick = {
                                                    (context as? MainActivity)?.speechHelper?.speak(result.normalized_query, activeLangCode)
                                                },
                                                modifier = Modifier.size(48.dp)
                                            ) {
                                                Icon(
                                                    imageVector = Icons.Default.VolumeUp,
                                                    contentDescription = "Odsłuchaj słowo nagłówkowe",
                                                    tint = LingoSecondary,
                                                    modifier = Modifier.size(24.dp)
                                                )
                                            }
                                        }

                                        Surface(
                                            shape = RoundedCornerShape(8.dp),
                                            color = LingoPrimary.copy(alpha = 0.1f)
                                        ) {
                                            Text(
                                                text = "Inteligentna Analiza AI",
                                                color = LingoPrimary,
                                                fontSize = 10.sp,
                                                fontWeight = FontWeight.Bold,
                                                modifier = Modifier.padding(horizontal = 8.dp, vertical = 4.dp)
                                            )
                                        }
                                    }

                                    if (result.phonetic.isNotEmpty() || result.part_of_speech.isNotEmpty()) {
                                        val subParts = listOfNotNull(
                                            result.phonetic.takeIf { it.isNotEmpty() },
                                            result.part_of_speech.takeIf { it.isNotEmpty() }
                                        )
                                        Text(
                                            text = subParts.joinToString(" • "),
                                            fontSize = 12.sp,
                                            fontWeight = FontWeight.Medium,
                                            color = MaterialTheme.colorScheme.onSurfaceVariant.copy(alpha = 0.6f)
                                        )
                                    }

                                    HorizontalDivider(color = MaterialTheme.colorScheme.outlineVariant.copy(alpha = 0.5f))

                                    // Podpis: nativeWord [Język Polski 🇵🇱]
                                    Column(verticalArrangement = Arrangement.spacedBy(4.dp)) {
                                        Text(
                                            text = "Tłumaczenie 🇵🇱",
                                            fontSize = 11.sp,
                                            fontWeight = FontWeight.Bold,
                                            color = MaterialTheme.colorScheme.onSurfaceVariant.copy(alpha = 0.6f)
                                        )
                                        Text(
                                            text = "🇵🇱 ${result.translated_text}",
                                            fontSize = 18.sp,
                                            fontWeight = FontWeight.Bold,
                                            color = MaterialTheme.colorScheme.onSurface
                                        )
                                    }

                                    // Sekcja Kontekstu
                                    if (result.example_target.isNotEmpty()) {
                                        Column(verticalArrangement = Arrangement.spacedBy(6.dp)) {
                                            Text(
                                                text = "Przykład Użycia",
                                                fontSize = 11.sp,
                                                fontWeight = FontWeight.Bold,
                                                color = MaterialTheme.colorScheme.onSurfaceVariant.copy(alpha = 0.6f)
                                            )
                                            Row(
                                                verticalAlignment = Alignment.CenterVertically,
                                                horizontalArrangement = Arrangement.spacedBy(8.dp)
                                            ) {
                                                Text(
                                                    text = result.example_target,
                                                    fontSize = 14.sp,
                                                    fontWeight = FontWeight.Medium,
                                                    color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.95f),
                                                    modifier = Modifier.weight(1f)
                                                )
                                                IconButton(
                                                    onClick = {
                                                        (context as? MainActivity)?.speechHelper?.speak(result.example_target, activeLangCode)
                                                    },
                                                    modifier = Modifier.size(48.dp)
                                                ) {
                                                    Icon(
                                                        imageVector = Icons.Default.VolumeUp,
                                                        contentDescription = "Odsłuchaj przykład",
                                                        tint = LingoSecondary,
                                                        modifier = Modifier.size(20.dp)
                                                    )
                                                }
                                            }
                                            Text(
                                                text = "🇵🇱 ${result.example_pl}",
                                                fontSize = 13.sp,
                                                fontStyle = androidx.compose.ui.text.font.FontStyle.Italic,
                                                color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.7f)
                                            )
                                        }
                                    }

                                    Spacer(modifier = Modifier.height(4.dp))

                                    Button(
                                        onClick = {
                                            viewModel.addDictionaryEntryToVocabulary(result)
                                            android.widget.Toast.makeText(context, "Dodano do powtórek SRS! 🚀", android.widget.Toast.LENGTH_SHORT).show()
                                        },
                                        modifier = Modifier.fillMaxWidth(),
                                        shape = RoundedCornerShape(10.dp),
                                        colors = ButtonDefaults.buttonColors(containerColor = LingoSecondary)
                                    ) {
                                        Icon(
                                            imageVector = Icons.Default.Star,
                                            contentDescription = null,
                                            modifier = Modifier.size(16.dp)
                                        )
                                        Spacer(modifier = Modifier.width(6.dp))
                                        Text("DODAJ DO POWTÓREK SRS ⚡", fontSize = 12.sp, fontWeight = FontWeight.Bold)
                                    }

                                    if (onPasteToChat != null) {
                                        Spacer(modifier = Modifier.height(8.dp))
                                        Button(
                                            onClick = {
                                                onPasteToChat(result.translated_text.ifEmpty { result.normalized_query })
                                                android.widget.Toast.makeText(context, "Wklejono do czatu! ✍️", android.widget.Toast.LENGTH_SHORT).show()
                                                viewModel.clearDictionaryResult()
                                                onDismiss()
                                            },
                                            modifier = Modifier.fillMaxWidth(),
                                            shape = RoundedCornerShape(10.dp),
                                            colors = ButtonDefaults.buttonColors(containerColor = LingoPrimary)
                                        ) {
                                            Icon(
                                                imageVector = Icons.Default.Send,
                                                contentDescription = null,
                                                modifier = Modifier.size(16.dp)
                                            )
                                            Spacer(modifier = Modifier.width(6.dp))
                                            Text("Wklej do czatu ✍️", fontSize = 12.sp, fontWeight = FontWeight.Bold)
                                        }
                                    }
                                }
                            }
                        }
                    }

                    if (recentSearches.isNotEmpty()) {
                        item {
                            Text(
                                text = "Historia Wyszukiwania",
                                fontSize = 14.sp,
                                fontWeight = FontWeight.Bold,
                                color = MaterialTheme.colorScheme.onBackground.copy(alpha = 0.7f),
                                modifier = Modifier.padding(top = 8.dp)
                            )
                        }

                        items(recentSearches) { search ->
                            Card(
                                modifier = Modifier
                                    .fillMaxWidth()
                                    .clickable {
                                        queryState.value = search.normalized_query
                                        viewModel.searchDictionary(search.normalized_query, activeLangCode)
                                    },
                                shape = RoundedCornerShape(12.dp),
                                colors = CardDefaults.cardColors(
                                    containerColor = MaterialTheme.colorScheme.surface.copy(alpha = 0.6f)
                                ),
                                border = BorderStroke(1.dp, MaterialTheme.colorScheme.outline.copy(alpha = 0.1f))
                            ) {
                                Row(
                                    modifier = Modifier
                                        .fillMaxWidth()
                                        .padding(12.dp),
                                    verticalAlignment = Alignment.CenterVertically,
                                    horizontalArrangement = Arrangement.SpaceBetween
                                ) {
                                    Column(modifier = Modifier.weight(1f)) {
                                        Text(
                                            text = search.normalized_query,
                                            fontSize = 14.sp,
                                            fontWeight = FontWeight.Bold,
                                            color = MaterialTheme.colorScheme.onSurface
                                        )
                                        Text(
                                            text = search.definition_pl,
                                            fontSize = 12.sp,
                                            color = MaterialTheme.colorScheme.onSurfaceVariant
                                        )
                                    }
                                    IconButton(
                                        onClick = {
                                            viewModel.deleteRecentSearch(search.id)
                                        }
                                    ) {
                                        Icon(
                                            imageVector = Icons.Default.Delete,
                                            contentDescription = "Usuń z historii",
                                            tint = MaterialTheme.colorScheme.error.copy(alpha = 0.7f),
                                            modifier = Modifier.size(18.dp)
                                        )
                                    }
                                }
                            }
                        }
                    } else if (searchResult == null) {
                        item {
                            Box(
                                modifier = Modifier
                                    .fillMaxWidth()
                                    .padding(32.dp),
                                contentAlignment = Alignment.Center
                            ) {
                                Text(
                                    text = "Brak niedawnych wyszukiwań.\nWyszukaj dowolne słowo wyżej!",
                                    color = MaterialTheme.colorScheme.onSurfaceVariant.copy(alpha = 0.5f),
                                    fontSize = 13.sp,
                                    textAlign = TextAlign.Center
                                )
                            }
                        }
                    }
                }
            }
        }
    }
}

